function tokenTimingCategoryFromRaw(value = "") {
  const key = String(value || "").toLowerCase().trim();
  if (key === "reroll") return TOKEN_TIMING_CATEGORIES.ENCOUNTER;
  if (Object.values(TOKEN_TIMING_CATEGORIES).includes(key)) return key;
  if (key === "curses") return TOKEN_TIMING_CATEGORIES.CURSE;
  if (key === "encounters") return TOKEN_TIMING_CATEGORIES.ENCOUNTER;
  if (key === "manual" || key === "other") return TOKEN_TIMING_CATEGORIES.MANUAL;
  return "";
}

function tokenEngineDefinitionByName(tokenName = "") {
  const key = slugify(tokenName);
  if (!key) return null;
  const entry = Object.entries(TOKEN_TIMING_ENGINE_V1_DEFINITIONS)
    .find(([id, definition]) => slugify(id) === key || (definition.names || []).some((name) => slugify(name) === key));
  return entry ? { ...entry[1], id: entry[1].id || entry[0], source: "engine-v1" } : null;
}

function tokenTimingDefinitionByName(tokenName = "") {
  const key = slugify(tokenName);
  if (!key) return null;
  const legacy = TOKEN_TIMING_LEGACY_OVERRIDES[key];
  if (legacy) return { id: key, source: "legacy", ...legacy };
  const engine = tokenEngineDefinitionByName(tokenName);
  if (engine) return { id: engine.id || key, source: "engine-v1", ...engine };
  const effectDefinition = Object.values(tokenEffectDefinitions).find((definition) => slugify(definition.name || definition.id) === key);
  if (effectDefinition?.timingCategory) return { id: effectDefinition.id, source: "effect", ...effectDefinition };
  const utilityEntry = Object.entries(utilityTokenDefinitions).find(([, definition]) => definition.names.some((candidate) => slugify(candidate) === key));
  if (utilityEntry) {
    const [, definition] = utilityEntry;
    const category = tokenTimingCategoryFromRaw(definition.timingCategory || definition.category);
    return { id: utilityEntry[0], source: "utility", ...TOKEN_TIMING_DEFAULTS[category], ...definition, timingCategory: category || definition.category };
  }
  const statusEntry = Object.entries(statusTokenDefinitions).find(([, definition]) => definition.names.some((candidate) => slugify(candidate) === key));
  if (statusEntry) {
    const [, definition] = statusEntry;
    const category = tokenTimingCategoryFromRaw(definition.timingCategory || definition.category);
    return { id: statusEntry[0], source: "status", ...TOKEN_TIMING_DEFAULTS[category], ...definition, timingCategory: category || definition.category };
  }
  const shopEntry = activeTokenCatalog().find((item) => slugify(item.name || item.id) === key || (item.legacyIds || []).some((id) => slugify(id) === key));
  if (shopEntry) {
    const category = tokenTimingCategoryFromRaw(shopEntry.timingCategory || shopEntry.tokenType || shopEntry.category);
    return { id: shopEntry.id, source: "shop", ...TOKEN_TIMING_DEFAULTS[category], ...shopEntry, timingCategory: category };
  }
  return null;
}

function tokenTimingCategoryForName(tokenName = "", fallback = "") {
  return tokenTimingCategoryFromRaw(tokenTimingDefinitionByName(tokenName)?.timingCategory || fallback);
}

function normalizeEffectTargetType(value = "") {
  const raw = String(value || "").trim();
  const key = raw.toLowerCase();
  const values = Object.values(EFFECT_TARGET_TYPES);
  if (values.includes(raw)) return raw;
  if (key === "current-prompt") return EFFECT_TARGET_TYPES.CURRENT_PROMPT;
  if (key === "pending-random-result" || key === "pending-result") return EFFECT_TARGET_TYPES.ENCOUNTER_RESULT;
  if (/encounter|random/.test(key)) return EFFECT_TARGET_TYPES.ENCOUNTER_RESULT;
  if (/pokemon/.test(key)) return EFFECT_TARGET_TYPES.POKEMON;
  if (/player/.test(key)) return EFFECT_TARGET_TYPES.PLAYER;
  if (/team/.test(key)) return EFFECT_TARGET_TYPES.TEAM;
  if (/resource|item|token|money|tm/.test(key)) return EFFECT_TARGET_TYPES.RESOURCE;
  if (/table|field|global/.test(key)) return EFFECT_TARGET_TYPES.TABLE;
  if (key === "none") return EFFECT_TARGET_TYPES.NONE;
  if (key === "manual") return EFFECT_TARGET_TYPES.MANUAL;
  return "";
}

function normalizeEffectTargetScope(value = "") {
  const raw = String(value || "").trim();
  const key = raw.toLowerCase();
  const values = Object.values(EFFECT_TARGET_SCOPES);
  if (values.includes(raw)) return raw;
  if (key === "current-prompt" || key === "pending-result") return EFFECT_TARGET_SCOPES.CURRENT_PROMPT;
  if (key === "pokemon-species" || key === "species-name") return EFFECT_TARGET_SCOPES.SPECIES;
  if (key === "single-pokemon" || key === "owned-copy" || key === "roster-instance") return EFFECT_TARGET_SCOPES.ROSTER_INSTANCE;
  if (key === "player" || key === "single-player") return EFFECT_TARGET_SCOPES.SINGLE_PLAYER;
  if (key === "all-players") return EFFECT_TARGET_SCOPES.ALL_PLAYERS;
  if (key === "team" || key === "single-team") return EFFECT_TARGET_SCOPES.SINGLE_TEAM;
  if (key === "all-teams") return EFFECT_TARGET_SCOPES.ALL_TEAMS;
  if (key === "resource" || key === "single-resource") return EFFECT_TARGET_SCOPES.SINGLE_RESOURCE;
  if (key === "all-matching-resources") return EFFECT_TARGET_SCOPES.ALL_MATCHING_RESOURCES;
  if (key === "table" || key === "table-wide" || key === "global" || key === "field" || key === "none") return EFFECT_TARGET_SCOPES.TABLE_WIDE;
  if (key === "manual") return EFFECT_TARGET_SCOPES.MANUAL;
  return "";
}

function effectTargetTypeFromDefinition(definition = {}, category = "") {
  const explicit = normalizeEffectTargetType(definition.targetType);
  if (explicit) return explicit;
  if (category === TOKEN_TIMING_CATEGORIES.PROTECTION) return EFFECT_TARGET_TYPES.CURRENT_PROMPT;
  if (category === TOKEN_TIMING_CATEGORIES.ENCOUNTER) return EFFECT_TARGET_TYPES.ENCOUNTER_RESULT;
  const mode = String(definition.targetMode || "").toLowerCase();
  if (/pokemon/.test(mode) || mode === "banned-pokemon") return EFFECT_TARGET_TYPES.POKEMON;
  if (/player/.test(mode)) return EFFECT_TARGET_TYPES.PLAYER;
  if (/field/.test(mode) || definition.effectType === "field") return EFFECT_TARGET_TYPES.TABLE;
  if (/item|tm|token|money/.test(mode) || definition.choiceLabel) return EFFECT_TARGET_TYPES.RESOURCE;
  if (mode === "none") return EFFECT_TARGET_TYPES.TABLE;
  return EFFECT_TARGET_TYPES.MANUAL;
}

function effectTargetScopeFromDefinition(definition = {}, targetType = "", category = "") {
  const explicit = normalizeEffectTargetScope(definition.targetScope);
  if (explicit) return explicit;
  if (targetType === EFFECT_TARGET_TYPES.CURRENT_PROMPT) return EFFECT_TARGET_SCOPES.CURRENT_PROMPT;
  if (targetType === EFFECT_TARGET_TYPES.ENCOUNTER_RESULT) return EFFECT_TARGET_SCOPES.CURRENT_PROMPT;
  if (targetType === EFFECT_TARGET_TYPES.PLAYER) return EFFECT_TARGET_SCOPES.SINGLE_PLAYER;
  if (targetType === EFFECT_TARGET_TYPES.TABLE) return EFFECT_TARGET_SCOPES.TABLE_WIDE;
  if (targetType === EFFECT_TARGET_TYPES.RESOURCE) return definition.targetMode === "none"
    ? EFFECT_TARGET_SCOPES.ALL_MATCHING_RESOURCES
    : EFFECT_TARGET_SCOPES.SINGLE_RESOURCE;
  if (targetType === EFFECT_TARGET_TYPES.POKEMON) {
    if (statusTokenTargetsPokemonSpecies(definition)) return EFFECT_TARGET_SCOPES.SPECIES;
    if (definition.targetMode === "multi-pokemon" || definition.targetMode === "single-pokemon" || definition.targetMode === "banned-pokemon") {
      return EFFECT_TARGET_SCOPES.ROSTER_INSTANCE;
    }
  }
  if (targetType === EFFECT_TARGET_TYPES.NONE) return EFFECT_TARGET_SCOPES.NONE;
  return category === TOKEN_TIMING_CATEGORIES.MANUAL ? EFFECT_TARGET_SCOPES.MANUAL : EFFECT_TARGET_SCOPES.MANUAL;
}

function targetCategoryFromEffectBucket(targetType = "", targetScope = "") {
  if (targetType === EFFECT_TARGET_TYPES.POKEMON) return EFFECT_TARGET_CATEGORIES.POKEMON;
  if (targetType === EFFECT_TARGET_TYPES.ENCOUNTER_RESULT) return EFFECT_TARGET_CATEGORIES.ENCOUNTER_RESULT;
  if (targetType === EFFECT_TARGET_TYPES.PLAYER) return EFFECT_TARGET_CATEGORIES.PLAYER;
  if (targetType === EFFECT_TARGET_TYPES.RESOURCE) return EFFECT_TARGET_CATEGORIES.TOKEN;
  if (targetType === EFFECT_TARGET_TYPES.TABLE || targetType === EFFECT_TARGET_TYPES.TEAM) return EFFECT_TARGET_CATEGORIES.WHOLE_TABLE;
  if (targetType === EFFECT_TARGET_TYPES.CURRENT_PROMPT) return EFFECT_TARGET_CATEGORIES.MANUAL;
  if (targetScope === EFFECT_TARGET_SCOPES.TABLE_WIDE) return EFFECT_TARGET_CATEGORIES.WHOLE_TABLE;
  return EFFECT_TARGET_CATEGORIES.MANUAL;
}

function tokenContractDefinitionByName(tokenName = "") {
  const contract = globalThis.rivalSagaTokenEffectContract;
  if (!contract?.definitionFor) return null;
  const direct = contract.definitionFor(tokenName);
  if (direct) return direct;
  const timingDefinition = tokenTimingDefinitionByName(tokenName);
  return timingDefinition?.id ? contract.definitionFor(timingDefinition.id) : null;
}

function normalizeEffectResolutionMode(value = "") {
  const key = String(value || "").trim().toLowerCase();
  if (key === EFFECT_RESOLUTION_MODES.AUTOMATIC) return EFFECT_RESOLUTION_MODES.AUTOMATIC;
  if (key === EFFECT_RESOLUTION_MODES.GUIDED || key === "hybrid") return EFFECT_RESOLUTION_MODES.GUIDED;
  if (["hostconfirmed", "host-confirmed", "manual", "audit"].includes(key)) return EFFECT_RESOLUTION_MODES.HOST_CONFIRMED;
  return EFFECT_RESOLUTION_MODES.HOST_CONFIRMED;
}

function tokenResolutionModeForDefinition(definition = {}) {
  if (definition.resolverMode || definition.resolutionMode) {
    return normalizeEffectResolutionMode(definition.resolverMode || definition.resolutionMode);
  }
  const key = slugify(definition.name || definition.id || definition.names?.[0] || "");
  if (key === "reroll-token" || key === "reroll") return EFFECT_RESOLUTION_MODES.AUTOMATIC;
  if (["restrict", "immunity", "counterProtection", "substituteAttach"].includes(definition.resolverId)) return EFFECT_RESOLUTION_MODES.AUTOMATIC;
  if (definition.resolverId === "safeguard") return EFFECT_RESOLUTION_MODES.AUTOMATIC;
  if (definition.resolverId === "extraEncounter") return EFFECT_RESOLUTION_MODES.AUTOMATIC;
  return EFFECT_RESOLUTION_MODES.HOST_CONFIRMED;
}

function tokenConsumptionModeForDefinition(definition = {}) {
  const category = tokenTimingCategoryFromRaw(definition.timingCategory || definition.category);
  if (!category || category === TOKEN_TIMING_CATEGORIES.MANUAL) return TOKEN_CONSUMPTION_MODES.MANUAL_CONSUMPTION;
  return TOKEN_CONSUMPTION_MODES.CONSUME_ON_USE;
}

function tokenEffectMetadataByName(tokenName = "") {
  const timingDefinition = tokenTimingDefinitionByName(tokenName) || {};
  const engineDefinition = tokenEngineDefinitionByName(tokenName) || {};
  const contractDefinition = tokenContractDefinitionByName(tokenName) || {};
  const definition = { ...timingDefinition, ...engineDefinition, ...contractDefinition };
  const category = tokenTimingCategoryFromRaw(definition.timingCategory || definition.category) || TOKEN_TIMING_CATEGORIES.MANUAL;
  const defaults = TOKEN_TIMING_DEFAULTS[category] || {};
  const displayName = displayInventoryTokenName(tokenName || definition.name || definition.names?.[0] || definition.id || "Token");
  const resolutionMode = tokenResolutionModeForDefinition({ ...definition, name: displayName });
  const consumptionMode = tokenConsumptionModeForDefinition({ ...definition, timingCategory: category });
  const targetType = effectTargetTypeFromDefinition(definition, category);
  const targetScope = effectTargetScopeFromDefinition(definition, targetType, category);
  const applicationScope = definition.applicationScope || ({
    [EFFECT_TARGET_SCOPES.SPECIES]: EFFECT_APPLICATION_SCOPES.GLOBAL_SPECIES,
    [EFFECT_TARGET_SCOPES.ROSTER_INSTANCE]: EFFECT_APPLICATION_SCOPES.ROSTER_INSTANCE,
    [EFFECT_TARGET_SCOPES.SINGLE_TEAM]: EFFECT_APPLICATION_SCOPES.SUBMITTED_TEAM_INSTANCES,
    [EFFECT_TARGET_SCOPES.SINGLE_PLAYER]: EFFECT_APPLICATION_SCOPES.SINGLE_PLAYER,
    [EFFECT_TARGET_SCOPES.ALL_PLAYERS]: EFFECT_APPLICATION_SCOPES.ALL_PLAYERS,
    [EFFECT_TARGET_SCOPES.TABLE_WIDE]: EFFECT_APPLICATION_SCOPES.TABLE_WIDE
  }[targetScope] || EFFECT_APPLICATION_SCOPES.MANUAL);
  return {
    id: definition.canonicalId || definition.id || slugify(displayName),
    name: displayName,
    sourceType: EFFECT_SOURCE_TYPES.TOKEN,
    timingCategory: category,
    targetType,
    targetScope,
    selectedTargetType: definition.selectedTargetType || targetType,
    applicationScope,
    affectedEntityType: definition.affectedEntityType || targetType,
    substituteInterceptionPolicy: definition.substituteInterceptionPolicy || "",
    substituteChecksSelectedTargetOnly: Boolean(definition.substituteChecksSelectedTargetOnly),
    targetCategory: targetCategoryFromEffectBucket(targetType, targetScope),
    resolutionMode,
    consumptionMode,
    objectType: definition.objectType || TOKEN_OBJECT_TYPES.TOKEN,
    family: Array.isArray(definition.family) ? definition.family : [definition.family || category].filter(Boolean),
    timingWindows: Array.isArray(definition.timingWindows) ? definition.timingWindows : [],
    activationPattern: definition.activationPattern || "",
    persistence: definition.persistence || TOKEN_PERSISTENCE_BUCKETS.NONE,
    resolutionPayloads: Array.isArray(definition.resolutionPayloads) ? definition.resolutionPayloads : [],
    duration: definition.duration || "",
    consumesOnLegalUse: definition.consumesOnLegalUse !== false,
    consumeIfMisses: definition.consumeIfMisses !== false,
    consumeIfBlocked: definition.consumeIfBlocked !== false,
    canOpenPendingEvent: Boolean(definition.canOpenPendingEvent ?? definition.createsPendingEvent ?? defaults.createsPendingEvent),
    canBeRespondedTo: Boolean(definition.canBeRespondedTo ?? definition.opensResponseWindow ?? defaults.opensResponseWindow),
    canRespondTo: Array.isArray(definition.canRespondTo) ? definition.canRespondTo : [],
    protectionScope: Array.isArray(definition.protectionScope) ? definition.protectionScope : [],
    removableBy: Array.isArray(definition.removableBy) ? definition.removableBy : [],
    visibility: definition.visibility || "public",
    logType: definition.logType || "tokenUsed",
    resolverId: definition.resolverId || "",
    resolverMode: resolutionMode,
    rulesText: definition.rulesText || definition.description || definition.note || "",
    legalPhases: Array.isArray(definition.legalPhases) ? definition.legalPhases : [],
    legalControlContexts: Array.isArray(definition.legalControlContexts) ? definition.legalControlContexts : [],
    activationType: definition.activationType || "",
    usesControlTiming: Boolean(definition.usesControlTiming),
    isResponse: Boolean(definition.isResponse),
    specialPriority: definition.specialPriority || "",
    requiredChoices: Array.isArray(definition.requiredChoices) ? definition.requiredChoices : [],
    targetValidation: definition.targetValidation || "",
    redirectPolicy: definition.redirectPolicy || null,
    targetsRedirectable: definition.redirectPolicy ? false : definition.targetsRedirectable === true,
    revalidateOnResolution: definition.revalidateOnResolution !== false,
    declarationCost: definition.declarationCost || "Consume 1 Token",
    consumptionTiming: definition.consumptionTiming || "Declaration confirmation",
    otherDeclarationCosts: Array.isArray(definition.otherDeclarationCosts) ? definition.otherDeclarationCosts : [],
    declarationAnnouncement: definition.declarationAnnouncement || "",
    automaticMutations: Array.isArray(definition.automaticMutations) ? definition.automaticMutations : [],
    guidedTask: definition.guidedTask || null,
    hostTask: definition.hostTask || null,
    successConditions: Array.isArray(definition.successConditions) ? definition.successConditions : [],
    failureConditions: Array.isArray(definition.failureConditions) ? definition.failureConditions : [],
    parentInteraction: definition.parentInteraction || "",
    expirationPoint: definition.expirationPoint || "",
    replacementRules: definition.replacementRules || "",
    stackingRules: definition.stackingRules || "",
    stateClassification: definition.stateClassification || "",
    outcomeTemplate: definition.outcomeTemplate || "",
    auditFields: Array.isArray(definition.auditFields) ? definition.auditFields : [],
    undoPayload: Array.isArray(definition.undoPayload) ? definition.undoPayload : [],
    implementationStatus: definition.implementationStatus || "",
    runtimeImplementationStatus: definition.runtimeImplementationStatus || "",
    runtimeUsability: definition.runtimeUsability || "usable",
    runtimeUsabilityReason: definition.runtimeUsabilityReason || "",
    requiredTests: Array.isArray(definition.requiredTests) ? definition.requiredTests : [],
    targetControllerRelation: definition.targetControllerRelation || "",
    selfOnly: Boolean(definition.selfOnly),
    otherPlayerOnly: Boolean(definition.otherPlayerOnly),
    excludeActor: Boolean(definition.excludeActor),
    differentControllerRequired: Boolean(definition.differentControllerRequired),
    createsPendingEvent: Boolean(definition.createsPendingEvent ?? definition.canOpenPendingEvent ?? defaults.createsPendingEvent),
    requiresPendingEvent: Boolean(definition.requiresPendingEvent ?? defaults.requiresPendingEvent),
    opensResponseWindow: Boolean(definition.opensResponseWindow ?? defaults.opensResponseWindow),
    transactionsAllowed: definition.transactionsAllowed !== undefined ? Boolean(definition.transactionsAllowed) : defaults.transactionsAllowed !== false,
    promptTemplate: "{actor} used {token} on {target}.",
    shortPromptText: definition.note || definition.description || "",
    definition
  };
}

function tokenRuntimeUsabilityCheck(metadataOrName = "") {
  const metadata = typeof metadataOrName === "object" && metadataOrName
    ? metadataOrName
    : tokenEffectMetadataByName(metadataOrName);
  const definition = metadata?.definition?.runtimeUsability
    ? metadata.definition
    : tokenContractDefinitionByName(metadata?.id || metadata?.name || metadataOrName);
  const contract = globalThis.rivalSagaTokenEffectContract;
  if (!definition || !contract?.activationUsabilityFor) {
    return { ok: true, status: "usable", mayConsume: true, reason: "" };
  }
  return contract.activationUsabilityFor(definition);
}

function tokenRuntimeResultSafetyCheck(metadataOrName = "", outcome = {}) {
  const metadata = typeof metadataOrName === "object" && metadataOrName
    ? metadataOrName
    : tokenEffectMetadataByName(metadataOrName);
  const contract = globalThis.rivalSagaTokenEffectContract;
  if (!contract?.runtimeResultSafetyFor) return { ok: true, reason: "" };
  return contract.runtimeResultSafetyFor(metadata?.definition || metadata?.id || metadata?.name || metadataOrName, outcome);
}

function tokenTimingCategoryLabel(category) {
  return {
    [TOKEN_TIMING_CATEGORIES.CONTROL]: "Control Token",
    [TOKEN_TIMING_CATEGORIES.PROTECTION]: "Protection Token",
    [TOKEN_TIMING_CATEGORIES.ENCOUNTER]: "Encounter Token",
    [TOKEN_TIMING_CATEGORIES.CURSE]: "Curse Token",
    [TOKEN_TIMING_CATEGORIES.MANUAL]: "Manual Token"
  }[category] || "Token";
}

function ordinaryControlBlockingReason(targetState = state) {
  const phaseRecord = provisionalDeclarationRuntime.phaseStateRecord?.(targetState) || null;
  const battlePhase = phaseRecord?.battlePhase || {};
  if ((battlePhase.revisionOperations || []).some((operation) => operation.status === "WAITING_FOR_REVISIONS")) {
    return "A required team revision is still open.";
  }
  if ((battlePhase.revisionWindows || []).some((window) => window.status === "open")) {
    return "A required team revision is still open.";
  }
  if ((targetState.playerNotifications || []).some((notification) => notification.requiresAction !== false
    && !["completed", "resolved", "cancelled", "dismissed"].includes(String(notification.status || "pending").toLowerCase()))) {
    return "A required gameplay choice is still open.";
  }
  if (activeArenaTrapCustomizationStatus?.("", targetState)) {
    return "Arena Trap customization must finish before another effect is declared.";
  }
  return "";
}

function battlePayoutCompleteForState(targetState = state) {
  return (targetState.gymResults || []).some((result) => !result.undone
    && result.series === targetState.series
    && Number(result.gym) === Number(targetState.gym));
}

function ordinaryControlTimingStatusForState(targetState = state) {
  return provisionalDeclarationRuntime.ordinaryControlTimingStatus(targetState, {
    actionsPerPlayer: actionPhaseRules.actionsPerPlayer,
    isBlocking: interactionSituationLifecycle.isBlocking,
    battlePayoutComplete: battlePayoutCompleteForState(targetState),
    blockingReason: ordinaryControlBlockingReason(targetState)
  });
}

function tokenTimingWindowsForContext(context = {}) {
  const pendingEvent = context.pendingEvent || getCurrentPendingEvent?.() || null;
  const targetState = context.targetState || state;
  const windows = new Set();
  if (context.manualHost) windows.add(TOKEN_TIMING_WINDOWS.MANUAL_HOST);
  if (pendingEvent) {
    windows.add(TOKEN_TIMING_WINDOWS.RESPONSE_WINDOW);
    const resultSession = liveResultSessionForActivity?.(pendingEvent);
    const pendingKind = `${pendingEvent.type || ""} ${pendingEvent.sourceType || ""}`;
    if (resultSession || /encounter-result|pokemon-result/i.test(pendingKind)) {
      windows.add("encounterResult");
      windows.add(TOKEN_TIMING_WINDOWS.WHEEL_WINDOW);
    } else if (pendingEvent.payload?.encounterStage === "beforeRoll" || /encounter-before|wheel-before/i.test(pendingKind)) {
      windows.add("encounterBeforeRoll");
    } else if (/wheel/i.test(pendingKind)) {
      windows.add(TOKEN_TIMING_WINDOWS.WHEEL_WINDOW);
    }
  } else {
    const phase = currentPhase?.() || "";
    if (phase) windows.add(phase);
    if (phase === "start") windows.add("gymStart");
    const ordinaryControl = ordinaryControlTimingStatusForState(targetState);
    if (ordinaryControl.open) {
      windows.add(ordinaryControl.context);
      if (ordinaryControl.context === "actionOpenControl") windows.add(TOKEN_TIMING_WINDOWS.ACTION_OPEN);
      if (ordinaryControl.context === "teamBuilding") windows.add(TOKEN_TIMING_WINDOWS.TEAM_BUILDING);
      if (ordinaryControl.context === "shop") windows.add(TOKEN_TIMING_WINDOWS.SHOP_OPEN);
      if (ordinaryControl.context === "postBattleControl") windows.add("postBattleControl");
    }
    if (phase === "battle-results") {
      windows.add(TOKEN_TIMING_WINDOWS.BATTLE_RESULTS);
      windows.add("battleResults");
    }
    try {
      if (phase === "battle") {
        const substep = battlePhaseSubstep?.();
        if (substep === "teamPreparation" || substep === "teamSubmissionLock") windows.add(TOKEN_TIMING_WINDOWS.BATTLE_PREP);
        if (substep === "sabotage") windows.add(TOKEN_TIMING_WINDOWS.SABOTAGE);
        if (BATTLE_PHASE_REVEALED_SUBSTEPS?.includes?.(substep)) windows.add(TOKEN_TIMING_WINDOWS.TEAM_PREVIEW);
      }
    } catch {
      // Battle substep helpers are not required for non-battle timing checks.
    }
  }
  if (context.teamBuilding) windows.add(TOKEN_TIMING_WINDOWS.TEAM_BUILDING);
  if (context.battlePrep) windows.add(TOKEN_TIMING_WINDOWS.BATTLE_PREP);
  if (context.encounterBeforeRoll) windows.add("encounterBeforeRoll");
  if (context.encounterResult) windows.add("encounterResult");
  return [...windows];
}

function tokenUseTimingCheck({ player, tokenName, metadata = tokenEffectMetadataByName(tokenName), context = {} } = {}) {
  if (!player) return { ok: false, reason: "Choose a player before using this token." };
  if (!tokenName) return { ok: false, reason: "Choose a token before using it." };
  const usability = tokenRuntimeUsabilityCheck(metadata);
  if (!usability.ok) return { ...usability, ok: false };
  if (!playerHasTokenForEffect(player, tokenName, metadata)) return { ok: false, reason: `${player.name} does not have ${tokenName}.` };
  const pendingEvent = context.pendingEvent || getCurrentPendingEvent?.() || null;
  const windows = tokenTimingWindowsForContext({ ...context, pendingEvent });
  const legalWindows = metadata.timingWindows || [];
  const legalControlContexts = metadata.legalControlContexts || [];
  const phaseSpecificControlContext = !pendingEvent && !context.manualHost
    ? ([
      ["sabotageCurseWindow", windows.includes(TOKEN_TIMING_WINDOWS.SABOTAGE)],
      ["gymStartPreparationControl", windows.includes("gymStartPreparationControl")]
    ].find(([contextName, active]) => active && legalControlContexts.includes(contextName))?.[0] || "")
    : "";
  const ordinaryControl = !pendingEvent && !context.manualHost && metadata.usesControlTiming && !phaseSpecificControlContext
    ? ordinaryControlTimingStatusForState(context.targetState || state)
    : null;
  if (ordinaryControl && !ordinaryControl.open) {
    return { ok: false, reason: ordinaryControl.reason, windows, legalWindows };
  }
  const activeControlContext = phaseSpecificControlContext || ordinaryControl?.context || "";
  const legalByWindow = metadata.usesControlTiming && activeControlContext
    ? (!legalControlContexts.length || legalControlContexts.includes(activeControlContext))
    : (!legalWindows.length || legalWindows.some((windowName) => windows.includes(windowName)));
  if (!legalByWindow) {
    return {
      ok: false,
      reason: `${metadata.name || tokenName} is not legal in the current timing window.`,
      windows,
      legalWindows,
      legalControlContexts
    };
  }
  const isResponse = metadata.activationPattern === TOKEN_ACTIVATION_PATTERNS.RESPONSE
    || legalWindows.includes(TOKEN_TIMING_WINDOWS.RESPONSE_WINDOW)
    || legalWindows.includes(TOKEN_TIMING_WINDOWS.WHEEL_WINDOW);
  if (isResponse && !pendingEvent && !context.manualHost) {
    return { ok: false, reason: `${metadata.name || tokenName} needs an open pending or wheel window.` };
  }
  if (!isResponse && pendingEvent && !context.manualHost) {
    return { ok: false, reason: `${metadata.name || tokenName} is not a response to the current prompt.` };
  }
  return { ok: true, windows, legalWindows };
}

function canUseTokenNow(targetState = state, playerId = activePlayer().id, tokenName = "", context = {}) {
  const player = (targetState.players || []).find((entry) => entry.id === playerId);
  const metadata = tokenEffectMetadataByName(tokenName);
  return tokenUseTimingCheck({ player, tokenName, metadata, context }).ok;
}

function getActiveEffectsForTarget(targetState = state, targetId = "") {
  const predicate = (effect) => effect.targetPlayerId === targetId
    || effect.targetPokemonId === targetId
    || effect.targetPokemonNameKey === pokemonRuleKey(targetId);
  if (controlTokenEffects?.activeStatuses) {
    return controlTokenEffects.activeStatuses(targetState, {
      ...controlTokenEffectOptions(),
      state: targetState
    }, predicate);
  }
  return (targetState.lingeringStatuses || []).filter((effect) => effect.status === "active" && predicate(effect));
}

function hasProtectionAgainst(targetState = state, targetId = "", incomingEffect = {}) {
  const category = [incomingEffect.type, incomingEffect.resolverId, ...(incomingEffect.protectionKeys || [])]
    .find((key) => controlTokenEffects?.safeguardProtectsOperation?.(key));
  if (category && controlTokenEffects?.playerHasActiveSafeguard) {
    return controlTokenEffects.playerHasActiveSafeguard(targetState, targetId, category, {
      ...controlTokenEffectOptions(),
      state: targetState
    });
  }
  const effects = getActiveEffectsForTarget(targetState, targetId);
  return effects.some((effect) => {
    if (effect.type !== "safeguard") return false;
    const scope = effect.payload?.protectionScope || [];
    const incomingKeys = [
      incomingEffect.type,
      incomingEffect.family,
      incomingEffect.resolverId,
      ...(incomingEffect.families || []),
      ...(incomingEffect.protectionKeys || [])
    ].filter(Boolean);
    return incomingKeys.some((key) => scope.includes(key));
  });
}

function applyAutomaticSafeguardActivity(activity, metadata) {
  if (metadata?.id !== "safeguard" || !controlTokenEffects?.resolveSafeguard) return null;
  const targetPlayerId = activity.targetPlayerId || activity.payload?.targetPlayerId || activity.actorPlayerId || "";
  if (targetPlayerId !== activity.actorPlayerId) {
    return { result: "systemFailure", refundRequired: true, details: ["Safeguard's exact self target changed before resolution."], mutations: [], persistentStateIds: [] };
  }
  const expires = statusExpiresAt(1);
  const resolution = controlTokenEffects.resolveSafeguard(state, {
    sourceTokenId: activity.payload?.consumedTokenId || "",
    sourceTokenName: metadata.name,
    actorPlayerId: activity.actorPlayerId,
    targetPlayerId,
    sourceEffectId: activity.id,
    expiresAtSeries: expires.expiresAtSeries,
    expiresAtGym: expires.expiresAtGym,
    expiresAtPhase: "start"
  }, controlTokenEffectOptions(new Date().toISOString()));
  return {
    result: resolution.result,
    details: [resolution.reason],
    mutations: (resolution.statusIds || []).map((id) => `Created exact-player Safeguard status ${id}`),
    persistentStateIds: resolution.statusIds || [],
    resultData: {
      createdStatusIds: resolution.statusIds || [],
      affectedPlayerIds: [targetPlayerId].filter(Boolean),
      protectionScope: resolution.protectionScope || []
    }
  };
}

function applyLingeringEffect(effectRecord) {
  state.lingeringStatuses ||= [];
  const record = {
    id: effectRecord.id || `status-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
    status: "active",
    sourceType: "token",
    series: state.series,
    gym: Number(state.gym),
    phase: currentPhase(),
    createdAt: new Date().toISOString(),
    payload: {},
    ...effectRecord
  };
  state.lingeringStatuses.push(record);
  return record;
}

function tokenPendingEventNegations(activity) {
  const rootPromptId = interactionRootPromptId(activity);
  return (activity?.responses || []).filter((response) => {
    if (interactionResponseCanceled(response) || interactionResponseAnswerPromptId(activity, response) !== rootPromptId) return false;
    const promptStepId = interactionResponsePromptStepId(response);
    const resolution = activity?.promptResolutions?.[promptStepId];
    if (resolution) return resolution.status === "resolved" && resolution.outcome === "negates-parent";
    return slugify(response.tokenName || "") === "immunity" || response.type === "immunity";
  });
}

function tokenEffectScopeForActivity(activity, metadata) {
  const draft = tokenDraftFromActivity(activity);
  const definition = statusTokenDefinitionByName(metadata.name);
  const applicationScope = activity?.payload?.applicationScope
    || metadata.applicationScope
    || (draft.targetScope === EFFECT_TARGET_SCOPES.SPECIES
      ? EFFECT_APPLICATION_SCOPES.GLOBAL_SPECIES
      : draft.targetScope === EFFECT_TARGET_SCOPES.ROSTER_INSTANCE
        ? EFFECT_APPLICATION_SCOPES.ROSTER_INSTANCE
        : EFFECT_APPLICATION_SCOPES.MANUAL);
  const targetPokemon = draft.targetPokemonId
    ? (state.pokemonRecords || []).find((pokemon) => pokemon.id === draft.targetPokemonId)
    : null;
  const speciesName = targetPokemon?.name || draft.targetPokemonName || draft.targetText || "";
  const selectedRosterInstanceIds = activity?.payload?.selectedRosterInstanceIds || [draft.targetPokemonId].filter(Boolean);
  const selectedRosterInstanceId = activity?.payload?.selectedRosterInstanceId || selectedRosterInstanceIds[0] || "";
  const selectedSpeciesId = activity?.payload?.selectedSpeciesId || pokemonRuleKey(speciesName);
  return {
    effectType: metadata.id === "extra-ban-token" ? "ban"
      : metadata.id === "restrict-token" ? "restrict"
        : metadata.id === "steal-token" ? "steal"
        : definition?.statusType || metadata.resolverId || metadata.id,
    selectedTargetType: activity?.payload?.selectedTargetType || metadata.selectedTargetType || draft.targetType,
    applicationScope,
    affectedEntityType: activity?.payload?.affectedEntityType || metadata.affectedEntityType || draft.targetType,
    speciesName,
    selectedRosterInstanceId,
    selectedSpeciesId,
    speciesId: selectedSpeciesId,
    targetPlayerId: draft.targetPlayerId || "",
    selectedRosterInstanceIds,
    affectedRosterInstanceIds: activity?.payload?.affectedRosterInstanceIds || [draft.targetPokemonId].filter(Boolean),
    excludedRosterInstanceIds: activity?.payload?.excludedRosterInstanceIds || [],
    substituteInterceptionPolicy: activity?.payload?.substituteInterceptionPolicy || metadata.substituteInterceptionPolicy || "",
    substituteChecksSelectedTargetOnly: activity?.payload?.substituteChecksSelectedTargetOnly ?? metadata.substituteChecksSelectedTargetOnly,
    sourceEffectId: activity?.id || "",
    sourcePlayerId: activity?.actorPlayerId || ""
  };
}

function applySubstituteInterceptionBeforeMutation(activity, metadata) {
  if (!controlTokenEffects?.interceptEffectWithSubstitute) return null;
  const scope = tokenEffectScopeForActivity(activity, metadata);
  if (scope.affectedEntityType !== EFFECT_TARGET_TYPES.POKEMON) return null;
  const interception = controlTokenEffects.interceptEffectWithSubstitute(state, scope, controlTokenEffectOptions());
  activity.payload ||= {};
  activity.payload.selectedTargetType = scope.selectedTargetType;
  activity.payload.applicationScope = scope.applicationScope;
  activity.payload.affectedEntityType = scope.affectedEntityType;
  activity.payload.selectedRosterInstanceId = scope.selectedRosterInstanceId;
  activity.payload.selectedSpeciesId = scope.selectedSpeciesId;
  activity.payload.speciesId = scope.speciesId;
  activity.payload.selectedRosterInstanceIds = scope.selectedRosterInstanceIds;
  activity.payload.affectedRosterInstanceIds = interception.affectedRosterInstanceIds || scope.affectedRosterInstanceIds;
  activity.payload.excludedRosterInstanceIds = interception.excludedRosterInstanceIds || scope.excludedRosterInstanceIds;
  activity.payload.substituteInterception = {
    result: interception.result,
    reason: interception.reason,
    negateEntireEffect: Boolean(interception.negateEntireEffect),
    consumedStatusIds: interception.consumedStatusIds || [],
    createdStatusIds: interception.createdStatusIds || [],
    rageImmuneRosterInstanceIds: interception.rageImmuneRosterInstanceIds || [],
    curseImmuneRosterInstanceIds: interception.curseImmuneRosterInstanceIds || []
  };
  return interception;
}

function createTokenActivationRecord({ consumedToken, metadata, draft, statusIds = [], details = [] }) {
  const selectedRosterInstanceIds = [draft.targetPokemonId].filter(Boolean);
  const selectedRosterInstanceId = draft.selectedRosterInstanceId || selectedRosterInstanceIds[0] || "";
  const selectedSpeciesId = draft.selectedSpeciesId || draft.speciesId || pokemonRuleKey(draft.targetPokemonName || draft.targetText || "");
  const activation = {
    id: `token-activation-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
    tokenId: consumedToken?.id || "",
    tokenName: consumedToken?.name || draft.tokenName,
    tokenDefinitionId: metadata.id,
    tokenCategory: metadata.timingCategory,
    objectType: metadata.objectType,
    family: metadata.family,
    activationPattern: metadata.activationPattern,
    persistence: metadata.persistence,
    resolverId: metadata.resolverId,
    actorPlayerId: draft.actorPlayerId,
    targetPlayerId: draft.targetPlayerId || "",
    targetPokemonIds: [draft.targetPokemonId].filter(Boolean),
    targetPokemonNames: [draft.targetPokemonName || draft.targetText].filter(Boolean),
    selectedTargetType: draft.selectedTargetType || metadata.selectedTargetType || draft.targetType || "",
    applicationScope: draft.applicationScope || metadata.applicationScope || "",
    affectedEntityType: draft.affectedEntityType || metadata.affectedEntityType || draft.targetType || "",
    selectedRosterInstanceId,
    selectedSpeciesId,
    speciesId: selectedSpeciesId,
    selectedRosterInstanceIds,
    affectedRosterInstanceIds: draft.affectedRosterInstanceIds || selectedRosterInstanceIds,
    excludedRosterInstanceIds: draft.excludedRosterInstanceIds || [],
    substituteInterceptionPolicy: draft.substituteInterceptionPolicy || metadata.substituteInterceptionPolicy || "",
    substituteChecksSelectedTargetOnly: draft.substituteChecksSelectedTargetOnly ?? metadata.substituteChecksSelectedTargetOnly,
    sourceEffectId: draft.sourceEffectId || "",
    sourcePlayerId: draft.actorPlayerId || "",
    statusIds,
    series: state.series,
    gym: Number(state.gym),
    phase: currentPhase(),
    details,
    createdAt: new Date().toISOString()
  };
  state.tokenActivations ||= [];
  state.tokenActivations.unshift(activation);
  return activation;
}

function tokenUseRollbackSnapshot() {
  return {
    previousPlayers: structuredClone(state.players || []),
    previousPokemonRecords: structuredClone(state.pokemonRecords || []),
    previousPokemonLog: structuredClone(state.pokemonLog || []),
    previousLingeringStatuses: structuredClone(state.lingeringStatuses || []),
    previousTokenActivations: structuredClone(state.tokenActivations || []),
    previousTokenConsumptions: structuredClone(state.tokenConsumptions || []),
    previousPlayerNotifications: structuredClone(state.playerNotifications || []),
    previousWheelSessions: structuredClone(state.wheelSessions || []),
    previousRandomPokemonSessions: structuredClone(state.randomPokemonSessions || []),
    previousInteractionEvents: structuredClone(state.interactionEvents || []),
    previousTransactions: structuredClone(state.transactions || []),
    previousGlobalPokemonRules: structuredClone(state.globalPokemonRules || {}),
    previousBanlistHistory: structuredClone(state.banlistHistory || []),
    previousTeambuilder: structuredClone(state.teambuilder || {}),
    previousBattleTeams: structuredClone(state.battleTeams || {}),
    previousPerkSystem: structuredClone(state.perkSystem || {}),
    previousClassStateByPlayerId: structuredClone(state.classStateByPlayerId || {}),
    previousPhaseState: structuredClone(state.phaseState || {}),
    previousEffectAuditRecords: structuredClone(state.effectAuditRecords || []),
    previousEffectOperations: structuredClone(state.effectOperations || []),
    previousDelayedEffects: structuredClone(state.delayedEffects || []),
    previousBroughtTeamSnapshots: structuredClone(state.broughtTeamSnapshots || []),
    previousCopiedActivations: structuredClone(state.copiedActivations || []),
    previousPostPayoutProcedures: structuredClone(state.postPayoutProcedures || []),
    previousEndOfActionProcedures: structuredClone(state.endOfActionProcedures || []),
    previousCopiedTokenRelationships: structuredClone(state.copiedTokenRelationships || []),
    previousPrivateEffectRecords: structuredClone(state.privateEffectRecords || []),
    previousEncounterCopyRecords: structuredClone(state.encounterCopyRecords || [])
  };
}

function tokenEffectAuditRecord({
  stage = "declaration",
  activity = null,
  response = null,
  draft = {},
  metadata = tokenEffectMetadataByName(draft.tokenName || activity?.payload?.tokenName || response?.tokenName || ""),
  result = "pending",
  mutations = [],
  persistentStateIds = [],
  hostConfirmation = "",
  undoLogId = ""
} = {}) {
  const tokenName = draft.tokenName || activity?.payload?.tokenName || response?.tokenName || metadata.name || "Token";
  const actorPlayerId = draft.actorPlayerId || response?.playerId || activity?.actorPlayerId || "";
  const promptId = response?.respondingToPromptId || activity && interactionRootPromptId(activity) || "";
  const record = {
    id: `effect-audit-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
    effectId: activity?.id || response?.id || `immediate:${Date.now()}`,
    tokenDefinitionId: metadata.id || slugify(tokenName),
    tokenId: draft.consumedTokenId || response?.tokenId || activity?.payload?.consumedTokenId || "",
    tokenName,
    stage,
    userPlayerId: actorPlayerId,
    originalOwnerPlayerId: actorPlayerId,
    timestamp: new Date().toISOString(),
    series: state.series,
    gym: Number(state.gym),
    phase: currentPhase(),
    timingWindow: tokenTimingWindowsForContext({ pendingEvent: activity || getCurrentPendingEvent() }),
    targets: {
      playerId: draft.targetPlayerId || response?.targetPlayerId || activity?.targetPlayerId || "",
      pokemonId: draft.targetPokemonId || response?.targetPokemonId || activity?.payload?.targetPokemonId || "",
      text: tokenUseTargetLabel(draft) || response?.targetText || activity?.payload?.targetText || "",
      selectedTargetType: draft.selectedTargetType || activity?.payload?.selectedTargetType || metadata.selectedTargetType || "",
      applicationScope: draft.applicationScope || activity?.payload?.applicationScope || metadata.applicationScope || "",
      affectedEntityType: draft.affectedEntityType || activity?.payload?.affectedEntityType || metadata.affectedEntityType || "",
      selectedRosterInstanceId: draft.selectedRosterInstanceId || activity?.payload?.selectedRosterInstanceId || "",
      selectedSpeciesId: draft.selectedSpeciesId || activity?.payload?.selectedSpeciesId || "",
      speciesId: draft.speciesId || activity?.payload?.speciesId || "",
      selectedRosterInstanceIds: draft.selectedRosterInstanceIds || activity?.payload?.selectedRosterInstanceIds || [],
      affectedRosterInstanceIds: draft.affectedRosterInstanceIds || activity?.payload?.affectedRosterInstanceIds || [],
      excludedRosterInstanceIds: draft.excludedRosterInstanceIds || activity?.payload?.excludedRosterInstanceIds || [],
      substituteInterceptionPolicy: draft.substituteInterceptionPolicy || activity?.payload?.substituteInterceptionPolicy || metadata.substituteInterceptionPolicy || "",
      substituteChecksSelectedTargetOnly: draft.substituteChecksSelectedTargetOnly ?? activity?.payload?.substituteChecksSelectedTargetOnly ?? metadata.substituteChecksSelectedTargetOnly
    },
    requiredChoices: metadata.requiredChoices || [],
    choices: draft.notes || response?.resolutionText || activity?.payload?.resolutionResultText || "",
    tokenConsumed: Boolean(draft.consumedTokenId || response?.tokenId || activity?.payload?.consumedTokenId),
    declarationCosts: metadata.declarationCost || "Consume 1 Token",
    responseIds: (activity?.responses || []).map((entry) => entry.id),
    passOrder: (activity?.responses || []).filter((entry) => entry.type === "pass").map((entry) => entry.playerId),
    resolverMode: metadata.resolutionMode,
    resolutionResult: result,
    stateMutations: mutations,
    persistentStateIds,
    parentEffectId: response?.respondingToPromptId || "",
    childEffectIds: (activity?.responses || []).map((entry) => entry.id),
    hostConfirmation,
    undoLogId,
    undoStatus: "available",
    testData: Boolean(state.testingTools?.activeScenario)
  };
  state.effectAuditRecords ||= [];
  state.effectAuditRecords.unshift(record);
  return record;
}

async function resolveImmediateTokenUse(draft, { context = {} } = {}) {
  const metadata = tokenEffectMetadataByName(draft.tokenName);
  if (metadata.resolverId === "extraEncounter") {
    alert("Extra Encounter is used from the current Route action. Open Routes and use the Token on the Route you want to explore.");
    return null;
  }
  const timingCheck = tokenUseTimingCheck({ player: draft.actor, tokenName: draft.tokenName, metadata, context });
  if (!timingCheck.ok) {
    alert(timingCheck.reason);
    return null;
  }
  if (metadata.id === "substitute") {
    const legality = controlTokenDraftLegality(draft, metadata);
    if (!legality.ok) {
      alert(legality.reason);
      return null;
    }
  }
  if (metadata.resolverId === "substituteAttach") {
    const targetPokemon = (state.pokemonRecords || []).find((pokemon) => pokemon.id === draft.targetPokemonId);
    if (!targetPokemon || targetPokemon.trainerId !== draft.actorPlayerId || ["Released", "Removed"].includes(targetPokemon.status)) {
      alert("Choose a specific Pokemon owned by the acting player for Substitute.");
      return null;
    }
    const activeSubstitute = (state.lingeringStatuses || []).some((status) => status.status === "active"
      && status.type === "substitute-attached"
      && status.targetPokemonId === targetPokemon.id);
    if (activeSubstitute) {
      alert(`${targetPokemon.name} already has a Substitute.`);
      return null;
    }
  }
  const rollbackSnapshot = tokenUseRollbackSnapshot();
  const consumed = metadata.consumesOnLegalUse
    ? consumeTokenForEffect({
      player: draft.actor,
      tokenName: draft.tokenName,
      metadata,
      source: "token-engine-v1"
    })
    : { token: null, consumption: null };
  if (metadata.consumesOnLegalUse && !consumed?.token) {
    alert(`${draft.actor.name} does not have ${draft.tokenName}.`);
    return null;
  }
  const consumedToken = consumed?.token || { id: "", name: draft.tokenName };
  const now = new Date().toISOString();
  const details = [
    `Token: ${consumedToken.name || draft.tokenName}`,
    `Timing: ${(timingCheck.windows || []).join(", ") || "manual"}`,
    `Pattern: ${metadata.activationPattern || "manual"}`
  ];
  const statusIds = [];
  let result = "resolved";
  if (metadata.resolverId === "safeguard") {
    const expires = statusExpiresAt(1);
    const status = applyLingeringEffect({
      type: "safeguard",
      name: "Safeguard",
      category: TOKEN_TIMING_CATEGORIES.PROTECTION,
      isCurse: false,
      sourceTokenId: consumedToken.id || "",
      sourceTokenName: consumedToken.name || draft.tokenName,
      actorPlayerId: draft.actorPlayerId,
      actorPlayerName: draft.actor?.name || "",
      targetPlayerId: draft.actorPlayerId,
      targetPlayerName: draft.actor?.name || "",
      duration: metadata.duration,
      durationGyms: 1,
      expiresAtSeries: expires.expiresAtSeries,
      expiresAtGym: expires.expiresAtGym,
      payload: { protectionScope: metadata.protectionScope },
      note: "Money and Tokens cannot be stolen, destroyed, or copied. Follow Me and Embargo do not affect this player.",
      createdAt: now
    });
    statusIds.push(status.id);
    details.push("Created lingering Safeguard protection.");
    result = "lingering-protection-created";
  } else if (metadata.resolverId === "substituteAttach") {
    const targetPokemon = (state.pokemonRecords || []).find((pokemon) => pokemon.id === draft.targetPokemonId);
    const expires = statusExpiresAt(1);
    const placement = controlTokenEffects?.resolveSubstitutePlacement(state, {
      sourceTokenId: consumedToken.id || "",
      sourceTokenName: consumedToken.name || draft.tokenName,
      actorPlayerId: draft.actorPlayerId,
      actorPlayerName: draft.actor?.name || "",
      targetPokemonId: targetPokemon.id,
      requiredOwnerPlayerId: draft.actorPlayerId,
      duration: metadata.duration,
      durationGyms: 1,
      expiresAtSeries: expires.expiresAtSeries,
      expiresAtGym: expires.expiresAtGym,
      sourceEffectId: `substitute-placement-${Date.now()}`
    }, controlTokenEffectOptions(now));
    if (!placement || placement.result !== "resolved") {
      alert(placement?.reason || "Substitute could not be attached.");
      return null;
    }
    statusIds.push(...placement.statusIds);
    details.push(placement.reason);
    result = "attached-protection-created";
  } else {
    details.push(metadata.shortPromptText || "Token use recorded. Effect application is manual.");
    result = "manual-required";
  }
  const activation = createTokenActivationRecord({ consumedToken, metadata, draft, statusIds, details });
  const targetLabel = tokenUseTargetLabel(draft);
  const resolutionAudit = tokenEffectAuditRecord({
    stage: "resolution",
    draft: { ...draft, consumedTokenId: consumedToken.id || "" },
    metadata,
    result: result === "manual-required" ? "noEffect" : "resolved",
    mutations: details,
    persistentStateIds: [...statusIds].filter(Boolean)
  });
  const resolutionLog = addLogEntry({
    action: "token",
    category: "tokens",
    player: draft.actor?.name || "Table",
    item: `${draft.actor?.name || "A player"} used ${consumedToken.name || draft.tokenName}${targetLabel ? ` on ${targetLabel}` : ""}.`,
    title: `${draft.actor?.name || "A player"} used ${consumedToken.name || draft.tokenName}`,
    summary: details.join("\n"),
    details,
    type: "token-engine-v1",
    categories: ["tokens", metadata.timingCategory, metadata.persistence, metadata.objectType].filter(Boolean),
    tags: ["token-engine-v1", metadata.resolverId, ...(metadata.family || []), consumedToken.name || draft.tokenName].filter(Boolean),
    playerIds: [draft.actorPlayerId, draft.targetPlayerId].filter(Boolean),
    tokenNames: [consumedToken.name || draft.tokenName],
    tokenId: consumedToken.id || "",
    tokenActivationId: activation.id,
    encounterSessionId,
    effectAuditId: resolutionAudit.id,
    tokenConsumptionIds: consumed?.consumption ? [consumed.consumption.id] : [],
    statusIds,
    tokenUse: {
      tokenName: consumedToken.name || draft.tokenName,
      actorId: draft.actorPlayerId,
      sourceTokenId: consumedToken.id || "",
      timingWindow: timingCheck.windows,
      activationPattern: metadata.activationPattern,
      target: targetLabel,
      result,
      consumed: Boolean(consumed?.token),
      blocked: false,
      createdEffectId: statusIds[0] || "",
      pendingEventId: "",
      timestamp: now
    },
    undoable: true,
    undone: false,
    undoData: {
      actionType: "undoUtilityTokenActivation",
      activationId: activation.id,
      ...rollbackSnapshot
    }
  });
  resolutionAudit.undoLogId = resolutionLog?.id || "";
  const outcomeTitle = metadata.resolverId === "safeguard"
      ? "Safeguard active."
      : metadata.resolverId === "substituteAttach"
        ? "Substitute attached."
        : `${consumedToken.name || draft.tokenName} resolved.`;
  const immediateActivity = {
    id: activation.id,
    title: consumedToken.name || draft.tokenName,
    actorPlayerId: draft.actorPlayerId,
    targetPlayerId: draft.targetPlayerId || findPokemonRecord(draft.targetPokemonId)?.trainerId || "",
    responses: [],
    payload: {
      tokenName: consumedToken.name || draft.tokenName,
      targetPlayerId: draft.targetPlayerId || findPokemonRecord(draft.targetPokemonId)?.trainerId || "",
      targetPokemonId: draft.targetPokemonId || "",
      targetPokemonName: draft.targetPokemonName || "",
      selectedTargetType: draft.selectedTargetType || metadata.selectedTargetType || draft.targetType || "",
      selectedRosterInstanceId: draft.selectedRosterInstanceId || draft.targetPokemonId || "",
      selectedSpeciesId: draft.selectedSpeciesId || draft.speciesId || "",
      applicationScope: draft.applicationScope || metadata.applicationScope || ""
    }
  };
  const immediateSummary = tokenResultSummary?.buildResultSummary?.({
    state,
    activity: immediateActivity,
    finalOutcome: result === "manual-required" ? "resolvedNoEffect" : "resolved",
    resultData: {
      createdStatusIds: statusIds,
      affectedRosterInstanceIds: [draft.targetPokemonId].filter(Boolean),
      consumedTokenRecords: consumed?.consumption ? [consumed.consumption] : [],
      operations: []
    },
    continuation: details.slice(-2).join(" ")
  });
  const immediatePresentation = immediateSummary && tokenResultSummary?.announcementForResult
    ? tokenResultSummary.announcementForResult(immediateSummary, state)
    : { title: outcomeTitle, detail: details.slice(-2).join(" "), tone: result === "manual-required" ? "manual" : "resolved" };
  queueLiveResolutionAnnouncement({
    id: `resolution:${activation.id}`,
    ...immediatePresentation,
    linkedEventId: "",
    resultSummary: immediateSummary
  });
  syncPlayerPokemonLists();
  saveState({ immediate: true });
  render();
  return activation;
}

function resolveDittoInventoryCopyUse(draft, metadata) {
  const legality = controlTokenDraftLegality(draft, metadata);
  if (!legality.ok) { alert(legality.reason); return null; }
  const definition = globalThis.rivalSagaTokenEffectContract?.definitionFor?.(draft.resourceDefinitionId || "");
  const undo = tokenUseRollbackSnapshot();
  const consumed = consumeTokenForEffect({ player: draft.actor, tokenName: draft.tokenName, metadata, source: "ditto-transform" });
  if (!consumed?.token) { alert(`${draft.actor.name} does not have ${draft.tokenName}.`); return null; }
  const sourceEffectId = `ditto:${consumed.consumption?.id || consumed.token.id}`;
  const result = controlTokenEffects.createCanonicalTokenInventoryCopy(state, {
    ownerPlayerId: draft.actorPlayerId, definition, sourceEffectId,
    sourceInventoryRecordId: consumed.token.id, sourcePlayerId: draft.actorPlayerId, copySourceType: "ditto"
  }, { ...controlTokenEffectOptions(), definitionFor: (value) => globalThis.rivalSagaTokenEffectContract?.definitionFor?.(value) || null });
  if (result.result !== "resolved") {
    restoreTokenEffectContractUndoData(undo);
    alert(result.reason);
    return null;
  }
  addLogEntry({
    action: "token", category: "tokens", player: draft.actor.name,
    item: `${draft.actor.name}'s Ditto became ${definition.name}.`, title: "Ditto transformed",
    summary: `Created one canonical ${definition.name} inventory copy. It was not activated.`,
    type: "ditto-token-copy", categories: ["tokens"], tags: ["ditto", "inventory-copy"],
    playerIds: [draft.actorPlayerId], tokenNames: ["Ditto", definition.name], undoable: true, undone: false,
    undoData: { actionType: "undoTokenEffectContract", ...undo }
  });
  resetLiveRefereeScreenState();
  saveState({ immediate: true });
  render();
  return result;
}

async function resolveTokenUse(draft, { context = {} } = {}) {
  if (!draft?.actor) {
    alert("Choose a player before using this token.");
    return null;
  }
  const metadata = tokenEffectMetadataByName(draft.tokenName);
  const pendingEvent = context.pendingEvent || getCurrentPendingEvent();
  const timingCheck = tokenUseTimingCheck({ player: draft.actor, tokenName: draft.tokenName, metadata, context: { ...context, pendingEvent } });
  if (!timingCheck.ok) {
    alert(timingCheck.reason);
    return null;
  }
  if (pendingEvent) {
    if (metadata.timingWindows.includes(TOKEN_TIMING_WINDOWS.WHEEL_WINDOW) || metadata.timingCategory === TOKEN_TIMING_CATEGORIES.ENCOUNTER) {
      return recordEncounterTokenUse(draft);
    }
    if (metadata.activationPattern === TOKEN_ACTIVATION_PATTERNS.RESPONSE || metadata.timingCategory === TOKEN_TIMING_CATEGORIES.PROTECTION) {
      return recordProtectionTokenUse(draft);
    }
    alert(`${metadata.name || draft.tokenName} is not a response to the current prompt.`);
    return null;
  }
  if (metadata.id === "ditto-token") return resolveDittoInventoryCopyUse(draft, metadata);
  if (metadata.canOpenPendingEvent || metadata.createsPendingEvent || [TOKEN_TIMING_CATEGORIES.CONTROL, TOKEN_TIMING_CATEGORIES.CURSE].includes(metadata.timingCategory)) {
    return createTokenPendingEventFromUse(draft);
  }
  return resolveImmediateTokenUse(draft, { context });
}

function tokenDraftFromActivity(activity, resolutionText = "") {
  const actor = state.players.find((player) => player.id === activity?.actorPlayerId);
  const target = state.players.find((player) => player.id === activity?.targetPlayerId);
  return {
    actor,
    target,
    actorPlayerId: actor?.id || activity?.actorPlayerId || "",
    targetPlayerId: target?.id || activity?.targetPlayerId || "",
    targetPlayerName: target?.name || activity?.payload?.targetPlayerName || "",
    targetPokemonId: activity?.payload?.targetPokemonId || "",
    targetPokemonName: activity?.payload?.targetPokemonName || "",
    targetText: activity?.payload?.targetText || "",
    tokenName: activity?.payload?.tokenName || "",
    category: tokenTimingCategoryFromRaw(activity?.payload?.tokenTimingCategory),
    targetType: activity?.payload?.targetType || "",
    targetScope: activity?.payload?.targetScope || "",
    selectedTargetType: activity?.payload?.selectedTargetType || "",
    applicationScope: activity?.payload?.applicationScope || "",
    affectedEntityType: activity?.payload?.affectedEntityType || "",
    selectedRosterInstanceId: activity?.payload?.selectedRosterInstanceId || "",
    selectedStatusId: activity?.payload?.selectedStatusId || "",
    selectedSpeciesId: activity?.payload?.selectedSpeciesId || "",
    speciesId: activity?.payload?.speciesId || "",
    selectedRosterInstanceIds: activity?.payload?.selectedRosterInstanceIds || [],
    affectedRosterInstanceIds: activity?.payload?.affectedRosterInstanceIds || [],
    excludedRosterInstanceIds: activity?.payload?.excludedRosterInstanceIds || [],
    resourceSelections: activity?.payload?.resourceSelections || [],
    substituteInterceptionPolicy: activity?.payload?.substituteInterceptionPolicy || "",
    substituteChecksSelectedTargetOnly: activity?.payload?.substituteChecksSelectedTargetOnly,
    sourceEffectId: activity?.id || "",
    notes: resolutionText
  };
}

function causalIdCollectionDelta(previous = [], current = []) {
  const before = new Map((previous || []).filter((entry) => entry?.id).map((entry) => [entry.id, entry]));
  const after = new Map((current || []).filter((entry) => entry?.id).map((entry) => [entry.id, entry]));
  return {
    createdIds: [...after.keys()].filter((id) => !before.has(id)),
    previousRecords: [...before.entries()]
      .filter(([id]) => !after.has(id))
      .map(([, record]) => structuredClone(record)),
    changedRecords: [...before.entries()]
      .filter(([id, record]) => after.has(id) && JSON.stringify(record) !== JSON.stringify(after.get(id)))
      .map(([id, record]) => ({
        id,
        fields: causalTopLevelFieldDelta(record, after.get(id))
      }))
  };
}

function causalTopLevelFieldDelta(previous = {}, current = {}, ignoredKeys = []) {
  const ignored = new Set(ignoredKeys || []);
  return [...new Set([...Object.keys(previous || {}), ...Object.keys(current || {})])]
    .filter((key) => !ignored.has(key) && JSON.stringify(previous?.[key]) !== JSON.stringify(current?.[key]))
    .map((key) => ({
      key,
      previousExists: Object.prototype.hasOwnProperty.call(previous || {}, key),
      previous: structuredClone(previous?.[key]),
      appliedExists: Object.prototype.hasOwnProperty.call(current || {}, key),
      applied: structuredClone(current?.[key])
    }));
}

function causalScalarSetDelta(previous = [], current = []) {
  const before = new Set(previous || []);
  const after = new Set(current || []);
  return {
    added: [...after].filter((value) => !before.has(value)),
    removed: [...before].filter((value) => !after.has(value))
  };
}

function mergeCausalIdCollectionDelta(base = {}, later = {}) {
  const createdIds = [...new Set([...(base.createdIds || []), ...(later.createdIds || [])])];
  const created = new Set(createdIds);
  const previousById = new Map((base.previousRecords || []).map((record) => [record.id, structuredClone(record)]));
  (later.previousRecords || []).forEach((record) => {
    if (!created.has(record.id) && !previousById.has(record.id)) previousById.set(record.id, structuredClone(record));
  });
  const changedById = new Map((base.changedRecords || []).map((entry) => [entry.id, structuredClone(entry)]));
  (later.changedRecords || []).forEach((entry) => {
    if (created.has(entry.id) || previousById.has(entry.id)) return;
    const existing = changedById.get(entry.id);
    if (!existing) {
      changedById.set(entry.id, structuredClone(entry));
      return;
    }
    const fieldsByKey = new Map((existing.fields || []).map((field) => [field.key, field]));
    (entry.fields || []).forEach((field) => {
      if (!fieldsByKey.has(field.key)) fieldsByKey.set(field.key, structuredClone(field));
      else fieldsByKey.get(field.key).applied = structuredClone(field.applied);
    });
    existing.fields = [...fieldsByKey.values()];
  });
  return { createdIds, previousRecords: [...previousById.values()], changedRecords: [...changedById.values()] };
}

function mergeCausalScalarSetDelta(base = {}, later = {}) {
  const added = new Set(base.added || []);
  const removed = new Set(base.removed || []);
  (later.added || []).forEach((value) => removed.delete(value) || added.add(value));
  (later.removed || []).forEach((value) => added.delete(value) || removed.add(value));
  return { added: [...added], removed: [...removed] };
}

function causalPlayerCollectionDeltas(previousPlayers = [], currentPlayers = [], field = "inventory") {
  const currentById = new Map((currentPlayers || []).map((player) => [player.id, player]));
  return (previousPlayers || []).map((player) => ({
    playerId: player.id,
    delta: causalIdCollectionDelta(player[field] || [], currentById.get(player.id)?.[field] || [])
  })).filter((entry) => entry.delta.createdIds.length || entry.delta.previousRecords.length || entry.delta.changedRecords.length);
}

function causalGrantMapDeltas(previousMap = {}, currentMap = {}) {
  return [...new Set([...Object.keys(previousMap || {}), ...Object.keys(currentMap || {})])].map((playerId) => ({
    playerId,
    delta: causalIdCollectionDelta(previousMap?.[playerId] || [], currentMap?.[playerId] || [])
  })).filter((entry) => entry.delta.createdIds.length || entry.delta.previousRecords.length || entry.delta.changedRecords.length);
}

function buildCausalTokenEffectUndo(snapshot, activity, metadata) {
  const previousPokemonById = new Map((snapshot.previousPokemonRecords || []).map((pokemon) => [pokemon.id, pokemon]));
  const pokemonDeltas = (state.pokemonRecords || []).map((pokemon) => {
    const previous = previousPokemonById.get(pokemon.id);
    if (!previous) return null;
    const effectBuffs = causalIdCollectionDelta(previous.effectBuffs || [], pokemon.effectBuffs || []);
    const logs = causalIdCollectionDelta(previous.log || [], pokemon.log || []);
    const beforeLabels = new Set(previous.buffs || []);
    const afterLabels = new Set(pokemon.buffs || []);
    const labelsAdded = [...afterLabels].filter((label) => !beforeLabels.has(label));
    const labelsRemoved = [...beforeLabels].filter((label) => !afterLabels.has(label));
    if (!effectBuffs.createdIds.length && !effectBuffs.previousRecords.length && !logs.createdIds.length
      && !logs.previousRecords.length && !labelsAdded.length && !labelsRemoved.length) return null;
    return { pokemonId: pokemon.id, effectBuffs, logs, labelsAdded, labelsRemoved, previousLabelOrder: structuredClone(previous.buffs || []) };
  }).filter(Boolean);
  const previousRules = snapshot.previousGlobalPokemonRules || {};
  const currentRules = state.globalPokemonRules || {};
  const ruleDeltas = [...new Set([...Object.keys(previousRules), ...Object.keys(currentRules)])]
    .filter((key) => JSON.stringify(previousRules[key]) !== JSON.stringify(currentRules[key]))
    .map((key) => ({ key, existed: Object.prototype.hasOwnProperty.call(previousRules, key), previous: structuredClone(previousRules[key] || null) }));
  const currentPlayersById = new Map((state.players || []).map((player) => [player.id, player]));
  const playerBalanceDeltas = (snapshot.previousPlayers || []).map((player) => ({
    playerId: player.id,
    amount: Number(currentPlayersById.get(player.id)?.balance || 0) - Number(player.balance || 0)
  })).filter((entry) => entry.amount !== 0);
  const currentPokemonIdsByPlayer = new Map((state.players || []).map((player) => [player.id, player.pokemonIds || []]));
  const playerPokemonIdDeltas = (snapshot.previousPlayers || []).map((player) => ({
    playerId: player.id,
    delta: causalScalarSetDelta(player.pokemonIds || [], currentPokemonIdsByPlayer.get(player.id) || [])
  })).filter((entry) => entry.delta.added.length || entry.delta.removed.length);
  return {
    actionType: "undoTokenEffectContractCausal",
    causalUndoVersion: 1,
    effectId: activity.id,
    tokenDefinitionId: metadata.id,
    inventoryByPlayer: causalPlayerCollectionDeltas(snapshot.previousPlayers, state.players, "inventory"),
    playerBalanceDeltas,
    moveGrantsByPlayer: causalPlayerCollectionDeltas(snapshot.previousPlayers, state.players, "moveAccessGrants"),
    playerPokemonIdDeltas,
    pokemonRecords: causalIdCollectionDelta(snapshot.previousPokemonRecords, state.pokemonRecords),
    statuses: causalIdCollectionDelta(snapshot.previousLingeringStatuses, state.lingeringStatuses),
    activations: causalIdCollectionDelta(snapshot.previousTokenActivations, state.tokenActivations),
    consumptions: causalIdCollectionDelta(snapshot.previousTokenConsumptions, state.tokenConsumptions),
    transactions: causalIdCollectionDelta(snapshot.previousTransactions, state.transactions),
    notifications: causalIdCollectionDelta(snapshot.previousPlayerNotifications, state.playerNotifications),
    effectOperations: causalIdCollectionDelta(snapshot.previousEffectOperations, state.effectOperations),
    copiedActivations: causalIdCollectionDelta(snapshot.previousCopiedActivations, state.copiedActivations),
    copiedTokenRelationships: causalIdCollectionDelta(snapshot.previousCopiedTokenRelationships, state.copiedTokenRelationships),
    wheelSessions: causalIdCollectionDelta(snapshot.previousWheelSessions, state.wheelSessions),
    randomPokemonSessions: causalIdCollectionDelta(snapshot.previousRandomPokemonSessions, state.randomPokemonSessions),
    delayedEffects: causalIdCollectionDelta(snapshot.previousDelayedEffects, state.delayedEffects),
    broughtTeamSnapshots: causalIdCollectionDelta(snapshot.previousBroughtTeamSnapshots, state.broughtTeamSnapshots),
    postPayoutProcedures: causalIdCollectionDelta(snapshot.previousPostPayoutProcedures, state.postPayoutProcedures),
    encounterCopyRecords: causalIdCollectionDelta(snapshot.previousEncounterCopyRecords, state.encounterCopyRecords),
    teambuilderFields: causalTopLevelFieldDelta(snapshot.previousTeambuilder || {}, state.teambuilder || {}, ["moveAccessGrantsByPlayerId"]),
    battleTeamFields: causalTopLevelFieldDelta(snapshot.previousBattleTeams || {}, state.battleTeams || {}),
    pokemonDeltas,
    pokemonLog: causalIdCollectionDelta(snapshot.previousPokemonLog || [], state.pokemonLog || []),
    teambuilderMoveGrants: causalGrantMapDeltas(snapshot.previousTeambuilder?.moveAccessGrantsByPlayerId, state.teambuilder?.moveAccessGrantsByPlayerId),
    perkMoveGrants: causalGrantMapDeltas(snapshot.previousPerkSystem?.moveAccessGrantsByPlayerId, state.perkSystem?.moveAccessGrantsByPlayerId),
    classMoveGrants: causalGrantMapDeltas(
      Object.fromEntries(Object.entries(snapshot.previousClassStateByPlayerId || {}).map(([id, value]) => [id, value?.moveAccessGrants || []])),
      Object.fromEntries(Object.entries(state.classStateByPlayerId || {}).map(([id, value]) => [id, value?.moveAccessGrants || []]))
    ),
    ruleDeltas,
    banlistHistory: causalIdCollectionDelta(snapshot.previousBanlistHistory, state.banlistHistory)
  };
}

function mergeCausalTokenUndoData(base = {}, later = {}) {
  const merged = structuredClone(base || {});
  const collectionKeys = [
    "pokemonRecords", "statuses", "activations", "consumptions", "transactions", "notifications",
    "effectOperations", "copiedActivations", "copiedTokenRelationships", "wheelSessions",
    "randomPokemonSessions", "delayedEffects", "broughtTeamSnapshots", "postPayoutProcedures",
    "encounterCopyRecords", "pokemonLog", "banlistHistory"
  ];
  collectionKeys.forEach((key) => {
    merged[key] = mergeCausalIdCollectionDelta(merged[key], later[key]);
  });
  const mergePlayerDeltas = (key) => {
    const byPlayer = new Map((merged[key] || []).map((entry) => [entry.playerId, structuredClone(entry)]));
    (later[key] || []).forEach((entry) => {
      if (!byPlayer.has(entry.playerId)) byPlayer.set(entry.playerId, structuredClone(entry));
      else byPlayer.get(entry.playerId).delta = mergeCausalIdCollectionDelta(byPlayer.get(entry.playerId).delta, entry.delta);
    });
    merged[key] = [...byPlayer.values()];
  };
  ["inventoryByPlayer", "moveGrantsByPlayer", "teambuilderMoveGrants", "perkMoveGrants", "classMoveGrants"].forEach(mergePlayerDeltas);
  const pokemonIdsByPlayer = new Map((merged.playerPokemonIdDeltas || []).map((entry) => [entry.playerId, structuredClone(entry)]));
  (later.playerPokemonIdDeltas || []).forEach((entry) => {
    if (!pokemonIdsByPlayer.has(entry.playerId)) pokemonIdsByPlayer.set(entry.playerId, structuredClone(entry));
    else pokemonIdsByPlayer.get(entry.playerId).delta = mergeCausalScalarSetDelta(pokemonIdsByPlayer.get(entry.playerId).delta, entry.delta);
  });
  merged.playerPokemonIdDeltas = [...pokemonIdsByPlayer.values()];
  const mergeFields = (baseFields = [], laterFields = []) => {
    const byKey = new Map((baseFields || []).map((field) => [field.key, structuredClone(field)]));
    (laterFields || []).forEach((field) => {
      if (!byKey.has(field.key)) byKey.set(field.key, structuredClone(field));
      else {
        byKey.get(field.key).appliedExists = field.appliedExists;
        byKey.get(field.key).applied = structuredClone(field.applied);
      }
    });
    return [...byKey.values()];
  };
  merged.teambuilderFields = mergeFields(merged.teambuilderFields, later.teambuilderFields);
  merged.battleTeamFields = mergeFields(merged.battleTeamFields, later.battleTeamFields);
  merged.pokemonDeltas = [...(merged.pokemonDeltas || []), ...(later.pokemonDeltas || [])];
  merged.ruleDeltas = [...(merged.ruleDeltas || []), ...(later.ruleDeltas || []).filter((entry) => !(merged.ruleDeltas || []).some((current) => current.key === entry.key))];
  return merged;
}

function applyCausalIdCollectionUndo(collection = [], delta = {}) {
  const createdIds = new Set(delta.createdIds || []);
  const next = (collection || []).filter((entry) => !createdIds.has(entry?.id));
  (delta.previousRecords || []).forEach((record) => {
    const index = next.findIndex((entry) => entry?.id === record.id);
    if (index >= 0) next[index] = structuredClone(record);
    else next.push(structuredClone(record));
  });
  (delta.changedRecords || []).forEach(({ id, fields }) => {
    const record = next.find((entry) => entry?.id === id);
    if (!record) return;
    (fields || []).forEach((field) => {
      const currentExists = Object.prototype.hasOwnProperty.call(record, field.key);
      if (currentExists !== Boolean(field.appliedExists) || JSON.stringify(record[field.key]) !== JSON.stringify(field.applied)) return;
      if (field.previousExists) record[field.key] = structuredClone(field.previous);
      else delete record[field.key];
    });
  });
  return next;
}

function applyCausalScalarSetUndo(collection = [], delta = {}) {
  const added = new Set(delta.added || []);
  const next = (collection || []).filter((value) => !added.has(value));
  (delta.removed || []).forEach((value) => {
    if (!next.includes(value)) next.push(value);
  });
  return next;
}

function applyCausalTopLevelFieldUndo(target = {}, fields = []) {
  (fields || []).forEach((field) => {
    const currentExists = Object.prototype.hasOwnProperty.call(target, field.key);
    if (currentExists !== Boolean(field.appliedExists) || JSON.stringify(target[field.key]) !== JSON.stringify(field.applied)) return;
    if (field.previousExists) target[field.key] = structuredClone(field.previous);
    else delete target[field.key];
  });
  return target;
}

function restoreCausalTokenEffectUndoData(undoData) {
  (undoData.inventoryByPlayer || []).forEach(({ playerId, delta }) => {
    const player = state.players.find((entry) => entry.id === playerId);
    if (player) player.inventory = applyCausalIdCollectionUndo(player.inventory, delta);
  });
  (undoData.playerBalanceDeltas || []).forEach(({ playerId, amount }) => {
    const player = state.players.find((entry) => entry.id === playerId);
    if (player) player.balance = Number(player.balance || 0) - Number(amount || 0);
  });
  (undoData.moveGrantsByPlayer || []).forEach(({ playerId, delta }) => {
    const player = state.players.find((entry) => entry.id === playerId);
    if (player) player.moveAccessGrants = applyCausalIdCollectionUndo(player.moveAccessGrants, delta);
  });
  (undoData.playerPokemonIdDeltas || []).forEach(({ playerId, delta }) => {
    const player = state.players.find((entry) => entry.id === playerId);
    if (player) player.pokemonIds = applyCausalScalarSetUndo(player.pokemonIds, delta);
  });
  state.pokemonRecords = applyCausalIdCollectionUndo(state.pokemonRecords, undoData.pokemonRecords);
  state.lingeringStatuses = applyCausalIdCollectionUndo(state.lingeringStatuses, undoData.statuses);
  state.tokenActivations = applyCausalIdCollectionUndo(state.tokenActivations, undoData.activations);
  state.tokenConsumptions = applyCausalIdCollectionUndo(state.tokenConsumptions, undoData.consumptions);
  state.transactions = applyCausalIdCollectionUndo(state.transactions, undoData.transactions);
  state.playerNotifications = applyCausalIdCollectionUndo(state.playerNotifications, undoData.notifications);
  state.effectOperations = applyCausalIdCollectionUndo(state.effectOperations, undoData.effectOperations);
  state.copiedActivations = applyCausalIdCollectionUndo(state.copiedActivations, undoData.copiedActivations);
  state.copiedTokenRelationships = applyCausalIdCollectionUndo(state.copiedTokenRelationships, undoData.copiedTokenRelationships);
  state.wheelSessions = applyCausalIdCollectionUndo(state.wheelSessions, undoData.wheelSessions);
  state.randomPokemonSessions = applyCausalIdCollectionUndo(state.randomPokemonSessions, undoData.randomPokemonSessions);
  state.delayedEffects = applyCausalIdCollectionUndo(state.delayedEffects, undoData.delayedEffects);
  state.broughtTeamSnapshots = applyCausalIdCollectionUndo(state.broughtTeamSnapshots, undoData.broughtTeamSnapshots);
  state.postPayoutProcedures = applyCausalIdCollectionUndo(state.postPayoutProcedures, undoData.postPayoutProcedures);
  state.encounterCopyRecords = applyCausalIdCollectionUndo(state.encounterCopyRecords, undoData.encounterCopyRecords);
  state.teambuilder ||= {};
  applyCausalTopLevelFieldUndo(state.teambuilder, undoData.teambuilderFields);
  state.battleTeams ||= {};
  applyCausalTopLevelFieldUndo(state.battleTeams, undoData.battleTeamFields);
  (undoData.pokemonDeltas || []).forEach((delta) => {
    const pokemon = state.pokemonRecords.find((entry) => entry.id === delta.pokemonId);
    if (!pokemon) return;
    pokemon.effectBuffs = applyCausalIdCollectionUndo(pokemon.effectBuffs, delta.effectBuffs);
    pokemon.log = applyCausalIdCollectionUndo(pokemon.log, delta.logs);
    const removeLabels = new Set(delta.labelsAdded || []);
    const previousLabels = delta.previousLabelOrder || [];
    const laterLabels = (pokemon.buffs || []).filter((label) => !removeLabels.has(label) && !previousLabels.includes(label));
    pokemon.buffs = [...previousLabels, ...laterLabels];
  });
  state.pokemonLog = applyCausalIdCollectionUndo(state.pokemonLog, undoData.pokemonLog);
  const restoreGrantMap = (root, deltas) => (deltas || []).forEach(({ playerId, delta }) => {
    root[playerId] = applyCausalIdCollectionUndo(root[playerId], delta);
  });
  state.teambuilder.moveAccessGrantsByPlayerId ||= {};
  restoreGrantMap(state.teambuilder.moveAccessGrantsByPlayerId, undoData.teambuilderMoveGrants);
  state.perkSystem ||= {};
  state.perkSystem.moveAccessGrantsByPlayerId ||= {};
  restoreGrantMap(state.perkSystem.moveAccessGrantsByPlayerId, undoData.perkMoveGrants);
  state.classStateByPlayerId ||= {};
  (undoData.classMoveGrants || []).forEach(({ playerId, delta }) => {
    state.classStateByPlayerId[playerId] ||= {};
    state.classStateByPlayerId[playerId].moveAccessGrants = applyCausalIdCollectionUndo(state.classStateByPlayerId[playerId].moveAccessGrants, delta);
  });
  (undoData.ruleDeltas || []).forEach((delta) => {
    if (delta.existed) state.globalPokemonRules[delta.key] = structuredClone(delta.previous);
    else delete state.globalPokemonRules[delta.key];
  });
  state.banlistHistory = applyCausalIdCollectionUndo(state.banlistHistory, undoData.banlistHistory);
  if (undoData.tokenDefinitionId === "honey-token" && undoData.procedureId) {
    const procedure = (state.endOfActionProcedures || []).find((entry) => entry.id === undoData.procedureId);
    if (procedure) {
      procedure.status = "undone";
      procedure.undoneAt = new Date().toISOString();
    }
  }
  if (state.selectedRandomPokemonSessionId && !(state.randomPokemonSessions || []).some((entry) => entry.id === state.selectedRandomPokemonSessionId)) {
    state.selectedRandomPokemonSessionId = "";
    state.randomPokemonDrawerOpen = false;
  }
  syncLinkedTransactions();
  syncPlayerPokemonLists();
}

function recordTokenContractResolution(activity, metadata, {
  result = "resolved",
  details = [],
  mutations = [],
  persistentStateIds = [],
  hostConfirmation = ""
} = {}) {
  const canonicalResult = result === "noEffect" ? "resolvedNoEffect"
    : result === "canceled" ? "canceledRefunded"
      : result;
  const draft = tokenDraftFromActivity(activity, hostConfirmation);
  const audit = tokenEffectAuditRecord({
    stage: "resolution",
    activity,
    draft: { ...draft, consumedTokenId: activity?.payload?.consumedTokenId || "" },
    metadata,
    result: canonicalResult,
    mutations,
    persistentStateIds,
    hostConfirmation
  });
  const undoSnapshot = activity?.payload?.tokenDeclarationUndo;
  let causalUndo = undoSnapshot && ["restrict-token", "extra-ban-token", "unban-token", "clear-smog", "rage-candy-bar", "safeguard", "cold-wave", "wicked-blow", "purge-curse"].includes(metadata.id)
    ? buildCausalTokenEffectUndo(undoSnapshot, activity, metadata)
    : null;
  if (causalUndo && activity?.payload?.teleportDelayedEffectId) {
    const delayed = (state.delayedEffects || []).find((entry) => entry.id === activity.payload.teleportDelayedEffectId);
    const originalEventId = delayed?.parentEffect?.id || activity.payload.teleportOriginalEventId || "";
    const originalLog = (state.log || []).find((entry) => !entry.undone
      && entry.undoData?.actionType === "undoTokenEffectContractCausal"
      && (entry.linkedEventId === originalEventId
        || entry.undoData?.delayedEffects?.createdIds?.includes(delayed?.id)));
    if (originalLog) {
      causalUndo = mergeCausalTokenUndoData(originalLog.undoData, causalUndo);
      originalLog.undoable = false;
      originalLog.supersededByTeleportReturnEventId = activity.id;
    }
  }
  const logEntry = addLogEntry({
    action: "token",
    category: "tokens",
    player: draft.actor?.name || "Table",
    item: `${metadata.name || draft.tokenName} ${canonicalResult === "negated" ? "was negated" : canonicalResult === "resolvedNoEffect" ? "resolved with no effect" : canonicalResult === "canceledRefunded" ? "was canceled and refunded" : "resolved"}.`,
    title: `${metadata.name || draft.tokenName} ${canonicalResult === "negated" ? "negated" : canonicalResult === "resolvedNoEffect" ? "resolved with no effect" : canonicalResult === "canceledRefunded" ? "canceled and refunded" : "resolved"}`,
    summary: details.join("\n"),
    details,
    type: "token-effect-resolution",
    categories: ["tokens", "interaction", metadata.timingCategory, canonicalResult].filter(Boolean),
    tags: ["token-effect-contract", metadata.resolverId, metadata.name, canonicalResult].filter(Boolean),
    playerIds: [activity?.actorPlayerId, activity?.targetPlayerId].filter(Boolean),
    pokemonIds: [activity?.payload?.targetPokemonId].filter(Boolean),
    pokemonNames: [activity?.payload?.targetPokemonName || activity?.payload?.targetText].filter(Boolean),
    tokenNames: [metadata.name].filter(Boolean),
    linkedEventId: activity?.id || "",
    effectAuditId: audit.id,
    persistentStateIds,
    resolverMode: metadata.resolutionMode,
    resolutionResult: canonicalResult,
    undoable: Boolean(undoSnapshot),
    undone: false,
    undoData: undoSnapshot ? (causalUndo || {
      actionType: "undoTokenEffectContract",
      effectId: activity.id,
      auditId: audit.id,
      ...structuredClone(undoSnapshot)
    }) : null,
    eventOrder: nextEventOrder()
  });
  audit.undoLogId = logEntry?.id || "";
  activity.payload ||= {};
  activity.payload.resolutionAuditId = audit.id;
  activity.payload.resolutionResult = canonicalResult;
  activity.payload.stateMutations = mutations;
  return { audit, logEntry };
}

function controlTokenResourceDefinitionForName(resourceName = "") {
  const key = slugify(resourceName);
  if (!key) return null;
  const item = typeof itemShopData === "undefined"
    ? null
    : (itemShopData || []).find((entry) => slugify(entry.name) === key);
  if (item) return { ...structuredClone(item), type: "ITEM" };
  const tm = typeof tmShopData === "undefined"
    ? null
    : (tmShopData || []).find((entry) => slugify(entry.name) === key);
  if (tm) {
    return {
      ...structuredClone(tm),
      type: "TM",
      moveName: tm.name
    };
  }
  const inventoryResource = (state.players || [])
    .flatMap((player) => player.inventory || [])
    .find((entry) => (
      ["ITEM", "TM"].includes(String(entry.type || "").toUpperCase())
      && [entry.name, entry.moveName].some((name) => slugify(name || "") === key)
    ));
  return inventoryResource ? structuredClone(inventoryResource) : null;
}

function wickedBlowFinalEvolutionEntries(pokemon, teamSpecies) {
  const lock = activeSeriesEvolutionLock(pokemon, state.series);
  if (lock) {
    const lockedSpecies = teambuilderSpeciesById(lock.speciesId, { requestLoad: false })
      || teambuilderSpeciesByName(lock.speciesName, { requestLoad: false });
    return lockedSpecies ? [lockedSpecies] : [];
  }
  const source = teambuilderSpeciesByName(teamSpecies, { requestLoad: false });
  if (!source) return [];
  const reachable = teambuilderReachableEvolutionOptions(teamSpecies, { requestLoad: false });
  const reachableIds = new Set(reachable.map((entry) => String(entry.speciesId || "")).filter(Boolean));
  const childrenByParent = teambuilderEvolutionChildrenByParent({ requestLoad: false });
  return reachable
    .filter((entry) => !(childrenByParent.get(String(entry.speciesId || "")) || [])
      .some((child) => reachableIds.has(String(child.speciesId || ""))))
    .map((entry) => teambuilderSpeciesById(entry.speciesId, { requestLoad: false })
      || teambuilderSpeciesByName(entry.species, { requestLoad: false }))
    .filter(Boolean);
}

function wickedBlowReplacementPool(tierIndex) {
  if (!Number.isInteger(tierIndex) || tierIndex < 0 || tierIndex >= SAGA_TIERS.length) return [];
  const entries = Object.entries(buildPokemonBalanceTierMap())
    .map(([key, entry]) => ({ key, ...entry }))
    .filter((entry) => entry.displayName && getTierIndex(entry.balanceTierLabel || entry.balanceTier) === tierIndex)
    .filter((entry) => currentPokemonRuleStatusByName(entry.displayName) !== "Banned")
    .sort((a, b) => a.displayName.localeCompare(b.displayName) || a.key.localeCompare(b.key));
  const groups = new Map();
  entries.forEach((entry) => {
    const groupKey = pokemonRollGroupKey(entry);
    if (!groups.has(groupKey)) groups.set(groupKey, []);
    groups.get(groupKey).push(entry);
  });
  return [...groups.entries()].map(([rollGroup, forms]) => ({ rollGroup, forms }));
}

function wickedBlowEvolutionLockNotification(owner, pokemon, acquisition, previousName, now) {
  if (!owner || !acquisition?.lockCreated) return null;
  return {
    id: `notification-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
    playerId: owner.id,
    type: "series-evolution-lock-created",
    title: "Evolution Branch Locked",
    message: `Wicked Blow rerolled ${previousName} into ${acquisition.obtainedSpecies}. ${acquisition.receivedSpecies} is now locked to the ${acquisition.lockSpecies} evolution branch for the remainder of this Series. Battle Tier restrictions still apply.`,
    sourceType: "wicked-blow",
    sourceId: pokemon.id,
    pokemonId: pokemon.id,
    series: state.series,
    gym: Number(state.gym),
    phase: currentPhase(),
    status: "pending",
    priority: 3,
    requiresAction: false,
    payload: {
      obtainedPokemon: acquisition.obtainedSpecies,
      receivedPokemon: acquisition.receivedSpecies,
      lockedEvolution: acquisition.lockSpecies,
      duration: "Current Series",
      lockPath: acquisition.lockPath.map((entry) => entry.species)
    },
    createdAt: now,
    completedAt: null
  };
}

function wickedBlowReplacementPlan(targetState, pokemon, targetContext = {}) {
  const selectedRosterSpecies = String(
    pokemonCommittedSpecies(pokemon)
    || pokemon?.name
    || ""
  ).trim();
  if (!selectedRosterSpecies) return { ok: false, reason: "Wicked Blow could not determine the selected Active Roster Pokemon's species." };

  const finalEntries = wickedBlowFinalEvolutionEntries(pokemon, selectedRosterSpecies);
  if (!finalEntries.length) {
    return { ok: false, reason: `Wicked Blow needs loaded evolution data for ${selectedRosterSpecies} before it can resolve safely.` };
  }
  const finalTierDetails = finalEntries.map((entry) => {
    const species = entry.name || pokemonDisplayName(entry.pokeapiKey || "");
    const tier = pokemonSagaTier(species);
    return { species, tier, tierIndex: getTierIndex(tier) };
  });
  if (finalTierDetails.some((entry) => entry.tierIndex < 0)) {
    return { ok: false, reason: `Wicked Blow could not determine every final-evolution Battle Tier for ${selectedRosterSpecies}.` };
  }
  const finalTierIndexes = [...new Set(finalTierDetails.map((entry) => entry.tierIndex))];
  if (finalTierIndexes.length !== 1) {
    const branches = finalTierDetails.map((entry) => `${entry.species} (${entry.tier})`).join(", ");
    return { ok: false, reason: `Wicked Blow cannot safely choose between final-evolution branches with different Battle Tiers: ${branches}.` };
  }
  const finalTierIndex = finalTierIndexes[0];
  const replacementTierIndex = finalTierIndex - 3;
  if (replacementTierIndex < 0) {
    return { ok: false, reason: `${finalTierDetails[0].tier} has no Battle Tier three ordered steps below it.` };
  }
  const pool = wickedBlowReplacementPool(replacementTierIndex);
  if (!pool.length) {
    return { ok: false, reason: `No legal Pokemon are available in ${SAGA_TIERS[replacementTierIndex]} for Wicked Blow.` };
  }
  const tierCalculation = {
    selectedRosterSpecies,
    finalEvolutionSpecies: finalTierDetails.map((entry) => entry.species),
    finalEvolutionTier: SAGA_TIERS[finalTierIndex],
    finalEvolutionTierIndex: finalTierIndex,
    orderedStepsBelow: 3,
    replacementTier: SAGA_TIERS[replacementTierIndex],
    replacementTierIndex
  };
  if (targetContext.preview) {
    return { ok: true, poolSize: pool.length, tierCalculation };
  }

  const chosenGroup = randomSample(pool, 1)[0];
  const rolled = randomSample(chosenGroup?.forms || [], 1)[0];
  if (!rolled) return { ok: false, reason: "Wicked Blow's legal replacement pool became empty." };
  const acquisition = resolvePokemonAcquisitionSpecies(rolled.displayName, { source: "Wicked Blow" });
  const receivedSpecies = acquisition.receivedSpecies || rolled.displayName;
  const spriteKey = choosePokemonSpriteLookupKey(receivedSpecies);
  const now = new Date().toISOString();
  const owner = (targetState.players || []).find((player) => player.id === pokemon.trainerId) || null;
  const pokemonPatch = normalizePokemonRecord({
    ...structuredClone(pokemon),
    name: receivedSpecies,
    baseSpecies: receivedSpecies,
    currentSpecies: receivedSpecies,
    currentEvolutionStage: teambuilderEvolutionStageIndex(receivedSpecies, { requestLoad: false }),
    evolutionLineId: teambuilderEvolutionLineId(receivedSpecies, { requestLoad: false }),
    acquiredSpeciesId: acquisition.obtainedSpeciesId,
    acquiredSpeciesName: acquisition.obtainedSpecies,
    rosterSpeciesId: acquisition.receivedSpeciesId,
    rosterSpeciesName: receivedSpecies,
    seriesEvolutionLockSpeciesId: acquisition.lockSpeciesId,
    seriesEvolutionLockSpeciesName: acquisition.lockSpecies,
    seriesEvolutionLockSeriesId: acquisition.lockCreated ? targetState.series : "",
    seriesEvolutionLockCreatedAt: acquisition.lockCreated ? now : "",
    seriesStartSpecies: receivedSpecies,
    resetsToSpecies: receivedSpecies,
    ruleStatus: "Normal",
    spriteUrl: pokemonDbSpriteUrlForLookup(spriteKey),
    chosenSpriteKey: spriteKey,
    source: "Wicked Blow",
    sourceTier: getPokemonAcquisitionTier(rolled.displayName),
    acquisitionTier: getPokemonAcquisitionTier(rolled.displayName),
    gameCornerMetadata: getPokemonGameCornerMetadata(rolled.displayName) || null
  });
  const assignedBadgePoints = teambuilderRequiredBadgePointsForSpecies(receivedSpecies, targetState.gym);
  const notification = wickedBlowEvolutionLockNotification(owner, pokemon, acquisition, pokemon.name, now);
  return {
    ok: true,
    replacementSpecies: receivedSpecies,
    rolledSpecies: rolled.displayName,
    teamSpecies: receivedSpecies,
    pokemonPatch,
    assignedBadgePoints,
    poolSize: pool.length,
    tierCalculation: {
      ...tierCalculation,
      rolledSpecies: rolled.displayName,
      receivedSpecies
    },
    playerNotifications: [notification].filter(Boolean),
    teambuilderSlotPatch: (_slot, index) => normalizeTeamBuildSlot({
      pokemonRecordId: pokemon.id,
      slotIndex: index,
      selectedBattleSpecies: receivedSpecies,
      selectedBattleForm: receivedSpecies,
      assignedBadgePoints
    }, pokemon.trainerId)
  };
}

function moveDeleterTimingCheck() {
  const phase = currentPhase();
  if (["battle-results", "shop"].includes(phase)) {
    return { ok: false, reason: "Move Deleter cannot be declared after team submission." };
  }
  if (phase === "battle" && !["teamPreparation", "teamSubmissionLock"].includes(battlePhaseSubstep())) {
    return { ok: false, reason: "Move Deleter cannot be declared after team submission." };
  }
  return { ok: true, reason: "" };
}

function purgeTimingCheck() {
  if (["battle-results", "shop"].includes(currentPhase()) || finalizedGymResult(state.series, state.gym)) {
    return { ok: false, reason: "Purge must be declared before this Gym reaches its Battle Payout checkpoint." };
  }
  return { ok: true, reason: "" };
}

function controlTokenEffectOptions(now = new Date().toISOString()) {
  return {
    state,
    keyForSpecies: pokemonRuleKey,
    series: state.series,
    gym: Number(state.gym),
    phase: currentPhase(),
    seriesOrder: seriesNames,
    now,
    makeId: (prefix) => `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
    battleTeamKey: () => currentPhaseKey(),
    teamSizeForPlayer: (playerId) => battleTeamSlotCount(playerId),
    battleTierForPokemon: (pokemon) => pokemonSagaTier(pokemonCommittedSpecies(pokemon) || pokemon),
    naturalBattleTier: () => getNaturalGymTier(state.gym),
    tierIndexForName: getTierIndex,
    requiredBadgePointsForPokemon: (pokemon) => teambuilderRequiredBadgePointsForSpecies(pokemonCommittedSpecies(pokemon), state.gym),
    bringLegalityForPokemon: arenaTrapBringLegalityForPokemon,
    abilityExists: (abilityName) => Boolean(teambuilderDataSource().abilities?.[teambuilderDataKey(abilityName)]),
    moveExists: teambuilderKnownMoveName,
    moveDeleterTimingCheck,
    purgeTimingCheck,
    resourceDefinitionForName: controlTokenResourceDefinitionForName,
    wickedBlowReplacementPlan,
    definitionFor: (value) => globalThis.rivalSagaTokenEffectContract?.definitionFor?.(value) || null,
    isTokenCopyProtected: (playerId) => hasProtectionAgainst(state, playerId, { protectionKeys: ["tokenCopy"] }),
    preEvolutionFor: (speciesName) => {
      const species = teambuilderSpeciesByName(speciesName);
      const rawParents = [species?.evolvesFrom, ...(species?.evolvesFromIds || []), ...(species?.preEvolutions || [])]
        .flat().filter(Boolean);
      const parentKeys = [...new Set(rawParents.map((value) => teambuilderDataKey(typeof value === "object" ? value.name || value.id : value)).filter(Boolean))];
      if (parentKeys.length !== 1) return { ok: false, reason: parentKeys.length ? `${speciesName} has an ambiguous direct pre-evolution.` : `${speciesName} has no direct pre-evolution.` };
      const parent = teambuilderSpeciesById(parentKeys[0]) || teambuilderSpeciesByName(parentKeys[0]);
      if (!parent?.name) return { ok: false, reason: `${speciesName}'s direct pre-evolution data is unavailable or unsafe.` };
      return { ok: true, speciesName: parent.name, speciesId: parent.id || parentKeys[0] };
    },
    teamBuildSlotForPokemon: (playerId, pokemonId) => (activeTeamBuildDraftForPlayer(playerId)?.slots || []).find((slot) => slot.pokemonRecordId === pokemonId) || null,
    lockedTeamSlotsForPlayer: (playerId) => lockedBattleTeamSlots(playerId)
  };
}

function teleportDelayedConsumptionIds(record) {
  return [...new Set([
    record?.teleportConsumptionRecordId,
    ...(record?.parentConsumptionRecordIds || [])
  ].map(String).filter(Boolean))];
}

function refundTokenConsumptionsByIds(ids = [], reason = "Delayed effect recovery") {
  const wanted = new Set((ids || []).map(String).filter(Boolean));
  let refunded = 0;
  (state.tokenConsumptions || []).forEach((record) => {
    if (wanted.has(String(record.id || "")) && refundTokenConsumption(record, reason)) refunded += 1;
  });
  return refunded;
}

function teleportReturnEventId(record) {
  return `interaction-teleport-return-${slugify(record?.id || "delayed-effect")}`;
}

function teleportDelayedEffectIsTerminal(record) {
  return ["resolved", "resolvedNoEffect", "canceledRefunded"].includes(record?.status);
}

function teleportDelayedEffectDue(record) {
  return Boolean(record?.dueAt
    && String(record.dueAt.series || "") === String(state.series || "")
    && Number(record.dueAt.gym || 0) === Number(state.gym || 0)
    && String(record.dueAt.phase || "") === String(currentPhase() || ""));
}

function teleportReturnRevalidation(record, parentEffect = record?.parentEffect) {
  const snapshot = parentEffect && typeof parentEffect === "object" ? structuredClone(parentEffect) : null;
  if (!snapshot?.payload) {
    return { ok: false, classification: "unsupported", reason: "Teleport lost the exact delayed declaration payload." };
  }
  const metadata = tokenEffectMetadataByName(snapshot.payload.tokenName || snapshot.title || "");
  if (!metadata?.id || !tokenControlController?.CONTROL_TOKEN_IDS?.includes(metadata.id) || metadata.id === "purge-curse") {
    return { ok: false, classification: "unsupported", reason: "The delayed effect no longer has a supported production controller." };
  }
  const runtime = tokenRuntimeUsabilityCheck(metadata);
  if (!runtime.ok) return { ok: false, classification: "unsupported", reason: runtime.reason };
  try {
    const validation = tokenControlController.validateResolutionState?.(state, {
      ...snapshot,
      status: "open",
      payload: { ...snapshot.payload, teleportDelayedEffectId: record.id }
    }, controlTokenEffectOptions());
    if (!validation) {
      return { ok: false, classification: "unsupported", reason: "The delayed effect revalidator is unavailable." };
    }
    return validation.ok
      ? { ok: true, classification: "", reason: "", metadata }
      : { ok: false, classification: "gameplay", reason: validation.reason || "The original declaration is no longer legal.", metadata };
  } catch (error) {
    return { ok: false, classification: "unsupported", reason: error?.message || "The delayed effect revalidator failed.", metadata };
  }
}

function closeTeleportDelayedRecordWithoutReturn(record, validation, now = new Date().toISOString()) {
  const gameplayIllegal = validation?.classification === "gameplay";
  record.status = gameplayIllegal ? "resolvedNoEffect" : "canceledRefunded";
  record.resolvedAt = now;
  record.resolutionReason = validation?.reason || (gameplayIllegal
    ? "The original declaration was no longer legal when Teleport returned."
    : "The delayed effect could not be reconstructed safely.");
  record.refundRequired = !gameplayIllegal;
  const refundedCount = gameplayIllegal
    ? 0
    : refundTokenConsumptionsByIds(teleportDelayedConsumptionIds(record), record.resolutionReason);
  const originalLog = (state.log || []).find((entry) => !entry.undone
    && entry.undoData?.actionType === "undoTokenEffectContractCausal"
    && (entry.linkedEventId === record.parentEffect?.id
      || entry.undoData?.delayedEffects?.createdIds?.includes(record.id)));
  const terminalLog = addLogEntry({
    action: "token",
    category: "tokens",
    player: livePlayerName(record.sourcePlayerId, "Teleport"),
    item: gameplayIllegal
      ? `Teleport returned, but ${record.parentEffect?.title || "the delayed effect"} was no longer legal and had no effect.`
      : `Teleport return failed safely for ${record.parentEffect?.title || "the delayed effect"}.`,
    title: gameplayIllegal ? "Delayed effect resolved with no effect" : "Delayed effect canceled and refunded",
    summary: [
      record.resolutionReason,
      gameplayIllegal
        ? "The original target was not changed. Both confirmed Tokens remain consumed."
        : `${refundedCount} exact Token consumption record${refundedCount === 1 ? " was" : "s were"} refunded.`
    ].join("\n"),
    type: gameplayIllegal ? "teleport-return-no-effect" : "teleport-return-canceled-refunded",
    categories: ["tokens", "delayed-effect", "system"],
    tags: ["teleport", gameplayIllegal ? "no-effect" : "canceled-refunded"],
    playerIds: [record.sourcePlayerId, record.parentEffect?.actorPlayerId, record.parentEffect?.targetPlayerId].filter(Boolean),
    linkedEventId: record.parentEffect?.id || "",
    delayedEffectId: record.id,
    resultData: { delayedEffectId: record.id, refundedTokenCount: refundedCount },
    undoable: Boolean(originalLog?.undoData),
    undone: false,
    undoData: originalLog?.undoData ? structuredClone(originalLog.undoData) : null,
    eventOrder: nextEventOrder()
  });
  if (originalLog && terminalLog) {
    originalLog.undoable = false;
    originalLog.supersededByTeleportTerminalLogId = terminalLog.id;
  }
  queueLiveResolutionAnnouncement({
    id: `resolution:teleport:${record.id}:${record.status}`,
    title: gameplayIllegal ? "The delayed effect had no effect." : "The delayed effect was canceled safely.",
    detail: record.resolutionReason,
    tone: gameplayIllegal ? "resolved" : "canceledRefunded",
    linkedEventId: record.parentEffect?.id || ""
  });
  return { terminal: true, gameplayIllegal, refundedCount };
}

function processDueTeleportDelayedEffects(now = new Date().toISOString()) {
  state.delayedEffects ||= [];
  let changed = false;
  let opened = 0;
  state.delayedEffects
    .filter((record) => record?.type === "teleport" && !teleportDelayedEffectIsTerminal(record))
    .forEach((record) => {
      const eventId = record.returnInteractionEventId || teleportReturnEventId(record);
      const existing = (state.interactionEvents || []).find((event) => event.id === eventId);
      if (existing) {
        record.returnInteractionEventId = existing.id;
        if (interactionSituationLifecycle.isTerminal(existing)) {
          record.status = existing.status === "canceled" ? "canceledRefunded" : "resolved";
          record.resolvedAt ||= existing.resolvedAt || now;
        } else {
          record.status = "awaitingReturnResolution";
        }
        changed = true;
        return;
      }
      if (!teleportDelayedEffectDue(record)) return;
      const validation = teleportReturnRevalidation(record);
      if (!validation.ok) {
        closeTeleportDelayedRecordWithoutReturn(record, validation, now);
        changed = true;
        return;
      }
      const parent = structuredClone(record.parentEffect);
      const payload = structuredClone(parent.payload || {});
      delete payload.appliedTokenEffectId;
      delete payload.tokenEffectBlocked;
      delete payload.finalResultSummary;
      delete payload.resolutionResultText;
      delete payload.negatedByPromptId;
      delete payload.negatedByResponseId;
      delete payload.delayedByPromptId;
      delete payload.delayedByResponseId;
      delete payload.delayedEffectId;
      delete payload.tokenDeclarationUndo;
      const returnEvent = createInteractionEvent({
        id: eventId,
        type: parent.type,
        title: `${parent.title || payload.tokenName || "Delayed effect"} returned.`,
        message: `${parent.message || parent.title || "The delayed effect"} returned at its preserved matching phase.`,
        actorPlayerId: parent.actorPlayerId || "",
        targetPlayerId: parent.targetPlayerId || "",
        sourceType: "token-use",
        sourceId: parent.sourceId || slugify(payload.tokenName || "delayed-effect"),
        payload: {
          ...payload,
          teleportReturn: true,
          teleportDelayedEffectId: record.id,
          teleportOriginalEventId: parent.id || "",
          teleportDeclarationPhaseAnchor: structuredClone(record.declarationPhaseAnchor),
          teleportResolutionPhaseAnchor: { series: state.series, gym: Number(state.gym), phase: currentPhase() }
        },
        responseTypes: structuredClone(parent.responseTypes || []),
        eligiblePlayerIds: payload.responsesAllowed === false
          ? []
          : structuredClone(parent.eligiblePlayerIds?.length ? parent.eligiblePlayerIds : state.players.map((player) => player.id)),
        series: state.series,
        gym: Number(state.gym),
        phase: currentPhase()
      });
      returnEvent.payload.sourceEffectId = returnEvent.id;
      returnEvent.payload.tokenDeclarationUndo = tokenUseRollbackSnapshot();
      record.status = "awaitingReturnResolution";
      record.returnInteractionEventId = returnEvent.id;
      record.returnOpenedAt = now;
      record.resolutionPhaseAnchor = { series: state.series, gym: Number(state.gym), phase: currentPhase() };
      addLogEntry({
        action: "token",
        category: "tokens",
        player: livePlayerName(parent.actorPlayerId, "Table"),
        item: `${parent.title || payload.tokenName || "Delayed effect"} returned through Teleport.`,
        title: "Delayed effect returned",
        summary: [
          `Original declaration: ${parent.title || payload.tokenName || "Effect"}`,
          `Return anchor: ${state.series} Gym ${state.gym} ${currentPhase()}`,
          "The original target is preserved. A normal response window is open before resolution."
        ].join("\n"),
        type: "teleport-return-opened",
        categories: ["tokens", "interaction", "delayed-effect"],
        tags: ["teleport", "return", "response-window"],
        playerIds: [parent.actorPlayerId, parent.targetPlayerId].filter(Boolean),
        linkedEventId: returnEvent.id,
        delayedEffectId: record.id,
        eventOrder: returnEvent.eventOrder
      });
      opened += 1;
      changed = true;
      if (!returnEvent.eligiblePlayerIds.length) advanceAutomaticInteractionPrompts(returnEvent);
    });
  return { changed, opened };
}

function controlTokenDraftLegality(draft, metadata = tokenEffectMetadataByName(draft?.tokenName || "")) {
  if (!controlTokenEffects || !draft) return { ok: true, reason: "" };
  const definitionId = metadata.id || slugify(metadata.name || draft.tokenName);
  if (tokenControlController?.CONTROL_TOKEN_IDS?.includes(definitionId)) {
    return tokenControlController.validateDeclaration(state, {
      tokenId: definitionId,
      tokenName: metadata.name || draft.tokenName,
      actorPlayerId: draft.actorPlayerId,
      targetPlayerId: draft.targetPlayerId,
      targetPokemonId: draft.targetPokemonId,
      targetPokemonName: draft.targetPokemonName,
      speciesName: draft.targetPokemonName || draft.targetText,
      selectedRosterInstanceId: draft.selectedRosterInstanceId,
      selectedStatusId: draft.selectedStatusId || "",
      selectedRosterInstanceIds: draft.targetPokemonIds || [],
      targetPokemonIds: draft.targetPokemonIds || [],
      resourceName: draft.targetText || draft.notes || "",
      resourceSelections: draft.resourceSelections || [],
      resourceDefinitionId: draft.resourceDefinitionId || "",
      choiceKind: draft.choiceKind || "",
      inventoryRecordId: draft.inventoryRecordId || "",
      moveName: draft.moveName || "",
      isVirtualActivation: Boolean(draft.isVirtualActivation)
    }, controlTokenEffectOptions());
  }
  const options = controlTokenEffectOptions();
  const targetPokemon = (state.pokemonRecords || []).find((record) => record.id === draft.targetPokemonId);
  const targetName = String(draft.targetPokemonName || draft.targetText || "").trim();
  if (metadata.timingCategory === TOKEN_TIMING_CATEGORIES.CURSE && targetPokemon
    && controlTokenEffects.pokemonHasArenaTrap?.(state, targetPokemon, options)) {
    return { ok: false, reason: `${targetPokemon.name} is Arena Trapped and cannot be cursed.` };
  }
  if (["restrict-token", "extra-ban-token"].includes(definitionId) && targetName
    && controlTokenEffects.speciesHasUnbanProtection(state, targetName, options)) {
    return { ok: false, reason: `${targetName} is protected from Ban and Restrict by Unban.` };
  }
  if (definitionId === "extra-ban-token" && targetName
    && controlTokenEffects.speciesHasBanPhaseProtection?.(state, targetName, options)) {
    return { ok: false, reason: `${targetName} cannot be banned again during this phase because Substitute protected it.` };
  }
  if (definitionId === "extra-ban-token" && (!targetPokemon || ["Released", "Removed"].includes(targetPokemon.status))) {
    return { ok: false, reason: "Choose a specific roster Pokemon as Extra Ban's declaration target." };
  }
  if (definitionId === "extra-ban-token" && targetPokemon.rosterType !== "Active") {
    return { ok: false, reason: "Extra Ban must target an exact Pokemon on an Active roster." };
  }
  if (["arena-trap", "clear-smog"].includes(definitionId) && (!targetPokemon || ["Released", "Removed"].includes(targetPokemon.status))) {
    return { ok: false, reason: `Choose a specific roster Pokemon for ${metadata.name}.` };
  }
  if (definitionId === "clear-smog" && targetPokemon.rosterType !== "Active") {
    return { ok: false, reason: "Clear Smog must target an exact Pokemon on an Active roster." };
  }
  if (definitionId === "arena-trap" && targetPokemon.trainerId === draft.actorPlayerId) {
    return { ok: false, reason: "Arena Trap must target a rival player's Pokemon." };
  }
  if (definitionId === "arena-trap" && targetPokemon.rosterType && targetPokemon.rosterType !== "Active") {
    return { ok: false, reason: "Arena Trap must target a Pokemon in a rival player's Active roster." };
  }
  if (definitionId === "arena-trap") {
    const bringLegality = arenaTrapBringLegalityForPokemon(targetPokemon, draft.actorPlayerId);
    if (!bringLegality.ok) return bringLegality;
  }
  if (definitionId === "restrict-token") {
    if (!targetName) return { ok: false, reason: "Choose a Pokemon species before using Restrict." };
    if (controlTokenEffects.activeSpeciesStatuses(state, targetName, "restrict", options).length
      || currentPokemonRuleStatusByName(targetName) === "Restricted") {
      return { ok: false, reason: `${targetName} is already Restricted.` };
    }
  }
  if (definitionId === "unban-token") {
    if (!targetName) return { ok: false, reason: "Choose a Banned or Restricted Pokemon species before using Unban." };
    const hasStatus = controlTokenEffects.activeSpeciesStatuses(state, targetName, ["ban", "restrict"], options).length > 0;
    const ruleStatus = currentPokemonRuleStatusByName(targetName);
    if (!hasStatus && !["Banned", "Restricted"].includes(ruleStatus)) {
      return { ok: false, reason: `${targetName} has no active Ban or Restrict to remove.` };
    }
  }
  if (definitionId === "rage-candy-bar") {
    if (!targetPokemon || ["Released", "Removed"].includes(targetPokemon.status) || targetPokemon.trainerId !== draft.actorPlayerId) {
      return { ok: false, reason: "Choose a specific owned roster Pokemon for Rage Candy Bar." };
    }
  }
  return { ok: true, reason: "" };
}

function applyAutomaticControlFoundationActivity(activity, metadata) {
  if (!controlTokenEffects || ![
    "restrict-token",
    "arena-trap",
    "clear-smog",
    "rage-candy-bar",
    "extra-ban-token",
    "move-deleter",
    "cold-wave",
    "lingering-aroma",
    "purge-curse",
    "unban-token",
    "incinerate",
    "steal-token",
    "wicked-blow",
    "toxic-curse",
    "iron-ball-curse",
    "flame-curse",
    "silencing-curse",
    "imprison-curse",
    "knock-off-curse",
    "haze-curse",
    "devolve-token"
  ].includes(metadata.id)) return null;
  if (tokenControlController?.resolveFoundationActivity) {
    const effectOptions = {
      ...controlTokenEffectOptions(new Date().toISOString()),
      statusExpiresAt
    };
    const revalidation = tokenControlController.validateResolutionState?.(state, activity, effectOptions);
    if (revalidation && !revalidation.ok) {
      return {
        result: revalidation.refund ? "systemFailure" : "blocked",
        refundRequired: Boolean(revalidation.refund),
        details: [revalidation.reason].filter(Boolean),
        mutations: [],
        persistentStateIds: [],
        resultData: {
          protectionResult: revalidation.protectionResult || "",
          operations: []
        }
      };
    }
    const foundation = tokenControlController.resolveFoundationActivity(state, activity, effectOptions);
    const resolution = foundation?.resolution;
    if (!resolution) return null;
    if (metadata.id === "arena-trap" && resolution.result === "resolved") {
      addPokemonLog(resolution.pokemon, "Arena Trap", "Must be brought this Battle Phase; cannot be cursed while trapped.");
    } else if (metadata.id === "clear-smog" && resolution.result === "resolved") {
      addPokemonLog(resolution.pokemon, "Clear Smog", resolution.reason);
    } else if (metadata.id === "rage-candy-bar" && resolution.result === "resolved" && resolution.buffIds.length) {
      addPokemonLog(resolution.pokemon, "Rage Candy Bar", resolution.extended
        ? "Shared Rage Candy duration extended by 2 Gyms; bonuses did not stack."
        : "+3 Levels; EV Cap +252; Restrict Immune for 2 Gyms");
    } else if (metadata.id === "steal-token" && resolution.result === "resolved") {
      addPokemonLog(
        resolution.pokemon,
        "Stolen",
        `${resolution.previousOwner?.name || "Previous owner"} -> ${resolution.newOwner?.name || "New owner"}`
      );
    } else if (metadata.id === "wicked-blow" && resolution.result === "resolved") {
      const previousName = resolution.previousPokemon?.name || "Previous Pokemon";
      const rolledName = resolution.tierCalculation?.rolledSpecies || resolution.replacementPokemon?.name || "replacement Pokemon";
      const receivedName = resolution.replacementPokemon?.name || rolledName;
      addPokemonLog(
        resolution.pokemon,
        "Wicked Blow",
        `${previousName} -> ${receivedName}${rolledName !== receivedName ? ` (rolled ${rolledName})` : ""}. ${resolution.tierCalculation?.finalEvolutionTier || "Unknown tier"} -> ${resolution.tierCalculation?.replacementTier || "Unknown tier"}.`
      );
      (state.teambuilder?.buildsByPlayerId?.[resolution.targetOwnerPlayerId] || []).forEach((build) => syncTeambuilderBadgeAssignments(build));
    } else if (isStandardCurseTokenId(metadata.id) && resolution.result === "resolved") {
      (resolution.affectedPokemon || []).forEach((pokemon) => addPokemonLog(pokemon, metadata.name, resolution.reason));
      const statusDefinition = statusTokenDefinitionByName(metadata.name);
      openSabotageRevisionWindowsForStatusActivation({
        definition: statusDefinition,
        activation: { id: activity.id, tokenName: metadata.name },
        targetPokemon: resolution.affectedPokemon || [],
        targetPlayer: null,
        sourceLogEntryId: activity.payload?.activityLogEntryId || ""
      });
    } else if (["haze-curse", "devolve-token"].includes(metadata.id) && resolution.result === "resolved") {
      const affectedPokemon = (resolution.resultData?.affectedRosterInstanceIds || []).map(findPokemonRecord).filter(Boolean);
      affectedPokemon.forEach((pokemon) => addPokemonLog(pokemon, metadata.name, resolution.reason));
      openSabotageRevisionWindowsForStatusActivation({
        definition: statusTokenDefinitionByName(metadata.name),
        activation: { id: activity.id, tokenName: metadata.name },
        targetPokemon: affectedPokemon,
        targetPlayer: null,
        sourceLogEntryId: activity.payload?.activityLogEntryId || ""
      });
    } else if (metadata.id === "knock-off-curse" && resolution.result === "resolved") {
      (resolution.resultData?.impactedLockedSlots || []).forEach((impacted) => {
        const pokemon = findPokemonRecord(impacted.pokemonRecordId);
        if (!pokemon) return;
        openBattleRevisionWindow({
          revisionType: BATTLE_REVISION_TYPES.SABOTAGE_SET,
          phase: "sabotage",
          affectedPlayerId: pokemon.trainerId,
          affectedPokemonRecordId: pokemon.id,
          affectedLockedSlotId: impacted.lockedSlotId,
          affectedLockedTeamId: lockedBattleTeamId(pokemon.trainerId),
          sourceEffectId: activity.id,
          sourceEffectName: metadata.name,
          sourceActivityId: activity.id,
          sourceTokenName: metadata.name,
          restrictionsApplied: [`TM access lost: ${impacted.moveName}`],
          affectedRosterInstanceIds: [pokemon.id],
          revisionReason: `${pokemon.name} lost TM access to ${impacted.moveName}.`,
          requiredChanges: [`Replace ${impacted.moveName}`],
          requiredChange: { removeMoveName: impacted.moveName },
          allowedScope: { affectedPokemonSet: true, teamMembership: false, badgeAssignments: false, unrelatedPokemonSets: false },
          scopeBaseline: battleRevisionScopeBaseline(pokemon.trainerId, pokemon.id),
          mustEditTeamMembership: false,
          mustEditSet: true,
          validationScope: BATTLE_REVISION_VALIDATION_SCOPES.SINGLE_POKEMON_SET,
          note: "Replace only the affected TM-derived move, then confirm the revision."
        });
      });
    }
    syncPlayerPokemonLists();
    const operationMutations = (resolution.operations || []).map((operation) => (
      operation.operationType === controlTokenEffects.EFFECT_OPERATION_TYPES?.DESTROY_INVENTORY_RESOURCE
        ? `Destroyed ${operation.targetObjectName} from ${livePlayerName(operation.targetPlayerId, "another player")}`
        : operation.operationType === controlTokenEffects.EFFECT_OPERATION_TYPES?.TRANSFER_POKEMON_OWNERSHIP
          ? `Transferred ${operation.targetObjectName} to ${livePlayerName(operation.newOwnerPlayerId, "the acting player")}`
          : operation.operationType === controlTokenEffects.EFFECT_OPERATION_TYPES?.REROLL_POKEMON
            ? `Rerolled ${operation.targetObjectName} into ${operation.replacementObjectName}`
            : `Completed effect operation ${operation.id}`
    ));
    return {
      result: resolution.result,
      refundRequired: Boolean(resolution.refundRequired),
      details: [resolution.reason].filter(Boolean),
      mutations: [
        ...(resolution.removedStatusIds || []).map((id) => `Removed status ${id}`),
        ...(resolution.removedEffectBuffIds || []).map((id) => `Removed Pokemon buff ${id}`),
        ...(resolution.removedMoveGrantIds || []).map((id) => `Removed move-access grant ${id}`),
        ...(resolution.removedBuffLabels || []).map((label) => `Removed buff ${label}`),
        ...(resolution.buffIds || []).map((id) => `${resolution.extended ? "Retained" : "Created"} timed buff ${id}`),
        ...(resolution.statusIds || []).map((id) => `Created status ${id}`),
        ...operationMutations
      ],
      persistentStateIds: [
        ...(resolution.statusIds || []),
        ...(resolution.buffIds || []),
        ...(resolution.operations || []).map((operation) => operation.id)
      ],
      resultData: {
        ...(resolution.resultData || {}),
        createdStatusIds: resolution.statusIds || [],
        removedStatusIds: resolution.removedStatusIds || [],
        affectedRosterInstanceIds: resolution.resultData?.affectedRosterInstanceIds || resolution.status?.affectedRosterInstanceIds || [resolution.pokemon?.id].filter(Boolean),
        excludedRosterInstanceIds: resolution.resultData?.excludedRosterInstanceIds || resolution.status?.excludedRosterInstanceIds || [],
        teamMutation: resolution.teamMutation || null,
        compensationStatus: resolution.compensationStatus || "",
        customization: resolution.customization || null,
        grantedCustomizations: resolution.grantedCustomizations || [],
        operations: resolution.operations || [],
        destroyedResourceIds: resolution.destroyedResourceIds || [],
        transferredPokemonId: resolution.transferredPokemonId || "",
        replacedPokemonId: resolution.replacedPokemonId || "",
        previousPokemon: resolution.previousPokemon || null,
        replacementPokemon: resolution.replacementPokemon || null,
        tierCalculation: resolution.tierCalculation || null,
        poolSize: Number(resolution.poolSize || 0),
        notificationIds: resolution.notificationIds || [],
        affectedPlayerIds: resolution.affectedPlayerIds || [],
        protectionResult: resolution.protectionResult || "",
        repairRequired: Boolean(resolution.repair),
        repairId: resolution.repair?.id || ""
      }
    };
  }
  const draft = tokenDraftFromActivity(activity);
  const now = new Date().toISOString();
  const options = controlTokenEffectOptions(now);
  const source = {
    sourceTokenId: activity.payload?.consumedTokenId || "",
    sourceTokenName: metadata.name,
    actorPlayerId: activity.actorPlayerId,
    actorPlayerName: draft.actor?.name || ""
  };
  let resolution = null;
  if (metadata.id === "restrict-token") {
    const targetName = String(draft.targetPokemonName || draft.targetText || "").trim();
    const expires = statusExpiresAt(6);
    resolution = controlTokenEffects.resolveRestrict(state, {
      ...source,
      speciesName: targetName,
      targetPlayerId: activity.targetPlayerId || "",
      targetPlayerName: activity.payload?.targetPlayerName || "",
      expiresAtSeries: expires.expiresAtSeries,
      expiresAtGym: expires.expiresAtGym,
      hasLegacyRestriction: currentPokemonRuleStatusByName(targetName) === "Restricted",
      selectedTargetType: activity.payload?.selectedTargetType,
      applicationScope: activity.payload?.applicationScope,
      affectedEntityType: activity.payload?.affectedEntityType,
      selectedRosterInstanceIds: activity.payload?.selectedRosterInstanceIds || [],
      affectedRosterInstanceIds: activity.payload?.affectedRosterInstanceIds || [],
      excludedRosterInstanceIds: activity.payload?.excludedRosterInstanceIds || [],
      sourceEffectId: activity.id
    }, options);
    if (resolution.result === "resolved") {
      recordPokemonRuleChange(targetName, "Restricted", `${draft.actor?.name || "A player"} used ${metadata.name}.`, {
        sourceType: "token",
        sourceTokenId: source.sourceTokenId,
        sourceTokenName: metadata.name,
        sourceStatusId: resolution.status.id,
        durationGyms: 6,
        expiresAtSeries: resolution.status.expiresAtSeries,
        expiresAtGym: resolution.status.expiresAtGym,
        applicationScope: resolution.status.applicationScope,
        excludedRosterInstanceIds: resolution.status.excludedRosterInstanceIds
      });
    }
  } else if (metadata.id === "arena-trap") {
    resolution = controlTokenEffects.resolveArenaTrap(state, {
      ...source,
      targetPokemonId: draft.targetPokemonId,
      sourceEffectId: activity.id
    }, options);
    if (resolution.result === "resolved") addPokemonLog(resolution.pokemon, "Arena Trap", "Must be brought this Battle Phase; cannot be cursed while trapped.");
  } else if (metadata.id === "clear-smog") {
    resolution = controlTokenEffects.resolveClearSmog(state, {
      ...source,
      targetPokemonId: draft.targetPokemonId,
      sourceEffectId: activity.id
    }, options);
    if (resolution.result === "resolved") addPokemonLog(resolution.pokemon, "Clear Smog", resolution.reason);
  } else if (metadata.id === "extra-ban-token") {
    const targetName = String(draft.targetPokemonName || draft.targetText || "").trim();
    resolution = controlTokenEffects.resolveExtraBan(state, {
      ...source,
      targetPokemonId: draft.targetPokemonId,
      selectedRosterInstanceId: activity.payload?.selectedRosterInstanceId || draft.targetPokemonId,
      selectedSpeciesId: activity.payload?.selectedSpeciesId || pokemonRuleKey(targetName),
      selectedRosterInstanceIds: activity.payload?.selectedRosterInstanceIds || [draft.targetPokemonId].filter(Boolean),
      affectedRosterInstanceIds: activity.payload?.affectedRosterInstanceIds || [],
      excludedRosterInstanceIds: activity.payload?.excludedRosterInstanceIds || [],
      sourceEffectId: activity.id,
      hasLegacyBan: currentPokemonRuleStatusByName(targetName) === "Banned"
    }, options);
    if (resolution.result === "resolved") {
      recordPokemonRuleChange(targetName, "Banned", `${draft.actor?.name || "A player"} used ${metadata.name}.`, {
        sourceType: "token",
        sourceTokenId: source.sourceTokenId,
        sourceTokenName: metadata.name,
        sourceStatusId: resolution.status.id,
        applicationScope: resolution.status.applicationScope,
        selectedRosterInstanceId: resolution.status.selectedRosterInstanceId,
        selectedSpeciesId: resolution.status.selectedSpeciesId
      });
    }
  } else if (metadata.id === "unban-token") {
    const targetName = String(draft.targetPokemonName || draft.targetText || "").trim();
    const previousRuleStatus = currentPokemonRuleStatusByName(targetName);
    const expires = statusExpiresAt(6);
    resolution = controlTokenEffects.resolveUnban(state, {
      ...source,
      speciesName: targetName,
      eventId: activity.id,
      selectedStatusId: activity.payload?.selectedStatusId || draft.selectedStatusId || "",
      hasLegacyRestriction: ["Banned", "Restricted"].includes(previousRuleStatus),
      expiresAtSeries: expires.expiresAtSeries,
      expiresAtGym: expires.expiresAtGym
    }, options);
    if (resolution.result === "resolved") {
      recordPokemonRuleChange(targetName, "Unbanned", `${draft.actor?.name || "A player"} used ${metadata.name}.`, {
        sourceType: "token",
        sourceTokenId: source.sourceTokenId,
        sourceTokenName: metadata.name,
        sourceStatusId: resolution.status.id,
        durationGyms: 6,
        expiresAtSeries: resolution.status.expiresAtSeries,
        expiresAtGym: resolution.status.expiresAtGym
      });
    }
  } else if (metadata.id === "rage-candy-bar") {
    const expires = statusExpiresAt(2);
    resolution = controlTokenEffects.resolveRageCandyBar(state, {
      ...source,
      targetPokemonId: draft.targetPokemonId,
      requiredOwnerPlayerId: activity.actorPlayerId,
      expiresAtSeries: expires.expiresAtSeries,
      expiresAtGym: expires.expiresAtGym
    }, options);
    if (resolution.result === "resolved" && resolution.buffIds.length) {
      addPokemonLog(resolution.pokemon, "Rage Candy Bar", resolution.extended
        ? "Shared Rage Candy duration extended by 2 Gyms; bonuses did not stack."
        : "+3 Levels; EV Cap +252; Restrict Immune for 2 Gyms");
    }
  }
  if (!resolution) return null;
  syncPlayerPokemonLists();
  return {
    result: resolution.result,
    details: [resolution.reason].filter(Boolean),
    mutations: [
      ...(resolution.removedStatusIds || []).map((id) => `Removed status ${id}`),
      ...(resolution.removedEffectBuffIds || []).map((id) => `Removed Pokemon buff ${id}`),
      ...(resolution.removedMoveGrantIds || []).map((id) => `Removed move-access grant ${id}`),
      ...(resolution.removedBuffLabels || []).map((label) => `Removed buff ${label}`),
      ...(resolution.buffIds || []).map((id) => `${resolution.extended ? "Retained" : "Created"} timed buff ${id}`),
      ...(resolution.statusIds || []).map((id) => `Created status ${id}`)
    ],
    persistentStateIds: [...(resolution.statusIds || []), ...(resolution.buffIds || [])],
    resultData: {
      createdStatusIds: resolution.statusIds || [],
      affectedRosterInstanceIds: resolution.status?.affectedRosterInstanceIds || [resolution.pokemon?.id].filter(Boolean),
      teamMutation: resolution.teamMutation || null,
      compensationStatus: resolution.compensationStatus || "",
      customization: resolution.customization || null,
      grantedCustomizations: resolution.grantedCustomizations || []
    }
  };
}

function applyAutomaticStatusTokenActivity(activity, metadata) {
  const definition = statusTokenDefinitionByName(metadata.name);
  if (!definition) return null;
  const draft = tokenDraftFromActivity(activity);
  const targetPokemon = draft.targetPokemonId
    ? (state.pokemonRecords || []).find((pokemon) => pokemon.id === draft.targetPokemonId)
    : null;
  const targetName = targetPokemon?.name || draft.targetPokemonName || draft.targetText;
  const applicationScope = activity.payload?.applicationScope || metadata.applicationScope
    || (draft.targetScope === EFFECT_TARGET_SCOPES.SPECIES ? EFFECT_APPLICATION_SCOPES.GLOBAL_SPECIES : EFFECT_APPLICATION_SCOPES.ROSTER_INSTANCE);
  const affectedRosterInstanceIds = activity.payload?.affectedRosterInstanceIds || [targetPokemon?.id].filter(Boolean);
  const excludedRosterInstanceIds = activity.payload?.excludedRosterInstanceIds || [];
  if (metadata.revalidateOnResolution && metadata.targetType === EFFECT_TARGET_TYPES.POKEMON && !targetName) {
    return { result: "noEffect", details: ["The target Pokemon no longer exists or was not recorded."], mutations: [], persistentStateIds: [] };
  }
  if (metadata.timingCategory === TOKEN_TIMING_CATEGORIES.CURSE && targetPokemon
    && controlTokenEffects?.pokemonHasArenaTrap?.(state, targetPokemon, controlTokenEffectOptions())) {
    return { result: "noEffect", details: [`${targetPokemon.name} is Arena Trapped and cannot be cursed.`], mutations: [], persistentStateIds: [] };
  }
  if (["ban", "restrict"].includes(definition.statusType)
    && controlTokenEffects?.speciesHasUnbanProtection(state, targetName, controlTokenEffectOptions())) {
    return {
      result: "noEffect",
      details: [`${targetName} is protected from Ban and Restrict by Unban.`],
      mutations: [],
      persistentStateIds: []
    };
  }
  if (definition.statusType === "ban"
    && controlTokenEffects?.speciesHasBanPhaseProtection(state, targetName, controlTokenEffectOptions())) {
    return {
      result: "noEffect",
      details: [`${targetName} cannot be banned again during this phase because Substitute protected it.`],
      mutations: [],
      persistentStateIds: []
    };
  }
  if (applicationScope !== EFFECT_APPLICATION_SCOPES.GLOBAL_SPECIES
    && affectedRosterInstanceIds.length
    && affectedRosterInstanceIds.every((id) => excludedRosterInstanceIds.includes(id))) {
    return {
      result: "resolved",
      details: [`Substitute exempted the selected roster instance from ${metadata.name}.`],
      mutations: [`Excluded roster instance ${affectedRosterInstanceIds.join(", ")}`],
      persistentStateIds: []
    };
  }
  const now = new Date().toISOString();
  const removedStatusIds = [];
  if (definition.statusType === "unban-protection") {
    activeLingeringStatuses({ pokemonNameKey: pokemonRuleKey(targetName) })
      .filter((status) => ["ban", "restrict"].includes(status.type))
      .forEach((status) => {
        status.status = "removed";
        status.removedAt = now;
        status.removedByEventId = activity.id;
        removedStatusIds.push(status.id);
      });
  }
  const expires = statusExpiresAt(definition.durationGyms);
  const status = applyLingeringEffect({
    type: definition.statusType,
    name: definition.statusName || definition.label || metadata.name,
    category: metadata.timingCategory,
    isCurse: metadata.timingCategory === TOKEN_TIMING_CATEGORIES.CURSE,
    sourceTokenId: activity.payload?.consumedTokenId || "",
    sourceTokenName: metadata.name,
    actorPlayerId: activity.actorPlayerId,
    actorPlayerName: draft.actor?.name || "",
    targetPlayerId: targetPokemon?.trainerId || activity.targetPlayerId || "",
    targetPlayerName: livePlayerName(targetPokemon?.trainerId || activity.targetPlayerId, ""),
    targetPokemonId: applicationScope === EFFECT_APPLICATION_SCOPES.GLOBAL_SPECIES ? "" : targetPokemon?.id || "",
    targetPokemonName: targetName,
    targetPokemonNameKey: pokemonRuleKey(targetName),
    selectedTargetType: activity.payload?.selectedTargetType || metadata.selectedTargetType || draft.targetType,
    applicationScope,
    affectedEntityType: activity.payload?.affectedEntityType || metadata.affectedEntityType || draft.targetType,
    selectedRosterInstanceId: activity.payload?.selectedRosterInstanceId || targetPokemon?.id || "",
    selectedSpeciesId: activity.payload?.selectedSpeciesId || pokemonRuleKey(targetName),
    speciesId: activity.payload?.speciesId || pokemonRuleKey(targetName),
    selectedRosterInstanceIds: activity.payload?.selectedRosterInstanceIds || [targetPokemon?.id].filter(Boolean),
    affectedRosterInstanceIds,
    excludedRosterInstanceIds,
    substituteInterceptionPolicy: activity.payload?.substituteInterceptionPolicy || metadata.substituteInterceptionPolicy || "",
    substituteChecksSelectedTargetOnly: activity.payload?.substituteChecksSelectedTargetOnly ?? metadata.substituteChecksSelectedTargetOnly,
    sourceEffectId: activity.id,
    sourcePlayerId: activity.actorPlayerId,
    duration: metadata.duration,
    durationGyms: definition.durationGyms || null,
    expiresAtSeries: expires.expiresAtSeries,
    expiresAtGym: expires.expiresAtGym,
    payload: {
      ...structuredClone(definition.payload || {}),
      selectedTargetType: activity.payload?.selectedTargetType || metadata.selectedTargetType || draft.targetType,
      applicationScope,
      affectedEntityType: activity.payload?.affectedEntityType || metadata.affectedEntityType || draft.targetType,
      selectedRosterInstanceId: activity.payload?.selectedRosterInstanceId || targetPokemon?.id || "",
      selectedSpeciesId: activity.payload?.selectedSpeciesId || pokemonRuleKey(targetName),
      selectedRosterInstanceIds: activity.payload?.selectedRosterInstanceIds || [targetPokemon?.id].filter(Boolean),
      affectedRosterInstanceIds,
      excludedRosterInstanceIds,
      substituteInterceptionPolicy: activity.payload?.substituteInterceptionPolicy || metadata.substituteInterceptionPolicy || "",
      substituteChecksSelectedTargetOnly: activity.payload?.substituteChecksSelectedTargetOnly ?? metadata.substituteChecksSelectedTargetOnly,
      sourceEffectId: activity.id,
      sourcePlayerId: activity.actorPlayerId
    },
    note: definition.note || metadata.rulesText,
    createdAt: now
  });
  if (["ban", "restrict"].includes(definition.statusType)) {
    recordPokemonRuleChange(targetName, definition.statusType === "ban" ? "Banned" : "Restricted", `${draft.actor?.name || "A player"} used ${metadata.name}.`, {
      sourceType: "token",
      sourceTokenId: activity.payload?.consumedTokenId || "",
      sourceTokenName: metadata.name,
      sourceStatusId: status.id,
      durationGyms: definition.durationGyms || null,
      expiresAtSeries: status.expiresAtSeries,
      expiresAtGym: status.expiresAtGym,
      applicationScope: status.applicationScope,
      excludedRosterInstanceIds: status.excludedRosterInstanceIds
    });
  } else if (definition.statusType === "unban-protection") {
    recordPokemonRuleChange(targetName, "Unbanned", `${draft.actor?.name || "A player"} used ${metadata.name}.`, {
      sourceType: "token",
      sourceTokenId: activity.payload?.consumedTokenId || "",
      sourceTokenName: metadata.name,
      sourceStatusId: status.id,
      durationGyms: definition.durationGyms || null,
      expiresAtSeries: status.expiresAtSeries,
      expiresAtGym: status.expiresAtGym
    });
  }
  return {
    result: "resolved",
    details: [
      `${metadata.name} applied to ${targetName || livePlayerName(activity.targetPlayerId, "the target")}.`,
      definition.note || metadata.rulesText,
      removedStatusIds.length ? `Removed ${removedStatusIds.length} prior Ban/Restrict status${removedStatusIds.length === 1 ? "" : "es"}.` : ""
    ].filter(Boolean),
    mutations: [...removedStatusIds.map((id) => `Removed status ${id}`), `Created status ${status.id}`],
    persistentStateIds: [status.id]
  };
}

function applyAutomaticUtilityTokenActivity(activity, metadata) {
  const definition = utilityTokenDefinitionByName(metadata.name);
  if (!definition) return null;
  const draft = tokenDraftFromActivity(activity);
  const actor = draft.actor;
  const targetPlayer = draft.target || state.players.find((player) => player.id === activity.targetPlayerId);
  const pokemon = (state.pokemonRecords || []).find((record) => record.id === draft.targetPokemonId);
  if (metadata.id === "embargo" && targetPlayer && hasProtectionAgainst(state, targetPlayer.id, { protectionKeys: ["embargo"] })) {
    return {
      result: "blocked",
      details: [`${targetPlayer.name} is unaffected by Embargo because Safeguard is active.`],
      mutations: [],
      persistentStateIds: [],
      resultData: { protectionResult: "blockedBySafeguard", affectedPlayerIds: [targetPlayer.id] }
    };
  }
  if (metadata.targetType === EFFECT_TARGET_TYPES.POKEMON && !pokemon) {
    return { result: "noEffect", details: ["The selected owned Pokemon is no longer available."], mutations: [], persistentStateIds: [] };
  }
  const mutations = [];
  const persistentStateIds = [];
  if (definition.effectType === "add-buffs") {
    pokemon.buffs = [...new Set([...(pokemon.buffs || []), ...(definition.buffs || [])])];
    mutations.push(`Added buffs to ${pokemon.name}: ${(definition.buffs || []).join(", ")}`);
    (definition.lingeringStatuses || []).forEach((statusDefinition) => {
      const expires = statusExpiresAt(statusDefinition.durationGyms);
      const status = applyLingeringEffect({
        type: statusDefinition.type,
        name: statusDefinition.name,
        category: metadata.timingCategory,
        sourceTokenId: activity.payload?.consumedTokenId || "",
        sourceTokenName: metadata.name,
        actorPlayerId: actor?.id || "",
        actorPlayerName: actor?.name || "",
        targetPlayerId: pokemon.trainerId,
        targetPlayerName: livePlayerName(pokemon.trainerId, ""),
        targetPokemonId: pokemon.id,
        targetPokemonName: pokemon.name,
        targetPokemonNameKey: pokemonRuleKey(pokemon.name),
        durationGyms: statusDefinition.durationGyms || null,
        expiresAtSeries: expires.expiresAtSeries,
        expiresAtGym: expires.expiresAtGym,
        payload: structuredClone(statusDefinition.payload || {})
      });
      persistentStateIds.push(status.id);
    });
  } else if (definition.effectType === "add-nerfs") {
    pokemon.nerfs = [...new Set([...(pokemon.nerfs || []), ...(definition.nerfs || [])])];
    mutations.push(`Added marker to ${pokemon.name}: ${(definition.nerfs || []).join(", ")}`);
  } else if (definition.effectType === "clear-buffs") {
    const removedEffectBuffs = (pokemon.effectBuffs || []).filter((buff) => buff.clearable !== false
      && !["removed", "expired", "replaced", "consumed"].includes(buff.status));
    const removedLabels = new Set(removedEffectBuffs.map((buff) => buff.label).filter(Boolean));
    removedEffectBuffs.forEach((buff) => {
      buff.status = "removed";
      buff.removedAt = new Date().toISOString();
      buff.removedByEffectId = activity.id;
    });
    const labelsStillActive = new Set((pokemon.effectBuffs || [])
      .filter((buff) => !["removed", "expired", "replaced", "consumed"].includes(buff.status))
      .map((buff) => buff.label));
    pokemon.buffs = (pokemon.buffs || []).filter((label) => !removedLabels.has(label) || labelsStillActive.has(label));
    mutations.push(`Removed ${removedEffectBuffs.length} structured buff record${removedEffectBuffs.length === 1 ? "" : "s"} from ${pokemon.name}`);
  } else if (definition.effectType === "steal-pokemon") {
    const previousOwner = state.players.find((player) => player.id === pokemon.trainerId);
    if (!actor || previousOwner?.id === actor.id) return { result: "noEffect", details: ["Steal cannot transfer the acting player's own Pokemon."], mutations: [], persistentStateIds: [] };
    pokemon.trainerId = actor.id;
    pokemon.status = "Active";
    pokemon.rosterType = "Active";
    mutations.push(`Transferred ${pokemon.name} from ${previousOwner?.name || "Unknown"} to ${actor.name}`);
  } else if (definition.effectType === "player-buff" && targetPlayer) {
    targetPlayer.buffs = [...new Set([...(targetPlayer.buffs || []), definition.buff])];
    mutations.push(`Added ${definition.buff} to ${targetPlayer.name}`);
  } else if (definition.effectType === "player-nerf" && targetPlayer) {
    targetPlayer.nerfs = [...new Set([...(targetPlayer.nerfs || []), definition.nerf])];
    mutations.push(`Added ${definition.nerf} to ${targetPlayer.name}`);
  } else {
    return null;
  }
  syncPlayerPokemonLists();
  return {
    result: mutations.length ? "resolved" : "noEffect",
    details: mutations.length ? mutations : [metadata.rulesText],
    mutations,
    persistentStateIds
  };
}

function applyGuidedTokenActivity(activity, metadata, resolutionText = "") {
  const resultText = String(resolutionText || "").trim();
  if (!resultText) return null;
  return {
    result: "resolved",
    details: [resultText, `${metadata.name} was completed through its guided host result.`],
    mutations: ["Guided host result recorded"],
    persistentStateIds: []
  };
}

function tokenResolutionFailureOutcome(activity, metadata, resolution) {
  if (resolution?.refundRequired || resolution?.result === "systemFailure") {
    const reason = resolution.details?.join(" ") || `${metadata.name} could not resolve against the saved declaration.`;
    const refundedCount = refundTokenConsumptionsForLink({ eventId: activity.id }, reason);
    const recorded = recordTokenContractResolution(activity, metadata, {
      result: "canceledRefunded",
      details: [
        reason,
        refundedCount
          ? `${refundedCount} Token${refundedCount === 1 ? " was" : "s were"} refunded.`
          : "No refundable Token record was found."
      ],
      mutations: []
    });
    activity.payload.tokenEffectBlocked = true;
    return {
      blocked: true,
      finalOutcome: "canceledRefunded",
      auditId: recorded.audit.id,
      announcementDetail: `${metadata.name} was canceled because its saved declaration was no longer valid. ${refundedCount ? "The Token was refunded." : "The refund requires host repair."}`,
      resultData: {
        refundedTokenCount: refundedCount,
        operations: []
      }
    };
  }
  if (resolution?.result === "blocked") {
    const recorded = recordTokenContractResolution(activity, metadata, resolution);
    activity.payload.tokenEffectBlocked = true;
    return {
      blocked: true,
      finalOutcome: "blocked",
      auditId: recorded.audit.id,
      announcementDetail: resolution.details?.join(" ") || `${metadata.name} was blocked.`,
      resultData: resolution.resultData || { operations: [] }
    };
  }
  return null;
}

function applyResolvedTokenPendingEvent(activity, { resolutionText = "" } = {}) {
  if (!activity || activity.status !== "open" || activity.sourceType !== "token-use") return null;
  if (activity.payload?.appliedTokenEffectId || activity.payload?.tokenEffectBlocked) return null;
  const tokenName = activity.payload?.tokenName || "";
  const metadata = tokenEffectMetadataByName(tokenName);
  const usability = tokenRuntimeUsabilityCheck(metadata);
  if (!usability.ok) return { blocked: true, failClosed: true, announcementDetail: usability.reason };
  const blockingResponses = tokenPendingEventNegations(activity);
  if (blockingResponses.length) {
    activity.payload.tokenEffectBlocked = true;
    const blockedBy = blockingResponses.map((response) => response.tokenName || response.type).join(", ");
    recordTokenContractResolution(activity, metadata, {
      result: "negated",
      details: [`Pending event: ${activity.title}`, `Negated by: ${blockedBy}`],
      mutations: ["Parent effect marked negated"]
    });
    return {
      blocked: true,
      finalOutcome: "negated",
      resolvedByEffectId: blockingResponses[blockingResponses.length - 1]?.id || "",
      announcementDetail: `${tokenName || activity.title} was negated by ${blockedBy}.`,
      resultData: { preventedMutationTypes: [metadata.resolverId || metadata.name || "effectMutation"] }
    };
  }
  if (activity.payload?.teleportDelayedEffectId) {
    const delayedRecord = (state.delayedEffects || []).find((record) => record.id === activity.payload.teleportDelayedEffectId);
    const validation = delayedRecord
      ? teleportReturnRevalidation(delayedRecord, activity)
      : { ok: false, classification: "unsupported", reason: "The authoritative Teleport delayed-effect record is missing." };
    if (!validation.ok) {
      const gameplayIllegal = validation.classification === "gameplay";
      const refundedCount = gameplayIllegal || !delayedRecord
        ? 0
        : refundTokenConsumptionsByIds(teleportDelayedConsumptionIds(delayedRecord), validation.reason);
      if (delayedRecord) {
        delayedRecord.status = gameplayIllegal ? "resolvedNoEffect" : "canceledRefunded";
        delayedRecord.resolvedAt = new Date().toISOString();
        delayedRecord.resolutionReason = validation.reason;
        delayedRecord.refundRequired = !gameplayIllegal;
      }
      activity.payload.tokenEffectBlocked = true;
      const recorded = recordTokenContractResolution(activity, metadata, {
        result: gameplayIllegal ? "noEffect" : "canceledRefunded",
        details: [
          validation.reason,
          gameplayIllegal
            ? "The original declaration was not retargeted. Both confirmed Tokens remain consumed."
            : `${refundedCount} exact Token consumption record${refundedCount === 1 ? " was" : "s were"} refunded.`
        ],
        mutations: []
      });
      return {
        blocked: true,
        finalOutcome: gameplayIllegal ? "resolvedNoEffect" : "canceledRefunded",
        auditId: recorded.audit.id,
        announcementDetail: gameplayIllegal
          ? `${metadata.name} returned through Teleport but was no longer legal, so it had no effect.`
          : `${metadata.name} could not return safely. The delayed declaration and Teleport were canceled and refunded.`,
        resultData: {
          delayedEffectId: delayedRecord?.id || activity.payload.teleportDelayedEffectId,
          refundedTokenCount: refundedCount,
          operations: []
        }
      };
    }
  }
  if (tokenControlController?.CONTROL_TOKEN_IDS?.includes(metadata.id)) {
    const revalidation = tokenControlController.validateResolutionState?.(state, activity, controlTokenEffectOptions());
    if (revalidation && !revalidation.ok) {
      return tokenResolutionFailureOutcome(activity, metadata, {
        result: revalidation.refund ? "systemFailure" : "blocked",
        refundRequired: Boolean(revalidation.refund),
        details: [revalidation.reason].filter(Boolean),
        mutations: [],
        resultData: {
          protectionResult: revalidation.protectionResult || "",
          operations: []
        }
      });
    }
  }
  const interception = applySubstituteInterceptionBeforeMutation(activity, metadata);
  if (interception?.negateEntireEffect) {
    activity.payload.tokenEffectBlocked = true;
    const details = [interception.reason, "The species-wide Ban was not created."];
    recordTokenContractResolution(activity, metadata, {
      result: "negated",
      details,
      mutations: [
        ...(interception.consumedStatusIds || []).map((id) => `Consumed Substitute ${id}`),
        ...(interception.createdStatusIds || []).map((id) => `Created current-phase Ban protection ${id}`)
      ],
      persistentStateIds: [...(interception.consumedStatusIds || []), ...(interception.createdStatusIds || [])]
    });
    return {
      blocked: true,
      finalOutcome: "negated",
      resolvedByEffectId: interception.consumedStatusIds?.[0] || "",
      statusId: interception.createdStatusIds?.[0] || "",
      announcementDetail: interception.reason,
      resultData: {
        createdStatusIds: interception.createdStatusIds || [],
        preventedMutationTypes: ["globalSpeciesBan"],
        affectedRosterInstanceIds: [],
        excludedRosterInstanceIds: [activity.payload?.selectedRosterInstanceId || activity.payload?.targetPokemonId].filter(Boolean),
        consumedSubstituteStatusIds: interception.consumedStatusIds || [],
        responseEffects: (interception.consumedStatusIds || []).map((effectId) => {
          const substitute = (state.lingeringStatuses || []).find((status) => status.id === effectId);
          return { effectId, effectName: "Substitute", actorId: substitute?.targetPlayerId || "", outcome: "resolved" };
        })
      }
    };
  }
  if (metadata.id === "steal-token" && interception?.result === "intercepted") {
    activity.payload.tokenEffectBlocked = true;
    recordTokenContractResolution(activity, metadata, {
      result: "negated",
      details: [interception.reason, "Ownership did not change."],
      mutations: (interception.consumedStatusIds || []).map((id) => `Consumed Substitute ${id}`),
      persistentStateIds: interception.consumedStatusIds || []
    });
    return {
      blocked: true,
      finalOutcome: "negated",
      resolvedByEffectId: interception.consumedStatusIds?.[0] || "",
      announcementDetail: interception.reason,
      resultData: {
        operations: [],
        affectedRosterInstanceIds: [],
        excludedRosterInstanceIds: [activity.payload?.selectedRosterInstanceId].filter(Boolean),
        consumedSubstituteStatusIds: interception.consumedStatusIds || []
      }
    };
  }
  let resolution = applyAutomaticControlFoundationActivity(activity, metadata);
  if (!resolution) resolution = applyAutomaticSafeguardActivity(activity, metadata);
  if (!resolution && metadata.resolverId === "statusEffect") resolution = applyAutomaticStatusTokenActivity(activity, metadata);
  if (!resolution && ["utilityEffect", "playerStatus"].includes(metadata.resolverId)) resolution = applyAutomaticUtilityTokenActivity(activity, metadata);
  if (!resolution && metadata.resolutionMode === EFFECT_RESOLUTION_MODES.GUIDED) resolution = applyGuidedTokenActivity(activity, metadata, resolutionText);
  if (!resolution && metadata.resolutionMode === EFFECT_RESOLUTION_MODES.HOST_CONFIRMED && resolutionText) {
    resolution = {
      result: "resolved",
      details: [resolutionText, metadata.hostTask?.websiteRecords].filter(Boolean),
      mutations: ["Host-confirmed external resolution recorded"],
      persistentStateIds: []
    };
  }
  if (!resolution) return null;
  const failedResolution = tokenResolutionFailureOutcome(activity, metadata, resolution);
  if (failedResolution) return failedResolution;
  if (interception?.result === "intercepted") {
    resolution.details = [interception.reason, ...(resolution.details || [])].filter(Boolean);
    resolution.mutations = [
      ...(interception.consumedStatusIds || []).map((id) => `Consumed Substitute ${id}`),
      ...(interception.rageImmuneRosterInstanceIds || []).map((id) => `Applied Rage Candy Restrict immunity before Substitute for ${id}`),
      ...(interception.curseImmuneRosterInstanceIds || []).map((id) => `Applied exact-instance Curse Immunity for ${id}`),
      ...(resolution.mutations || [])
    ];
    resolution.persistentStateIds = [...new Set([
      ...(interception.consumedStatusIds || []),
      ...(interception.createdStatusIds || []),
      ...(resolution.persistentStateIds || [])
    ])];
  }
  const draft = tokenDraftFromActivity(activity, resolutionText);
  const activation = createTokenActivationRecord({
    consumedToken: { id: activity.payload?.consumedTokenId || "", name: tokenName },
    metadata,
    draft,
    statusIds: resolution.persistentStateIds || [],
    details: resolution.details || []
  });
  (resolution.resultData?.operations || []).forEach((operation) => {
    operation.sourceActivationId ||= activation.id;
    const persisted = (state.effectOperations || []).find((entry) => entry.id === operation.id);
    if (persisted) persisted.sourceActivationId ||= activation.id;
  });
  activity.payload.appliedTokenEffectId = activation.id;
  activity.payload.createdEffectId = resolution.persistentStateIds?.[0] || "";
  const recorded = recordTokenContractResolution(activity, metadata, {
    ...resolution,
    hostConfirmation: metadata.resolutionMode === EFFECT_RESOLUTION_MODES.HOST_CONFIRMED ? resolutionText : ""
  });
  return {
    blocked: false,
    finalOutcome: resolution.result === "noEffect" ? "resolvedNoEffect"
      : interception?.result === "intercepted" ? "partiallyResolved"
        : "resolved",
    activationId: activation.id,
    auditId: recorded.audit.id,
    statusId: resolution.persistentStateIds?.[0] || "",
    announcementDetail: (resolution.details || []).join(" ") || `${metadata.name} resolved.`,
    resultData: {
      ...(resolution.resultData || {}),
      createdStatusIds: resolution.resultData?.createdStatusIds || resolution.persistentStateIds || [],
      affectedRosterInstanceIds: resolution.resultData?.affectedRosterInstanceIds
        || interception?.affectedRosterInstanceIds
        || activity.payload?.affectedRosterInstanceIds
        || [],
      excludedRosterInstanceIds: interception?.excludedRosterInstanceIds
        || resolution.resultData?.excludedRosterInstanceIds
        || activity.payload?.excludedRosterInstanceIds
        || [],
      consumedSubstituteStatusIds: interception?.consumedStatusIds || []
    }
  };
}

function tokenUseOptionRows(selectedName = "") {
  const seen = new Set();
  const add = (rows, tokenName, suffix = "") => {
    const name = displayInventoryTokenName(tokenName || "");
    const key = slugify(name);
    if (!key || seen.has(key)) return;
    seen.add(key);
    const definition = tokenTimingDefinitionByName(name);
    const category = tokenTimingCategoryFromRaw(definition?.timingCategory);
    rows.push(`<option value="${escapeHtml(name)}" data-token-category="${escapeHtml(category)}" ${name === selectedName ? "selected" : ""}>${escapeHtml(name)}${suffix}</option>`);
  };
  const rows = [`<option value="">Choose token</option>`];
  state.players.forEach((player) => {
    (player.inventory || [])
      .filter((item) => (itemIsTokenLike(item) || item.type === "TOKEN") && !isKeyItemTicket(item))
      .forEach((item) => add(rows, item.name, " (owned)"));
  });
  activeTokenCatalog().filter((item) => !isKeyItemTicket(item)).forEach((item) => add(rows, item.name));
  return rows.join("");
}

function tokenTimingCategoryOptions(selected = "") {
  return [
    [TOKEN_TIMING_CATEGORIES.CONTROL, "Control Token"],
    [TOKEN_TIMING_CATEGORIES.PROTECTION, "Protection Token"],
    [TOKEN_TIMING_CATEGORIES.ENCOUNTER, "Encounter Token"],
    [TOKEN_TIMING_CATEGORIES.CURSE, "Curse Token"],
  ].map(([value, label]) => `<option value="${escapeHtml(value)}" ${value === selected ? "selected" : ""}>${escapeHtml(label)}</option>`).join("");
}

