let pokemonFamilyTierCache = {};
const pendingPokemonFamilyTierLookups = new Set();
const pendingPokemonSpriteBackfills = new Set();
const pokemonIndexSpriteCache = {};
const pendingPokemonIndexSpriteLookups = new Set();
let pokemonIndexSpriteObserver = null;

function getPokemonSpriteLookupKey(name, targetState = state) {
  const key = normalizePokemonApiName(name);
  const indexKey = getPokemonIndexKey(name);
  return targetState.spriteAliases?.[key]
    || targetState.spriteAliases?.[indexKey]
    || spriteAliasMap[key]
    || spriteAliasMap[indexKey]
    || indexKey
    || key;
}

function pokemonSpriteVariantDefinition(name, targetState = state) {
  return getPokemonSpriteVariantPolicy(name, targetState);
}

function choosePokemonSpriteLookupKey(name, targetState = state) {
  const variant = pokemonSpriteVariantDefinition(name, targetState);
  const spriteKeys = (variant?.spriteKeys || []).filter(Boolean);
  if (variant?.randomSprite && spriteKeys.length) {
    return spriteKeys[Math.floor(Math.random() * spriteKeys.length)];
  }
  return getPokemonSpriteLookupKey(name, targetState);
}

function getPokemonRollPoolTier(name) {
  const key = getPokemonIndexKey(name) || normalizePokemonName(name);
  const override = pokemonTierOverrideFor(key);
  const overrideFamily = normalizeAcquisitionFamilyId(override?.acquisitionTier || override?.gameCornerTier || "");
  if (overrideFamily) return overrideFamily;
  const battleEntry = getPokemonBattleTierEntry(key) || getPokemonBattleTierEntry(name);
  return acquisitionFamilyIdFromBattleTier(battleEntry?.balanceTier || battleEntry?.balanceTierLabel || "")
    || normalizeAcquisitionFamilyId(rivalSagaPokemonTierMap[key]?.tier || rivalSagaPokemonTierMap[normalizePokemonName(name)]?.tier)
    || "";
}

function getPokemonFamilyAcquisitionTier(name) {
  const key = normalizePokemonName(name);
  const directTier = getPokemonRollPoolTier(key);
  if (directTier) return directTier;
  const cachedTier = pokemonFamilyTierCache[key]?.tier || "";
  if (cachedTier) return cachedTier;
  const familyKey = evolutionFamilyTierAliasMap[key]
    || evolutionFamilyTierAliasMap[spriteAliasMap[key]]
    || supplementalEvolutionFamilyTierAliasMap[key]
    || supplementalEvolutionFamilyTierAliasMap[spriteAliasMap[key]]
    || "";
  return familyKey ? getPokemonRollPoolTier(familyKey) : "";
}

function getPokemonAcquisitionTier(pokemonName) {
  return getPokemonFamilyAcquisitionTier(pokemonName);
}

function getPokemonMegaBaseKey(name) {
  const key = getPokemonIndexKey(name) || normalizePokemonName(name);
  if (!key) return "";
  if (key.endsWith("-mega-x") || key.endsWith("-mega-y")) return key.replace(/-mega-(x|y)$/, "");
  if (key.endsWith("-mega")) return key.replace(/-mega$/, "");
  if (key.startsWith("mega-")) return key.replace(/^mega-/, "").replace(/-(x|y)$/, "");
  return "";
}

function getPokemonUnlockTierInfo(name) {
  const key = getPokemonIndexKey(name) || normalizePokemonName(name);
  const aliasKey = spriteAliasMap[key] || key;
  const directTier = getPokemonRollPoolTier(key) || getPokemonRollPoolTier(aliasKey);
  if (directTier) {
    return {
      tier: directTier,
      sourceKey: key,
      sourceName: getRivalSagaPokemonDisplayName(key),
      direct: true
    };
  }
  const megaBaseKey = getPokemonMegaBaseKey(key) || getPokemonMegaBaseKey(aliasKey);
  if (megaBaseKey) {
    const megaBaseTier = getPokemonFamilyAcquisitionTier(megaBaseKey) || getPokemonRollPoolTier(megaBaseKey);
    if (megaBaseTier) {
      return {
        tier: megaBaseTier,
        sourceKey: megaBaseKey,
        sourceName: getRivalSagaPokemonDisplayName(megaBaseKey),
        direct: false
      };
    }
  }
  const cached = pokemonFamilyTierCache[key] || pokemonFamilyTierCache[aliasKey];
  if (cached?.tier) {
    return {
      tier: cached.tier,
      sourceKey: cached.baseName || "",
      sourceName: cached.baseName ? getRivalSagaPokemonDisplayName(cached.baseName) : "family source",
      direct: false
    };
  }
  const familyKey = evolutionFamilyTierAliasMap[key]
    || evolutionFamilyTierAliasMap[aliasKey]
    || supplementalEvolutionFamilyTierAliasMap[key]
    || supplementalEvolutionFamilyTierAliasMap[aliasKey]
    || "";
  const familyTier = familyKey ? getPokemonRollPoolTier(familyKey) : "";
  if (familyTier) {
    return {
      tier: familyTier,
      sourceKey: familyKey,
      sourceName: getRivalSagaPokemonDisplayName(familyKey),
      direct: false
    };
  }
  return { tier: "", sourceKey: "", sourceName: "", direct: false };
}

function getPokemonEvolutionFamilyKey(name) {
  const key = normalizePokemonName(name);
  if (!key) return "";
  const aliasKey = spriteAliasMap[key] || key;
  return evolutionFamilyTierAliasMap[key]
    || evolutionFamilyTierAliasMap[aliasKey]
    || supplementalEvolutionFamilyTierAliasMap[key]
    || supplementalEvolutionFamilyTierAliasMap[aliasKey]
    || pokemonFamilyTierCache[key]?.baseName
    || pokemonFamilyTierCache[aliasKey]?.baseName
    || aliasKey;
}

function playerHasPokemonFamily(playerId, pokemonName) {
  const familyKey = getPokemonEvolutionFamilyKey(pokemonName);
  if (!familyKey) return false;
  return (state.pokemonRecords || []).some((pokemon) => pokemon.trainerId === playerId
    && pokemon.status !== "Released"
    && ["Active", "Legacy"].includes(pokemon.rosterType || "Active")
    && getPokemonEvolutionFamilyKey(pokemon.name) === familyKey);
}

function activeStateOrNull() {
  try {
    return state || null;
  } catch {
    return null;
  }
}

function cachePokemonFamilyTier(name, tier, baseName = "", status = "resolved") {
  const key = normalizePokemonName(name);
  if (!key) return "";
  pokemonFamilyTierCache[key] = {
    tier: normalizeAcquisitionFamilyId(tier),
    baseName,
    status,
    resolvedAt: new Date().toISOString()
  };
  const targetState = activeStateOrNull();
  if (targetState) targetState.pokemonFamilyTierCache = pokemonFamilyTierCache;
  return pokemonFamilyTierCache[key].tier;
}

async function resolvePokemonFamilyAcquisitionTier(name) {
  const key = normalizePokemonName(name);
  if (!key) return "";
  const existing = getPokemonFamilyAcquisitionTier(name);
  if (existing) return cachePokemonFamilyTier(name, existing, key);
  for (const candidate of speciesCandidates(name)) {
    try {
      const species = await fetchPokemonJson(`https://pokeapi.co/api/v2/pokemon-species/${encodeURIComponent(candidate)}`);
      const chain = await fetchPokemonJson(species.evolution_chain?.url);
      const baseName = chain?.chain?.species?.name || "";
      const baseKey = normalizePokemonName(baseName);
      const tier = getPokemonRollPoolTier(baseKey) || getPokemonFamilyAcquisitionTier(baseKey);
      if (tier) return cachePokemonFamilyTier(name, tier, baseKey);
    } catch {
      // Try the next candidate before marking the family tier unresolved.
    }
  }
  return cachePokemonFamilyTier(name, "", "", "unresolved");
}

function queuePokemonFamilyTierLookup(name, onResolved = () => {}) {
  const key = normalizePokemonName(name);
  if (!key || getPokemonFamilyAcquisitionTier(name) || pendingPokemonFamilyTierLookups.has(key) || pokemonFamilyTierCache[key]?.status === "unresolved") return;
  pendingPokemonFamilyTierLookups.add(key);
  resolvePokemonFamilyAcquisitionTier(name).then((tier) => {
    pendingPokemonFamilyTierLookups.delete(key);
    if (tier) {
      const targetState = activeStateOrNull();
      if (targetState) {
        (targetState.pokemonRecords || []).forEach((pokemon) => {
          if (normalizePokemonName(pokemon.name) === key && !pokemon.acquisitionTier) pokemon.acquisitionTier = tier;
        });
        saveState();
      }
      onResolved(tier);
    }
  }).catch(() => {
    pendingPokemonFamilyTierLookups.delete(key);
  });
}

function queuePokemonIndexFamilyTierLookups(entries = []) {
  let queued = 0;
  entries.slice(0, 80).forEach((entry) => {
    if (queued >= 20) return;
    const unlockInfo = getPokemonUnlockTierInfo(entry.displayName || entry.indexKey);
    if (unlockInfo.tier) return;
    const key = normalizePokemonName(entry.displayName || entry.indexKey);
    if (!key || pokemonFamilyTierCache[key]?.status === "unresolved" || pendingPokemonFamilyTierLookups.has(key)) return;
    queued += 1;
    queuePokemonFamilyTierLookup(entry.displayName || entry.indexKey, () => renderBanlist());
  });
}

function getPokemonGameCornerMetadata(name) {
  const key = getPokemonIndexKey(name) || normalizePokemonName(name);
  const base = rivalSagaPokemonTierMap[key] || rivalSagaPokemonTierMap[normalizePokemonName(name)] || null;
  const override = pokemonTierOverrideFor(key);
  const battleEntry = getPokemonBattleTierEntry(key) || getPokemonBattleTierEntry(name);
  const tier = normalizeAcquisitionFamilyId(override?.acquisitionTier || override?.gameCornerTier || getPokemonAcquisitionTier(name));
  return {
    ...(base || {}),
    tier,
    acquisitionFamily: tier,
    battleTier: battleEntry?.balanceTier || "",
    battleTierLabel: battleEntry?.balanceTierLabel || "",
    displayName: override?.displayName || battleEntry?.displayName || base?.displayName || getRivalSagaPokemonDisplayName(key)
  };
}

function getPokemonByGameCornerTier(tier) {
  const tierId = normalizeAcquisitionFamilyId(tier);
  const names = new Set(Object.keys(buildPokemonBalanceTierMap()));
  Object.keys(normalizedPokemonTierOverrides()).forEach((key) => names.add(key));
  return [...names]
    .filter((pokemonName) => normalizeAcquisitionFamilyId(getPokemonRollPoolTier(pokemonName)) === tierId)
    .map((pokemonName) => pokemonName);
}

function pokemonSpeciesNameOptions(filterMode = "all") {
  const names = new Map();
  const addName = (name, metadata = {}) => {
    const sourceDisplayName = metadata.displayName || metadata.name || pokemonDisplayName(name || "");
    const key = getPokemonIndexKey(sourceDisplayName);
    const displayName = getRivalSagaPokemonDisplayName(sourceDisplayName);
    if (key && !names.has(key)) {
      const typeData = rivalSagaPokemonTypeData[key] || rivalSagaPokemonTypeData[pokemonTypeLookupAliasMap[key]] || {};
      const tierData = rivalSagaPokemonTierMap[key] || {};
      names.set(key, {
        key,
        displayName,
        dex: metadata.dex || typeData.dex || "",
        types: metadata.types || typeData.types || getPokemonTypes(displayName),
        tier: getPokemonFamilyAcquisitionTier(displayName) || normalizeAcquisitionFamilyId(metadata.tier || tierData.tier) || "",
        status: currentPokemonRuleStatusByName(displayName)
      });
    }
  };
  Object.entries(rivalSagaPokemonTierMap || {}).forEach(([key, metadata]) => addName(metadata.displayName || key));
  Object.entries(rivalSagaPokemonTypeData || {}).forEach(([key, metadata]) => addName(metadata.name || key, metadata));
  Object.keys(pokemonTypePlaceholderMap || {}).forEach(addName);
  (state.pokemonRecords || []).forEach((pokemon) => addName(pokemon.name));
  Object.values(state.globalPokemonRules || {}).forEach((rule) => addName(rule.name));
  (state.lingeringStatuses || []).forEach((status) => addName(status.targetPokemonName));
  return [...names.values()]
    .filter((entry) => {
      if (filterMode !== "banned-or-restricted") return true;
      return ["Banned", "Restricted"].includes(entry.status)
        || pokemonNameHasActiveStatus(entry.displayName, "ban")
        || pokemonNameHasActiveStatus(entry.displayName, "restrict");
    })
    .sort((a, b) => a.displayName.localeCompare(b.displayName));
}

function buildPokemonIndexEntries() {
  const entries = new Map();
  const ensureEntry = (name, source = "", metadata = {}) => {
    const indexKey = getPokemonIndexKey(name);
    if (!indexKey) return null;
    if (!entries.has(indexKey)) {
      const typeData = rivalSagaPokemonTypeData[indexKey] || rivalSagaPokemonTypeData[pokemonTypeLookupAliasMap[indexKey]] || {};
      const tierData = rivalSagaPokemonTierMap[indexKey] || {};
      const balanceTierData = getPokemonBalanceTierEntry(indexKey) || getPokemonBalanceTierEntry(name) || {};
      const displayName = getRivalSagaPokemonDisplayName(indexKey);
      const policy = getPokemonIndexFormPolicy(indexKey);
      entries.set(indexKey, {
        indexKey,
        displayName,
        types: typeData.types || metadata.types || getPokemonTypes(displayName),
        dex: typeData.dex || metadata.dex || "",
        acquisitionTier: getPokemonFamilyAcquisitionTier(indexKey) || normalizeAcquisitionFamilyId(tierData.tier) || "",
        rollPoolTier: getPokemonRollPoolTier(indexKey) || normalizeAcquisitionFamilyId(tierData.tier) || "",
        balanceTier: balanceTierData.balanceTier || "",
        balanceTierLabel: balanceTierData.balanceTierLabel || "",
        balanceTierOrder: balanceTierData.balanceTierOrder || 0,
        policy,
        sources: new Set(),
        aliases: new Set(),
        notes: new Set(),
        ownedCopies: [],
        globalRule: activeGlobalPokemonRule(indexKey),
        banHistory: [],
        unresolved: false
      });
    }
    const entry = entries.get(indexKey);
    if (source) entry.sources.add(source);
    if (name && normalizePokemonName(name) !== indexKey) entry.aliases.add(name);
    if (!entry.types.length && metadata.types?.length) entry.types = metadata.types;
    if (!entry.dex && metadata.dex) entry.dex = metadata.dex;
    if (metadata.note) entry.notes.add(metadata.note);
    if (metadata.extraRequirement) entry.notes.add(`Requirement: ${metadata.extraRequirement}`);
    if (!entry.rollPoolTier && metadata.tier) entry.rollPoolTier = normalizeAcquisitionFamilyId(metadata.tier);
    if (!entry.acquisitionTier && (metadata.tier || getPokemonFamilyAcquisitionTier(indexKey))) {
      entry.acquisitionTier = getPokemonFamilyAcquisitionTier(indexKey) || normalizeAcquisitionFamilyId(metadata.tier) || "";
    }
    if (!entry.balanceTier && metadata.balanceTier) {
      entry.balanceTier = normalizeBalanceTierId(metadata.balanceTier);
      entry.balanceTierLabel = metadata.balanceTierLabel || metadata.balanceTier || "";
      entry.balanceTierOrder = Number(metadata.balanceTierOrder || 0);
    }
    return entry;
  };
  rivalSagaPokemonBalanceTierRows.forEach((row) => ensureEntry(row.displayName, "balance-tier", {
    balanceTier: row.balanceTier,
    balanceTierLabel: row.balanceTierLabel,
    balanceTierOrder: row.balanceTierOrder
  }));
  Object.entries(rivalSagaPokemonTierMap || {}).forEach(([key, metadata]) => ensureEntry(metadata.displayName || key, "acquisition-family", metadata));
  Object.entries(rivalSagaPokemonTypeData || {}).forEach(([key, metadata]) => ensureEntry(key, "type-data", metadata));
  (state.pokemonRecords || []).forEach((pokemon) => {
    const entry = ensureEntry(pokemon.name, "owned-copy");
    if (entry) entry.ownedCopies.push(pokemon);
  });
  Object.values(state.globalPokemonRules || {}).forEach((rule) => {
    const entry = ensureEntry(rule.name, "global-rule");
    if (entry) entry.globalRule = activeGlobalPokemonRule(rule.name) || rule;
  });
  (state.banlistHistory || []).forEach((history) => {
    const entry = ensureEntry(history.pokemonName, "ban-history");
    if (entry) entry.banHistory.push(history);
  });
  entries.forEach((entry) => {
    entry.sources = [...entry.sources].sort();
    entry.aliases = [...entry.aliases].sort();
    entry.notes = [...entry.notes].sort();
    entry.banCount = entry.globalRule?.banCount || entry.banHistory.filter((history) => /ban|unban/i.test(history.action)).length;
    entry.restrictCount = entry.globalRule?.restrictCount || entry.banHistory.filter((history) => /restrict/i.test(history.action)).length;
    entry.unresolved = !entry.dex && !entry.rollPoolTier && !entry.ownedCopies.length;
  });
  return [...entries.values()].sort((a, b) => a.displayName.localeCompare(b.displayName));
}

function activationSpeciesFilterMode(definition) {
  return definition?.statusType === "unban-protection" ? "banned-or-restricted" : "all";
}

function pokemonSpeciesPreviewSprite(entry) {
  const dex = Number(String(entry?.dex || "").replace(/\D/g, ""));
  if (!dex) return "";
  return `https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/${dex}.png`;
}

function pokemonIndexSpriteLookupKey(entry) {
  const variant = getPokemonSpriteVariantPolicy(entry?.indexKey || entry?.displayName);
  if (variant?.spriteKeys?.length) return variant.spriteKeys[0];
  return getPokemonSpriteLookupKey(entry?.displayName || entry?.indexKey || "");
}

function pokemonDbSpriteKey(lookupKey) {
  const specialCases = {
    "basculegion-female": "basculegion-female",
    "basculegion-male": "basculegion-male",
    "calyrex-ice-rider": "calyrex-ice-rider",
    "calyrex-shadow-rider": "calyrex-shadow-rider",
    "floette-eternal-flower": "floette-eternal",
    "darmanitan-galar-standard": "darmanitan-galarian-standard",
    "darmanitan-galar-zen": "darmanitan-galarian-zen",
    "hoopa-unbound": "hoopa-unbound",
    "landorus-therian": "landorus-therian",
    "lycanroc": "lycanroc-midday",
    "lycanroc-midnight": "lycanroc-midnight",
    "meowstic": "meowstic-male",
    "meloetta": "meloetta-aria",
    "morpeko": "morpeko-full-belly",
    "ogerpon": "ogerpon",
    "ogerpon-cornerstone-mask": "ogerpon-cornerstone-mask",
    "ogerpon-hearthflame-mask": "ogerpon-hearthflame-mask",
    "ogerpon-wellspring-mask": "ogerpon-wellspring-mask",
    "oricorio-pau": "oricorio-pau",
    "palafin": "palafin-zero",
    "rotom-fan-rotom": "rotom-fan",
    "rotom-frost-rotom": "rotom-frost",
    "rotom-heat-rotom": "rotom-heat",
    "rotom-mow-rotom": "rotom-mow",
    "rotom-wash-rotom": "rotom-wash",
    "shaymin-sky": "shaymin-sky",
    "tauros-aqua-breed": "tauros-paldea-aqua-breed",
    "tauros-blaze-breed": "tauros-paldea-blaze-breed",
    "tauros-combat-breed": "tauros-paldea-combat-breed",
    "terapagos": "terapagos-normal",
    "thundurus-therian": "thundurus-therian",
    "tornadus-therian": "tornadus-therian",
    "toxtricity": "toxtricity-amped",
    "urshifu-rapid-strike-style": "urshifu-rapid-strike",
    "urshifu-single-strike-style": "urshifu-single-strike",
    "ursaluna-bloodmoon": "ursaluna-bloodmoon",
    "wormadam-plant-cloak": "wormadam-plant",
    "wormadam-sandy-cloak": "wormadam-sandy",
    "wormadam-trash-cloak": "wormadam-trash",
    "zygarde-10-forme": "zygarde-10",
    "zygarde-mega": "zygarde-complete"
  };
  const key = String(lookupKey || "");
  if (specialCases[key]) return specialCases[key];
  return key
    .replace(/-hisui$/i, "-hisuian")
    .replace(/-alola$/i, "-alolan")
    .replace(/-galar$/i, "-galarian")
    .replace(/-paldea$/i, "-paldean");
}

function pokemonDbSpriteUrlForLookup(lookupKey) {
  const normalized = normalizePokemonApiName(lookupKey);
  if (!normalized) return "";
  return `https://img.pokemondb.net/sprites/home/normal/${encodeURIComponent(pokemonDbSpriteKey(normalized))}.png`;
}

function pokemonSpriteImageCandidates(name, spriteUrl = "", chosenSpriteKey = "", targetState = state) {
  const candidates = [];
  const pushCandidate = (url) => {
    if (url && !candidates.includes(url)) candidates.push(url);
  };
  pushCandidate(spriteUrl);
  [
    chosenSpriteKey,
    getPokemonSpriteLookupKey(name, targetState),
    ...(pokemonSpriteVariantDefinition(name, targetState)?.spriteKeys || [])
  ].forEach((lookupKey) => pushCandidate(pokemonDbSpriteUrlForLookup(lookupKey)));
  return candidates;
}

function pokemonSpriteInitial(name, fallback = "?") {
  return String(name || fallback).slice(0, 1).toUpperCase();
}

function pokemonRecordSpriteCandidates(pokemon) {
  if (!pokemon) return [];
  return pokemonSpriteImageCandidates(pokemon.name, pokemon.spriteUrl, pokemon.chosenSpriteKey);
}

function renderPokemonSpriteContent(pokemon, options = {}) {
  const name = pokemon?.name || options.name || "Pokemon";
  const candidates = pokemonRecordSpriteCandidates(pokemon);
  const fallbackText = pokemonSpriteInitial(name);
  if (!candidates.length) return `<span>${escapeHtml(fallbackText)}</span>`;
  return `<img src="${escapeHtml(candidates[0])}" alt="${escapeHtml(options.alt ?? "")}" loading="${escapeHtml(options.loading || "lazy")}" data-fallback-srcs="${escapeHtml(JSON.stringify(candidates.slice(1)))}" data-fallback-text="${escapeHtml(fallbackText)}" onerror="handlePokemonSpriteImageError(this);">`;
}

function pokemonSpriteClassSuffix(pokemon) {
  return pokemonRecordSpriteCandidates(pokemon).length ? " has-sprite" : "";
}

function handlePokemonSpriteImageError(img) {
  if (!img) return;
  let fallbacks = [];
  try {
    fallbacks = JSON.parse(img.dataset.fallbackSrcs || "[]");
  } catch {
    fallbacks = [];
  }
  const next = fallbacks.shift();
  if (next) {
    img.dataset.fallbackSrcs = JSON.stringify(fallbacks);
    img.src = next;
    return;
  }
  const fallback = document.createElement("span");
  fallback.textContent = img.dataset.fallbackText || "?";
  img.parentElement?.classList.remove("has-sprite");
  img.replaceWith(fallback);
}

if (typeof window !== "undefined") {
  window.handlePokemonSpriteImageError = handlePokemonSpriteImageError;
}

function pokemonIndexDirectSpriteUrl(entry) {
  const lookupKey = pokemonIndexSpriteLookupKey(entry);
  if (!lookupKey || !shouldHydratePokemonIndexSprite(entry)) return "";
  return pokemonDbSpriteUrlForLookup(lookupKey);
}

function shouldHydratePokemonIndexSprite(entry) {
  const lookupKey = pokemonIndexSpriteLookupKey(entry);
  if (!lookupKey) return false;
  return !entry?.dex
    || Boolean(entry?.policy?.separateForm)
    || Boolean(entry?.policy?.randomSprite)
    || /(^|-)(mega|primal|origin|crowned|rider|sky|galar|alola|hisui|paldea|paldean|therian|incarnate|attack|defense|speed|dawn|dusk|midnight|black|white|blue|red|yellow|orange|green|indigo|violet|fire|water|rock|cornerstone|hearthflame|wellspring)(-|$)/i.test(lookupKey);
}

function pokemonIndexSpriteMarkup(entry) {
  const lookupKey = pokemonIndexSpriteLookupKey(entry);
  const cachedSprite = lookupKey ? pokemonIndexSpriteCache[lookupKey] : "";
  const fallbackSprite = pokemonSpeciesPreviewSprite(entry);
  const needsHydration = lookupKey && shouldHydratePokemonIndexSprite(entry) && !cachedSprite;
  const directSprite = needsHydration ? pokemonIndexDirectSpriteUrl(entry) : "";
  const sprite = cachedSprite || directSprite || (needsHydration ? "" : fallbackSprite);
  const hydrationAttrs = needsHydration
    ? ` data-pokemon-index-sprite-key="${escapeHtml(lookupKey)}" data-pokemon-index-sprite-name="${escapeHtml(entry.displayName)}" data-pokemon-index-fallback-sprite="${escapeHtml(fallbackSprite)}"`
    : "";
  return `
    <div class="banlist-card-image${needsHydration ? " loading-sprite" : ""}"${hydrationAttrs}>
      ${sprite ? `<img src="${escapeHtml(sprite)}" alt="${escapeHtml(entry.displayName)}" loading="lazy" onerror="this.onerror=null; if (this.parentElement?.dataset?.pokemonIndexFallbackSprite) this.src=this.parentElement.dataset.pokemonIndexFallbackSprite;">` : `<span>${escapeHtml(entry.displayName.slice(0, 1).toUpperCase())}</span>`}
    </div>
  `;
}

function setPokemonIndexSpriteElement(element, spriteUrl) {
  if (!element || !spriteUrl) return;
  const displayName = element.dataset.pokemonIndexSpriteName || "";
  element.innerHTML = `<img src="${escapeHtml(spriteUrl)}" alt="${escapeHtml(displayName)}" loading="lazy">`;
  element.classList.add("has-sprite");
  element.classList.remove("loading-sprite");
}

function hydratePokemonIndexSpriteElement(element) {
  const lookupKey = element?.dataset?.pokemonIndexSpriteKey || "";
  if (!lookupKey) return;
  if (pokemonIndexSpriteCache[lookupKey]) {
    setPokemonIndexSpriteElement(element, pokemonIndexSpriteCache[lookupKey]);
    return;
  }
  if (pendingPokemonIndexSpriteLookups.has(lookupKey)) return;
  pendingPokemonIndexSpriteLookups.add(lookupKey);
  fetchPokemonSpriteUrlForLookup(lookupKey).then((spriteUrl) => {
    pendingPokemonIndexSpriteLookups.delete(lookupKey);
    if (!spriteUrl) {
      const fallbackSprite = element.dataset.pokemonIndexFallbackSprite || "";
      if (fallbackSprite) setPokemonIndexSpriteElement(element, fallbackSprite);
      return;
    }
    pokemonIndexSpriteCache[lookupKey] = spriteUrl;
    document.querySelectorAll("[data-pokemon-index-sprite-key]").forEach((node) => {
      if (node.dataset.pokemonIndexSpriteKey === lookupKey) setPokemonIndexSpriteElement(node, spriteUrl);
    });
  }).catch(() => {
    pendingPokemonIndexSpriteLookups.delete(lookupKey);
    const fallbackSprite = element.dataset.pokemonIndexFallbackSprite || "";
    if (fallbackSprite) setPokemonIndexSpriteElement(element, fallbackSprite);
  });
}

function queuePokemonIndexSpriteHydration() {
  if (!els.currentBanlistBody) return;
  if (pokemonIndexSpriteObserver) {
    pokemonIndexSpriteObserver.disconnect();
    pokemonIndexSpriteObserver = null;
  }
  const nodes = [...els.currentBanlistBody.querySelectorAll("[data-pokemon-index-sprite-key]")];
  if (!nodes.length) return;
  nodes.slice(0, 24).forEach(hydratePokemonIndexSpriteElement);
  if ("IntersectionObserver" in window) {
    pokemonIndexSpriteObserver = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (!entry.isIntersecting) return;
        pokemonIndexSpriteObserver.unobserve(entry.target);
        hydratePokemonIndexSpriteElement(entry.target);
      });
    }, { rootMargin: "360px 0px" });
    nodes.forEach((node) => pokemonIndexSpriteObserver.observe(node));
    return;
  }
  nodes.slice(0, 80).forEach(hydratePokemonIndexSpriteElement);
}

function renderActivationSpeciesResults(definition = null) {
  if (!els.activationSpeciesResults || !els.activationSpeciesSearch) return;
  const term = normalizePokemonName(els.activationSpeciesSearch.value);
  const rawTerm = els.activationSpeciesSearch.value.trim().toLowerCase();
  const entries = pokemonSpeciesNameOptions(activationSpeciesFilterMode(definition))
    .filter((entry) => {
      if (!term && !rawTerm) return true;
      return entry.key.includes(term)
        || entry.displayName.toLowerCase().includes(rawTerm)
        || (entry.types || []).some((type) => type.toLowerCase().includes(rawTerm));
    })
    .slice(0, 36);
  els.activationSpeciesResults.innerHTML = entries.length ? entries.map((entry) => {
    const sprite = pokemonSpeciesPreviewSprite(entry);
    const tier = getPokemonTierLabel(entry.tier) || "";
    const status = entry.status && entry.status !== "Normal" ? entry.status : "";
    return `
      <button class="activation-species-card" type="button" data-activation-species="${escapeHtml(entry.displayName)}">
        <span class="activation-species-sprite">
          ${sprite ? `<img src="${escapeHtml(sprite)}" alt="" loading="lazy">` : `<span>${escapeHtml(entry.displayName.slice(0, 1).toUpperCase())}</span>`}
        </span>
        <span>
          <strong>${escapeHtml(entry.displayName)}</strong>
          <em>${[tier, ...(entry.types || []), status].filter(Boolean).map(escapeHtml).join(" - ") || "Pokemon"}</em>
        </span>
      </button>
    `;
  }).join("") : `<p class="empty-state compact">${definition?.statusType === "unban-protection" ? "No banned or restricted Pokemon match." : "No Pokemon match. You can still type a custom name."}</p>`;
}

