function normalizeClientLocalStateSnapshot(snapshot = {}) {
  const source = snapshot && typeof snapshot === "object" && !Array.isArray(snapshot) ? snapshot : {};
  const normalized = {};
  CLIENT_LOCAL_STATE_KEYS.forEach((key) => {
    if (source[key] !== undefined) normalized[key] = structuredClone(source[key]);
  });
  if (normalized.activePage !== undefined && !TOP_LEVEL_PAGE_IDS.includes(normalized.activePage)) {
    normalized.activePage = "playerHub";
  }
  if (normalized.activeView !== undefined && !PLAYER_HUB_VIEW_IDS.includes(normalized.activeView)) {
    normalized.activeView = "sheet";
  }
  if (normalized.routeUiState !== undefined) normalized.routeUiState = normalizeRouteUiState(normalized.routeUiState);
  return normalized;
}

function createDefaultRouteUiState() {
  return {
    routeWorkspaceBySeriesId: {},
    activeRouteActionIdBySeriesId: {},
    lastRouteAcquisitionMessage: "",
    routeEffectsOpen: false,
    routeEffectsX: 0,
    routeEffectsY: 0,
    routeEffectsExpandedId: "",
    publicActivityToasts: []
  };
}

function normalizeV2RouteWorkspaceSnapshot(workspace = {}) {
  const source = workspace && typeof workspace === "object" && !Array.isArray(workspace) ? workspace : {};
  return {
    screen: ["root", "route-list", "route-detail", "result"].includes(source.screen) ? source.screen : "root",
    selectedActionId: String(source.selectedActionId || "").trim(),
    selectedRouteNumber: Number(source.selectedRouteNumber || 0),
    activeActionId: String(source.activeActionId || "").trim(),
    activeOpportunityId: String(source.activeOpportunityId || "").trim()
  };
}

function normalizeRouteUiState(routeUiState = {}) {
  const source = routeUiState && typeof routeUiState === "object" && !Array.isArray(routeUiState)
    ? routeUiState
    : {};
  const normalized = createDefaultRouteUiState();
  Object.entries(source.routeWorkspaceBySeriesId || {}).forEach(([seriesId, workspace]) => {
    const key = String(seriesId || "").trim();
    if (key) normalized.routeWorkspaceBySeriesId[key] = normalizeV2RouteWorkspaceSnapshot(workspace);
  });
  Object.entries(source.activeRouteActionIdBySeriesId || {}).forEach(([seriesId, actionId]) => {
    const key = String(seriesId || "").trim();
    const value = String(actionId || "").trim();
    if (key && value) normalized.activeRouteActionIdBySeriesId[key] = value;
  });
  normalized.lastRouteAcquisitionMessage = String(source.lastRouteAcquisitionMessage || "").trim();
  normalized.routeEffectsOpen = source.routeEffectsOpen === true;
  normalized.routeEffectsX = Number.isFinite(Number(source.routeEffectsX)) ? Number(source.routeEffectsX) : 0;
  normalized.routeEffectsY = Number.isFinite(Number(source.routeEffectsY)) ? Number(source.routeEffectsY) : 0;
  normalized.routeEffectsExpandedId = String(source.routeEffectsExpandedId || "").trim();
  normalized.publicActivityToasts = (Array.isArray(source.publicActivityToasts) ? source.publicActivityToasts : [])
    .map((toast) => ({
      activityId: String(toast?.activityId || "").trim(),
      stage: String(toast?.stage || "").trim(),
      actorName: String(toast?.actorName || "").trim(),
      routeNumber: Number(toast?.routeNumber || 0),
      pokemonName: String(toast?.pokemonName || "").trim(),
      occurredAt: String(toast?.occurredAt || "").trim(),
      expiresAt: String(toast?.expiresAt || "").trim()
    }))
    .filter((toast) => toast.activityId && toast.expiresAt && new Date(toast.expiresAt).getTime() > Date.now())
    .slice(0, 5);
  return normalized;
}

function readClientUiState() {
  try {
    const saved = localStorage.getItem(CLIENT_UI_STATE_KEY);
    return saved ? normalizeClientLocalStateSnapshot(JSON.parse(saved)) : {};
  } catch {
    return {};
  }
}

function clientUiSnapshotForPersistence(nextState = state) {
  const current = clientLocalStateSnapshot(nextState);
  if (!tokenScenarioSandboxActive() || !tokenScenarioClientUiBaseline) return current;
  const safe = structuredClone(tokenScenarioClientUiBaseline);
  SANDBOX_SAFE_CLIENT_UI_KEYS.forEach((key) => {
    if (current[key] !== undefined) safe[key] = structuredClone(current[key]);
  });
  return normalizeClientLocalStateSnapshot(safe);
}

function writeClientUiState(nextState = state) {
  localStorage.setItem(CLIENT_UI_STATE_KEY, JSON.stringify(clientUiSnapshotForPersistence(nextState)));
}

function flushClientUiStateSave(nextState = state) {
  if (clientUiStateSaveTimer) {
    clearTimeout(clientUiStateSaveTimer);
    clientUiStateSaveTimer = null;
  }
  clientUiStateSaveQueued = false;
  writeClientUiState(nextState);
}

function queueClientUiStateSave() {
  clientUiStateSaveQueued = true;
  if (clientUiStateSaveTimer) clearTimeout(clientUiStateSaveTimer);
  clientUiStateSaveTimer = setTimeout(() => {
    flushClientUiStateSave();
  }, 120);
}

function compactUndoDataForPersistence(undoData) {
  saveCompactionRuntime.compactUndoData(undoData);
  return undoData;
}

function compactPersistedUndoSnapshots(snapshot) {
  saveCompactionRuntime.compactUndoSnapshots(snapshot);
}

function createPersistableStateSnapshot(source = state) {
  const snapshot = structuredClone(source || {});
  const ruleset = snapshot.ruleset && typeof snapshot.ruleset === "object" && !Array.isArray(snapshot.ruleset)
    ? snapshot.ruleset
    : {};
  const contentLibraries = ruleset.contentLibraries && typeof ruleset.contentLibraries === "object" && !Array.isArray(ruleset.contentLibraries)
    ? ruleset.contentLibraries
    : {};
  const sourceTokenArt = contentLibraries.tokenArt && typeof contentLibraries.tokenArt === "object" && !Array.isArray(contentLibraries.tokenArt)
    ? contentLibraries.tokenArt
    : snapshot.tokenArtLibrary;
  const tokenArt = normalizeTokenArtLibrary(sourceTokenArt || {});
  if (Object.keys(tokenArt).length) {
    ruleset.contentLibraries = { ...contentLibraries, tokenArt };
    snapshot.ruleset = ruleset;
  }
  compactPersistedUndoSnapshots(snapshot);
  delete snapshot.tokenArtLibrary;
  delete snapshot.routeUiState;
  if (snapshot.v2 && typeof snapshot.v2 === "object" && !Array.isArray(snapshot.v2)) {
    delete snapshot.v2.routeWorkspaceBySeriesId;
    delete snapshot.v2.activeRouteActionIdBySeriesId;
    delete snapshot.v2.lastRouteAcquisitionMessage;
  }
  return snapshot;
}

function writeStoredState(nextState = state, { sandboxSessionId = "" } = {}) {
  if (!tokenScenarioSandbox.canPersistGameplay({ sessionId: sandboxSessionId })) {
    try {
      writeClientUiState(nextState);
    } catch (error) {
      console.warn("Rival Saga local UI state could not be saved.", error);
    }
    return false;
  }
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(createPersistableStateSnapshot(nextState)));
  } catch (error) {
    if (error?.name === "QuotaExceededError") {
      console.info("Rival Saga local snapshot exceeds browser storage; authoritative backend persistence remains active.");
    } else {
      console.warn("Rival Saga local snapshot could not be saved; continuing with backend persistence.", error);
    }
  }
  try {
    writeClientUiState(nextState);
  } catch (error) {
    console.warn("Rival Saga local UI state could not be saved.", error);
  }
  return true;
}

function flushStoredStateSave(nextState = state, options = {}) {
  if (storedStateSaveTimer) {
    clearTimeout(storedStateSaveTimer);
    storedStateSaveTimer = null;
  }
  storedStateSaveQueued = false;
  return writeStoredState(nextState, options);
}

function queueStoredStateSave() {
  if (tokenScenarioSandboxActive()) return false;
  storedStateSaveQueued = true;
  if (storedStateSaveTimer) clearTimeout(storedStateSaveTimer);
  storedStateSaveTimer = setTimeout(() => {
    flushStoredStateSave();
  }, 120);
  return true;
}

function saveClientUiState({ immediate = false } = {}) {
  if (immediate) flushClientUiStateSave(state);
  else queueClientUiStateSave();
}

function loadState() {
  const clientUiState = readClientUiState();
  const saved = localStorage.getItem(STORAGE_KEY);
  if (!saved) {
    const normalized = restoreClientLocalState(normalizeState(structuredClone(initialState)), clientUiState);
    writeStoredState(normalized);
    return normalized;
  }

  try {
    const normalized = restoreClientLocalState(normalizeState(JSON.parse(saved)), clientUiState);
    writeStoredState(normalized);
    return normalized;
  } catch {
    const normalized = restoreClientLocalState(normalizeState(structuredClone(initialState)), clientUiState);
    writeStoredState(normalized);
    return normalized;
  }
}

function backendGameId() {
  try {
    const params = new URLSearchParams(window.location.search);
    const queryGameId = params.get("game") || params.get("gameId");
    if (queryGameId) {
      localStorage.setItem(BACKEND_GAME_ID_KEY, queryGameId);
      return queryGameId;
    }
    return localStorage.getItem(BACKEND_GAME_ID_KEY) || "default";
  } catch {
    return "default";
  }
}

function backendClientId() {
  return `client-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

function backendRequestMutatesGameplay(path, options = {}) {
  const method = String(options.method || "GET").toUpperCase();
  return method !== "GET" && method !== "HEAD" && /^\/api\/games\//.test(String(path || ""));
}

function backendFetch(path, options = {}) {
  const { sandboxSessionId = "", ...fetchOptions } = options;
  const mutatesGameplay = backendRequestMutatesGameplay(path, fetchOptions);
  if (mutatesGameplay
    && !tokenScenarioSandbox.canPersistGameplay({ sessionId: sandboxSessionId })) {
    return Promise.reject(new Error("Gameplay persistence is blocked while Token Sandbox Mode is active."));
  }
  const request = fetch(new URL(path, `${API_ORIGIN}/`).toString(), {
    ...fetchOptions,
    headers: {
      "content-type": "application/json",
      ...(fetchOptions.headers || {})
    }
  });
  if (!mutatesGameplay) return request;
  const trackedRequest = request
    .then(async (response) => {
      const payload = await response.clone().json().catch(() => null);
      const acknowledgedVersion = Number(payload?.version || payload?.currentVersion || 0);
      if (acknowledgedVersion > 0) {
        backendSync.version = Math.max(Number(backendSync.version || 0), acknowledgedVersion);
      }
      return response;
    })
    .finally(() => backendSync.pendingGameplayWrites.delete(trackedRequest));
  backendSync.pendingGameplayWrites.add(trackedRequest);
  return trackedRequest;
}

