let tokenImageOverrides = loadTokenImageOverrides();
let tokenImageEditorDraft = { key: "", setting: null, dragging: false, lastX: 0, lastY: 0 };

function loadTokenImageOverrides() {
  try {
    const parsed = JSON.parse(localStorage.getItem(TOKEN_IMAGE_SETTINGS_KEY) || "{}");
    return parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed : {};
  } catch {
    return {};
  }
}

function saveTokenImageOverrides() {
  try {
    localStorage.setItem(TOKEN_IMAGE_SETTINGS_KEY, JSON.stringify(tokenImageOverrides));
    return true;
  } catch (error) {
    console.warn("Could not save token image settings", error);
    return false;
  }
}

function normalizeTokenArtLibrary(library = {}) {
  const normalized = {};
  Object.entries(library && typeof library === "object" && !Array.isArray(library) ? library : {}).forEach(([key, value]) => {
    const safeKey = slugify(key);
    const setting = normalizeTokenImageSetting(value);
    if (!safeKey || CANCELED_TOKEN_CONTENT_IDS.has(safeKey) || !setting.src) return;
    normalized[safeKey] = setting;
  });
  return normalized;
}

function isCanceledGameContentEntry(entry = {}) {
  const normalizedEntry = typeof entry === "string" ? { id: entry, name: entry } : entry;
  const id = slugify(normalizedEntry.catalogId || normalizedEntry.id || "");
  const name = slugify(normalizedEntry.name || normalizedEntry.tokenName || "");
  return name === "link-cable" || id === "link-cable" || id.startsWith("link-cable-")
    || CANCELED_TOKEN_CONTENT_IDS.has(id)
    || String(normalizedEntry.tokenType || "").toLowerCase() === "field"
    || /-field-token$/.test(name);
}

function isDeprecatedTokenCatalogEntry(entry = {}) {
  const id = slugify(entry.id || entry.name || "");
  const tokenType = String(entry.tokenType || "").toLowerCase();
  const name = String(entry.name || "").toLowerCase();
  const removedIds = new Set([
    "safari-zone-token",
    "safari-zone-gc-token",
    "safari-gc-ticket",
    "pokeball-gc-token",
    "poke-gc-ticket",
    "greatball-gc-token",
    "great-gc-ticket",
    "ultraball-gc-token",
    "ultra-gc-ticket",
    "masterball-gc-token",
    "master-gc-ticket",
    "legacy-token",
    "legacy-ticket",
    "roll-pokeball-wheel",
    "roll-greatball-wheel",
    "roll-ultraball-wheel",
    "roll-masterball-wheel",
    "pokeball-insurance",
    "greatball-insurance",
    "ultraball-insurance",
    "masterball-insurance"
  ]);
  return isCanceledGameContentEntry(entry)
    || removedIds.has(id)
    || ["game-corner", "game-corner-wheel", "legacy", "insurance"].includes(tokenType)
    || /\binsurance\b/.test(name);
}

function normalizeTokenCatalog(catalog = [], defaults = defaultTokenShopData) {
  const defaultEntries = Array.isArray(defaults) ? defaults : [];
  const defaultById = new Map(defaultEntries.map((entry) => [String(entry.id || ""), entry]));
  const sourceEntries = Array.isArray(catalog) && catalog.length ? catalog : defaultEntries;
  const seen = new Set();
  const normalized = [];
  sourceEntries.forEach((entry) => {
    if (!entry || typeof entry !== "object") return;
    if (isDeprecatedTokenCatalogEntry(entry)) return;
    const id = slugify(entry.id || entry.name || "");
    if (!id || seen.has(id)) return;
    seen.add(id);
    const base = defaultById.get(id) || {};
    const merged = { ...base, ...entry, id };
    const price = Number(merged.price);
    normalized.push({
      ...merged,
      name: String(merged.name || base.name || id),
      tokenType: String(merged.tokenType || base.tokenType || "token"),
      tier: String(merged.tier || base.tier || "Tokens"),
      category: String(merged.category || base.category || merged.tier || "Tokens"),
      price: Number.isFinite(price) && price >= 0 ? Math.round(price) : Number(base.price || 0),
      description: String(merged.description || ""),
      cannotPurchase: Boolean(merged.cannotPurchase)
    });
  });
  defaultEntries.forEach((entry) => {
    if (!entry?.id || seen.has(entry.id)) return;
    normalized.push(structuredClone(entry));
  });
  return normalized;
}

function normalizeRuleset(ruleset = {}, legacyState = {}) {
  const base = createDefaultRuleset();
  const source = ruleset && typeof ruleset === "object" && !Array.isArray(ruleset) ? ruleset : {};
  const persistedActionPhaseVersion = source.actionPhaseVersion || legacyState.actionPhaseVersion;
  const sourceLibraries = source.contentLibraries && typeof source.contentLibraries === "object" && !Array.isArray(source.contentLibraries)
    ? source.contentLibraries
    : {};
  const tokenArtCandidates = [
    sourceLibraries.tokenArt,
    source.tokenArtLibrary,
    legacyState.tokenArtLibrary,
    legacyState.tokenImageOverrides
  ];
  const tokenArt = tokenArtCandidates.reduce((chosen, candidate) => {
    if (Object.keys(chosen).length) return chosen;
    return normalizeTokenArtLibrary(candidate || {});
  }, {});
  const tokenCatalog = normalizeTokenCatalog(sourceLibraries.tokenCatalog || source.tokenCatalog || legacyState.tokenCatalog || []);
  return {
    ...base,
    ...source,
    id: String(source.id || base.id),
    name: String(source.name || base.name),
    version: String(source.version || base.version),
    schemaVersion: Number(source.schemaVersion || base.schemaVersion),
    actionPhaseVersion: persistedActionPhaseVersion
      ? normalizeActionPhaseVersion(persistedActionPhaseVersion)
      : DEFAULT_ACTION_PHASE_VERSION,
    supportedActionPhaseVersions: [...new Set([
      ...base.supportedActionPhaseVersions,
      ...(Array.isArray(source.supportedActionPhaseVersions) ? source.supportedActionPhaseVersions : [])
    ].map(normalizeActionPhaseVersion))],
    updateMode: source.updateMode === "automatic" ? "automatic" : "manual",
    contentLibraries: {
      ...base.contentLibraries,
      ...sourceLibraries,
      tokenArt,
      tokenCatalog
    },
    editors: {
      ...base.editors,
      ...(source.editors && typeof source.editors === "object" && !Array.isArray(source.editors) ? source.editors : {})
    },
    notes: Array.isArray(source.notes) && source.notes.length ? source.notes : base.notes
  };
}

function ensureRulesetState() {
  state.ruleset = normalizeRuleset(state.ruleset, state);
  state.tokenArtLibrary = structuredClone(state.ruleset.contentLibraries.tokenArt || {});
  return state.ruleset;
}

function activeTokenArtLibrary() {
  return state?.ruleset?.contentLibraries?.tokenArt && typeof state.ruleset.contentLibraries.tokenArt === "object"
    ? state.ruleset.contentLibraries.tokenArt
    : state?.tokenArtLibrary && typeof state.tokenArtLibrary === "object"
      ? state.tokenArtLibrary
      : {};
}

function saveTokenArtLibrary() {
  const ruleset = ensureRulesetState();
  ruleset.contentLibraries.tokenArt = normalizeTokenArtLibrary(ruleset.contentLibraries.tokenArt || state.tokenArtLibrary || {});
  state.tokenArtLibrary = structuredClone(ruleset.contentLibraries.tokenArt);
  tokenImageOverrides = structuredClone(ruleset.contentLibraries.tokenArt);
  return saveTokenImageOverrides();
}

function mirrorTokenArtLibraryToLocal() {
  tokenImageOverrides = structuredClone(activeTokenArtLibrary());
  saveTokenImageOverrides();
}

function editableTokenArtLibrary() {
  const ruleset = ensureRulesetState();
  ruleset.contentLibraries.tokenArt ||= {};
  state.tokenArtLibrary = ruleset.contentLibraries.tokenArt;
  return ruleset.contentLibraries.tokenArt;
}

function activeTokenCatalog() {
  const catalog = state?.ruleset?.contentLibraries?.tokenCatalog;
  return normalizeTokenCatalog(Array.isArray(catalog) && catalog.length ? catalog : defaultTokenShopData);
}

function editableTokenCatalog() {
  const ruleset = ensureRulesetState();
  ruleset.contentLibraries.tokenCatalog = normalizeTokenCatalog(ruleset.contentLibraries.tokenCatalog || []);
  return ruleset.contentLibraries.tokenCatalog;
}

function saveTokenCatalog() {
  const ruleset = ensureRulesetState();
  ruleset.contentLibraries.tokenCatalog = normalizeTokenCatalog(ruleset.contentLibraries.tokenCatalog || []);
  return true;
}

async function persistTokenArtSetting(option, setting) {
  const normalized = normalizeTokenImageSetting(setting);
  if (!option || !normalized.src || !String(normalized.src).startsWith("data:") || !backendSync.enabled) return normalized;
  const gameId = backendSync.gameId || backendGameId();
  const response = await backendFetch(`/api/games/${encodeURIComponent(gameId)}/token-art/${encodeURIComponent(option.key)}`, {
    method: "PUT",
    body: JSON.stringify({ setting: normalized })
  });
  if (!response.ok) throw new Error(`Token art upload failed (${response.status})`);
  const payload = await response.json();
  return normalizeTokenImageSetting(payload.setting || normalized);
}

function tokenImageKeyFromName(name) {
  return slugify(displayInventoryTokenName(name || ""));
}

function normalizeTokenImageSetting(value) {
  if (!value) return { src: "", fit: "cover", zoom: 1, x: 0, y: 0, rotate: 0, borderColor: "" };
  if (typeof value === "string") {
    const src = String(value || "");
    return { src, fit: "cover", zoom: 1, x: 0, y: 0, rotate: 0, borderColor: "" };
  }
  return {
    src: String(value.src || value.url || ""),
    fit: value.fit === "contain" ? "contain" : "cover",
    zoom: Math.max(0.7, Math.min(1.5, Number(value.zoom || 1))),
    x: Math.max(-40, Math.min(40, Number(value.x || 0))),
    y: Math.max(-40, Math.min(40, Number(value.y || 0))),
    rotate: Math.max(-180, Math.min(180, Number(value.rotate || 0))),
    borderColor: /^#[0-9a-f]{6}$/i.test(String(value.borderColor || "")) ? value.borderColor : "",
    custom: Boolean(value.custom)
  };
}

function customTokenImageSettingForKey(key) {
  const sharedSetting = normalizeTokenImageSetting(activeTokenArtLibrary()[key]);
  if (sharedSetting.src && sharedSetting.custom) return sharedSetting;
  const localSetting = normalizeTokenImageSetting(tokenImageOverrides[key]);
  if (localSetting.src && localSetting.custom) return localSetting;
  return null;
}

function builtInTokenImageSettingForKey(key) {
  return tokenImageRegistry[key] ? normalizeTokenImageSetting(tokenImageRegistry[key]) : null;
}

function tokenImageSettingForKey(key) {
  return normalizeTokenImageSetting(customTokenImageSettingForKey(key) || builtInTokenImageSettingForKey(key) || "");
}

function makePokemonId(trainerId, name) {
  return `${trainerId}-${slugify(name) || "pokemon"}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 7)}`;
}

function phaseCode(series = state.series, gym = state.gym) {
  return `${seriesCodes[series] || series.slice(0, 1).toUpperCase()}G${gym}`;
}

function phaseStateKey(series = state.series, gym = state.gym) {
  return `${series}:G${Number(gym)}`;
}

function liveRefereeFlowStateForPhase(phase, phaseState = {}) {
  if (phase === "start") return LIVE_REFEREE_FLOW_STATES.PRE_GYM;
  if (phase === "action") return LIVE_REFEREE_FLOW_STATES.ACTION;
  if (phase === "battle") {
    return {
      teamPreparation: LIVE_REFEREE_FLOW_STATES.TEAM_BUILD,
      teamSubmissionLock: LIVE_REFEREE_FLOW_STATES.TEAM_LOCK,
      sabotage: LIVE_REFEREE_FLOW_STATES.SABOTAGE,
      teamPreview: LIVE_REFEREE_FLOW_STATES.TEAM_PREVIEW,
      rivalBattles: LIVE_REFEREE_FLOW_STATES.RIVAL_BATTLES,
      battleDataReporting: LIVE_REFEREE_FLOW_STATES.GYM_PAYOUT
    }[normalizeBattlePhaseSubstep(phaseState?.battlePhase?.substep)] || LIVE_REFEREE_FLOW_STATES.TEAM_BUILD;
  }
  if (phase === "battle-results") return LIVE_REFEREE_FLOW_STATES.GYM_PAYOUT;
  if (phase === "shop") return LIVE_REFEREE_FLOW_STATES.SHOPPING;
  return LIVE_REFEREE_FLOW_STATES.PRE_GYM;
}

function normalizeLiveRefereeFlowState(value, phase, phaseState = {}) {
  const valid = Object.values(LIVE_REFEREE_FLOW_STATES);
  return valid.includes(value) ? value : liveRefereeFlowStateForPhase(phase, phaseState);
}

function ensureGymPhaseState(series = state.series, gym = state.gym, targetState = state) {
  targetState.phaseState ||= {};
  const key = phaseStateKey(series, gym);
  const existing = targetState.phaseState[key] || {};
  const fallbackPhase = gymPhases.includes(targetState.currentPhase) ? targetState.currentPhase : "start";
  const currentPhase = gymPhases.includes(existing.currentPhase) ? existing.currentPhase : fallbackPhase;
  const phaseHistory = Array.isArray(existing.phaseHistory) ? existing.phaseHistory : [{
    series,
    gym: Number(gym),
    phase: currentPhase,
    enteredAt: existing.enteredAt || new Date().toISOString(),
    completedAt: null
  }];
  let flowState = normalizeLiveRefereeFlowState(existing.flowState, currentPhase, existing);
  if (!existing.flowStateUpdatedAt) {
    const latestRecordedFlow = [...phaseHistory].reverse().find((entry) => entry.phase === currentPhase
      && Object.values(LIVE_REFEREE_FLOW_STATES).includes(entry.flowState));
    if (latestRecordedFlow) flowState = latestRecordedFlow.flowState;
  }
  const normalized = {
    series,
    gym: Number(gym),
    currentPhase,
    flowState,
    flowStateUpdatedAt: existing.flowStateUpdatedAt || "",
    phaseHistory,
    momentumDecayApplied: Boolean(existing.momentumDecayApplied),
    shopLevelIncreaseApplied: Boolean(existing.shopLevelIncreaseApplied),
    activeGameCornerTokenSessionId: existing.activeGameCornerTokenSessionId || "",
    gameCornerTokenDraft: existing.gameCornerTokenDraft || null,
    battlePhase: existing.battlePhase && typeof existing.battlePhase === "object" ? existing.battlePhase : {}
  };
  Object.assign(existing, normalized);
  targetState.phaseState[key] = existing;
  targetState.currentPhase = currentPhase;
  return existing;
}

function currentGymPhaseState() {
  return ensureGymPhaseState();
}

function currentPhase() {
  return currentGymPhaseState().currentPhase;
}

function currentLiveRefereeFlowState() {
  const phaseState = currentGymPhaseState();
  if (phaseState.currentPhase === "battle") {
    const derived = liveRefereeFlowStateForPhase("battle", phaseState);
    if ([
      LIVE_REFEREE_FLOW_STATES.SABOTAGE,
      LIVE_REFEREE_FLOW_STATES.TEAM_PREVIEW,
      LIVE_REFEREE_FLOW_STATES.RIVAL_BATTLES,
      LIVE_REFEREE_FLOW_STATES.GYM_PAYOUT
    ].includes(derived)) phaseState.flowState = derived;
  }
  phaseState.flowState = normalizeLiveRefereeFlowState(phaseState.flowState, phaseState.currentPhase, phaseState);
  return phaseState.flowState;
}

function setLiveRefereeFlowState(flowState, phaseState = currentGymPhaseState()) {
  phaseState.flowState = normalizeLiveRefereeFlowState(flowState, phaseState.currentPhase, phaseState);
  phaseState.flowStateUpdatedAt = new Date().toISOString();
  return phaseState.flowState;
}

function setCurrentGymPhase(phase, series = state.series, gym = state.gym) {
  const phaseState = ensureGymPhaseState(series, gym);
  const changed = phaseState.currentPhase !== phase;
  phaseState.currentPhase = phase;
  if (changed) phaseState.flowState = liveRefereeFlowStateForPhase(phase, phaseState);
  state.currentPhase = phase;
  return phaseState;
}

function nextPhaseTarget() {
  if (state.seriesChoiceRequired) return { phase: "chooseStartSeries", label: "Start Series", requiresSeriesChoice: true };
  const phase = currentPhase();
  const flowState = currentLiveRefereeFlowState();
  if (phase === "start" && flowState === LIVE_REFEREE_FLOW_STATES.PRE_GYM) {
    return { phase, flowState: LIVE_REFEREE_FLOW_STATES.GYM_START, label: "Begin Gym Start", flowOnly: true };
  }
  if (phase === "start") return { phase: "action", label: "Start Action Phase" };
  if (phase === "action") return { phase: "battle", label: "Start Battle Phase" };
  if (phase === "battle") {
    if (flowState === LIVE_REFEREE_FLOW_STATES.TEAM_BUILD) {
      return { phase, flowState: LIVE_REFEREE_FLOW_STATES.TEAM_LOCK, label: "Open Team Lock", flowOnly: true };
    }
    if (flowState === LIVE_REFEREE_FLOW_STATES.TEAM_LOCK) {
      return { phase, flowState: LIVE_REFEREE_FLOW_STATES.SABOTAGE, label: "Begin Sabotage", flowOnly: true, requiresTeamsLocked: true };
    }
    if (flowState === LIVE_REFEREE_FLOW_STATES.SABOTAGE) {
      return { phase, flowState: LIVE_REFEREE_FLOW_STATES.TEAM_PREVIEW, label: "Reveal Team Preview", flowOnly: true, requiresTeamsLocked: true };
    }
    if (flowState === LIVE_REFEREE_FLOW_STATES.TEAM_PREVIEW) {
      return { phase, flowState: LIVE_REFEREE_FLOW_STATES.RIVAL_BATTLES, label: "Begin Rival Battles", flowOnly: true };
    }
    return { phase: "battle-results", label: "Begin Gym Payout" };
  }
  if (phase === "battle-results" && flowState === LIVE_REFEREE_FLOW_STATES.GYM_PAYOUT) {
    return { phase, flowState: LIVE_REFEREE_FLOW_STATES.VICTORY_ROAD, label: "Begin Victory Road", flowOnly: true };
  }
  if (phase === "battle-results") return { phase: "shop", label: "Begin Shopping" };
  if (phase === "shop" && flowState === LIVE_REFEREE_FLOW_STATES.SHOPPING) {
    return { phase, flowState: LIVE_REFEREE_FLOW_STATES.END_GYM, label: "End Shopping", flowOnly: true };
  }
  if (Number(state.gym) >= 9) return { phase: "nextGym", label: "Choose Next Series", requiresSeriesChoice: true };
  const next = nextSeriesGym();
  const label = next ? `Start ${next.series === state.series ? `Gym ${next.gym}` : `${next.series} Gym ${next.gym}`}` : "Start Next Gym";
  return { phase: "nextGym", label };
}

function compactPhaseAdvanceLabel(target = nextPhaseTarget()) {
  const label = String(target?.label || "").trim();
  const compactLabels = {
    "Start Series": "Series ->",
    "Begin Gym Start": "Gym Start ->",
    "Start Action Phase": "Action Phase ->",
    "Start Battle Phase": "Battle Phase ->",
    "Open Team Lock": "Team Lock ->",
    "Begin Sabotage": "Sabotage ->",
    "Reveal Team Preview": "Preview ->",
    "Begin Rival Battles": "Rivals ->",
    "Begin Gym Payout": "Payout ->",
    "Begin Victory Road": "Victory Road ->",
    "Begin Shopping": "Shopping ->",
    "End Shopping": "End Shop ->",
    "Choose Next Series": "Next Series ->"
  };
  return compactLabels[label] || label.replace(/^Start\s+/, "").replace(/^Begin\s+/, "").replace(/^Open\s+/, "") || "Next ->";
}

function nextSeriesGym(series = state.series, gym = state.gym, selectedSeries = "") {
  if (Number(gym) < 9) return { series, gym: Number(gym) + 1 };
  if (selectedSeries && seriesNames.includes(selectedSeries)) return { series: selectedSeries, gym: 1 };
  const currentIndex = seriesNames.indexOf(series);
  const nextSeries = seriesNames[currentIndex + 1];
  if (!nextSeries) return null;
  return { series: nextSeries, gym: 1 };
}

function availableSeriesChoices() {
  const played = new Set(state.seriesOrder || []);
  let options = seriesNames.filter((series) => series !== state.series && !played.has(series));
  if (!options.length) options = seriesNames.filter((series) => series !== state.series);
  return options.length ? options : [...seriesNames];
}

function randomSeriesChoice() {
  const options = availableSeriesChoices();
  return options[Math.floor(Math.random() * options.length)] || seriesNames[0];
}

function migratePokemonRecords(targetState = state) {
  const seen = new Set();
  targetState.pokemonRecords = (targetState.pokemonRecords || []).map((pokemon) => normalizePokemonRecord(pokemon));
  targetState.pokemonRecords.forEach((pokemon) => seen.add(`${pokemon.trainerId}:${pokemon.name.toLowerCase()}`));
  targetState.players.forEach((player) => {
    (player.pokemon || []).forEach((entry) => {
      const name = typeof entry === "string" ? entry : entry.name;
      if (!name) return;
      const key = `${player.id}:${name.toLowerCase()}`;
      if (seen.has(key)) return;
      targetState.pokemonRecords.push(normalizePokemonRecord({
        id: makePokemonId(player.id, name),
        name,
        trainerId: player.id,
        firstCaughtSeries: targetState.series || "Kanto",
        firstCaughtGym: Number(targetState.gym || 1),
        log: [{
          action: "Caught / Obtained",
          series: targetState.series || "Kanto",
          gym: Number(targetState.gym || 1),
          notes: "Migrated from existing roster",
          timestamp: new Date().toISOString()
        }]
      }));
      seen.add(key);
    });
  });
}

function normalizePokemonRecord(pokemon) {
  const status = pokemonStatuses.includes(pokemon.status) ? pokemon.status : "Active";
  const rosterType = pokemonRosterTypes.includes(pokemon.rosterType)
    ? pokemon.rosterType
    : status === "Released" ? "Released" : pokemon.status === "Legacy" ? "Legacy" : "Active";
  const displayName = pokemon.currentSpecies || pokemon.name || pokemon.baseSpecies || "Unknown Pokemon";
  const baseSpecies = pokemon.baseSpecies || pokemon.seriesStartSpecies || pokemon.resetsToSpecies || pokemon.name || displayName;
  const currentSpecies = pokemon.currentSpecies || displayName;
  const seriesStartSpecies = pokemon.seriesStartSpecies || baseSpecies;
  const resetsToSpecies = pokemon.resetsToSpecies || seriesStartSpecies;
  const acquiredSpeciesName = pokemon.acquiredSpeciesName || pokemon.acquiredSpecies || pokemon.originallyObtainedSpecies || displayName;
  const rosterSpeciesName = pokemon.rosterSpeciesName || pokemon.rosterSpecies || seriesStartSpecies || baseSpecies || displayName;
  return {
    id: pokemon.id || makePokemonId(pokemon.trainerId || "unknown", displayName),
    name: currentSpecies,
    trainerId: pokemon.trainerId || "unknown",
    ownerId: pokemon.ownerId || pokemon.trainerId || "unknown",
    baseSpecies,
    currentSpecies,
    currentEvolutionStage: Number.isFinite(Number(pokemon.currentEvolutionStage)) ? Number(pokemon.currentEvolutionStage) : teambuilderEvolutionStageIndex(currentSpecies),
    evolutionLineId: pokemon.evolutionLineId || teambuilderEvolutionLineId(currentSpecies),
    acquiredSpeciesId: pokemon.acquiredSpeciesId || normalizePokemonApiName(acquiredSpeciesName),
    acquiredSpeciesName,
    rosterSpeciesId: pokemon.rosterSpeciesId || normalizePokemonApiName(rosterSpeciesName),
    rosterSpeciesName,
    seriesEvolutionLockSpeciesId: pokemon.seriesEvolutionLockSpeciesId || "",
    seriesEvolutionLockSpeciesName: pokemon.seriesEvolutionLockSpeciesName || "",
    seriesEvolutionLockSeriesId: pokemon.seriesEvolutionLockSeriesId || "",
    seriesEvolutionLockCreatedAt: pokemon.seriesEvolutionLockCreatedAt || "",
    seriesStartSpecies,
    resetsToSpecies,
    status,
    rosterType,
    rosterStatus: pokemon.rosterStatus || rosterType.toLowerCase(),
    facilityStatus: pokemon.facilityStatus || "",
    unavailableUntil: pokemon.unavailableUntil || null,
    ruleStatus: pokemonRuleStatuses.includes(pokemon.ruleStatus) ? pokemon.ruleStatus : "Normal",
    firstCaughtSeries: pokemon.firstCaughtSeries || "Kanto",
    firstCaughtGym: Number(pokemon.firstCaughtGym || 1),
    spriteUrl: pokemon.spriteUrl || "",
    source: pokemon.source || "",
    sourceTier: normalizeAcquisitionFamilyId(pokemon.sourceTier) || pokemon.sourceTier || "",
    chosenSpriteKey: pokemon.chosenSpriteKey || "",
    acquisitionTier: normalizeAcquisitionFamilyId(pokemon.acquisitionTier) || getPokemonAcquisitionTier(acquiredSpeciesName || displayName),
    gameCornerMetadata: pokemon.gameCornerMetadata || getPokemonGameCornerMetadata(displayName) || null,
    addedAt: pokemon.addedAt || new Date().toISOString(),
    kills: Number(pokemon.kills || 0),
    deaths: Number(pokemon.deaths || 0),
    gymsBrought: Number(pokemon.gymsBrought || 0),
    gymsBenched: Number(pokemon.gymsBenched || 0),
    gymsOnRoster: Number(pokemon.gymsOnRoster || 0),
    battlesWon: Number(pokemon.battlesWon || 0),
    battlesLost: Number(pokemon.battlesLost || 0),
    buffs: (pokemon.buffs || [])
      .filter((buff) => slugify(buff) !== "link-cable")
      .map((buff) => /^Egg\s+Move\s+Pending$/i.test(String(buff)) ? "TM Move Pending" : buff),
    effectBuffs: Array.isArray(pokemon.effectBuffs) ? pokemon.effectBuffs : [],
    nerfs: pokemon.nerfs || [],
    breederStatus: pokemon.breederStatus || null,
    dragonDenStatus: pokemon.dragonDenStatus || null,
    routeEncounterMetadata: pokemon.routeEncounterMetadata || null,
    acquisitionMetadata: pokemon.acquisitionMetadata || null,
    evolutionHistory: Array.isArray(pokemon.evolutionHistory) ? pokemon.evolutionHistory : [],
    log: pokemon.log || []
  };
}

function inventoryCategoryChildArrays(entry = {}) {
  return [entry.contents, entry.records, entry.children, entry.inventoryRecords, entry.items]
    .filter(Array.isArray);
}

function concreteInventoryRecordFromCategory(parent, child, index = 0) {
  const source = typeof child === "string" ? { name: child } : (child || {});
  const name = String(source.name || source.itemName || source.moveName || "").trim();
  if (!name) return null;
  return normalizeTmInventoryEntry({
    ...parent,
    ...source,
    id: String(source.id || `${parent.id || slugify(parent.name)}--${slugify(name)}-${index + 1}`),
    name,
    parentInventoryRecordId: parent.id || "",
    parentShopItemName: parent.parentShopItemName || parent.name || "",
    inventoryCategoryContainer: false
  });
}

function expandInventoryCategoryRecords(entry = {}) {
  const definition = staticShopChoiceDefinitionByName(entry.name);
  const nested = inventoryCategoryChildArrays(entry).flat();
  if (nested.length) {
    return nested
      .map((child, index) => concreteInventoryRecordFromCategory(entry, child, index))
      .filter(Boolean);
  }
  if (definition?.options?.length && entry.source === "Max Testing Setup") {
    return definition.options
      .map((name, index) => concreteInventoryRecordFromCategory(entry, { name }, index))
      .filter(Boolean);
  }
  if (definition?.options?.length) {
    return [{ ...entry, inventoryCategoryContainer: true }];
  }
  return [entry];
}

function syncPlayerPokemonLists(targetState = state) {
  targetState.players.forEach((player) => {
    const ownedPokemon = targetState.pokemonRecords
      .filter((pokemon) => pokemon.trainerId === player.id && !["Released", "Removed"].includes(pokemon.status));
    player.pokemon = ownedPokemon.map((pokemon) => pokemon.name);
    player.pokemonIds = ownedPokemon.map((pokemon) => pokemon.id).filter(Boolean);
  });
}

function addPokemonLog(pokemon, action, notes = "", series = state.series, gym = state.gym) {
  const entry = {
    id: `poke-log-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
    pokemonId: pokemon.id,
    pokemonName: pokemon.name,
    trainerId: pokemon.trainerId,
    action,
    series,
    gym: Number(gym),
    notes,
    timestamp: new Date().toISOString()
  };
  pokemon.log = [entry, ...(pokemon.log || [])];
  state.pokemonLog = [entry, ...(state.pokemonLog || [])].slice(0, 300);
}

function createInteractionEvent({
  id = "",
  type,
  title,
  message,
  actorPlayerId = "",
  targetPlayerId = "",
  sourceType = "",
  sourceId = "",
  payload = {},
  responseTypes = [],
  eligiblePlayerIds = [],
  series = state.series,
  gym = Number(state.gym),
  phase = currentPhase()
}) {
  state.interactionEvents ||= [];
  const allowedResponseTypes = payload.responsesAllowed === false
    ? []
    : [...new Set(responseTypes.length ? responseTypes : activityResponseTypesFor({ type, sourceType, payload }))];
  const event = {
    id: id || `interaction-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
    type,
    title,
    message,
    actorPlayerId,
    targetPlayerId,
    sourceType,
    sourceId,
    payload,
    responseTypes: allowedResponseTypes,
    eligiblePlayerIds,
    responses: [],
    transactions: [],
    promptPriority: {},
    promptResolutions: {},
    series,
    gym: Number(gym || 1),
    phase,
    status: "open",
    eventOrder: nextEventOrder(),
    createdAt: new Date().toISOString()
  };
  interactionPromptResolution(event, interactionRootPromptId(event));
  ensureInteractionPromptPriority(event, interactionRootPromptStep(event), state);
  syncInteractionSituation(event);
  state.interactionEvents.unshift(event);
  console.info("Rival Saga respondable Activity created", {
    id: event.id,
    type: event.type,
    sourceType: event.sourceType,
    eligiblePlayerIds: event.eligiblePlayerIds,
    responseTypes: event.responseTypes
  });
  if (playerCanRespondToActivity(event, activePlayer().id)) createActivityToastFromInteraction(event);
  pushBackendActivity(event);
  eligiblePlayerIds.forEach((playerId) => {
    createPlayerNotification(playerId, {
      type: "interaction-window",
      title,
      message: `${message} A respondable Activity is open.`,
      sourceType: "interaction-event",
      sourceId: event.id,
      priority: 2,
      requiresAction: false,
      payload: { interactionEventId: event.id }
    });
  });
  return event;
}

function createPokemonResultTimingWindow(session, player) {
  if (!session || session.interactionEventId || !player) return null;
  const resultName = session.resultDisplayName || session.resultPokemonName || "Pokemon result";
  const isEncounter = session.sourceType === "encounter";
  const activity = createInteractionEvent({
    type: isEncounter ? "encounter-result" : "pokemon-result",
    title: `${player.name} rolled ${resultName}`,
    message: `${session.sourceLabel || "Pokemon result"} is pending before it resolves.`,
    actorPlayerId: player.id,
    targetPlayerId: player.id,
    sourceType: session.sourceType || "random-pokemon",
    sourceId: session.id,
    responseTypes: ["encounter-reroll", "steal-encounter"],
    eligiblePlayerIds: state.players.map((entry) => entry.id),
    series: session.series || state.series,
    gym: Number(session.gym || state.gym),
    phase: session.phase || currentPhase(),
    payload: {
      randomPokemonSessionId: session.id,
      gameCornerSessionId: session.gameCornerSessionId || "",
      actionVisitId: session.actionVisitId || "",
      encounterSessionId: session.encounterSessionId || "",
      encounterRollId: session.encounterRollId || "",
      resultName,
      sourceLabel: session.sourceLabel || ""
    }
  });
  session.interactionEventId = activity.id;
  return activity;
}

function resolvePokemonResultTimingWindow(session, mode = "resolved") {
  if (!session?.interactionEventId) return;
  resolveInteractionActivity(session.interactionEventId, mode, { renderAfter: false });
}

function createActivityToastFromInteraction(activity) {
  if (!activity) return;
  state.activityToasts ||= [];
  const toast = {
    id: `activity-toast-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
    interactionId: activity.id || "",
    title: activity.title || "Respondable Activity",
    message: activity.message || "",
    category: "interaction",
    playerIds: [activity.actorPlayerId, activity.targetPlayerId, ...(activity.eligiblePlayerIds || [])].filter(Boolean),
    createdAt: new Date().toISOString()
  };
  state.activityToasts.unshift(toast);
  state.activityToasts = state.activityToasts.slice(0, 5);
}

function activityRuleKey(activity) {
  if (!activity) return "";
  if (activityResponseRules[activity.type]) return activity.type;
  if (activity.sourceType === "status-token-activation") return "token-activation";
  if (activity.sourceType === "utility-token-activation") return "token-activation";
  if (/class/i.test(activity.sourceType || "")) return "class-activation";
  if (/perk/i.test(activity.sourceType || "")) return "perk-activation";
  if (/pokemon-result|random-pokemon|encounter/i.test(`${activity.type || ""} ${activity.sourceType || ""}`)) return "pokemon-result";
  return "";
}

function activityResponseTypesFor(activity) {
  const rule = activityResponseRules[activityRuleKey(activity)];
  return [...(activity?.responseTypes || []), ...(rule?.responseTypes || [])].filter(Boolean);
}

function normalizeInteractionResponse(activity, response) {
  if (!response || typeof response !== "object" || Array.isArray(response)) return null;
  const id = String(response.id || `interaction-response-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`);
  const type = String(response.type || "manual");
  const respondingToPromptId = String(response.respondingToPromptId || response.promptId || interactionRootPromptId(activity));
  const createsPrompt = response.createsPrompt !== undefined ? Boolean(response.createsPrompt) : type !== "pass";
  return {
    ...response,
    id,
    type,
    playerId: String(response.playerId || ""),
    respondingToPromptId,
    promptId: respondingToPromptId,
    createsPrompt,
    promptStepId: createsPrompt ? String(response.promptStepId || `response:${id}`) : "",
    status: String(response.status || ""),
    tokenName: String(response.tokenName || ""),
    note: String(response.note || ""),
    targetText: String(response.targetText || ""),
    createdAt: response.createdAt || new Date().toISOString(),
    eventOrder: Number(response.eventOrder || 0)
  };
}

function syncInteractionSituation(activity, patch = {}, targetState = state) {
  if (!activity || interactionSituationLifecycle.isMisroutedResponseActivity(activity)) return null;
  const current = interactionSituationLifecycle.normalizeSituation(activity);
  if (interactionSituationLifecycle.isTerminal(activity)) {
    return interactionSituationLifecycle.syncActivity(activity, patch);
  }
  if (current.status === interactionSituationLifecycle.STATUSES.FAILED_RECOVERY_REQUIRED
    && !patch.status) {
    return interactionSituationLifecycle.syncActivity(activity, patch);
  }
  if (current.status === interactionSituationLifecycle.STATUSES.RESOLVING && !patch.status) {
    return interactionSituationLifecycle.syncActivity(activity, patch);
  }
  if (provisionalDeclarationRuntime.isProvisionalActivity(activity) && !patch.status) {
    const actorName = (targetState.players || []).find((player) => player.id === activity.payload?.declaringPlayerId)?.name || "The declaring player";
    return interactionSituationLifecycle.syncActivity(activity, {
      status: interactionSituationLifecycle.STATUSES.AWAITING_REQUIRED_CHOICE,
      actingPlayerId: activity.payload?.declaringPlayerId || activity.actorPlayerId || "",
      requiredAction: `Complete the ${activity.payload?.effectName || "effect"} declaration or withdraw.`,
      blockingReason: `${actorName} has claimed the Control Timing window.`,
      resumesAfter: activity.situation?.resumesAfter || "Return to the interrupted Action destination decision.",
      ...patch
    });
  }
  const step = currentInteractionPromptStep(activity);
  const priority = currentInteractionPromptPriority(activity, step, targetState);
  const requiredChoiceText = String(activity.payload?.requiredChoiceText || "").trim();
  const waitingPlayerId = String(priority?.currentPriorityPlayerId || "");
  const status = requiredChoiceText
    ? interactionSituationLifecycle.STATUSES.AWAITING_REQUIRED_CHOICE
    : waitingPlayerId
      ? interactionSituationLifecycle.STATUSES.AWAITING_RESPONSE
      : interactionSituationLifecycle.STATUSES.PENDING;
  const requiredAction = requiredChoiceText
    || (waitingPlayerId ? "Respond or choose No Response." : "Resolve the current prompt.");
  return interactionSituationLifecycle.syncActivity(activity, {
    status,
    actingPlayerId: waitingPlayerId,
    requiredAction,
    blockingReason: `The ${activity.payload?.tokenName || activity.title || "current"} situation must finish before gameplay advances.`,
    resumesAfter: activity.payload?.resumesAfter || `Return to ${activity.phase || "the previous gameplay situation"}.`,
    ...patch
  });
}

function normalizeInteractionActivity(activity, targetState = state) {
  const rawStatus = activity?.status === "pending" ? "open" : activity?.status;
  const event = {
    ...activity,
    status: ["open", "resolved", "negated", "expired", "canceled", "withdrawn", "undone"].includes(rawStatus) ? rawStatus : "open",
    responses: Array.isArray(activity?.responses) ? activity.responses : [],
    transactions: Array.isArray(activity?.transactions) ? activity.transactions.map(normalizeTransactionRecord).filter(Boolean) : [],
    payload: activity?.payload || {},
    eligiblePlayerIds: Array.isArray(activity?.eligiblePlayerIds) ? activity.eligiblePlayerIds : [],
    promptPriority: activity?.promptPriority && typeof activity.promptPriority === "object" && !Array.isArray(activity.promptPriority)
      ? activity.promptPriority
      : {},
    promptResolutions: activity?.promptResolutions && typeof activity.promptResolutions === "object" && !Array.isArray(activity.promptResolutions)
      ? activity.promptResolutions
      : {},
    createdAt: activity?.createdAt || new Date().toISOString(),
    eventOrder: Number(activity?.eventOrder || 0)
  };
  event.responses = event.responses.map((response) => normalizeInteractionResponse(event, response)).filter(Boolean);
  event.responseTypes = [...new Set(event.responseTypes?.length ? event.responseTypes : activityResponseTypesFor(event))];
  normalizeInteractionPromptResolutions(event);
  normalizeInteractionPromptPriorities(event, targetState);
  const loadedSituation = interactionSituationLifecycle.normalizeSituation(event);
  if (loadedSituation.status === interactionSituationLifecycle.STATUSES.RESOLVING) {
    interactionSituationLifecycle.markFailed(event, "Resolution was interrupted before the event reached a terminal state.", {
      mutationState: loadedSituation.mutationState
    });
  } else {
    syncInteractionSituation(event, {}, targetState);
  }
  return event;
}

function mergeInteractionActivity(activity, { showToast = false, renderAfter = false } = {}) {
  if (!activity?.id) return null;
  if (interactionSituationLifecycle.isMisroutedResponseActivity(activity)) return null;
  state.interactionEvents ||= [];
  const incoming = normalizeInteractionActivity(activity, state);
  const index = state.interactionEvents.findIndex((event) => event.id === incoming.id);
  if (index >= 0) {
    const existing = state.interactionEvents[index];
    state.interactionEvents[index] = {
      ...existing,
      ...incoming,
      transactions: incoming.transactions?.length ? incoming.transactions : existing.transactions || []
    };
  } else {
    state.interactionEvents.unshift(incoming);
  }
  syncLinkedTransactions();
  if (showToast
    && playerCanRespondToActivity(incoming, activePlayer().id)
    && !(state.activityToasts || []).some((toast) => toast.interactionId === incoming.id)) {
    createActivityToastFromInteraction(incoming);
  }
  writeStoredState(state);
  if (renderAfter) render();
  return incoming;
}

function playerHasResponseResource(player, responseType) {
  const definition = activityResponseDefinitions[responseType];
  if (!definition) return false;
  return (definition.tokenNames || []).some((tokenName) => findInventoryTokenIndex(player, tokenName, responseType === "immunity" ? utilityTokenDefinitions.immunity : null) >= 0);
}

function sandboxSuppressedInteractionEventIds(targetState = state) {
  if (!tokenScenarioSandboxActive()) return new Set();
  return new Set((targetState.testingTools?.activeScenario?.suppressedInteractionEventIds || []).map(String));
}

function sandboxInteractionEventVisible(event, targetState = state) {
  return !sandboxSuppressedInteractionEventIds(targetState).has(String(event?.id || ""));
}

function openInteractionActivities(status = "open") {
  return (state.interactionEvents || [])
    .filter((event) => sandboxInteractionEventVisible(event, state))
    .filter((event) => interactionSituationLifecycle.isBlocking(event))
    .filter((event) => !status || event.status === status)
    .sort((a, b) => Number(a.eventOrder || 0) - Number(b.eventOrder || 0)
      || new Date(a.createdAt || 0) - new Date(b.createdAt || 0));
}

function openInteractionActivitiesForPlayer(playerId = activePlayer().id, status = "open") {
  return openInteractionActivities(status)
    .filter((activity) => playerCanRespondToActivity(activity, playerId));
}

function respondableActivityCount(playerId = activePlayer().id) {
  return openInteractionActivitiesForPlayer(playerId, "open").length;
}

function renderActivityToasts() {
  if (!els.activityToastStack) return;
  if (activityToastTimer) {
    clearTimeout(activityToastTimer);
    activityToastTimer = null;
  }
  state.activityToasts ||= [];
  const cutoff = Date.now() - 30000;
  state.activityToasts = state.activityToasts
    .filter((toast) => new Date(toast.createdAt || 0).getTime() >= cutoff)
    .slice(0, 5);
  state.routeUiState = normalizeRouteUiState(state.routeUiState);
  const publicRouteToasts = state.routeUiState.publicActivityToasts
    .filter((toast) => new Date(toast.expiresAt || 0).getTime() > Date.now())
    .slice(0, 5);
  state.routeUiState.publicActivityToasts = publicRouteToasts;
  const responseMarkup = state.activityToasts.map((toast) => {
    const createdAt = new Date(toast.createdAt || Date.now());
    return `
      <article class="activity-toast" data-toast-id="${escapeHtml(toast.id)}" data-open-activity-toast="${escapeHtml(toast.interactionId || "")}">
        <div>
          <span>Response Needed</span>
          <strong>${escapeHtml(toast.title || "Activity")}</strong>
          ${toast.message ? `<p>${escapeHtml(String(toast.message).split("\n")[0])}</p>` : ""}
          <em>${createdAt.toLocaleTimeString([], { hour: "numeric", minute: "2-digit" })}</em>
        </div>
        <button class="ghost-button mini-button" type="button" data-dismiss-activity-toast="${escapeHtml(toast.id)}" aria-label="Dismiss activity">x</button>
      </article>
    `;
  }).join("");
  const routeMarkup = publicRouteToasts.map((toast) => {
    const createdAt = new Date(toast.occurredAt || Date.now());
    const actor = toast.actorName || "Trainer";
    const routeLabel = toast.routeNumber ? `Route ${toast.routeNumber}` : "a Route";
    const messages = {
      exploring: `${actor} is exploring ${routeLabel}.`,
      encountered: `${actor} encountered a Pokemon on ${routeLabel}.`,
      rerolled: `${actor} rerolled their ${routeLabel} encounter.`,
      obtained: `${actor} obtained ${toast.pokemonName || "a Pokemon"} from ${routeLabel}.`
    };
    return `
      <article class="activity-toast route-public-activity-toast" data-route-public-toast="${escapeHtml(toast.activityId)}">
        <div>
          <span>Route Activity</span>
          <strong>${escapeHtml(messages[toast.stage] || `${actor} is active on ${routeLabel}.`)}</strong>
          <em>${createdAt.toLocaleTimeString([], { hour: "numeric", minute: "2-digit" })}</em>
        </div>
        <button class="ghost-button mini-button" type="button" data-dismiss-route-public-toast="${escapeHtml(toast.activityId)}" aria-label="Dismiss route activity">x</button>
      </article>
    `;
  }).join("");
  els.activityToastStack.innerHTML = `${responseMarkup}${routeMarkup}`;
  if (state.activityToasts.length || publicRouteToasts.length) {
    activityToastTimer = setTimeout(renderActivityToasts, 30000);
  }
}

function activityEligiblePlayerIds(activity) {
  if (activity?.payload?.responsesAllowed === false) return [];
  return [...new Set([activity?.targetPlayerId, ...(activity?.eligiblePlayerIds || [])].filter(Boolean))];
}

function activityResponsesAllowed(activity) {
  return Boolean(activity?.status === "open" && activity?.payload?.responsesAllowed !== false);
}

function activityTransactionsAllowed(activity) {
  return Boolean(activity?.status === "open" && activity?.payload?.transactionsAllowed !== false);
}

function playerCanRespondToActivity(activity, playerId) {
  if (!activityResponsesAllowed(activity)) return false;
  const promptStep = currentInteractionPromptStep(activity);
  const priority = currentInteractionPromptPriority(activity, promptStep, state);
  return Boolean(playerId
    && activity?.status === "open"
    && priority?.currentPriorityPlayerId === playerId
    && !playerAlreadyAnsweredActivity(activity, playerId, promptStep.id));
}

function playerHasImmunityToken(player) {
  return playerHasResponseResource(player, "immunity");
}

function activityResponseButtons(activity, responder) {
  const responseTypes = [...new Set(activityResponseTypesFor(activity))];
  if (!responseTypes.length) return `<span class="activity-response-empty">No response hooks for this Activity yet.</span>`;
  return responseTypes.map((responseType) => {
    const definition = activityResponseDefinitions[responseType];
    if (!definition) return "";
    const hasResource = playerHasResponseResource(responder, responseType);
    const implemented = responseType === "immunity";
    if (implemented) {
      return `<button class="buy-button mini-button" type="button" data-activity-response="${escapeHtml(responseType)}" data-activity-id="${escapeHtml(activity.id)}" ${hasResource ? "" : "disabled"}>${escapeHtml(definition.label)}</button>`;
    }
    return `<button class="ghost-button mini-button" type="button" disabled title="${escapeHtml(definition.description)}">${escapeHtml(definition.label)} Soon</button>`;
  }).join("");
}

function playerOptionsMarkup(selectedId = "", { includeBlank = false, blankLabel = "Choose player" } = {}) {
  const rows = includeBlank ? [`<option value="">${escapeHtml(blankLabel)}</option>`] : [];
  rows.push(...state.players.map((player) => `
    <option value="${escapeHtml(player.id)}" ${player.id === selectedId ? "selected" : ""}>${escapeHtml(player.name)}</option>
  `));
  return rows.join("");
}

function timingWindowResponseTypeOptions(selectedType = "") {
  const options = [
    ["", "Manual / table response"],
    ...Object.values(activityResponseDefinitions).map((definition) => [definition.id, definition.label])
  ];
  return options.map(([value, label]) => `
    <option value="${escapeHtml(value)}" ${value === selectedType ? "selected" : ""}>${escapeHtml(label)}</option>
  `).join("");
}

function manualTimingWindowFormMarkup() {
  return `
    <section class="timing-window-manual" data-manual-timing-window>
      <div class="timing-window-manual-title">
        <span>Open Window</span>
        <strong>Manual Pending Event</strong>
      </div>
      <div class="timing-window-manual-grid">
        <label>
          <span>Acting Player</span>
          <select data-manual-window-field="actorPlayerId">${playerOptionsMarkup(activePlayer().id)}</select>
        </label>
        <label>
          <span>Window</span>
          <select data-manual-window-field="windowType">
            <option value="manual-event">Manual Event</option>
            <option value="teamLockWindow">Sabotage</option>
          </select>
        </label>
        <label>
          <span>Response</span>
          <select data-manual-window-field="responseType">${timingWindowResponseTypeOptions()}</select>
        </label>
        <label class="wide">
          <span>Event</span>
          <input type="text" data-manual-window-field="title" placeholder="Austin rolls an encounter">
        </label>
        <label class="wide">
          <span>Details</span>
          <input type="text" data-manual-window-field="message" placeholder="Result pending before it resolves">
        </label>
      </div>
      <button class="buy-button mini-button" type="button" data-open-manual-window>Open Window</button>
    </section>
  `;
}

function tokenUseFormMarkup({ live = false } = {}) {
  const prefix = live ? "live-token-use" : "token-use";
  const active = activePlayer();
  const otherPlayer = state.players.find((player) => player.id !== active.id)?.id || active.id;
  return `
    <section class="${live ? "live-inline-form live-token-use-form" : "timing-window-manual token-use-form"}" data-${prefix}-form>
      <div class="${live ? "live-form-title" : "timing-window-manual-title"}">
        <span>Use Token</span>
        <strong>Token timing window</strong>
      </div>
      <p class="${live ? "live-form-note" : "timing-window-token-note"}">Control and Curse tokens open pending events. Protection and Encounter tokens are recorded inside the current pending window.</p>
      <div class="${live ? "live-form-grid" : "timing-window-manual-grid"}">
        <label>
          <span>Player</span>
          <select data-${prefix}-field="actorPlayerId">${playerOptionsMarkup(active.id)}</select>
        </label>
        <label>
          <span>Token</span>
          <select data-${prefix}-field="tokenName">${tokenUseOptionRows()}</select>
        </label>
        <label>
          <span>Timing</span>
          <select data-${prefix}-field="timingCategory">${tokenTimingCategoryOptions(TOKEN_TIMING_CATEGORIES.CONTROL)}</select>
        </label>
        <label>
          <span>Target Player</span>
          <select data-${prefix}-field="targetPlayerId">${playerOptionsMarkup(otherPlayer, { includeBlank: true, blankLabel: "No player target" })}</select>
        </label>
        <label class="wide">
          <span>Target / Details</span>
          <input type="text" data-${prefix}-field="targetText" placeholder="Pokemon, move, curse target, encounter result, or resource">
        </label>
        <label class="wide">
          <span>Notes</span>
          <input type="text" data-${prefix}-field="notes" placeholder="Optional table note">
        </label>
        <label class="${live ? "live-checkbox wide" : "live-checkbox wide"}">
          <input type="checkbox" data-${prefix}-field="teamLock">
          <span>Sabotage window</span>
        </label>
      </div>
      <button class="buy-button mini-button" type="button" data-${prefix}-submit>Use Token / Open Window</button>
    </section>
  `;
}

function liveTimingHelpMarkup({ live = false } = {}) {
  return `
    <details class="${live ? "live-timing-help" : "timing-window-help"}">
      <summary>What does this mean?</summary>
      <div class="timing-help-grid">
        <article><strong>Manual Event</strong><p>A host-created pending event for anything the website does not have a dedicated button for yet.</p></article>
        <article><strong>Pending Event</strong><p>Something is happening, but it is not final until its response cycle closes and the current prompt resolves.</p></article>
        <article><strong>Response Window</strong><p>The pause while a Pending Event is open. Players may respond, trade, or choose No Response.</p></article>
        <article><strong>No Response</strong><p>That player is passing on their chance to respond. It does not finalize the event by itself.</p></article>
        <article><strong>Trade</strong><p>Tracked resources move after the receiving player accepts. Promises remain table notes.</p></article>
        <article><strong>Control Token</strong><p>A proactive disruptive token such as Move Deleter, Restrict, Haze, Clear Smog, Arena Trap, or Imprison.</p></article>
        <article><strong>Protection Token</strong><p>A response used during a Pending Event to protect, block, cleanse, prevent, or answer a threat.</p></article>
        <article><strong>Encounter Token</strong><p>A token used during an encounter result window before the encounter is finalized.</p></article>
        <article><strong>Curse Token</strong><p>A dangerous pending curse event. Curses are strongest during Sabotage, after teams are locked and before Team Preview.</p></article>
      </div>
    </details>
  `;
}

function activityStatusLabel(activity) {
  if (activity?.status === "open") return "Pending";
  if (activity?.status === "expired") return "Passed";
  if (activity?.status === "negated") return "Negated";
  if (activity?.status === "canceled") return "Canceled";
  if (activity?.status === "withdrawn") return "Withdrawn";
  if (activity?.status === "undone") return "Undone";
  return "Resolved";
}

function responseHistoryMarkup(activity) {
  const responses = activity.responses || [];
  if (!responses.length) return `<p class="empty-state compact">No responses recorded yet.</p>`;
  return `
    <div class="timing-record-list">
      ${responses.map((response) => {
        const player = state.players.find((entry) => entry.id === response.playerId);
        const label = activityResponseDefinitions[response.type]?.label || response.type || "Response";
        const promptStep = interactionPromptStepById(activity, interactionResponseAnswerPromptId(activity, response));
        const canceled = interactionResponseCanceled(response);
        return `
          <article>
            <span>${escapeHtml(canceled ? `${label} - Canceled` : label)}</span>
            <strong>${escapeHtml(player?.name || "Table")}</strong>
            ${response.tokenName ? `<em>${escapeHtml(response.tokenName)}</em>` : ""}
            ${promptStep ? `<small>Prompt: ${escapeHtml(liveRefereePromptStepLabel(activity, promptStep, { short: true }))}</small>` : ""}
            ${response.note ? `<p>${escapeHtml(response.note)}</p>` : ""}
          </article>
        `;
      }).join("")}
    </div>
  `;
}

function responseFormMarkup(activity) {
  if (activity.status !== "open") return "";
  if (!activityResponsesAllowed(activity)) return `<p class="empty-state compact">Responses are closed for this event.</p>`;
  return `
    <div class="response-composer" data-response-form="${escapeHtml(activity.id)}">
      <label>
        <span>Responder</span>
        <select data-response-field="playerId">${playerOptionsMarkup(activePlayer().id)}</select>
      </label>
      <label>
        <span>Source</span>
        <select data-response-field="source">
          <option value="manual">Manual</option>
          <option value="token">Token</option>
          <option value="class ability">Class Ability</option>
          <option value="item">Item</option>
          <option value="perk">Perk</option>
        </select>
      </label>
      <label class="wide">
        <span>Response</span>
        <input type="text" data-response-field="note" placeholder="Uses a Reroll Token, protection, class effect, or table ruling">
      </label>
      <button class="ghost-button mini-button" type="button" data-record-manual-response="${escapeHtml(activity.id)}">Record Response</button>
    </div>
  `;
}

function transactionResourceParts(transaction) {
  return transactionResourceFields
    .map(([key, label]) => [label, String(transaction[key] || "").trim()])
    .filter(([, value]) => value);
}

function transactionHasAuditOnlyContent(transaction) {
  return Boolean((transaction?.services || []).length
    || String(transaction?.notes || transaction?.promiseText || "").trim());
}

function transactionHasMaterialContent(transaction) {
  return Boolean(Number(transaction?.money?.amount ?? transaction?.moneyAmount ?? 0) > 0
    || (transaction?.pokemon || []).length
    || (transaction?.items || []).length
    || (transaction?.tms || []).length
    || (transaction?.tokens || []).length);
}

function transactionAppliedSummary(transaction) {
  const lines = [];
  if (Number(transaction.money?.amount ?? transaction.moneyAmount ?? 0) > 0) {
    lines.push(`${formatMoney(transaction.money?.amount ?? transaction.moneyAmount)} ${transaction.money?.appliedAutomatically ? "transferred" : "offered"}`);
  }
  if ((transaction.pokemon || []).length) lines.push(`${transaction.pokemon.length} Pokemon ${transaction.pokemon.every((entry) => entry.appliedAutomatically) ? "transferred" : "offered"}`);
  if ((transaction.items || []).length) lines.push(`${transaction.items.length} item${transaction.items.length === 1 ? "" : "s"} ${transaction.items.every((entry) => entry.appliedAutomatically) ? "transferred" : "offered"}`);
  if ((transaction.tms || []).length) lines.push(`${transaction.tms.length} TM${transaction.tms.length === 1 ? "" : "s"} ${transaction.tms.every((entry) => entry.appliedAutomatically) ? "transferred" : "offered"}`);
  if ((transaction.tokens || []).length) lines.push(`${transaction.tokens.length} token${transaction.tokens.length === 1 ? "" : "s"} ${transaction.tokens.every((entry) => entry.appliedAutomatically) ? "transferred" : "offered"}`);
  if ((transaction.services || []).length) lines.push(`${transaction.services.length} service${transaction.services.length === 1 ? "" : "s"} audit-only`);
  if (transaction.notes) lines.push("notes audit-only");
  return lines;
}

function transactionStatusLabel(status) {
  return {
    draft: "Draft",
    submitted: "Submitted",
    pendingAcceptance: "Waiting for Acceptance",
    completed: "Completed",
    declined: "Declined",
    canceled: "Canceled",
    reversed: "Reversed",
    manualOnly: "Manual Only",
    partiallyApplied: "Partially Applied",
    promised: "Promised",
    failed: "Failed"
  }[status] || "Waiting for Acceptance";
}

function transactionSummary(transaction) {
  const parts = [];
  if (Number(transaction.money?.amount ?? transaction.moneyAmount ?? 0)) {
    const applied = transaction.money?.appliedAutomatically ? "transferred" : "offered";
    parts.push(`Money: ${formatMoney(transaction.money?.amount ?? transaction.moneyAmount)} (${applied})`);
  }
  transactionResourceParts(transaction).forEach(([label, value]) => {
    const auditLabel = label === "Promise / Note" || label === "Service" ? "audit note" : "tracked transfer";
    parts.push(`${label}: ${value} (${auditLabel})`);
  });
  return parts.join(" / ") || "No resources listed";
}

function activityTransactionRecords(activity) {
  const byId = new Map();
  (activity.transactions || []).forEach((transaction) => byId.set(transaction.id, transaction));
  (state.transactions || [])
    .filter((transaction) => transaction.linkedEventId === activity.id)
    .forEach((transaction) => byId.set(transaction.id, transaction));
  return [...byId.values()].sort((a, b) => Number(b.eventOrder || 0) - Number(a.eventOrder || 0)
    || new Date(b.createdAt || 0) - new Date(a.createdAt || 0));
}

function transactionHistoryMarkup(activity) {
  const transactions = activityTransactionRecords(activity);
  if (!transactions.length) return `<p class="empty-state compact">No trades linked to this window.</p>`;
  return `
    <div class="timing-record-list transaction-records">
      ${transactions.map((transaction) => {
        const from = state.players.find((player) => player.id === transaction.fromPlayerId);
        const to = state.players.find((player) => player.id === transaction.toPlayerId);
        return `
          <article class="${transaction.status}">
            <span>${escapeHtml(transactionStatusLabel(transaction.status))}</span>
            <strong>${escapeHtml(from?.name || "Table")} -> ${escapeHtml(to?.name || "Table")}</strong>
            <p>${escapeHtml(transactionSummary(transaction))}</p>
            ${transactionAppliedSummary(transaction).length ? `<small>${escapeHtml(transactionAppliedSummary(transaction).join(" - "))}</small>` : ""}
          </article>
        `;
      }).join("")}
    </div>
  `;
}

function tokenConsumptionRecordsForActivity(activity) {
  if (!activity?.id) return [];
  return (state.tokenConsumptions || [])
    .filter((record) => record.linkedEventId === activity.id)
    .map(normalizeTokenConsumptionRecord)
    .filter(Boolean)
    .sort((a, b) => Number(b.eventOrder || 0) - Number(a.eventOrder || 0)
      || new Date(b.consumedAt || 0) - new Date(a.consumedAt || 0));
}

function tokenConsumptionHistoryMarkup(activity) {
  const records = tokenConsumptionRecordsForActivity(activity);
  if (!records.length) return `<p class="empty-state compact">No token uses linked to this window.</p>`;
  return `
    <div class="timing-record-list token-consumption-records">
      ${records.map((record) => {
        const player = state.players.find((entry) => entry.id === record.playerId);
        const status = record.status === "refunded"
          ? "Refunded"
          : record.status === "manual-refund-needed"
            ? "Manual Refund Needed"
            : "Consumed";
        return `
          <article class="${escapeHtml(record.status)}">
            <span>${escapeHtml(status)}</span>
            <strong>${escapeHtml(player?.name || "Table")} - ${escapeHtml(record.tokenName)}</strong>
            <p>${escapeHtml(record.refundReason || effectApplicationLabel(tokenEffectMetadataByName(record.tokenName).resolutionMode))}</p>
          </article>
        `;
      }).join("")}
    </div>
  `;
}

function transactionFormMarkup(activity) {
  if (activity.status !== "open") return "";
  if (!activityTransactionsAllowed(activity)) return `<p class="empty-state compact">Trades are closed for this event.</p>`;
  const activeId = activePlayer().id;
  const otherPlayer = state.players.find((player) => player.id !== activeId)?.id || activeId;
  return `
    <div class="transaction-composer" data-transaction-form="${escapeHtml(activity.id)}">
      <div class="transaction-composer-grid">
        <label>
          <span>From</span>
          <select data-transaction-field="fromPlayerId">${playerOptionsMarkup(activeId)}</select>
        </label>
        <label>
          <span>To</span>
          <select data-transaction-field="toPlayerId">${playerOptionsMarkup(otherPlayer)}</select>
        </label>
        <label>
          <span>Status</span>
          <select data-transaction-field="status">
            <option value="completed">Completed</option>
            <option value="promised">Promise</option>
            <option value="canceled">Canceled</option>
          </select>
        </label>
        <label>
          <span>Money</span>
          <input type="number" min="0" step="1" data-transaction-field="moneyAmount" placeholder="0">
        </label>
        <label>
          <span>Pokemon</span>
          <input type="text" data-transaction-field="pokemonText" placeholder="Names or IDs">
        </label>
        <label>
          <span>Items</span>
          <input type="text" data-transaction-field="itemText" placeholder="Items">
        </label>
        <label>
          <span>TMs</span>
          <input type="text" data-transaction-field="tmText" placeholder="TMs">
        </label>
        <label>
          <span>Tokens</span>
          <input type="text" data-transaction-field="tokenText" placeholder="Reroll Token">
        </label>
        <label class="wide">
          <span>Service</span>
          <input type="text" data-transaction-field="serviceText" placeholder="Ranger reroll, Daycare TM move">
        </label>
        <label class="wide">
          <span>Promise / Note</span>
          <input type="text" data-transaction-field="promiseText" placeholder="Future agreement or timing note">
        </label>
      </div>
      <button class="buy-button mini-button" type="button" data-record-transaction="${escapeHtml(activity.id)}">Record Trade</button>
    </div>
  `;
}

function renderActivityResponseDrawer() {
  if (!els.activityResponseDrawer || !els.activityResponseList) return;
  const responder = activePlayer();
  const openActivities = openInteractionActivities("open");
  const count = openActivities.length;
  const responseCount = openActivities.filter((activity) => playerCanRespondToActivity(activity, responder.id)).length;
  const open = Boolean(state.activityResponseDrawerOpen);
  els.activityResponseColumn?.classList.toggle("drawer-open", open);
  els.activityResponseDrawer.classList.toggle("open", open);
  els.activityResponseTab?.classList.toggle("has-activity", count > 0);
  if (els.activityResponseTab) {
    els.activityResponseTab.textContent = count ? `Windows (${count})` : "Timing";
    els.activityResponseTab.title = responseCount ? `${responseCount} response window${responseCount === 1 ? "" : "s"} available to ${responder.name}` : "Timing windows and trades";
    els.activityResponseTab.setAttribute("aria-expanded", String(open));
  }
  if (!open) return;
  const cards = openActivities.length ? openActivities.map((activity) => {
    const actor = state.players.find((player) => player.id === activity.actorPlayerId);
    const target = state.players.find((player) => player.id === activity.targetPlayerId);
    const eligible = (activity.eligiblePlayerIds || []).map((id) => state.players.find((player) => player.id === id)?.name).filter(Boolean);
    const canRespond = playerCanRespondToActivity(activity, responder.id);
    const responses = canRespond ? activityResponseButtons(activity, responder) : "";
    return `
      <article class="activity-response-card timing-window-card" data-activity-card="${escapeHtml(activity.id)}">
        <div>
          <div class="timing-window-meta">
            <span>#${Number(activity.eventOrder || 0) || "--"}</span>
            <span>${escapeHtml(activityStatusLabel(activity))}</span>
          </div>
          <strong>${escapeHtml(activity.title || "Respondable Activity")}</strong>
          <p>${escapeHtml(activity.message || "")}</p>
          <span>${escapeHtml(activity.series || state.series)} Gym ${Number(activity.gym || state.gym)} - ${escapeHtml(phaseLabels[activity.phase] || "Phase")}</span>
          <small>${actor ? `Actor: ${escapeHtml(actor.name)}` : ""}${target ? ` / Target: ${escapeHtml(target.name)}` : ""}</small>
          ${eligible.length ? `<small>Eligible responders: ${escapeHtml(eligible.join(", "))}</small>` : ""}
          <small>${canRespond ? `Responding as ${escapeHtml(responder.name)}` : "Select an eligible player to respond."}</small>
        </div>
        <div class="activity-response-actions">
          <button class="ghost-button mini-button" type="button" data-activity-pass="${escapeHtml(activity.id)}" ${canRespond ? "" : "disabled"}>Pass</button>
          ${responses}
          <button class="ghost-button mini-button" type="button" data-activity-resolve="${escapeHtml(activity.id)}">Resolve</button>
        </div>
        <section class="timing-window-records">
          <div>
            <span>Responses</span>
            ${responseHistoryMarkup(activity)}
          </div>
          <div>
            <span>Trade Receipts</span>
            ${transactionHistoryMarkup(activity)}
          </div>
        </section>
        ${responseFormMarkup(activity)}
        ${transactionFormMarkup(activity)}
      </article>
    `;
  }).join("") : `<p class="empty-state compact">No pending timing windows.</p>`;
  els.activityResponseList.innerHTML = `${liveTimingHelpMarkup()}${manualTimingWindowFormMarkup()}${tokenUseFormMarkup()}${cards}`;
}

function addInteractionResponse(activityId, response) {
  const activity = (state.interactionEvents || []).find((event) => event.id === activityId);
  if (!activity || activity.status !== "open") return null;
  activity.responses ||= [];
  const responseId = response.id || `interaction-response-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`;
  const answeringPromptId = String(response.respondingToPromptId || response.promptId || currentInteractionPromptStep(activity).id);
  const createsPrompt = response.createsPrompt ?? response.type !== "pass";
  const savedResponse = {
    ...response,
    id: responseId,
    respondingToPromptId: answeringPromptId,
    promptId: answeringPromptId,
    createsPrompt: Boolean(createsPrompt),
    promptStepId: createsPrompt ? response.promptStepId || `response:${responseId}` : "",
    eventOrder: nextEventOrder(),
    createdAt: new Date().toISOString()
  };
  activity.responses.push(savedResponse);
  ensureInteractionPromptPriority(activity, interactionPromptStepById(activity, answeringPromptId), state);
  if (savedResponse.createsPrompt) {
    const childStep = interactionPromptStepById(activity, savedResponse.promptStepId);
    interactionPromptResolution(activity, savedResponse.promptStepId);
    ensureInteractionPromptPriority(activity, childStep, state);
  }
  syncInteractionSituation(activity);
  pushBackendActivityResponse(activityId, savedResponse, activity.status, activity);
  return activity;
}

function transactionDraftFromForm(form) {
  const read = (field) => form.querySelector(`[data-transaction-field="${field}"]`)?.value || "";
  return {
    linkedEventId: form.dataset.transactionForm || "",
    fromPlayerId: read("fromPlayerId"),
    toPlayerId: read("toPlayerId"),
    status: read("status"),
    moneyAmount: Number(read("moneyAmount") || 0),
    pokemonText: read("pokemonText"),
    itemText: read("itemText"),
    tmText: read("tmText"),
    tokenText: read("tokenText"),
    serviceText: read("serviceText"),
    promiseText: read("promiseText")
  };
}

function recordManualResponseFromDrawer(button) {
  const form = button.closest("[data-response-form]");
  if (!form) return;
  const activityId = form.dataset.responseForm || button.dataset.recordManualResponse;
  const activity = (state.interactionEvents || []).find((event) => event.id === activityId);
  if (!activity || activity.status !== "open") {
    alert("Responses can only be linked to a pending timing window.");
    return;
  }
  const read = (field) => form.querySelector(`[data-response-field="${field}"]`)?.value || "";
  const playerId = read("playerId") || activePlayer().id;
  const source = read("source") || "manual";
  const note = read("note").trim();
  if (!note) {
    alert("Describe the response before recording it.");
    return;
  }
  const response = {
    type: "manual",
    playerId,
    source,
    note
  };
  const updated = addInteractionResponse(activity.id, response);
  const responder = state.players.find((player) => player.id === playerId);
  const savedResponse = updated?.responses?.[updated.responses.length - 1];
  addLogEntry({
    action: "interaction",
    category: "system",
    player: responder?.name || "Table",
    item: `${responder?.name || "A player"} responded to ${activity.title}: ${note}`,
    title: "Response recorded",
    summary: [`Window: ${activity.title}`, `Source: ${source}`, note],
    type: "interaction-response",
    categories: ["system", "interaction"],
    tags: ["timing-window", "response", source],
    playerIds: [playerId, activity.actorPlayerId, activity.targetPlayerId].filter(Boolean),
    linkedEventId: activity.id,
    responseId: savedResponse?.id || "",
    eventOrder: savedResponse?.eventOrder
  });
  advanceAutomaticInteractionPrompts(activity);
  resetLiveRefereeScreenState();
  saveState({ immediate: true });
  render();
}

function transactionHasContent(transaction) {
  return Number(transaction.moneyAmount || 0) > 0 || transactionResourceParts(transaction).length > 0;
}

function applyTransactionMoney(transaction) {
  if (transaction.status !== "completed" || Number(transaction.moneyAmount || 0) <= 0) return [];
  const from = state.players.find((player) => player.id === transaction.fromPlayerId);
  const to = state.players.find((player) => player.id === transaction.toPlayerId);
  if (!from || !to || from.id === to.id) return [];
  const amount = Number(transaction.moneyAmount || 0);
  if (Number(from.balance || 0) < amount) {
    alert(`${from.name} needs ${formatMoney(amount)} to complete this trade.`);
    return null;
  }
  const fromChange = applyPlayerMoneyChange(from, -amount, {
    sourceType: "transaction",
    sourceLabel: "Trade",
    note: `Paid ${to.name}`,
    transactionId: transaction.id,
    linkedEventId: transaction.linkedEventId
  });
  const toChange = applyPlayerMoneyChange(to, amount, {
    sourceType: "transaction",
    sourceLabel: "Trade",
    note: `Received from ${from.name}`,
    transactionId: transaction.id,
    linkedEventId: transaction.linkedEventId
  });
  return [fromChange.ledgerEntry?.id, toChange.ledgerEntry?.id].filter(Boolean);
}

function addTransactionLogEntry(transaction, activity) {
  const from = state.players.find((player) => player.id === transaction.fromPlayerId);
  const to = state.players.find((player) => player.id === transaction.toPlayerId);
  const appliedLines = transactionAppliedSummary(transaction);
  const transactionIdLine = `Transaction ID: ${transaction.id}`;
  const summary = [
    `${from?.name || "Table"} -> ${to?.name || "Table"}`,
    `Status: ${transactionStatusLabel(transaction.status)}`,
    transactionSummary(transaction),
    appliedLines.length ? `Application: ${appliedLines.join("; ")}` : "",
    transactionHasAuditOnlyContent(transaction) ? "Audit-only fields do not transfer ownership automatically." : "",
    transaction.promptText ? `Prompt: ${transaction.promptText}` : "",
    activity ? `Linked window: ${activity.title || activity.id}` : "",
    transactionIdLine
  ].filter(Boolean);
  const moneyText = Number(transaction.money?.amount ?? transaction.moneyAmount ?? 0) > 0
    ? ` ${transaction.status === "completed" ? "sent" : "offered"} ${formatMoney(transaction.money?.amount ?? transaction.moneyAmount)} to ${to?.name || "Table"}`
    : "";
  return addLogEntry({
    action: "transaction",
    category: "transactions",
    player: from?.name || "Table",
    item: moneyText
      ? `Trade ${transactionStatusLabel(transaction.status).toLowerCase()}: ${from?.name || "Table"}${moneyText}.`
      : `${from?.name || "Table"} submitted a trade with ${to?.name || "Table"}.`,
    title: transaction.status === "completed"
      ? "Trade completed"
      : transaction.status === "pendingAcceptance"
        ? "Trade offer sent"
        : transaction.status === "declined"
          ? "Trade declined"
      : transaction.status === "partiallyApplied"
        ? "Trade partially applied"
        : transaction.status === "manualOnly"
          ? "Trade recorded for manual cleanup"
          : "Trade recorded",
    summary,
    details: summary,
    type: "transaction",
    categories: ["transactions", Number(transaction.moneyAmount || 0) ? "money" : "interaction"],
    tags: ["transaction", "trade", transaction.status],
    playerIds: [transaction.fromPlayerId, transaction.toPlayerId].filter(Boolean),
    transactionId: transaction.id,
    linkedEventId: transaction.linkedEventId,
    moneyAmount: transaction.moneyAmount,
    moneyChanges: transaction.ledgerEntryIds.map((ledgerEntryId) => ({ ledgerEntryId, sourceType: "transaction" })),
    ledgerEntryIds: transaction.ledgerEntryIds,
    price: Number(transaction.moneyAmount || 0),
    balanceAfter: from?.balance ?? 0,
    eventOrder: transaction.eventOrder
  });
}

function recordTransactionDraft(activity, transactionInput) {
  if (activity && activity.status !== "open") {
    alert("This response window is no longer open.");
    return null;
  }
  if (activity && !activityTransactionsAllowed(activity)) {
    alert("Trades are not open for this event.");
    return null;
  }
  const promptStep = activity ? currentInteractionPromptStep(activity) : null;
  const draft = normalizeTransactionRecord({
    ...transactionInput,
    id: `transaction-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
    linkedEventId: activity?.id || "",
    promptId: transactionInput.promptId || promptStep?.id || "",
    promptText: transactionInput.promptText || (promptStep ? livePromptStepText(activity, promptStep, { short: true }) : ""),
    series: activity?.series || state.series,
    gym: Number(activity?.gym || state.gym),
    phase: activity?.phase || currentPhase(),
    eventOrder: nextEventOrder(),
    createdAt: new Date().toISOString()
  });
  if (!draft || !transactionHasContent(draft)) {
    alert("Add money, Pokemon, items, TMs, tokens, a service, or notes before recording a trade.");
    return null;
  }
  if (!draft.fromPlayerId || !draft.toPlayerId || draft.fromPlayerId === draft.toPlayerId) {
    alert("Choose two different players for this trade.");
    return null;
  }
  draft.status = transactionHasMaterialContent(draft) ? "pendingAcceptance" : "promised";
  draft.submittedByPlayerId = draft.fromPlayerId;
  draft.confirmedAt = "";
  draft.completedAt = "";
  draft.money.appliedAutomatically = false;
  draft.ledgerEntryIds = [];
  draft.money.ledgerEntryIds = [];
  if (activity) {
    activity.transactions ||= [];
    activity.transactions.unshift(draft);
  }
  state.transactions ||= [];
  state.transactions.unshift(draft);
  const logEntry = addTransactionLogEntry(draft, activity);
  if (logEntry?.id) draft.activityLogEntryIds = [logEntry.id, ...(draft.activityLogEntryIds || [])];
  syncLinkedTransactions();
  return draft;
}

function transactionById(transactionId) {
  return (state.transactions || []).find((transaction) => transaction.id === transactionId)
    || (state.interactionEvents || []).flatMap((activity) => activity.transactions || []).find((transaction) => transaction.id === transactionId)
    || null;
}

function updateTransactionCopies(transactionId, changes = {}) {
  const apply = (transaction) => {
    if (transaction?.id !== transactionId) return;
    Object.assign(transaction, changes);
  };
  (state.transactions || []).forEach(apply);
  (state.interactionEvents || []).forEach((activity) => (activity.transactions || []).forEach(apply));
  syncLinkedTransactions();
  return transactionById(transactionId);
}

function resolveTransactionPokemonEntry(entry, fromPlayerId) {
  const records = (state.pokemonRecords || []).filter((pokemon) => pokemon.trainerId === fromPlayerId
    && !["Released", "Removed"].includes(pokemon.status));
  if (entry.pokemonRecordId) return records.find((pokemon) => pokemon.id === entry.pokemonRecordId) || null;
  const matches = records.filter((pokemon) => pokemon.name.toLowerCase() === String(entry.displayName || "").toLowerCase());
  return matches.length === 1 ? matches[0] : null;
}

function resolveTransactionInventoryEntry(entry, fromPlayer, expectedType) {
  const recordId = entry.itemId || entry.tokenRecordId || entry.moveId || "";
  const displayName = entry.itemName || entry.tokenName || entry.moveName || "";
  const matchesType = (item) => expectedType === "TOKEN"
    ? itemIsTokenLike(item) && !isKeyItemTicket(item)
    : expectedType === "ITEM"
      ? ["ITEM", "TICKET"].includes(item.type)
      : item.type === expectedType;
  if (recordId) return (fromPlayer.inventory || []).find((item) => item.id === recordId && matchesType(item)) || null;
  const matches = (fromPlayer.inventory || []).filter((item) => matchesType(item)
    && String(item.name || "").toLowerCase() === String(displayName).toLowerCase());
  return matches.length === 1 ? matches[0] : null;
}

function buildTransactionTransferPlan(transaction) {
  const from = state.players.find((player) => player.id === transaction.fromPlayerId);
  const to = state.players.find((player) => player.id === transaction.toPlayerId);
  if (!from || !to || from.id === to.id) return { ok: false, reason: "The trade players are no longer valid." };
  const amount = Number(transaction.money?.amount ?? transaction.moneyAmount ?? 0);
  if (amount > Number(from.balance || 0)) return { ok: false, reason: `${from.name} no longer has ${formatMoney(amount)}.` };
  const pokemon = (transaction.pokemon || []).map((entry) => ({ entry, record: resolveTransactionPokemonEntry(entry, from.id) }));
  const items = (transaction.items || []).map((entry) => ({ entry, record: resolveTransactionInventoryEntry(entry, from, "ITEM") }));
  const tms = (transaction.tms || []).map((entry) => ({ entry, record: resolveTransactionInventoryEntry(entry, from, "TM") }));
  const tokens = (transaction.tokens || []).map((entry) => ({ entry, record: resolveTransactionInventoryEntry(entry, from, "TOKEN") }));
  const missing = [...pokemon, ...items, ...tms, ...tokens].filter((part) => !part.record);
  if (missing.length) return { ok: false, reason: "One or more offered resources are no longer owned by the proposing player." };
  const ids = [...pokemon, ...items, ...tms, ...tokens].map((part) => part.record.id).filter(Boolean);
  if (ids.length !== new Set(ids).size) return { ok: false, reason: "The same resource appears more than once in this trade." };
  return { ok: true, from, to, amount, pokemon, items, tms, tokens };
}

function applyAcceptedTransaction(transaction, acceptingPlayerId) {
  if (!transaction || transaction.status !== "pendingAcceptance") return { ok: false, reason: "This trade is no longer waiting for acceptance." };
  if (acceptingPlayerId !== transaction.toPlayerId) return { ok: false, reason: "Only the receiving player can accept this trade." };
  const plan = buildTransactionTransferPlan(transaction);
  if (!plan.ok) return plan;
  transaction.status = "completed";
  const ledgerEntryIds = applyTransactionMoney(transaction);
  if (ledgerEntryIds === null) {
    transaction.status = "pendingAcceptance";
    return { ok: false, reason: "The money transfer could not be completed." };
  }
  [...plan.items, ...plan.tms, ...plan.tokens].forEach(({ entry, record }) => {
    const index = plan.from.inventory.findIndex((item) => item.id === record.id);
    if (index >= 0) plan.to.inventory.push(plan.from.inventory.splice(index, 1)[0]);
    entry.appliedAutomatically = true;
    entry.manualNote = "Transferred after recipient acceptance.";
  });
  plan.pokemon.forEach(({ entry, record }) => {
    record.trainerId = plan.to.id;
    record.lastTransferAt = new Date().toISOString();
    record.lastTransferTransactionId = transaction.id;
    entry.appliedAutomatically = true;
    entry.manualNote = "Transferred after recipient acceptance.";
    addPokemonLog(record, "Traded", `${plan.from.name} traded ${record.name} to ${plan.to.name}.`);
  });
  const now = new Date().toISOString();
  transaction.money.appliedAutomatically = ledgerEntryIds.length > 0;
  transaction.money.ledgerEntryIds = ledgerEntryIds;
  transaction.ledgerEntryIds = ledgerEntryIds;
  transaction.acceptedAt = now;
  transaction.acceptedByPlayerId = acceptingPlayerId;
  transaction.confirmedAt = now;
  transaction.completedAt = now;
  syncPlayerPokemonLists();
  return { ok: true, transaction, plan };
}

function acceptLiveTransaction(transactionId) {
  const transaction = transactionById(transactionId);
  const controlledPlayerId = liveRefereeControlledPlayerId();
  const result = applyAcceptedTransaction(transaction, controlledPlayerId);
  if (!result.ok) {
    alert(result.reason);
    return false;
  }
  updateTransactionCopies(transaction.id, transaction);
  const activity = liveActivityById(transaction.linkedEventId);
  const logEntry = addTransactionLogEntry(transaction, activity);
  if (logEntry?.id) transaction.activityLogEntryIds = [logEntry.id, ...(transaction.activityLogEntryIds || [])];
  resetLiveRefereeScreenState();
  saveState({ immediate: true });
  render();
  return true;
}

function declineLiveTransaction(transactionId) {
  const transaction = transactionById(transactionId);
  const controlledPlayerId = liveRefereeControlledPlayerId();
  if (!transaction || transaction.status !== "pendingAcceptance") return false;
  if (controlledPlayerId !== transaction.toPlayerId) {
    alert("Only the receiving player can decline this trade.");
    return false;
  }
  const now = new Date().toISOString();
  transaction.status = "declined";
  transaction.declinedAt = now;
  transaction.declinedByPlayerId = controlledPlayerId;
  updateTransactionCopies(transaction.id, transaction);
  addTransactionLogEntry(transaction, liveActivityById(transaction.linkedEventId));
  resetLiveRefereeScreenState();
  saveState({ immediate: true });
  render();
  return true;
}

function recordTransactionFromDrawer(button) {
  const form = button.closest("[data-transaction-form]");
  if (!form) return;
  if (form.closest("#liveRefereePanel")) {
    const fromPlayerId = form.querySelector('[data-live-transaction-field="fromPlayerId"]')?.value || "";
    const access = liveRefereeControlAccess();
    if (!access.allowed || fromPlayerId !== access.controlledPlayerId) {
      alert("The current viewer cannot offer this trade for that trainer.");
      return;
    }
  }
  const activityId = form.dataset.transactionForm || button.dataset.recordTransaction;
  const activity = (state.interactionEvents || []).find((event) => event.id === activityId);
  if (!activity || activity.status !== "open") {
    alert("Trades can only be linked to a pending timing window.");
    return;
  }
  const draft = recordTransactionDraft(activity, transactionDraftFromForm(form));
  if (!draft) return;
  saveState({ immediate: true });
  render();
}

function openManualTimingWindowFromDrawer() {
  const root = els.activityResponseDrawer?.querySelector("[data-manual-timing-window]");
  if (!root) return;
  const read = (field) => root.querySelector(`[data-manual-window-field="${field}"]`)?.value || "";
  const actorPlayerId = read("actorPlayerId") || activePlayer().id;
  const actor = state.players.find((player) => player.id === actorPlayerId) || activePlayer();
  const windowType = read("windowType") || "manual-event";
  const isTeamLockWindow = windowType === TOKEN_PENDING_EVENT_TYPES.TEAM_LOCK_WINDOW;
  const responseType = read("responseType");
  const title = read("title").trim();
  const message = read("message").trim();
  const finalTitle = title || (isTeamLockWindow ? "Sabotage Window" : "");
  const finalMessage = message || (isTeamLockWindow
    ? "Sabotage is open. Submitted teams are locked before Team Preview."
    : `${finalTitle} is pending.`);
  if (!finalTitle) {
    alert("Name the pending event before opening the window.");
    return;
  }
  const activity = createInteractionEvent({
    type: isTeamLockWindow ? TOKEN_PENDING_EVENT_TYPES.TEAM_LOCK_WINDOW : responseType ? "manual-response-window" : "manual-event",
    title: finalTitle,
    message: finalMessage,
    actorPlayerId: actor.id,
    sourceType: "manual",
    responseTypes: responseType ? [responseType] : [],
    eligiblePlayerIds: state.players.map((player) => player.id),
    payload: {
      responsesAllowed: true,
      transactionsAllowed: true,
      teamLock: isTeamLockWindow,
      livePromptType: isTeamLockWindow ? TOKEN_PENDING_EVENT_TYPES.TEAM_LOCK_WINDOW : TOKEN_PENDING_EVENT_TYPES.MANUAL_EVENT
    }
  });
  addLogEntry({
    action: "interaction",
    category: "system",
    player: actor.name,
    item: `Opened pending event: ${finalTitle}`,
    title: isTeamLockWindow ? "Sabotage window opened" : "Timing window opened",
    summary: [`Pending event: ${finalTitle}`, finalMessage],
    type: "interaction-created",
    categories: ["system", "interaction"],
    tags: ["timing-window", "pending-event", isTeamLockWindow ? "team-lock" : "manual"].filter(Boolean),
    playerIds: state.players.map((player) => player.id),
    linkedEventId: activity.id,
    eventOrder: activity.eventOrder
  });
  state.activityResponseDrawerOpen = true;
  saveState({ immediate: true });
  render();
}

function interactionFinalOutcome(mode, tokenResolution = null) {
  if (mode === "canceled") return "canceledRefunded";
  if (mode === "negated") return "negated";
  if (mode === "pass") return "resolvedNoEffect";
  if (tokenResolution?.finalOutcome) return tokenResolution.finalOutcome;
  if (tokenResolution?.blocked) return "blocked";
  return "resolved";
}

function buildInteractionFinalResultSummary(activity, mode, tokenResolution = null, context = {}) {
  if (!tokenResultSummary?.buildResultSummary) return null;
  let continuation = String(context.continuation || "").trim();
  if (!continuation && tokenResolution?.resultData?.teamMutation?.repairRequired) {
    continuation = `${livePlayerName(activity?.targetPlayerId, "The target player")} must repair their Battle Phase team before Team Lock.`;
  }
  if (!continuation
    && interactionFinalOutcome(mode, tokenResolution) === "resolved"
    && String(activity?.payload?.tokenName || "") !== "Arena Trap") {
    continuation = String(tokenResolution?.announcementDetail || "").trim();
  }
  return tokenResultSummary.buildResultSummary({
    state,
    activity,
    finalOutcome: interactionFinalOutcome(mode, tokenResolution),
    resolvedByEffectId: context.resolvedByEffectId || tokenResolution?.resolvedByEffectId || "",
    resultData: { ...(tokenResolution?.resultData || {}), ...(context.resultData || {}) },
    continuation
  });
}

function rootInteractionResolutionAnnouncement(activity, mode, tokenResolution = null, resolutionText = "", context = {}) {
  const resultSummary = context.resultSummary || buildInteractionFinalResultSummary(activity, mode, tokenResolution, context);
  if (resultSummary && tokenResultSummary?.announcementForResult) {
    const presentation = tokenResultSummary.announcementForResult(resultSummary, state);
    return {
      id: `resolution:${activity?.id || "event"}:${interactionRootPromptId(activity)}:${resultSummary.finalOutcome}`,
      ...presentation,
      linkedEventId: activity?.id || "",
      linkedPromptId: interactionRootPromptId(activity)
    };
  }
  const actorName = livePlayerName(activity?.actorPlayerId, "The table");
  const effectName = String(activity?.payload?.tokenName || activity?.title || "The event").trim();
  const canceled = mode === "canceled";
  const blocked = Boolean(tokenResolution?.blocked);
  const detail = String(resolutionText || tokenResolution?.announcementDetail || "").trim()
    || (canceled ? "The pending effect did not apply." : blocked ? "The effect did not apply." : "The effect finished resolving.");
  return {
    id: `resolution:${activity?.id || "event"}:${interactionRootPromptId(activity)}:${canceled ? "canceled" : blocked ? "blocked" : "resolved"}`,
    title: canceled
      ? `${effectName} was canceled and refunded.`
      : `${liveRefereePossessive(actorName)} ${effectName} resolved.`,
    detail,
    tone: canceled ? "canceledRefunded" : blocked ? "blocked" : resolutionText ? "manual" : "resolved",
    linkedEventId: activity?.id || "",
    linkedPromptId: interactionRootPromptId(activity)
  };
}

function resolveInteractionActivity(activityId, mode = "resolved", {
  renderAfter = true,
  resolutionText = "",
  announcement = null,
  resultContext = {}
} = {}) {
  const activity = (state.interactionEvents || []).find((event) => event.id === activityId);
  if (!activity) return false;
  syncInteractionSituation(activity);
  if (interactionSituationLifecycle.isTerminal(activity)) return true;
  if (activity.status !== "open") return false;
  const revengeProcedure = revengeProcedureForActivity(activity);
  if (mode === "resolved" && revengeProcedure && revengeProcedure.status === "awaitingChoice") {
    syncInteractionSituation(activity, {
      status: interactionSituationLifecycle.STATUSES.AWAITING_REQUIRED_CHOICE,
      actingPlayerId: revengeProcedure.sourcePlayerId,
      requiredAction: "Use or decline Revenge through its exact post-payout choice screen."
    });
    saveState({ immediate: true });
    alert("Revenge cannot be finalized generically. Choose exactly two Pokemon or decline the optional offer.");
    if (renderAfter) render();
    return false;
  }
  const tokenMetadata = activity.sourceType === "token-use"
    ? tokenEffectMetadataByName(activity.payload?.tokenName || "")
    : null;
  if (mode === "resolved" && tokenMetadata) {
    const usability = tokenRuntimeUsabilityCheck(tokenMetadata);
    if (!usability.ok) {
      interactionSituationLifecycle.markFailed(activity, usability.reason, {
        mutationState: interactionSituationLifecycle.MUTATION_STATES.NOT_STARTED
      });
      saveState({ immediate: true });
      alert(usability.reason);
      if (renderAfter) render();
      return false;
    }
  }
  if (mode === "resolved") {
    const promptSafety = interactionPromptStepTokenResolutionSafety(activity, currentInteractionPromptStep(activity));
    if (!promptSafety.ok) {
      interactionSituationLifecycle.markFailed(activity, promptSafety.reason, {
        mutationState: interactionSituationLifecycle.MUTATION_STATES.NOT_STARTED
      });
      saveState({ immediate: true });
      alert(promptSafety.reason);
      if (renderAfter) render();
      return false;
    }
  }
  if (mode === "resolved"
    && tokenMetadata
    && tokenMetadata.resolutionMode !== EFFECT_RESOLUTION_MODES.AUTOMATIC
    && !String(resolutionText || "").trim()) {
    syncInteractionSituation(activity, {
      status: interactionSituationLifecycle.STATUSES.AWAITING_REQUIRED_CHOICE,
      requiredAction: `Record the required ${effectApplicationLabel(tokenMetadata.resolutionMode)} result.`,
      actingPlayerId: ""
    });
    saveState({ immediate: true });
    alert(`${tokenMetadata.name} uses ${effectApplicationLabel(tokenMetadata.resolutionMode)} resolution. Record the requested result before closing it.`);
    if (renderAfter) render();
    return false;
  }
  const completionKey = `${activity.id}:${interactionRootPromptId(activity)}:${mode}`;
  const resolutionStart = interactionSituationLifecycle.beginResolution(activity, completionKey);
  if (!resolutionStart.allowed) {
    if (resolutionStart.reconciled) {
      saveState({ immediate: true });
      if (renderAfter) render();
      return true;
    }
    return resolutionStart.reason === "terminal";
  }
  let tokenResolution = null;
  try {
    tokenResolution = mode === "resolved" ? applyResolvedTokenPendingEvent(activity, { resolutionText }) : null;
  } catch (error) {
    const reason = `Resolution failed before it could safely finish: ${error?.message || "Unknown controller error"}`;
    interactionSituationLifecycle.markFailed(activity, reason);
    console.error("Rival Saga interaction resolution failed.", error);
    saveState({ immediate: true });
    alert(reason);
    if (renderAfter) render();
    return false;
  }
  if (mode === "resolved" && tokenResolution?.failClosed) {
    interactionSituationLifecycle.markFailed(activity, tokenResolution.announcementDetail || `${tokenMetadata?.name || "This Token"} cannot resolve safely yet.`);
    saveState({ immediate: true });
    alert(tokenResolution.announcementDetail || `${tokenMetadata?.name || "This Token"} cannot resolve safely yet.`);
    if (renderAfter) render();
    return false;
  }
  if (mode === "resolved" && tokenMetadata && !tokenResolution) {
    recordTokenContractResolution(activity, tokenMetadata, {
      result: "noEffect",
      details: ["The effect reached resolution but no legal state mutation could be applied."],
      mutations: []
    });
    tokenResolution = { blocked: false, announcementDetail: `${tokenMetadata.name} had no effect.` };
  }
  if (mode === "negated" && tokenMetadata) {
    recordTokenContractResolution(activity, tokenMetadata, {
      result: "negated",
      details: [resultContext.detail || `${tokenMetadata.name} was negated by a gameplay response.`, "Confirmed Token consumption remains."],
      mutations: []
    });
    tokenResolution = {
      blocked: true,
      finalOutcome: "negated",
      resolvedByEffectId: resultContext.resolvedByEffectId || "",
      resultData: resultContext.resultData || {},
      announcementDetail: resultContext.detail || `${tokenMetadata.name} was negated.`
    };
  }
  if (mode === "canceled" && tokenMetadata) {
    const refundedCount = refundTokenConsumptionsForLink({ eventId: activity.id }, "Administrative cancellation");
    recordTokenContractResolution(activity, tokenMetadata, {
      result: "canceledRefunded",
      details: ["The declared event was canceled administratively.", refundedCount ? `${refundedCount} Token${refundedCount === 1 ? " was" : "s were"} refunded.` : "No refundable Token record was found."],
      mutations: []
    });
    tokenResolution = {
      blocked: true,
      finalOutcome: "canceledRefunded",
      announcementDetail: `${tokenMetadata.name} was canceled and ${refundedCount ? "refunded" : "recorded for repair"}.`,
      resultData: { refundedTokenCount: refundedCount }
    };
  }
  const finalOutcome = interactionFinalOutcome(mode, tokenResolution);
  const settledCopyRelationships = controlTokenEffects?.settleTokenCopyRelationshipsForEffect?.(
    state,
    activity.id,
    finalOutcome,
    {
      ...controlTokenEffectOptions(),
      canActivateRelationship: (record) => {
        const sourceResponse = (activity.responses || []).find((response) => response.id === record.sourceEffectId);
        if (!sourceResponse) return false;
        const sourceResolution = interactionPromptResolution(activity, interactionResponsePromptStepId(sourceResponse));
        return sourceResolution.status === "resolved" && sourceResolution.outcome !== "negated-by-response";
      }
    }
  ) || [];
  if (settledCopyRelationships.length) {
    activity.payload ||= {};
    activity.payload.settledCopyRelationshipIds = settledCopyRelationships.map((record) => record.id);
  }
  const gameplayNegated = finalOutcome === "negated";
  const teleportDelayedRecord = activity.payload?.teleportDelayedEffectId
    ? (state.delayedEffects || []).find((record) => record.id === activity.payload.teleportDelayedEffectId)
    : null;
  if (teleportDelayedRecord) {
    if (mode === "canceled" || finalOutcome === "canceledRefunded") {
      const refundedCount = refundTokenConsumptionsByIds(
        teleportDelayedConsumptionIds(teleportDelayedRecord),
        tokenResolution?.announcementDetail || "Teleport return canceled administratively"
      );
      teleportDelayedRecord.status = "canceledRefunded";
      teleportDelayedRecord.refundRequired = true;
      teleportDelayedRecord.refundedTokenCount = Math.max(Number(teleportDelayedRecord.refundedTokenCount || 0), refundedCount);
    } else if (["negated", "blocked", "resolvedNoEffect", "noEffect"].includes(finalOutcome)) {
      teleportDelayedRecord.status = "resolvedNoEffect";
      teleportDelayedRecord.refundRequired = false;
    } else {
      teleportDelayedRecord.status = "resolved";
      teleportDelayedRecord.refundRequired = false;
      teleportDelayedRecord.mutationCompleted = true;
    }
    teleportDelayedRecord.mutationStarted = true;
    teleportDelayedRecord.resolvedAt = new Date().toISOString();
    teleportDelayedRecord.resolutionReason = tokenResolution?.announcementDetail || resolutionText || `${activity.title} finished its Teleport return.`;
    teleportDelayedRecord.resultData = structuredClone(tokenResolution?.resultData || null);
  }
  const rootResolution = interactionPromptResolution(activity, interactionRootPromptId(activity));
  rootResolution.status = mode === "canceled" ? "canceled" : gameplayNegated ? "negated" : "resolved";
  rootResolution.outcome = finalOutcome;
  rootResolution.resultText = String(resolutionText || rootResolution.resultText || "").trim();
  rootResolution.resolvedAt ||= new Date().toISOString();
  activity.payload ||= {};
  if (rootResolution.resultText) activity.payload.resolutionResultText = rootResolution.resultText;
  if (mode === "canceled" || finalOutcome === "canceledRefunded") {
    interactionSituationLifecycle.markCanceledRefunded(activity, {
      tokenConsumed: Boolean(activity.situation?.tokenConsumed)
    });
  } else {
    interactionSituationLifecycle.markResolved(activity, {
      tokenConsumed: Boolean(activity.situation?.tokenConsumed)
    });
  }
  activity.status = mode === "pass"
    ? "expired"
    : mode === "canceled" || finalOutcome === "canceledRefunded"
      ? "canceled"
      : gameplayNegated
        ? "negated"
        : "resolved";
  activity.resolvedAt = new Date().toISOString();
  activity.resolutionMode = mode;
  state.liveTable = normalizeLiveTableState({ ...(state.liveTable || {}), lastResolvedEventId: activity.id });
  pushBackendActivityStatus(activityId, activity.status, mode, activity);
  const finalResultSummary = buildInteractionFinalResultSummary(activity, mode, tokenResolution, resultContext);
  activity.payload.finalResultSummary = finalResultSummary;
  const finalAnnouncement = rootInteractionResolutionAnnouncement(activity, mode, tokenResolution, rootResolution.resultText, {
    ...resultContext,
    resultSummary: finalResultSummary
  });
  addLogEntry({
    action: "interaction",
    category: "system",
    player: "Activity",
    item: mode === "pass" ? `${activity.title} passed with no response.`
      : mode === "canceled" ? `${activity.title} canceled and refunded.`
        : gameplayNegated ? `${activity.title} negated.`
        : `${activity.title} resolved.`,
    title: mode === "pass" ? "Activity passed" : mode === "canceled" ? "Activity canceled and refunded" : gameplayNegated ? "Activity negated" : "Activity resolved",
    summary: [
      activity.title,
      mode === "pass" ? "No response used." : mode === "canceled" ? "Administrative cancellation; refundable Tokens returned." : gameplayNegated ? "A gameplay response negated the declared effect." : "Marked resolved.",
      gameplayNegated ? "Confirmed Token consumption remains." : tokenResolution?.blocked ? "Token effect was blocked." : tokenResolution?.statusId ? "Token effect applied." : "",
      rootResolution.resultText,
      finalAnnouncement.detail
    ].filter(Boolean).join("\n"),
    type: "interaction-resolution",
    categories: ["system", "interaction"],
    tags: ["activity", "interaction", mode],
    playerIds: [activity.actorPlayerId, activity.targetPlayerId, ...(activity.eligiblePlayerIds || [])].filter(Boolean),
    linkedEventId: activity.id || "",
    sourceType: activity.sourceType || activity.payload?.sourceType || "",
    sourceId: activity.sourceId || activity.payload?.sourceId || "",
    randomPokemonSessionId: activity.payload?.randomPokemonSessionId || "",
    gameCornerSessionId: activity.payload?.gameCornerSessionId || "",
    actionVisitId: activity.payload?.actionVisitId || "",
    finalResultSummary
  });
  const customAnnouncementAllowed = !gameplayNegated && mode !== "canceled";
  queueLiveResolutionAnnouncement(customAnnouncementAllowed && announcement
    ? { ...finalAnnouncement, ...announcement, resultSummary: finalResultSummary, cards: finalAnnouncement.cards }
    : finalAnnouncement);
  const actionOperation = currentActionOperation();
  if (actionOperation
    && (!actionOperation.linkedPendingSituationId || actionOperation.linkedPendingSituationId === activity.id)) {
    completeActionOperationForVisit(actionOperation.visitId, `linked-event-${mode}`);
  }
  saveState();
  if (renderAfter) render();
  return true;
}

function interactionPromptStepResolutionMode(activity, step = currentInteractionPromptStep(activity)) {
  if (!step) return EFFECT_RESOLUTION_MODES.MANUAL_REQUIRED;
  if (step.kind === "event" && activity?.sourceType === "token-use") {
    return tokenEffectMetadataByName(activity.payload?.tokenName || activity.title || "").resolutionMode;
  }
  if (step.kind === "response") {
    const response = step.response || {};
    if (response.source === "token" || response.tokenName) {
      return tokenEffectMetadataByName(response.tokenName || livePromptStepResponseLabel(response)).resolutionMode;
    }
    return EFFECT_RESOLUTION_MODES.MANUAL_REQUIRED;
  }
  return activityEffectApplication(activity) === "automatic"
    ? EFFECT_RESOLUTION_MODES.AUTOMATIC
    : EFFECT_RESOLUTION_MODES.MANUAL_REQUIRED;
}

function interactionPromptStepTokenUsability(activity, step = currentInteractionPromptStep(activity)) {
  if (!step) return { ok: true, status: "usable", mayConsume: true, reason: "" };
  if (step.kind === "event" && activity?.sourceType === "token-use") {
    return tokenRuntimeUsabilityCheck(tokenEffectMetadataByName(activity.payload?.tokenName || activity.title || ""));
  }
  if (step.kind === "response" && (step.response?.source === "token" || step.response?.tokenName)) {
    return tokenRuntimeUsabilityCheck(tokenEffectMetadataByName(step.response?.tokenName || livePromptStepResponseLabel(step.response)));
  }
  return { ok: true, status: "usable", mayConsume: true, reason: "" };
}

function smokescreenResponseResolutionPlan(activity, step = currentInteractionPromptStep(activity)) {
  if (!activity || step?.kind !== "response" || !controlTokenEffects?.resolveSmokescreenRedirect) {
    return { result: "systemFailure", refundRequired: true, reason: "The Smokescreen resolver is unavailable." };
  }
  const parentStep = parentInteractionPromptStep(activity, step);
  const parentSource = parentStep?.kind === "response" ? parentStep.response : activity.payload;
  if (!parentSource) return { result: "systemFailure", refundRequired: true, reason: "Smokescreen could not find the effect it is answering." };
  const parentMetadata = tokenEffectMetadataByName(parentStep?.kind === "response"
    ? parentStep.response?.tokenName || livePromptStepResponseLabel(parentStep.response)
    : activity.payload?.tokenName || activity.title);
  const sourcePlayerId = parentStep?.actorPlayerId || activity.actorPlayerId || "";
  const relation = String(parentMetadata.targetControllerRelation || "").trim();
  const playerIsCorresponding = (player) => {
    if (!player?.id) return false;
    if (parentMetadata.selfOnly || relation === "self" || relation === "sameController") return player.id === sourcePlayerId;
    if (parentMetadata.otherPlayerOnly || parentMetadata.excludeActor
      || ["rival", "otherPlayer", "differentController"].includes(relation)) return player.id !== sourcePlayerId;
    return true;
  };
  return controlTokenEffects.resolveSmokescreenRedirect(state, {
    parentSource,
    wheelResultPlayerId: step.response?.smokescreenWheelResultPlayerId || "",
    replacementTargetId: step.response?.smokescreenReplacementTargetId || ""
  }, {
    isLegalPlayer: playerIsCorresponding,
    isLegalPokemon: (pokemon) => playerIsCorresponding(state.players.find((player) => player.id === pokemon.trainerId))
  });
}

function teleportDelayableParentPlan(activity, step = currentInteractionPromptStep(activity)) {
  if (!activity || step?.kind !== "response") {
    return { ok: false, reason: "Teleport needs an open Token effect to delay." };
  }
  const parentStep = parentInteractionPromptStep(activity, step);
  if (parentStep?.kind !== "event" || activity.sourceType !== "token-use") {
    return { ok: false, reason: "Teleport currently supports exact declared Token events, not nested response effects." };
  }
  const parentMetadata = tokenEffectMetadataByName(activity.payload?.tokenName || activity.title || "");
  if (!parentMetadata?.id || !tokenControlController?.CONTROL_TOKEN_IDS?.includes(parentMetadata.id)) {
    return { ok: false, reason: "This effect does not yet have a safe delayed-return controller." };
  }
  if (parentMetadata.id === "purge-curse") {
    return { ok: false, reason: "Purge is an absolute post-payout procedure and cannot be delayed by Teleport." };
  }
  return { ok: true, reason: "", parentStep, parentMetadata };
}

function teleportParentEffectSnapshot(activity) {
  return {
    id: activity.id,
    type: activity.type,
    title: activity.title,
    message: activity.message,
    actorPlayerId: activity.actorPlayerId || "",
    targetPlayerId: activity.targetPlayerId || "",
    sourceType: activity.sourceType || "token-use",
    sourceId: activity.sourceId || "",
    payload: structuredClone(activity.payload || {}),
    responseTypes: structuredClone(activity.responseTypes || []),
    eligiblePlayerIds: structuredClone(activity.eligiblePlayerIds || [])
  };
}

function interactionPromptStepTokenResolutionSafety(activity, step = currentInteractionPromptStep(activity)) {
  if (!step) return { ok: true, reason: "" };
  const metadata = step.kind === "event" && activity?.sourceType === "token-use"
    ? tokenEffectMetadataByName(activity.payload?.tokenName || activity.title || "")
    : step.kind === "response" && (step.response?.source === "token" || step.response?.tokenName)
      ? tokenEffectMetadataByName(step.response?.tokenName || livePromptStepResponseLabel(step.response))
      : null;
  if (!metadata) return { ok: true, reason: "" };
  if (step.kind === "response" && metadata.resolverId === "smokescreenRedirect") {
    const plan = smokescreenResponseResolutionPlan(activity, step);
    if (["systemFailure", "awaitingRequiredChoice"].includes(plan.result)) {
      return { ok: false, reason: plan.reason, refundRequired: plan.result === "systemFailure", smokescreenPlan: plan };
    }
    const safety = tokenRuntimeResultSafetyCheck(metadata, {
      closed: true,
      wheelResultPlayerId: plan.wheelResultPlayerId,
      originalTargetPlayerId: plan.originalTargetPlayerId,
      replacementTargetId: plan.replacementTargetId || "",
      replacedOriginalTarget: Boolean(plan.replacedOriginalTarget),
      keptOriginalTarget: Boolean(plan.keptOriginalTarget),
      noLegalCorrespondingTarget: Boolean(plan.noLegalCorrespondingTarget)
    });
    return safety.ok ? { ...safety, smokescreenPlan: plan } : { ...safety, refundRequired: true, smokescreenPlan: plan };
  }
  if (step.kind === "response"
    && ["counterProtection", "restoreNegatedTokenWithCooldown", "redirectParentToSelf", "copyParentEffect"].includes(metadata.resolverId)) {
    const plan = specialTokenResponseResolutionPlan(
      activity,
      parentInteractionPromptStep(activity, step),
      step.actorPlayerId,
      metadata,
      step.response || {}
    );
    return plan.ok
      ? { ok: true, reason: "", specialPlan: plan }
      : { ok: false, reason: plan.reason, refundRequired: true, specialPlan: plan };
  }
  const response = step.response || {};
  const payload = activity?.payload || {};
  return tokenRuntimeResultSafetyCheck(metadata, {
    closed: true,
    negatedProtectionToken: metadata.resolverId === "counterProtection",
    temporaryCopyTokenId: response.temporaryCopyTokenId || payload.temporaryCopyTokenId || "",
    mandatoryGuidedContinuationId: response.mandatoryGuidedContinuationId || payload.mandatoryGuidedContinuationId || "",
    replacedOriginalTarget: Boolean(response.replacedOriginalTarget || payload.replacedOriginalTarget),
    originalTargetsPreserved: Boolean(response.originalTargetsPreserved || payload.originalTargetsPreserved),
    addedTargetId: response.addedTargetId || payload.addedTargetId || "",
    addedTargetResponseOpportunityId: response.addedTargetResponseOpportunityId || payload.addedTargetResponseOpportunityId || "",
    redirectedTarget: metadata.resolverId === "redirectParentToSelf",
    ongoingCopyRelationshipId: response.ongoingCopyRelationshipId || payload.ongoingCopyRelationshipId || "",
    playerScopedPrivateRecordId: response.playerScopedPrivateRecordId || payload.playerScopedPrivateRecordId || "",
    sourcePlayerId: step.actorPlayerId || activity?.actorPlayerId || "",
    sharedPayloadContainsPrivateSetData: false,
    revealRecipientPlayerIds: response.revealRecipientPlayerIds || payload.revealRecipientPlayerIds || []
  });
}

function interactionPromptStepNegatesParent(step) {
  if (step?.kind !== "response") return false;
  const response = step.response || {};
  const metadata = tokenEffectMetadataByName(response.tokenName || livePromptStepResponseLabel(response));
  if (!tokenRuntimeUsabilityCheck(metadata).ok) return false;
  if (metadata.resolverId === "counterProtection") {
    const parentStep = parentInteractionPromptStep(step.activity, step);
    const parentMetadata = parentStep?.kind === "response"
      ? tokenEffectMetadataByName(parentStep.response?.tokenName || livePromptStepResponseLabel(parentStep.response))
      : null;
    return parentMetadata?.timingCategory === TOKEN_TIMING_CATEGORIES.PROTECTION;
  }
  return Boolean(response.negatesParent
    || response.outcome === "negates-parent"
    || metadata.resolverId === "immunity");
}

function applySpecialTokenResponseInventoryEffect(activity, step, metadata) {
  const parentStep = parentInteractionPromptStep(activity, step);
  const plan = specialTokenResponseResolutionPlan(activity, parentStep, step.actorPlayerId, metadata, step.response || {});
  if (!plan.applies) return { handled: false, mutations: [], persistentStateIds: [] };
  if (!plan.ok) return { handled: true, blocked: true, refundRequired: true, reason: plan.reason, mutations: [], persistentStateIds: [] };
  if (["followMeRedirect", "afterYouControl", "afterYouImmunity", "afterYouProtection"].includes(plan.kind)) {
    return { handled: false, plan, mutations: [], persistentStateIds: [] };
  }

  const responder = state.players.find((player) => player.id === step.actorPlayerId);
  if (!responder) {
    return { handled: true, blocked: true, refundRequired: true, reason: "The responding player no longer exists.", mutations: [], persistentStateIds: [] };
  }
  const previousPlayers = structuredClone(state.players || []);
  const previousConsumptions = structuredClone(state.tokenConsumptions || []);
  const previousResponse = structuredClone(step.response || {});
  const mutations = [];
  const persistentStateIds = [];
  const context = tokenInventoryRuntimeContext();
  try {
    responder.inventory ||= [];
    if (plan.kind === "temporaryCopy") {
      const temporaryCopy = tokenInventoryRuntime.temporaryCopy(plan.sourceItem, {
        ownerPlayerId: responder.id,
        sourceDefinitionId: plan.sourceDefinition.id,
        sourceActivationId: plan.sourceStep.response?.id || activity.id,
        sourceResponseId: plan.sourceStep.response?.id || "",
        series: context.series,
        gym: context.gym,
        phase: context.phase
      });
      if ((state.players || []).some((player) => (player.inventory || []).some((item) => item.id === temporaryCopy.id))) {
        throw new Error("The temporary copied Token ID already exists.");
      }
      responder.inventory.unshift(temporaryCopy);
      step.response.temporaryCopyTokenId = temporaryCopy.id;
      step.response.copiedTokenName = plan.sourceDefinition.name;
      step.response.copiedFromTokenId = plan.sourceItem.id;
      step.response.temporaryCopyExpiresAt = "endOfCreationGym";
      mutations.push(`Negated ${plan.sourceDefinition.name}`);
      mutations.push(`Created one temporary ${plan.sourceDefinition.name} for ${responder.name}`);
      persistentStateIds.push(temporaryCopy.id);
      const safety = tokenRuntimeResultSafetyCheck(metadata, {
        closed: true,
        negatedProtectionToken: true,
        temporaryCopyTokenId: temporaryCopy.id
      });
      if (!safety.ok) throw new Error(safety.reason);
      return {
        handled: true,
        metadata,
        mutations,
        persistentStateIds,
        resultData: {
          copiedTokenId: temporaryCopy.id,
          copiedTokenName: plan.sourceDefinition.name,
          expiresAt: "End of the current Gym"
        }
      };
    }

    const restoredToken = tokenInventoryRuntime.cooldownRestoration(plan.sourceItem, {
      ownerPlayerId: responder.id,
      sourceDefinitionId: plan.sourceDefinition.id,
      sourceActivationId: plan.sourceStep.kind === "response" ? plan.sourceStep.response?.id : activity.id,
      sourceResponseId: plan.negatingStep?.response?.id || "",
      series: context.series,
      gym: context.gym,
      phase: context.phase,
      anchorPhase: context.phase,
      cooldownGyms: 2
    });
    if ((state.players || []).some((player) => (player.inventory || []).some((item) => item.id === restoredToken.id))) {
      throw new Error("The exact negated Token already exists in an inventory.");
    }
    responder.inventory.unshift(restoredToken);
    plan.sourceConsumption.status = "restored-cooldown";
    plan.sourceConsumption.restoredTokenId = restoredToken.id;
    plan.sourceConsumption.restoredByResponseId = step.response.id;
    plan.sourceConsumption.restoredAt = new Date().toISOString();
    step.response.restoredTokenId = restoredToken.id;
    step.response.restoredTokenName = plan.sourceDefinition.name;
    step.response.cooldownGyms = 2;
    step.response.cooldownAnchorPhase = context.phase;
    mutations.push(`Restored exact ${plan.sourceDefinition.name} inventory record on a two-Gym cooldown`);
    persistentStateIds.push(restoredToken.id);
    return {
      handled: true,
      metadata,
      mutations,
      persistentStateIds,
      resultData: {
        restoredTokenId: restoredToken.id,
        restoredTokenName: plan.sourceDefinition.name,
        cooldownGyms: 2,
        cooldownAnchorPhase: context.phase
      }
    };
  } catch (error) {
    state.players = previousPlayers;
    state.tokenConsumptions = previousConsumptions;
    Object.keys(step.response || {}).forEach((key) => delete step.response[key]);
    Object.assign(step.response, previousResponse);
    return {
      handled: true,
      blocked: true,
      refundRequired: true,
      reason: error?.message || "The exact Token inventory mutation could not complete atomically.",
      mutations: [],
      persistentStateIds: []
    };
  }
}

function applyAfterYouCopiedActivation(activity, step, plan) {
  if (!plan?.ok || !plan.sourceDefinition || !plan.sourceStep) {
    return { blocked: true, refundRequired: true, reason: plan?.reason || "After You could not construct its exact copied activation." };
  }
  const existing = (state.copiedActivations || []).find((record) => record.sourceCopyEffectId === step.response.id);
  if (existing && ["resolved", "negated-original"].includes(existing.status)) {
    return {
      mutations: existing.mutations || [],
      persistentStateIds: [existing.id, existing.operationId].filter(Boolean),
      resultData: existing.resultData || { copiedActivationId: existing.id },
      negatesParent: existing.status === "negated-original"
    };
  }
  const saved = controlTokenEffects.snapshot(state);
  const copied = controlTokenEffects.createCopiedActivation(state, {
    sourceActivation: {
      id: plan.sourceStep.kind === "response" ? plan.sourceStep.response?.id : activity.id,
      definitionId: plan.sourceDefinition.id,
      actorPlayerId: plan.sourceStep.actorPlayerId || activity.actorPlayerId || "",
      isCopiedActivation: Boolean(plan.sourceStep.response?.isCopiedActivation),
      copyProvenance: plan.sourceStep.response?.copyProvenance || null
    },
    sourceCopyEffectId: step.response.id,
    sourceDefinitionId: plan.sourceDefinition.id,
    copiedUserPlayerId: step.actorPlayerId,
    copyMode: globalThis.rivalSagaTokenEffectContract.copyActivationModes.AFTER_YOU,
    copyPolicy: globalThis.rivalSagaTokenEffectContract.copyActivationPolicyFor(globalThis.rivalSagaTokenEffectContract.copyActivationModes.AFTER_YOU),
    targets: [plan.copyDraft?.targetPlayerId, plan.copyDraft?.targetPokemonId, plan.copyDraft?.targetText].filter(Boolean),
    choices: {
      targetPlayerId: plan.copyDraft?.targetPlayerId || "",
      targetPokemonId: plan.copyDraft?.targetPokemonId || "",
      targetPokemonIds: plan.copyDraft?.targetPokemonIds || [],
      targetText: plan.copyDraft?.targetText || "",
      resourceDefinitionId: plan.copyDraft?.resourceDefinitionId || "",
      choiceKind: plan.copyDraft?.choiceKind || "",
      inventoryRecordId: plan.copyDraft?.inventoryRecordId || "",
      moveName: plan.copyDraft?.moveName || ""
    },
    explicitCosts: []
  }, controlTokenEffectOptions());
  if (copied.result !== "resolved" || !copied.record) {
    controlTokenEffects.restore(state, saved);
    return { blocked: true, refundRequired: copied.refundRequired !== false, reason: copied.reason || "After You could not create its virtual activation." };
  }

  let copiedResolution = null;
  let negatesParent = false;
  if (plan.kind === "afterYouImmunity") {
    negatesParent = true;
    copiedResolution = {
      result: "resolved",
      details: [`Copied Immunity negated the original ${plan.sourceDefinition.name}.`],
      mutations: [`Negated original ${plan.sourceDefinition.name}`],
      persistentStateIds: []
    };
  } else if (plan.kind === "afterYouProtection" && plan.sourceDefinition.id === "safeguard") {
    const expires = statusExpiresAt(1);
    const actor = state.players.find((player) => player.id === step.actorPlayerId);
    const status = applyLingeringEffect({
      type: "safeguard",
      name: "Safeguard",
      category: TOKEN_TIMING_CATEGORIES.PROTECTION,
      isCurse: false,
      sourceTokenId: "",
      sourceTokenName: "Safeguard",
      actorPlayerId: actor?.id || "",
      actorPlayerName: actor?.name || "",
      targetPlayerId: actor?.id || "",
      targetPlayerName: actor?.name || "",
      duration: "Until Gym end",
      durationGyms: 1,
      expiresAtSeries: expires.expiresAtSeries,
      expiresAtGym: expires.expiresAtGym,
      payload: { protectionScope: plan.sourceDefinition.protectionScope || [], copiedByAfterYou: true },
      note: "Copied by After You before the original Safeguard resolved.",
      createdAt: new Date().toISOString()
    });
    copiedResolution = {
      result: "resolved",
      details: [`${actor?.name || "The After You user"} gained copied Safeguard protection.`],
      mutations: ["Created copied Safeguard protection"],
      persistentStateIds: [status.id],
      resultData: { createdStatusIds: [status.id] }
    };
  } else if (plan.kind === "afterYouControl") {
    const fakeActivity = {
      id: copied.record.id,
      sourceType: "token-use",
      actorPlayerId: step.actorPlayerId,
      targetPlayerId: plan.copyDraft.targetPlayerId || "",
      payload: {
        tokenId: plan.sourceDefinition.id,
        tokenName: plan.sourceDefinition.name,
        sourceEffectId: copied.record.id,
        targetPlayerId: plan.copyDraft.targetPlayerId || "",
        targetPlayerName: plan.copyDraft.targetPlayerName || "",
        targetPokemonId: plan.copyDraft.targetPokemonId || "",
        targetPokemonName: plan.copyDraft.targetPokemonName || "",
        targetPokemonIds: plan.copyDraft.targetPokemonIds || [],
        selectedRosterInstanceIds: plan.copyDraft.targetPokemonIds?.length
          ? plan.copyDraft.targetPokemonIds
          : [plan.copyDraft.targetPokemonId].filter(Boolean),
        targetText: plan.copyDraft.targetText || "",
        targetType: plan.copyDraft.targetType || plan.sourceMetadata.targetType,
        targetScope: plan.copyDraft.targetScope || plan.sourceMetadata.targetScope,
        resourceSelections: plan.copyDraft.resourceSelections || [],
        resourceDefinitionId: plan.copyDraft.resourceDefinitionId || "",
        choiceKind: plan.copyDraft.choiceKind || "",
        inventoryRecordId: plan.copyDraft.inventoryRecordId || "",
        moveName: plan.copyDraft.moveName || "",
        isVirtualActivation: true,
        copyProvenance: copied.record.copyProvenance
      }
    };
    const interception = applySubstituteInterceptionBeforeMutation(fakeActivity, plan.sourceMetadata);
    copiedResolution = interception?.negateEntireEffect
      ? {
        result: "resolved",
        details: [interception.reason],
        mutations: [],
        persistentStateIds: [...(interception.consumedStatusIds || []), ...(interception.createdStatusIds || [])],
        resultData: { substituteInterception: structuredClone(fakeActivity.payload.substituteInterception || {}) }
      }
      : applyAutomaticControlFoundationActivity(fakeActivity, plan.sourceMetadata);
  }

  if (!copiedResolution || ["systemFailure", "blocked", "awaitingRequiredChoice"].includes(copiedResolution.result)) {
    controlTokenEffects.restore(state, saved);
    return {
      blocked: true,
      refundRequired: true,
      reason: copiedResolution?.details?.join(" ") || `${plan.sourceDefinition.name} cannot be copied safely in this state.`
    };
  }
  copied.record.status = negatesParent ? "negated-original" : "resolved";
  copied.record.resolvedAt = new Date().toISOString();
  copied.record.mutations = copiedResolution.mutations || [];
  copied.record.resultData = copiedResolution.resultData || {};
  state.effectOperations ||= [];
  const operation = {
    id: `effect-operation-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
    operationType: "resolveAfterYouCopiedActivation",
    sourceEffectId: step.response.id,
    copiedActivationId: copied.record.id,
    status: "completed",
    undoData: saved,
    createdAt: copied.record.resolvedAt
  };
  copied.record.operationId = operation.id;
  state.effectOperations.push(operation);
  if (negatesParent) step.response.negatesParent = true;
  step.response.isCopiedActivation = false;
  step.response.copiedActivationId = copied.record.id;
  step.response.copiedDefinitionId = plan.sourceDefinition.id;
  return {
    mutations: [`Virtually copied ${plan.sourceDefinition.name}`, ...(copiedResolution.mutations || [])],
    persistentStateIds: [copied.record.id, operation.id, ...(copiedResolution.persistentStateIds || [])],
    resultData: {
      copiedActivationId: copied.record.id,
      copiedDefinitionId: plan.sourceDefinition.id,
      resolvesBeforeOriginal: true,
      negatedOriginalActivation: negatesParent,
      ...(copiedResolution.resultData || {})
    },
    negatesParent
  };
}

function applyTokenResponseParentInteraction(activity, step, resolutionText = "") {
  if (step?.kind !== "response" || !step.response?.tokenName) return { mutations: [], persistentStateIds: [] };
  const metadata = tokenEffectMetadataByName(step.response.tokenName);
  const usability = tokenRuntimeUsabilityCheck(metadata);
  if (!usability.ok) return { metadata, mutations: [], persistentStateIds: [], blocked: true, reason: usability.reason };
  const parentStep = parentInteractionPromptStep(activity, step);
  const parentSource = parentStep?.kind === "response" ? parentStep.response : activity.payload;
  const specialEffect = applySpecialTokenResponseInventoryEffect(activity, step, metadata);
  if (specialEffect.blocked) return specialEffect;
  const mutations = [...(specialEffect.mutations || [])];
  const persistentStateIds = [...(specialEffect.persistentStateIds || [])];
  let resultData = specialEffect.resultData || null;
  let delaysParent = false;
  let delayedRecord = null;
  const specialPlan = specialEffect.plan || specialTokenResponseResolutionPlan(activity, parentStep, step.actorPlayerId, metadata, step.response || {});
  if (metadata.resolverId === "copyParentEffect") {
    const copiedEffect = applyAfterYouCopiedActivation(activity, step, specialPlan);
    if (copiedEffect.blocked) return { metadata, ...copiedEffect, mutations: [], persistentStateIds: [] };
    mutations.push(...(copiedEffect.mutations || []));
    persistentStateIds.push(...(copiedEffect.persistentStateIds || []));
    resultData = copiedEffect.resultData || resultData;
  }
  if (metadata.resolverId === "delayParent") {
    const plan = teleportDelayableParentPlan(activity, step);
    if (!plan.ok) {
      return { metadata, mutations: [], persistentStateIds: [], blocked: true, refundRequired: true, reason: plan.reason };
    }
    const scheduled = controlTokenEffects?.scheduleTeleportDelayedEffect?.(state, {
      sourceResponseId: step.response.id,
      sourcePlayerId: step.actorPlayerId || step.response.playerId || "",
      parentEffect: teleportParentEffectSnapshot(activity),
      teleportConsumptionRecordId: step.response.tokenConsumptionIds?.[0] || "",
      parentConsumptionRecordIds: activity.payload?.tokenConsumptionIds || []
    }, controlTokenEffectOptions());
    if (!scheduled || scheduled.result === "systemFailure") {
      return {
        metadata,
        mutations: [],
        persistentStateIds: [],
        blocked: true,
        refundRequired: true,
        reason: scheduled?.reason || "Teleport could not create its delayed-effect record."
      };
    }
    delaysParent = true;
    delayedRecord = scheduled.record;
    mutations.push(scheduled.reason || "Delayed the parent effect until the next Gym's matching phase.");
    persistentStateIds.push(delayedRecord.id);
    resultData = {
      delayedEffectId: delayedRecord.id,
      declarationPhaseAnchor: structuredClone(delayedRecord.declarationPhaseAnchor),
      dueAt: structuredClone(delayedRecord.dueAt),
      parentEffectId: activity.id
    };
  }
  if (metadata.resolverId === "smokescreenRedirect" && parentSource) {
    const plan = smokescreenResponseResolutionPlan(activity, step);
    if (["systemFailure", "awaitingRequiredChoice"].includes(plan.result)) {
      return { metadata, mutations: [], persistentStateIds: [], blocked: true, refundRequired: plan.result === "systemFailure", reason: plan.reason };
    }
    if (plan.targetPatch) Object.assign(parentSource, plan.targetPatch);
    step.response.smokescreenOriginalTargetPlayerId = plan.originalTargetPlayerId;
    step.response.smokescreenKeptOriginalTarget = Boolean(plan.keptOriginalTarget);
    step.response.smokescreenNoLegalCorrespondingTarget = Boolean(plan.noLegalCorrespondingTarget);
    step.response.smokescreenReplacementTargetId = plan.replacementTargetId || "";
    mutations.push(plan.reason);
    resultData = {
      wheelResultPlayerId: plan.wheelResultPlayerId,
      originalTargetPlayerId: plan.originalTargetPlayerId,
      replacementTargetId: plan.replacementTargetId || "",
      keptOriginalTarget: Boolean(plan.keptOriginalTarget),
      noLegalCorrespondingTarget: Boolean(plan.noLegalCorrespondingTarget)
    };
  }
  if (metadata.resolverId === "redirectParentToSelf" && parentSource) {
    const plan = specialPlan;
    if (!plan?.ok || plan.kind !== "followMeRedirect") {
      return { metadata, mutations: [], persistentStateIds: [], blocked: true, refundRequired: true, reason: plan?.reason || "Follow Me could not preserve a legal corresponding target." };
    }
    const responder = plan.responder;
    parentSource.targetPlayerId = responder.id;
    parentSource.targetPlayerName = responder.name || "";
    parentSource.targetPokemonId = plan.pokemon?.id || "";
    parentSource.targetPokemonName = plan.pokemon?.name || "";
    parentSource.targetText = plan.pokemon ? `${responder.name}'s ${plan.pokemon.name}` : responder.name;
    parentSource.targetType = plan.pokemon ? EFFECT_TARGET_TYPES.POKEMON : EFFECT_TARGET_TYPES.PLAYER;
    parentSource.targetScope = plan.pokemon ? EFFECT_TARGET_SCOPES.ROSTER_INSTANCE : EFFECT_TARGET_SCOPES.SINGLE_PLAYER;
    const relationship = controlTokenEffects.createFollowMeCopyRelationship(state, {
      sourceEffectId: step.response.id,
      activateAfterEffectId: activity.id,
      sourcePlayerId: plan.sourcePlayerId,
      beneficiaryPlayerId: responder.id
    }, controlTokenEffectOptions());
    if (relationship.result !== "resolved" || !relationship.record) {
      return { metadata, mutations: [], persistentStateIds: [], blocked: true, refundRequired: true, reason: relationship.reason || "Follow Me could not create its required copy relationship." };
    }
    step.response.ongoingCopyRelationshipId = relationship.record.id;
    step.response.redirectedTargetPlayerId = responder.id;
    step.response.redirectedTargetPokemonId = plan.pokemon?.id || "";
    mutations.push(`Redirected the parent effect to ${parentSource.targetText}`);
    mutations.push(`Queued Follow Me's Token-copy relationship for activation after the parent resolves`);
    persistentStateIds.push(relationship.record.id);
    resultData = {
      redirectedTargetPlayerId: responder.id,
      redirectedTargetPokemonId: plan.pokemon?.id || "",
      ongoingCopyRelationshipId: relationship.record.id,
      relationshipStatus: relationship.record.status
    };
  }
  const audit = tokenEffectAuditRecord({
    stage: "resolution",
    activity,
    response: step.response,
    metadata,
    result: interactionPromptStepNegatesParent(step) ? "negated" : mutations.some((entry) => entry.startsWith("Redirected")) ? "redirected" : "resolved",
    mutations,
    persistentStateIds,
    hostConfirmation: metadata.resolutionMode === EFFECT_RESOLUTION_MODES.HOST_CONFIRMED ? resolutionText : ""
  });
  step.response.resolutionAuditId = audit.id;
  return { metadata, mutations, persistentStateIds, resultData, audit, delaysParent, delayedRecord };
}

function setInteractionPromptResolution(activity, step, status, details = {}) {
  if (!activity || !step?.id) return null;
  const record = interactionPromptResolution(activity, step.id);
  Object.assign(record, details, {
    promptId: step.id,
    status,
    resolvedAt: details.resolvedAt || record.resolvedAt || new Date().toISOString()
  });
  if (step.response) {
    step.response.resolutionStatus = status;
    step.response.resolutionOutcome = record.outcome || "";
    step.response.resolvedAt = record.resolvedAt;
  }
  return record;
}

function cancelFailedTokenResponseAndRefund(activity, step, reason = "This Token response could not resolve safely.") {
  if (!activity || step?.kind !== "response" || !step.response) return 0;
  const refunded = refundTokenConsumptionsForLink({ eventId: activity.id, responseId: step.response.id }, reason);
  step.response.status = "canceled";
  step.response.createsPrompt = false;
  step.response.canceledAt = new Date().toISOString();
  step.response.cancellationReason = reason;
  setInteractionPromptResolution(activity, step, "canceled", {
    outcome: "canceledRefunded",
    resultText: reason,
    source: "failed-special-response-recovery"
  });
  addLogEntry({
    action: "interaction",
    category: "system",
    player: livePlayerName(step.actorPlayerId, "Table"),
    item: `${livePromptStepResponseLabel(step.response)} was canceled and refunded because it could not resolve safely.`,
    title: "Token response canceled and refunded",
    summary: [reason, `Refunded Tokens: ${refunded}`],
    type: "interaction-response-recovery",
    categories: ["system", "interaction", "tokens"],
    tags: ["canceledRefunded", "fail-closed"],
    playerIds: [step.actorPlayerId].filter(Boolean),
    linkedEventId: activity.id,
    responseId: step.response.id,
    eventOrder: nextEventOrder()
  });
  syncInteractionSituation(activity);
  saveState({ immediate: true });
  render();
  return refunded;
}

function resolveCurrentInteractionPrompt(activity, { force = false, source = "live-referee", resolutionText = "", suppressAnnouncement = false } = {}) {
  if (!activity || activity.status !== "open") return { resolved: false, closed: false };
  const step = currentInteractionPromptStep(activity);
  const usability = interactionPromptStepTokenUsability(activity, step);
  if (!usability.ok) {
    alert(usability.reason);
    return { resolved: false, closed: false, blocked: true, reason: usability.reason };
  }
  const resultSafety = interactionPromptStepTokenResolutionSafety(activity, step);
  if (!resultSafety.ok) {
    if (resultSafety.refundRequired) cancelFailedTokenResponseAndRefund(activity, step, resultSafety.reason);
    alert(resultSafety.reason);
    return { resolved: false, closed: false, blocked: true, canceledRefunded: Boolean(resultSafety.refundRequired), reason: resultSafety.reason };
  }
  const priority = currentInteractionPromptPriority(activity, step, state);
  if (!force && !priority?.complete) return { resolved: false, closed: false, waiting: true };
  if (step.kind === "event") {
    const closed = resolveInteractionActivity(activity.id, "resolved", { renderAfter: false, resolutionText });
    if (!closed) return { resolved: false, closed: false, blocked: true, promptId: step.id };
    return { resolved: true, closed: true, promptId: step.id };
  }

  const parentStep = parentInteractionPromptStep(activity, step);
  const responseEffect = applyTokenResponseParentInteraction(activity, step, resolutionText);
  if (responseEffect.blocked) {
    if (responseEffect.refundRequired) cancelFailedTokenResponseAndRefund(activity, step, responseEffect.reason);
    alert(responseEffect.reason || "This response cannot resolve safely yet.");
    return { resolved: false, closed: false, blocked: true, canceledRefunded: Boolean(responseEffect.refundRequired), reason: responseEffect.reason || "" };
  }
  if (responseEffect.delaysParent && responseEffect.delayedRecord) {
    const responseLabel = livePromptStepResponseLabel(step.response);
    const parentText = livePromptStepText(activity, parentStep, { short: true });
    setInteractionPromptResolution(activity, step, "resolved", {
      outcome: "delays-parent",
      resultText: String(resolutionText || responseEffect.delayedRecord.resolutionReason || "").trim(),
      delayedEffectId: responseEffect.delayedRecord.id,
      source
    });
    setInteractionPromptResolution(activity, parentStep, "delayed", {
      outcome: "delayed-to-next-matching-phase",
      resolvedByPromptId: step.id,
      delayedEffectId: responseEffect.delayedRecord.id,
      source
    });
    activity.payload ||= {};
    activity.payload.delayedByPromptId = step.id;
    activity.payload.delayedByResponseId = step.response?.id || "";
    activity.payload.delayedEffectId = responseEffect.delayedRecord.id;
    interactionSituationLifecycle.markResolved(activity, {
      tokenConsumed: Boolean(activity.situation?.tokenConsumed),
      resumesAfter: `${responseEffect.delayedRecord.dueAt.series} Gym ${responseEffect.delayedRecord.dueAt.gym} ${phaseLabels[responseEffect.delayedRecord.dueAt.phase] || responseEffect.delayedRecord.dueAt.phase}`
    });
    activity.status = "resolved";
    activity.resolvedAt = new Date().toISOString();
    activity.resolutionMode = "delayed";
    state.liveTable = normalizeLiveTableState({ ...(state.liveTable || {}), lastResolvedEventId: activity.id });
    pushBackendActivityStatus(activity.id, activity.status, "delayed", activity);
    const dueLabel = `${responseEffect.delayedRecord.dueAt.series} Gym ${responseEffect.delayedRecord.dueAt.gym} ${phaseLabels[responseEffect.delayedRecord.dueAt.phase] || responseEffect.delayedRecord.dueAt.phase}`;
    const teleportCausalUndo = activity.payload?.tokenDeclarationUndo
      ? buildCausalTokenEffectUndo(activity.payload.tokenDeclarationUndo, activity, { id: "teleport", name: "Teleport" })
      : null;
    addLogEntry({
      action: "token",
      category: "tokens",
      player: livePlayerName(step.actorPlayerId, "Table"),
      item: `${responseLabel} delayed ${parentText} until ${dueLabel}.`,
      title: `${responseLabel} delayed the effect`,
      summary: [
        `Delayed effect: ${parentText}`,
        `Declaration anchor: ${responseEffect.delayedRecord.declarationPhaseAnchor.series} Gym ${responseEffect.delayedRecord.declarationPhaseAnchor.gym} ${responseEffect.delayedRecord.declarationPhaseAnchor.phase}`,
        `Return: ${dueLabel}`,
        "The original target and declaration are preserved. The effect will be revalidated without retargeting."
      ].join("\n"),
      type: "teleport-delay-scheduled",
      categories: ["tokens", "interaction", "delayed-effect"],
      tags: ["teleport", "delayed", "phase-anchor"],
      playerIds: [step.actorPlayerId, activity.actorPlayerId, activity.targetPlayerId].filter(Boolean),
      linkedEventId: activity.id,
      responseId: step.response?.id || "",
      effectAuditId: responseEffect.audit?.id || "",
      delayedEffectId: responseEffect.delayedRecord.id,
      resultData: responseEffect.resultData,
      undoable: Boolean(teleportCausalUndo),
      undone: false,
      undoData: teleportCausalUndo,
      eventOrder: nextEventOrder()
    });
    if (!suppressAnnouncement) {
      queueLiveResolutionAnnouncement({
        id: `resolution:${activity.id}:${step.id}:delayed`,
        title: `${responseLabel} delayed the effect.`,
        detail: `${parentText} will return at ${dueLabel}.`,
        tone: "resolved",
        linkedEventId: activity.id,
        linkedPromptId: step.id
      });
    }
    const actionOperation = currentActionOperation();
    if (actionOperation
      && (!actionOperation.linkedPendingSituationId || actionOperation.linkedPendingSituationId === activity.id)) {
      completeActionOperationForVisit(actionOperation.visitId, "linked-event-delayed");
    }
    saveState({ immediate: true });
    return { resolved: true, closed: true, delayed: true, promptId: step.id, delayedEffectId: responseEffect.delayedRecord.id };
  }
  const negatesParent = interactionPromptStepNegatesParent(step);
  const responseLabel = livePromptStepResponseLabel(step.response);
  setInteractionPromptResolution(activity, step, "resolved", {
    outcome: negatesParent ? "negates-parent" : "completed",
    resultText: String(resolutionText || "").trim(),
    source
  });
  if (step.response && resolutionText) step.response.resolutionText = String(resolutionText).trim();

  if (negatesParent && parentStep) {
    setInteractionPromptResolution(activity, parentStep, "negated", {
      outcome: "negated-by-response",
      resolvedByPromptId: step.id,
      source
    });
  }

  addLogEntry({
    action: "interaction",
    category: "system",
    player: livePlayerName(step.actorPlayerId, "Table"),
    item: negatesParent
      ? `${responseLabel} resolved and negated ${livePromptStepText(activity, parentStep, { short: true })}.`
      : `${responseLabel} resolved.`,
    title: `${responseLabel} resolved`,
    summary: [
      `Window: ${activity.title}`,
      String(resolutionText || "").trim(),
      negatesParent && parentStep ? `Negated: ${livePromptStepText(activity, parentStep, { short: true })}` : "Parent prompt resumes at its saved priority position."
    ].filter(Boolean),
    type: "interaction-prompt-resolution",
    categories: ["system", "interaction", "prompt-resolution"],
    tags: ["live-referee", "prompt-resolution", negatesParent ? "negates-parent" : "resume-parent"],
    playerIds: [step.actorPlayerId, parentStep?.actorPlayerId, activity.actorPlayerId, activity.targetPlayerId].filter(Boolean),
    linkedEventId: activity.id,
    responseId: step.response?.id || "",
    effectAuditId: responseEffect.audit?.id || "",
    resolverMode: responseEffect.metadata?.resolutionMode || "",
    stateMutations: responseEffect.mutations || [],
    resultData: responseEffect.resultData || null,
    eventOrder: nextEventOrder()
  });

  const parentText = parentStep ? livePromptStepText(activity, parentStep, { short: true }) : "the previous prompt";
  const resumedParent = parentStep ? parentInteractionPromptStep(activity, parentStep) : null;
  const returnText = negatesParent && parentStep?.kind === "response" && resumedParent
    ? ` Returning to ${livePromptStepText(activity, resumedParent, { short: true })}.`
    : !negatesParent
      ? ` Returning to ${parentText}.`
      : "";
  const promptAnnouncement = {
    id: `resolution:${activity.id}:${step.id}:${negatesParent ? "negated-parent" : "resolved"}`,
    title: `${liveRefereePossessive(livePlayerName(step.actorPlayerId, "A player"))} ${responseLabel} resolved.`,
    detail: [
      String(resolutionText || "").trim(),
      negatesParent ? `${parentText} was negated.${returnText}` : returnText.trim()
    ].filter(Boolean).join(" "),
    tone: resolutionText ? "manual" : "resolved",
    linkedEventId: activity.id,
    linkedPromptId: step.id
  };

  if (negatesParent && parentStep?.kind === "event") {
    activity.payload ||= {};
    activity.payload.negatedByPromptId = step.id;
    activity.payload.negatedByResponseId = step.response?.id || "";
    resolveInteractionActivity(activity.id, "negated", {
      renderAfter: false,
      announcement: suppressAnnouncement ? null : promptAnnouncement,
      resultContext: {
        resolvedByEffectId: step.response?.id || step.id,
        detail: `${liveRefereePossessive(livePlayerName(step.actorPlayerId, "A player"))} ${responseLabel} negated ${parentText}.`,
        resultData: { preventedMutationTypes: [tokenEffectMetadataByName(activity.payload?.tokenName || activity.title || "").resolverId || "parentEffectMutation"] }
      }
    });
    return { resolved: true, closed: true, promptId: step.id, canceledParentId: parentStep.id };
  }

  if (!suppressAnnouncement) queueLiveResolutionAnnouncement(promptAnnouncement);

  return {
    resolved: true,
    closed: false,
    promptId: step.id,
    canceledParentId: negatesParent ? parentStep?.id || "" : "",
    resumedPromptId: currentInteractionPromptStep(activity).id
  };
}

function advanceAutomaticInteractionPrompts(activity) {
  if (!activity || activity.status !== "open") return 0;
  let resolutions = 0;
  while (activity.status === "open" && resolutions < 20) {
    const step = currentInteractionPromptStep(activity);
    const priority = currentInteractionPromptPriority(activity, step, state);
    if (!priority?.complete) break;
    if (interactionPromptStepResolutionMode(activity, step) !== EFFECT_RESOLUTION_MODES.AUTOMATIC) {
      activity.payload ||= {};
      activity.payload.automationStatus = "guided-or-host-confirmed";
      break;
    }
    const beforeId = step.id;
    const result = resolveCurrentInteractionPrompt(activity, {
      force: true,
      source: "automatic-chain",
      suppressAnnouncement: step.kind === "response"
    });
    if (!result.resolved) break;
    resolutions += 1;
    if (result.closed || currentInteractionPromptStep(activity).id === beforeId) break;
  }
  if (activity.status === "open") syncInteractionSituation(activity);
  return resolutions;
}

function liveGameflowMode(targetState = state) {
  return normalizeLiveTableState(targetState.liveTable || {}).gameflowMode;
}

function liveGameflowModeLabel(mode = liveGameflowMode()) {
  return mode === "batch" ? "Batch Order" : "Individual Turn Order";
}

function getCurrentPendingEvent(targetState = state) {
  return (targetState.interactionEvents || [])
    .filter((event) => sandboxInteractionEventVisible(event, targetState))
    .filter((event) => interactionSituationLifecycle.isBlocking(event))
    .sort((a, b) => Number(a.eventOrder || 0) - Number(b.eventOrder || 0)
      || new Date(a.createdAt || 0) - new Date(b.createdAt || 0))[0] || null;
}

function canShowLiveResponseControls(targetState = state) {
  return Boolean(getCurrentPendingEvent(targetState));
}

function canShowLiveTransactionControls(targetState = state) {
  return Boolean(getCurrentPendingEvent(targetState));
}

function liveResultSessionForActivity(activity, targetState = state) {
  if (!activity) return null;
  const sessionId = activity.payload?.randomPokemonSessionId
    || (/pokemon-result|encounter-result/.test(activity.type || "") ? activity.sourceId : "");
  if (!sessionId) return null;
  return (targetState.randomPokemonSessions || []).find((session) => session.id === sessionId && session.status === "pending") || null;
}

function liveActivityTimingCategory(activity) {
  if (!activity) return "";
  if (activity.payload?.tokenTimingCategory) return tokenTimingCategoryFromRaw(activity.payload.tokenTimingCategory);
  if (activity.type === TOKEN_PENDING_EVENT_TYPES.CONTROL_TOKEN) return TOKEN_TIMING_CATEGORIES.CONTROL;
  if (activity.type === TOKEN_PENDING_EVENT_TYPES.CURSE_TOKEN) return TOKEN_TIMING_CATEGORIES.CURSE;
  if (activity.type === TOKEN_PENDING_EVENT_TYPES.ENCOUNTER_RESULT || activity.type === "encounter-result") return TOKEN_TIMING_CATEGORIES.ENCOUNTER;
  return "";
}

function liveTokenPromptDetails(activity, resultSession = null, targetState = state) {
  const category = liveActivityTimingCategory(activity);
  const actor = targetState.players.find((player) => player.id === activity?.actorPlayerId);
  const target = targetState.players.find((player) => player.id === activity?.targetPlayerId);
  const tokenName = activity?.payload?.tokenName || activity?.sourceId || "Token";
  const targetText = activity?.payload?.targetText || activity?.payload?.targetPlayerName || target?.name || "the target";
  const teamLockText = activity?.payload?.teamLock
    ? " This is happening during Sabotage. Submitted teams are locked before Team Preview."
    : "";
  if (resultSession || activity?.type === "encounter-result" || activity?.type === TOKEN_PENDING_EVENT_TYPES.ENCOUNTER_RESULT) {
    const resultOwnerId = resultSession?.resultOwnerPlayerId || resultSession?.ownerPlayerId || resultSession?.playerId || activity?.actorPlayerId || "";
    const resultOwner = targetState.players.find((player) => player.id === resultOwnerId);
    const resultName = resultSession?.resultDisplayName || activity?.payload?.resultName || "an encounter";
    return {
      type: "encounter-result-pending",
      statusLabel: "Waiting to Resolve",
      title: "Encounter Result Pending",
      body: `${resultOwner?.name || actor?.name || "A player"} rolled ${resultName}. Encounter modifiers, rerolls, responses, and trades may happen before this result is finalized.`,
      helperText: "Use Encounter Tokens during this window, trade, record No Response, then finalize the result."
    };
  }
  if (category === TOKEN_TIMING_CATEGORIES.CONTROL) {
    return {
      type: "control-token-pending",
      statusLabel: "Control Token Pending",
      title: "Control Token Pending",
      body: `${actor?.name || "A player"} used ${tokenName} targeting ${targetText}. Protection responses and trades may happen before this resolves.`,
      helperText: "Record protection responses, trades, or No Response. Finalize only when the table is ready to resolve the token."
    };
  }
  if (category === TOKEN_TIMING_CATEGORIES.CURSE) {
    return {
      type: "curse-token-pending",
      statusLabel: "Curse Pending",
      title: "Curse Pending",
      body: `${actor?.name || "A player"} used ${tokenName} targeting ${targetText}. Protection or cleanse effects may happen before this resolves.${teamLockText}`,
      helperText: `If this curse resolves and the target is valid for Battle Phase, the curse applies according to its effect.${teamLockText}`
    };
  }
  if (activity?.type === TOKEN_PENDING_EVENT_TYPES.TEAM_LOCK_WINDOW) {
    return {
      type: "sabotage-pending",
      statusLabel: "Sabotage",
      title: activity.title || "Sabotage Window",
      body: activity.message || "Sabotage is open. Submitted teams are locked before Team Preview.",
      helperText: "Use this window for final pre-preview responses, trades, or No Response before teams are considered locked."
    };
  }
  if (activity?.type === TOKEN_PENDING_EVENT_TYPES.MANUAL_EVENT || activity?.type === "manual-event") {
    return {
      type: "manual-event-pending",
      statusLabel: "Manual Event",
      title: activity.title || "Manual Event Pending",
      body: activity.message || "This manual event is pending before it resolves.",
      helperText: "Use this table window to record responses, trades, or No Response before finalizing."
    };
  }
  return null;
}

function interactionRootPromptId(activity) {
  return activity?.id ? `event:${activity.id}` : "event:unknown";
}

function interactionResponsePromptStepId(response) {
  return response?.promptStepId || (response?.id ? `response:${response.id}` : "");
}

function interactionResponseAnswerPromptId(activity, response) {
  return String(response?.respondingToPromptId || response?.promptId || interactionRootPromptId(activity));
}

function interactionResponseCanceled(response) {
  const status = String(response?.status || "").toLowerCase();
  return Boolean(response?.canceledAt || status === "canceled" || status === "cancelled" || status === "undone");
}

function interactionResponseCreatesPrompt(response) {
  return Boolean(response && response.type !== "pass" && response.createsPrompt !== false && !interactionResponseCanceled(response));
}

function interactionResponsesInOrder(activity) {
  return [...(activity?.responses || [])].sort((a, b) => Number(a.eventOrder || 0) - Number(b.eventOrder || 0)
    || new Date(a.createdAt || 0) - new Date(b.createdAt || 0));
}

function interactionRootPromptStep(activity) {
  return {
    id: interactionRootPromptId(activity),
    kind: "event",
    activity,
    response: null,
    parentId: "",
    actorPlayerId: activity?.actorPlayerId || activity?.targetPlayerId || "",
    createdAt: activity?.createdAt || "",
    eventOrder: Number(activity?.eventOrder || 0)
  };
}

function interactionPromptChain(activity) {
  if (!activity) return [];
  const root = interactionRootPromptStep(activity);
  const steps = [root];
  const byId = new Map([[root.id, root]]);
  interactionResponsesInOrder(activity).forEach((response) => {
    if (!interactionResponseCreatesPrompt(response)) return;
    const stepId = interactionResponsePromptStepId(response);
    if (!stepId || byId.has(stepId)) return;
    const rawParentId = interactionResponseAnswerPromptId(activity, response);
    const parent = byId.get(rawParentId);
    if (!parent) return;
    const step = {
      id: stepId,
      kind: "response",
      activity,
      response,
      parentId: parent.id,
      actorPlayerId: response.playerId || "",
      createdAt: response.createdAt || "",
      eventOrder: Number(response.eventOrder || 0)
    };
    steps.push(step);
    byId.set(step.id, step);
  });
  return steps;
}

function normalizeInteractionPromptResolutionRecord(record, promptId = "") {
  const source = record && typeof record === "object" && !Array.isArray(record) ? record : {};
  const status = ["open", "resolved", "negated", "delayed", "canceled"].includes(source.status) ? source.status : "open";
  return {
    ...source,
    promptId: String(source.promptId || promptId),
    status,
    outcome: String(source.outcome || ""),
    resolvedAt: source.resolvedAt || "",
    resolvedByPromptId: String(source.resolvedByPromptId || ""),
    canceledByPromptId: String(source.canceledByPromptId || "")
  };
}

function normalizeInteractionPromptResolutions(activity) {
  activity.promptResolutions ||= {};
  activity.promptResolutions = Object.fromEntries(Object.entries(activity.promptResolutions)
    .map(([promptId, record]) => [promptId, normalizeInteractionPromptResolutionRecord(record, promptId)]));
  interactionPromptChain(activity).forEach((step) => {
    activity.promptResolutions[step.id] ||= normalizeInteractionPromptResolutionRecord({}, step.id);
  });
  return activity.promptResolutions;
}

function interactionPromptResolution(activity, promptId = "") {
  if (!activity || !promptId) return normalizeInteractionPromptResolutionRecord({}, promptId);
  activity.promptResolutions ||= {};
  activity.promptResolutions[promptId] ||= normalizeInteractionPromptResolutionRecord({}, promptId);
  return activity.promptResolutions[promptId];
}

function interactionPromptStepIsOpen(activity, step) {
  return Boolean(step?.id && interactionPromptResolution(activity, step.id).status === "open");
}

function currentInteractionPromptStep(activity) {
  const chain = interactionPromptChain(activity);
  return [...chain].reverse().find((step) => interactionPromptStepIsOpen(activity, step))
    || interactionRootPromptStep(activity);
}

function interactionPromptStepById(activity, promptId = "") {
  return interactionPromptChain(activity).find((step) => step.id === promptId) || null;
}

function parentInteractionPromptStep(activity, step) {
  if (!activity || !step?.parentId) return null;
  return interactionPromptStepById(activity, step.parentId) || interactionRootPromptStep(activity);
}

function interactionPromptStepTokenConsumptionRecords(activity, step) {
  if (!activity || !step) return [];
  const source = step.kind === "response" ? step.response || {} : activity.payload || {};
  const consumptionIds = new Set([
    ...(Array.isArray(source.tokenConsumptionIds) ? source.tokenConsumptionIds : []),
    source.consumptionRecordId
  ].filter(Boolean));
  return (state.tokenConsumptions || []).filter((record) => consumptionIds.has(record.id)
    || (step.kind === "response" && record.linkedResponseId === step.response?.id)
    || (step.kind === "event" && record.linkedEventId === activity.id && !record.linkedResponseId));
}

function interactionPromptStepTokenConsumptionRecord(activity, step) {
  return interactionPromptStepTokenConsumptionRecords(activity, step)
    .find((record) => record.inventoryItem && String(record.tokenId || record.inventoryItem.id || "").trim()) || null;
}

function interactionPromptStepTokenMetadata(activity, step) {
  if (!step) return null;
  if (step.kind === "event" && activity?.sourceType === "token-use") {
    return tokenEffectMetadataByName(activity.payload?.tokenName || activity.title || "");
  }
  if (step.kind === "response" && (step.response?.source === "token" || step.response?.tokenName)) {
    return tokenEffectMetadataByName(step.response?.tokenName || livePromptStepResponseLabel(step.response));
  }
  return null;
}

function playerMatchesEffectTargetRelation(playerId, sourcePlayerId, metadata = {}) {
  if (!playerId) return false;
  const relation = String(metadata.targetControllerRelation || "");
  if (metadata.selfOnly || relation === "self" || relation === "sameController") return playerId === sourcePlayerId;
  if (metadata.otherPlayerOnly || metadata.excludeActor
    || ["rival", "otherPlayer", "differentController"].includes(relation)) return playerId !== sourcePlayerId;
  return true;
}

function followMeResponseResolutionPlan(activity, respondingToStep, responderPlayerId, responseDraft = {}) {
  const sourceMetadata = interactionPromptStepTokenMetadata(activity, respondingToStep);
  const parentSource = respondingToStep?.kind === "response" ? respondingToStep.response : activity?.payload;
  const sourcePlayerId = respondingToStep?.actorPlayerId || activity?.actorPlayerId || "";
  const responder = state.players.find((player) => player.id === responderPlayerId);
  if (!activity || !respondingToStep || !parentSource || !sourceMetadata || !responder) {
    return { ok: false, applies: true, reason: "Follow Me needs one exact pending Token target and responding player." };
  }
  if (sourcePlayerId === responderPlayerId) {
    return { ok: false, applies: true, reason: "Follow Me can only redirect another player's effect." };
  }
  if (hasProtectionAgainst(state, responderPlayerId, { protectionKeys: ["followMe"] })) {
    return { ok: false, applies: true, reason: "Safeguard prevents this player from becoming a Follow Me target." };
  }
  const targetType = normalizeEffectTargetType(parentSource.targetType || sourceMetadata.targetType);
  const targetScope = normalizeEffectTargetScope(parentSource.targetScope || sourceMetadata.targetScope);
  if (targetScope === EFFECT_TARGET_SCOPES.ROSTER_INSTANCE && targetType === EFFECT_TARGET_TYPES.POKEMON) {
    if (responseDraft.previewOnly) {
      return { ok: true, applies: true, kind: "followMeRedirect", sourceMetadata, sourcePlayerId, responder, pokemon: null, parentSource, requiresPokemonChoice: true };
    }
    const pokemon = findPokemonRecord(responseDraft.targetPokemonId || "");
    if (!pokemon || pokemon.trainerId !== responderPlayerId || ["Released", "Removed"].includes(pokemon.status)
      || (pokemon.rosterType && pokemon.rosterType !== "Active")) {
      return { ok: false, applies: true, reason: "Choose one exact Active Roster Pokemon owned by the Follow Me user." };
    }
    if (!playerMatchesEffectTargetRelation(pokemon.trainerId, sourcePlayerId, sourceMetadata)) {
      return { ok: false, applies: true, reason: `${pokemon.name} is not a legal corresponding target for the original effect.` };
    }
    return { ok: true, applies: true, kind: "followMeRedirect", sourceMetadata, sourcePlayerId, responder, pokemon, parentSource };
  }
  if (targetScope === EFFECT_TARGET_SCOPES.SINGLE_PLAYER && targetType === EFFECT_TARGET_TYPES.PLAYER) {
    if (!playerMatchesEffectTargetRelation(responderPlayerId, sourcePlayerId, sourceMetadata)) {
      return { ok: false, applies: true, reason: `${responder.name} is not a legal corresponding target for the original effect.` };
    }
    return { ok: true, applies: true, kind: "followMeRedirect", sourceMetadata, sourcePlayerId, responder, pokemon: null, parentSource };
  }
  return { ok: false, applies: true, reason: "Follow Me can only redirect one exact player or Active Roster Pokemon target. Global and targetless effects are not legal." };
}

function afterYouResponseResolutionPlan(activity, respondingToStep, responderPlayerId, responseDraft = {}) {
  const sourceMetadata = interactionPromptStepTokenMetadata(activity, respondingToStep);
  const sourceDefinition = tokenContractDefinitionByName(sourceMetadata?.id || sourceMetadata?.name || "");
  if (!activity || !respondingToStep || !sourceMetadata || !sourceDefinition) {
    return { ok: false, applies: true, reason: "After You needs one exact pending Token activation to copy." };
  }
  if (sourceMetadata.id === "after-you" || respondingToStep.response?.isCopiedActivation) {
    return { ok: false, applies: true, reason: "After You cannot recursively copy an After You or another virtual copied activation." };
  }
  if (sourceDefinition.family === "Protection") {
    const interaction = globalThis.rivalSagaTokenEffectContract?.afterYouProtectionInteractionFor?.(sourceDefinition.id)
      || { supported: false, reason: "This Protection interaction is not approved." };
    if (!interaction.supported) return { ok: false, applies: true, reason: interaction.reason };
    return {
      ok: true,
      applies: true,
      kind: interaction.negatesOriginal ? "afterYouImmunity" : "afterYouProtection",
      sourceMetadata,
      sourceDefinition,
      sourceStep: respondingToStep,
      interaction,
      copyDraft: responseDraft
    };
  }
  if (sourceDefinition.family !== "Control" || sourceMetadata.resolutionMode !== EFFECT_RESOLUTION_MODES.AUTOMATIC
    || !tokenControlController?.CONTROL_TOKEN_IDS?.includes(sourceDefinition.id)) {
    return { ok: false, applies: true, reason: `After You does not yet support ${sourceDefinition.name}; only automatic Control Tokens and approved Protection interactions are available.` };
  }
  const copiedTargetType = normalizeEffectTargetType(sourceMetadata.targetType);
  const copiedTargetScope = normalizeEffectTargetScope(sourceMetadata.targetScope);
  const supportedSimpleTarget = (
    (copiedTargetType === EFFECT_TARGET_TYPES.POKEMON
      && [EFFECT_TARGET_SCOPES.SPECIES, EFFECT_TARGET_SCOPES.ROSTER_INSTANCE].includes(copiedTargetScope))
    || (copiedTargetType === EFFECT_TARGET_TYPES.PLAYER && copiedTargetScope === EFFECT_TARGET_SCOPES.SINGLE_PLAYER)
    || [EFFECT_TARGET_TYPES.TABLE, EFFECT_TARGET_TYPES.NONE].includes(copiedTargetType)
  );
  const customChoiceIds = new Set(["incinerate", "move-deleter", "lingering-aroma", "haze-curse", "knock-off-curse", "ditto-token"]);
  if (!supportedSimpleTarget || customChoiceIds.has(sourceDefinition.id)) {
    return { ok: false, applies: true, reason: `After You cannot safely collect ${sourceDefinition.name}'s fresh exact choices yet. This interaction alone remains unavailable.` };
  }
  const actor = state.players.find((player) => player.id === responderPlayerId) || null;
  const copyDraft = {
    ...responseDraft,
    actor,
    actorPlayerId: responderPlayerId,
    tokenName: sourceDefinition.name,
    category: sourceMetadata.timingCategory,
    targetType: responseDraft.targetType || sourceMetadata.targetType,
    targetScope: responseDraft.targetScope || sourceMetadata.targetScope,
    isVirtualActivation: true
  };
  if (responseDraft.previewOnly) {
    return { ok: true, applies: true, kind: "afterYouControl", sourceMetadata, sourceDefinition, sourceStep: respondingToStep, copyDraft, previewOnly: true };
  }
  const legality = controlTokenDraftLegality(copyDraft, sourceMetadata);
  if (!legality.ok) return { ok: false, applies: true, reason: `Copied ${sourceDefinition.name}: ${legality.reason}` };
  return {
    ok: true,
    applies: true,
    kind: "afterYouControl",
    sourceMetadata,
    sourceDefinition,
    sourceStep: respondingToStep,
    copyDraft
  };
}

function specialTokenResponseResolutionPlan(activity, respondingToStep, responderPlayerId, responseMetadata, responseDraft = {}) {
  const resolverId = responseMetadata?.resolverId || "";
  const specialResolver = ["counterProtection", "restoreNegatedTokenWithCooldown", "redirectParentToSelf", "copyParentEffect"].includes(resolverId);
  if (!specialResolver) return { ok: true, applies: false };
  if (resolverId === "redirectParentToSelf") {
    return followMeResponseResolutionPlan(activity, respondingToStep, responderPlayerId, responseDraft);
  }
  if (resolverId === "copyParentEffect") {
    return afterYouResponseResolutionPlan(activity, respondingToStep, responderPlayerId, responseDraft);
  }
  if (!tokenInventoryRuntime) {
    return { ok: false, applies: true, reason: "The exact Token inventory runtime is unavailable." };
  }
  if (!activity || !respondingToStep || respondingToStep.kind !== "response") {
    return { ok: false, applies: true, reason: `${responseMetadata.name} needs the exact response it is answering.` };
  }

  if (resolverId === "counterProtection") {
    const sourceMetadata = tokenEffectMetadataByName(respondingToStep.response?.tokenName || livePromptStepResponseLabel(respondingToStep.response));
    if (sourceMetadata.timingCategory !== TOKEN_TIMING_CATEGORIES.PROTECTION) {
      return { ok: false, applies: true, reason: "7 Tools can only answer an activated Protection Token." };
    }
    const sourceConsumption = interactionPromptStepTokenConsumptionRecord(activity, respondingToStep);
    if (!sourceConsumption || sourceConsumption.status !== "consumed" || !sourceConsumption.inventoryItem) {
      return { ok: false, applies: true, reason: "The exact consumed Protection Token could not be found. 7 Tools was not used." };
    }
    const protectedPlayerId = sourceConsumption.playerId || respondingToStep.actorPlayerId || "";
    if (hasProtectionAgainst(state, protectedPlayerId, { protectionKeys: ["tokenCopy"] })) {
      return { ok: false, applies: true, reason: "Safeguard prevents this player's Protection Token from being copied. 7 Tools was not used." };
    }
    const sourceDefinition = tokenContractDefinitionByName(sourceMetadata.id || sourceConsumption.tokenName || sourceConsumption.inventoryItem.name);
    if (!sourceDefinition) {
      return { ok: false, applies: true, reason: "The Protection Token has no canonical definition to copy. 7 Tools was not used." };
    }
    return {
      ok: true,
      applies: true,
      kind: "temporaryCopy",
      sourceStep: respondingToStep,
      sourceMetadata,
      sourceDefinition,
      sourceConsumption,
      sourceItem: sourceConsumption.inventoryItem
    };
  }

  if (!interactionPromptStepNegatesParent(respondingToStep)) {
    return { ok: false, applies: true, reason: "Counterspell can only answer a response that would negate one of your Tokens." };
  }
  const negatedStep = parentInteractionPromptStep(activity, respondingToStep);
  if (!negatedStep || negatedStep.actorPlayerId !== responderPlayerId) {
    return { ok: false, applies: true, reason: "Counterspell can only restore your own Token that is about to be negated." };
  }
  const sourceConsumption = interactionPromptStepTokenConsumptionRecord(activity, negatedStep);
  if (!sourceConsumption || sourceConsumption.playerId !== responderPlayerId
    || sourceConsumption.status !== "consumed" || !sourceConsumption.inventoryItem) {
    return { ok: false, applies: true, reason: "The exact consumed Token could not be restored. Counterspell was not used." };
  }
  const sourceName = negatedStep.kind === "response"
    ? negatedStep.response?.tokenName
    : activity.payload?.tokenName || activity.title;
  const sourceMetadata = tokenEffectMetadataByName(sourceName || sourceConsumption.tokenName || sourceConsumption.inventoryItem.name);
  const sourceDefinition = tokenContractDefinitionByName(sourceMetadata.id || sourceConsumption.tokenName || sourceConsumption.inventoryItem.name);
  if (!sourceDefinition) {
    return { ok: false, applies: true, reason: "The negated Token has no canonical definition to restore. Counterspell was not used." };
  }
  const responder = state.players.find((player) => player.id === responderPlayerId);
  const exactTokenId = String(sourceConsumption.inventoryItem.id || sourceConsumption.tokenId || "");
  if (!responder || !exactTokenId || (responder.inventory || []).some((item) => item.id === exactTokenId)) {
    return { ok: false, applies: true, reason: "The exact negated Token cannot be restored without creating a duplicate. Counterspell was not used." };
  }
  return {
    ok: true,
    applies: true,
    kind: "cooldownRestoration",
    sourceStep: negatedStep,
    negatingStep: respondingToStep,
    sourceMetadata,
    sourceDefinition,
    sourceConsumption,
    sourceItem: sourceConsumption.inventoryItem
  };
}

function livePromptStepResponseLabel(response) {
  if (!response) return "a response";
  return response.tokenName
    || activityResponseDefinitions[response.type]?.label
    || (response.source ? `${capitalize(response.source)} response` : "a response");
}

function livePromptStepText(activity, step, { short = false } = {}) {
  if (!step || step.kind === "event") {
    return [activity?.message, activity?.title]
      .map((part) => String(part || "").trim())
      .filter(Boolean)[0] || "Original pending event";
  }
  const response = step.response || {};
  const playerName = livePlayerName(response.playerId, "A player");
  const responseLabel = livePromptStepResponseLabel(response);
  if (short) return `${playerName} used ${responseLabel}`;
  const note = String(response.note || "").trim();
  if (note) return note;
  const targetText = String(response.targetText || "").trim();
  return `${playerName} used ${responseLabel}${targetText ? ` targeting ${targetText}` : ""}.`;
}

function activityEligiblePlayerIdsForPrompt(activity, promptStep = currentInteractionPromptStep(activity), targetState = state) {
  const eligiblePlayerIds = activityEligiblePlayerIds(activity);
  if (!eligiblePlayerIds.length) return [];
  if (promptStep?.kind !== "response") return eligiblePlayerIds;
  const responsePlayerId = promptStep.response?.playerId || "";
  return eligiblePlayerIds.filter((playerId) => playerId !== responsePlayerId);
}

function interactionPromptDirectlyAffectedPlayerIds(activity, promptStep = currentInteractionPromptStep(activity), targetState = state) {
  if (!activity || !promptStep) return [];
  const source = promptStep.kind === "response" ? promptStep.response || {} : activity.payload || {};
  const ids = [];
  const add = (playerId) => {
    if (playerId && (targetState.players || []).some((player) => player.id === playerId)) ids.push(playerId);
  };
  add(promptStep.kind === "response" ? source.targetPlayerId : activity.targetPlayerId);
  const targetPokemonId = source.targetPokemonId || "";
  const targetPokemon = (targetState.pokemonRecords || []).find((pokemon) => pokemon.id === targetPokemonId);
  add(targetPokemon?.trainerId);
  const targetScope = normalizeEffectTargetScope(source.targetScope || "");
  const targetName = String(source.targetPokemonName || source.targetText || "").trim();
  if (targetScope === EFFECT_TARGET_SCOPES.SPECIES && targetName) {
    const speciesKey = pokemonRuleKey(targetName);
    (targetState.pokemonRecords || [])
      .filter((pokemon) => !["Released", "Removed"].includes(pokemon.status))
      .filter((pokemon) => pokemonRuleKey(pokemon.name) === speciesKey
        || pokemonRuleKey(pokemon.currentSpecies) === speciesKey)
      .forEach((pokemon) => add(pokemon.trainerId));
  }
  if (promptStep.kind === "response"
    && (source.targetType === EFFECT_TARGET_TYPES.CURRENT_PROMPT
      || targetScope === EFFECT_TARGET_SCOPES.CURRENT_PROMPT
      || !ids.length)) {
    add(parentInteractionPromptStep(activity, promptStep)?.actorPlayerId);
  }
  return [...new Set(ids)];
}

function interactionPriorityStandingsOrder(activity, targetState = state) {
  const players = targetState.players || [];
  const playerIds = players.map((player) => player.id).filter(Boolean);
  const series = activity?.series || targetState.series;
  const gym = Number(activity?.gym || targetState.gym || 1);
  const previous = (targetState.gymResults || []).find((result) => result.series === series
    && Number(result.gym) === gym - 1
    && !result.undone);
  const previousOrder = [...(previous?.placements || [])]
    .sort((a, b) => Number(a.rank || 99) - Number(b.rank || 99))
    .map((placement) => placement.playerId)
    .filter((playerId) => playerIds.includes(playerId));
  const seriesIndex = seriesNames.indexOf(series);
  const fallbackOrder = players.map((player, index) => {
    const performance = player.seriesPerformance?.[seriesIndex] || {};
    return {
      playerId: player.id,
      index,
      placement: Number(performance.placement || 99),
      sagaPoints: Number(performance.sagaPoints || 0)
    };
  }).sort((a, b) => a.placement - b.placement || b.sagaPoints - a.sagaPoints || a.index - b.index)
    .map((entry) => entry.playerId);
  const seeded = previousOrder.length ? previousOrder : fallbackOrder;
  return [...new Set([...seeded, ...playerIds])];
}

function rotateInteractionPriorityOrder(order, anchorPlayerId = "", { startAfter = false } = {}) {
  if (!order.length || !anchorPlayerId) return [...order];
  const anchorIndex = order.indexOf(anchorPlayerId);
  if (anchorIndex < 0) return [...order];
  const startIndex = (anchorIndex + (startAfter ? 1 : 0)) % order.length;
  return [...order.slice(startIndex), ...order.slice(0, startIndex)];
}

function calculatedInteractionPromptPriorityOrder(activity, promptStep, targetState = state) {
  const eligiblePlayerIds = activityEligiblePlayerIdsForPrompt(activity, promptStep, targetState);
  const standingsOrder = interactionPriorityStandingsOrder(activity, targetState);
  const explicitOrder = promptStep?.kind === "response"
    ? promptStep.response?.priorityPlayerIds
    : activity?.payload?.priorityPlayerIds;
  const baseOrder = Array.isArray(explicitOrder) && explicitOrder.length
    ? [...new Set([...explicitOrder, ...standingsOrder])]
    : standingsOrder;
  const actorPlayerId = String(promptStep?.actorPlayerId || "");
  const directlyAffectedPlayerIds = interactionPromptDirectlyAffectedPlayerIds(activity, promptStep, targetState)
    .filter((playerId) => eligiblePlayerIds.includes(playerId));
  const remainingOrder = rotateInteractionPriorityOrder(baseOrder, actorPlayerId, { startAfter: true })
    .filter((playerId) => eligiblePlayerIds.includes(playerId) && !directlyAffectedPlayerIds.includes(playerId));
  return [...new Set([...directlyAffectedPlayerIds, ...remainingOrder, ...eligiblePlayerIds])];
}

function ensureInteractionPromptPriority(activity, promptStep = currentInteractionPromptStep(activity), targetState = state) {
  if (!activity || !promptStep?.id) return null;
  activity.promptPriority ||= {};
  const existing = activity.promptPriority[promptStep.id];
  const stored = existing && typeof existing === "object" && !Array.isArray(existing) ? existing : {};
  const eligiblePlayerIds = activityEligiblePlayerIdsForPrompt(activity, promptStep, targetState);
  const calculatedOrder = calculatedInteractionPromptPriorityOrder(activity, promptStep, targetState);
  const storedOrder = Number(stored.priorityModelVersion || 0) >= 2 && Array.isArray(stored.priorityOrderPlayerIds)
    ? stored.priorityOrderPlayerIds.filter((playerId) => eligiblePlayerIds.includes(playerId))
    : [];
  const priorityOrderPlayerIds = [...new Set([
    ...(storedOrder.length ? storedOrder : calculatedOrder),
    ...calculatedOrder,
    ...eligiblePlayerIds
  ])];
  const answers = interactionResponsesInOrder(activity)
    .filter((response) => !interactionResponseCanceled(response))
    .filter((response) => interactionResponseAnswerPromptId(activity, response) === promptStep.id);
  const passedPlayerIds = [...new Set(answers.filter((response) => response.type === "pass").map((response) => response.playerId).filter(Boolean))];
  const respondedPlayerIds = [...new Set(answers.filter((response) => response.type !== "pass").map((response) => response.playerId).filter(Boolean))];
  const answeredPlayerIds = new Set([...passedPlayerIds, ...respondedPlayerIds]);
  const remainingPlayerIds = priorityOrderPlayerIds.filter((playerId) => !answeredPlayerIds.has(playerId));
  const currentPriorityPlayerId = remainingPlayerIds[0] || "";
  const record = {
    ...stored,
    priorityModelVersion: 2,
    promptId: promptStep.id,
    eligiblePlayerIds,
    priorityOrderPlayerIds,
    currentPriorityPlayerId,
    priorityIndex: currentPriorityPlayerId ? priorityOrderPlayerIds.indexOf(currentPriorityPlayerId) : priorityOrderPlayerIds.length,
    remainingPlayerIds,
    passedPlayerIds,
    respondedPlayerIds,
    complete: !currentPriorityPlayerId,
    initializedAt: stored.initializedAt || promptStep.createdAt || activity.createdAt || new Date().toISOString()
  };
  activity.promptPriority[promptStep.id] = record;
  return record;
}

function normalizeInteractionPromptPriorities(activity, targetState = state) {
  activity.promptPriority ||= {};
  interactionPromptChain(activity).forEach((promptStep) => ensureInteractionPromptPriority(activity, promptStep, targetState));
  return activity.promptPriority;
}

function currentInteractionPromptPriority(activity, promptStep = currentInteractionPromptStep(activity), targetState = state) {
  return ensureInteractionPromptPriority(activity, promptStep, targetState);
}

function livePromptPlayerIds(activity, promptStep = currentInteractionPromptStep(activity), targetState = state) {
  if (!activity) return { eligiblePlayerIds: [], passedPlayerIds: [], respondedPlayerIds: [], waitingOnPlayerIds: [], currentPriorityPlayerId: "", priorityOrderPlayerIds: [], priorityComplete: true, currentPromptId: "" };
  const currentPromptId = promptStep?.id || interactionRootPromptId(activity);
  const priority = currentInteractionPromptPriority(activity, promptStep, targetState);
  return {
    eligiblePlayerIds: priority?.eligiblePlayerIds || [],
    passedPlayerIds: priority?.passedPlayerIds || [],
    respondedPlayerIds: priority?.respondedPlayerIds || [],
    waitingOnPlayerIds: priority?.remainingPlayerIds || [],
    currentPriorityPlayerId: priority?.currentPriorityPlayerId || "",
    priorityOrderPlayerIds: priority?.priorityOrderPlayerIds || [],
    priorityComplete: Boolean(priority?.complete),
    currentPromptId
  };
}

function liveCurrentPromptDetails(activity, baseDetails = {}, promptStep = currentInteractionPromptStep(activity), parentStep = null) {
  if (promptStep?.kind === "response") {
    const currentText = livePromptStepText(activity, promptStep);
    const parentText = livePromptStepText(activity, parentStep || parentInteractionPromptStep(activity, promptStep), { short: true });
    return {
      statusLabel: "Current Prompt",
      title: livePromptStepText(activity, promptStep, { short: true }),
      body: `${currentText} Responding to: ${parentText}.`,
      helperText: "The table is now responding to this latest response. No Response, new responses, and trades apply to this prompt step."
    };
  }
  return {
    statusLabel: baseDetails?.statusLabel || "Waiting to Resolve",
    title: baseDetails?.title || activity?.title || "Pending event",
    body: baseDetails?.body || activity?.message || "This event is pending before it resolves.",
    helperText: baseDetails?.helperText || "Pause here until eligible players respond, trade, or choose No Response."
  };
}

function liveTablePromptStateSnapshot(prompt, liveTable = state.liveTable) {
  return normalizeLiveTableState({
    ...(liveTable || {}),
    enabled: true,
    gameflowMode: prompt.gameflowMode,
    currentLiveStep: prompt.type || "",
    currentPromptTitle: prompt.title || "",
    currentPromptBody: prompt.body || "",
    currentActorPlayerId: prompt.currentActorPlayerId || "",
    currentPriorityPlayerId: prompt.currentPriorityPlayerId || "",
    priorityOrderPlayerIds: prompt.priorityOrderPlayerIds || [],
    priorityComplete: Boolean(prompt.priorityComplete),
    requiredPlayerIds: prompt.requiredPlayerIds || [],
    waitingOnPlayerIds: prompt.waitingOnPlayerIds || [],
    passedPlayerIds: prompt.passedPlayerIds || [],
    respondedPlayerIds: prompt.respondedPlayerIds || [],
    currentPendingEventId: prompt.currentPendingEventId || "",
    currentBatchId: prompt.currentBatchId || "",
    responsesAllowed: Boolean(prompt.responsesAllowed),
    transactionsAllowed: Boolean(prompt.transactionsAllowed),
    canAdvance: Boolean(prompt.canAdvance),
    lastResolvedEventId: liveTable?.lastResolvedEventId || ""
  });
}

function getCurrentLivePrompt(targetState = state) {
  const pendingEvent = getCurrentPendingEvent(targetState);
  const phase = currentPhase();
  const flowMode = liveGameflowMode();
  if (pendingEvent) {
    const resultSession = liveResultSessionForActivity(pendingEvent, targetState);
    const promptChain = interactionPromptChain(pendingEvent);
    const currentPromptStep = currentInteractionPromptStep(pendingEvent);
    const respondingToPromptStep = parentInteractionPromptStep(pendingEvent, currentPromptStep);
    const playerIds = livePromptPlayerIds(pendingEvent, currentPromptStep, targetState);
    const resultOwnerId = resultSession?.resultOwnerPlayerId || resultSession?.ownerPlayerId || resultSession?.playerId || "";
    const resultOwner = targetState.players.find((player) => player.id === resultOwnerId);
    const resultName = resultSession?.resultDisplayName || pendingEvent.payload?.resultName || "";
    const sourceLabel = resultSession?.sourceLabel || pendingEvent.payload?.sourceLabel || pendingEvent.sourceType || "Event";
    const isEncounterResult = Boolean(resultSession?.sourceType === "encounter" || pendingEvent.type === "encounter-result");
    const tokenPrompt = liveTokenPromptDetails(pendingEvent, resultSession, targetState);
    const promptDisplay = liveCurrentPromptDetails(pendingEvent, tokenPrompt, currentPromptStep, respondingToPromptStep);
    if (resultSession) {
      return {
        id: `live-${pendingEvent.id}`,
        type: tokenPrompt?.type || (isEncounterResult ? "encounter-result-pending" : "pokemon-result-pending"),
        statusLabel: promptDisplay.statusLabel || "Waiting to Resolve",
        title: promptDisplay.title || (resultName ? `${resultOwner?.name || "A player"} rolled ${resultName}` : pendingEvent.title || "Pokemon result pending"),
        body: promptDisplay.body || `${resultName || "This Pokemon result"} from ${sourceLabel} is waiting to resolve.`,
        helperText: promptDisplay.helperText || "Before accepting it, players may use a legal response, trade, or choose No Response.",
        phase: pendingEvent.phase || phase,
        gameflowMode: flowMode,
        currentActorPlayerId: currentPromptStep.actorPlayerId || resultOwnerId || pendingEvent.actorPlayerId || pendingEvent.targetPlayerId || "",
        activePlayerIds: [currentPromptStep.actorPlayerId || resultOwnerId || pendingEvent.actorPlayerId].filter(Boolean),
        requiredPlayerIds: playerIds.eligiblePlayerIds,
        waitingOnPlayerIds: playerIds.waitingOnPlayerIds,
        passedPlayerIds: playerIds.passedPlayerIds,
        respondedPlayerIds: playerIds.respondedPlayerIds,
        currentPriorityPlayerId: playerIds.currentPriorityPlayerId,
        priorityOrderPlayerIds: playerIds.priorityOrderPlayerIds,
        priorityComplete: playerIds.priorityComplete,
        currentPromptId: playerIds.currentPromptId,
        currentPendingEventId: pendingEvent.id,
        currentBatchId: "",
        responsesAllowed: activityResponsesAllowed(pendingEvent),
        transactionsAllowed: activityTransactionsAllowed(pendingEvent),
        canAdvance: true,
        availableActions: ["acceptResult", "reroll", "useResponse", "makeTransaction", "pass", "finalizeEvent"],
        pendingEvent,
        currentPromptStep,
        respondingToPromptStep,
        promptChain,
        resultSession,
        resultName,
        sourceLabel
      };
    }
    const promptDetails = tokenPrompt || liveTokenPromptDetails(pendingEvent, null, targetState);
    const standardPromptDisplay = liveCurrentPromptDetails(pendingEvent, promptDetails, currentPromptStep, respondingToPromptStep);
    return {
      id: `live-${pendingEvent.id}`,
      type: promptDetails?.type || "pending-event",
      statusLabel: standardPromptDisplay.statusLabel || "Waiting to Resolve",
      title: standardPromptDisplay.title || pendingEvent.title || "Pending event",
      body: standardPromptDisplay.body || pendingEvent.message || "This event is pending before it resolves.",
      helperText: standardPromptDisplay.helperText || "Pause here until eligible players respond, trade, or choose No Response.",
      phase: pendingEvent.phase || phase,
      gameflowMode: flowMode,
      currentActorPlayerId: currentPromptStep.actorPlayerId || pendingEvent.actorPlayerId || pendingEvent.targetPlayerId || "",
      activePlayerIds: [currentPromptStep.actorPlayerId || pendingEvent.actorPlayerId].filter(Boolean),
      requiredPlayerIds: playerIds.eligiblePlayerIds,
      waitingOnPlayerIds: playerIds.waitingOnPlayerIds,
      passedPlayerIds: playerIds.passedPlayerIds,
      respondedPlayerIds: playerIds.respondedPlayerIds,
      currentPriorityPlayerId: playerIds.currentPriorityPlayerId,
      priorityOrderPlayerIds: playerIds.priorityOrderPlayerIds,
      priorityComplete: playerIds.priorityComplete,
      currentPromptId: playerIds.currentPromptId,
      currentPendingEventId: pendingEvent.id,
      currentBatchId: "",
      responsesAllowed: activityResponsesAllowed(pendingEvent),
      transactionsAllowed: activityTransactionsAllowed(pendingEvent),
      canAdvance: true,
      availableActions: ["useResponse", "makeTransaction", "pass", "finalizeEvent"],
      pendingEvent,
      currentPromptStep,
      respondingToPromptStep,
      promptChain
    };
  }

  if (phase === "action") {
    const turn = actionTurnInfo();
    const currentActor = targetState.players.find((player) => player.id === turn.currentPlayerId);
    return {
      id: turn.currentPlayerId ? `live-action-${turn.currentPlayerId}` : "live-action-complete",
      type: "action-turn",
      statusLabel: turn.resolving ? "Action Resolving" : "No Pending Event",
      title: turn.allComplete ? "Action Phase Complete" : turn.resolving
        ? `${currentActor?.name || "Current player"} is resolving their Action`
        : `Waiting on ${currentActor?.name || "current player"}`,
      body: turn.allComplete
        ? "All Action Phase actions are spent. Advance when the table is ready."
        : turn.resolving
          ? `Action ${turn.operation?.actionNumber || actionUsedByPlayer(turn.currentPlayerId)} at ${turn.operation?.locationName || "the selected location"} is committed and still resolving.`
          : `Waiting on ${currentActor?.name || "the current player"} to choose Action ${Math.min(actionPhaseRules.actionsPerPlayer, actionUsedByPlayer(turn.currentPlayerId) + 1)}.`,
      helperText: "Nothing is pending yet. When an action creates something respondable, create a manual event or use the advanced controls.",
      phase,
      gameflowMode: flowMode,
      currentActorPlayerId: turn.currentPlayerId || "",
      activePlayerIds: [turn.currentPlayerId].filter(Boolean),
      requiredPlayerIds: [turn.currentPlayerId].filter(Boolean),
      waitingOnPlayerIds: [turn.currentPlayerId].filter(Boolean),
      passedPlayerIds: [],
      respondedPlayerIds: [],
      currentPendingEventId: "",
      currentBatchId: "",
      responsesAllowed: false,
      transactionsAllowed: false,
      canAdvance: turn.allComplete,
      availableActions: ["goToActionPhase", "manualPendingEvent", "openTimingControls"],
      turn
    };
  }

  return {
    id: `live-${phase}`,
    type: "phase-control",
    statusLabel: "No Pending Event",
    title: `${phaseLabels[phase] || "Current phase"} is active`,
    body: "Continue the current phase, or open a manual event if something needs responses before resolving.",
    helperText: "Create a manual event when the table needs to pause before something resolves.",
    phase,
    gameflowMode: flowMode,
    currentActorPlayerId: "",
    activePlayerIds: [],
    requiredPlayerIds: [],
    waitingOnPlayerIds: [],
    passedPlayerIds: [],
    respondedPlayerIds: [],
    currentPendingEventId: "",
    currentBatchId: "",
    responsesAllowed: false,
    transactionsAllowed: false,
    canAdvance: true,
    availableActions: ["openTimingControls", "manualPendingEvent", "advancePhase"]
  };
}

function getLivePlayerStatuses(targetState = state, prompt = getCurrentLivePrompt(targetState)) {
  const pendingEvent = prompt.pendingEvent || null;
  const currentPromptId = prompt.currentPromptId || (pendingEvent ? currentInteractionPromptStep(pendingEvent).id : "");
  const flowState = currentLiveRefereeFlowState();
  const teams = prompt.phase === "battle" ? currentPhaseTeams() : {};
  const openRevisions = prompt.phase === "battle" ? openBattleRevisionWindows() : [];
  const schedule = targetState.battleSchedules?.[currentPhaseKey()];
  const scheduledBattles = schedule?.generatedBattles || [];
  return (targetState.players || []).map((player) => {
    const responses = (pendingEvent?.responses || [])
      .filter((response) => !interactionResponseCanceled(response))
      .filter((response) => interactionResponseAnswerPromptId(pendingEvent, response) === currentPromptId);
    const playerResponses = responses.filter((response) => response.playerId === player.id);
    const passed = playerResponses.some((response) => response.type === "pass");
    const responded = playerResponses.some((response) => response.type !== "pass");
    const eligible = pendingEvent ? (prompt.requiredPlayerIds || activityEligiblePlayerIdsForPrompt(pendingEvent, prompt.currentPromptStep)).includes(player.id) : false;
    let status = "Not involved";
    let tone = "idle";
    let detail = pendingEvent ? "Watching" : phaseLabels[prompt.phase] || "Phase";
    let icon = "—";

    if (passed) {
      status = "Passed";
      tone = "passed";
      detail = "No response to current prompt";
      icon = "—";
    } else if (responded) {
      status = "Responded";
      tone = "responded";
      detail = "Response to current prompt";
      icon = "↗";
    } else if (pendingEvent && prompt.currentPriorityPlayerId === player.id) {
      status = "Priority";
      tone = "acting";
      detail = "Choosing now";
      icon = "!";
    } else if (prompt.currentActorPlayerId === player.id) {
      status = prompt.phase === "action" ? "Taking Action" : "Acting";
      tone = "acting";
      detail = pendingEvent ? "Current prompt source" : "Current turn";
      icon = "▶";
    } else if (eligible) {
      status = "Waiting";
      tone = "waiting";
      detail = "Priority comes later";
      icon = "…";
    } else if (prompt.phase === "action" && actionRemainingForPlayer(player.id) <= 0) {
      status = "Actions Complete";
      tone = "done";
      detail = "Actions spent";
      icon = "✓";
    } else if (prompt.phase === "action") {
      status = "Waiting";
      tone = "waiting";
      detail = `${actionRemainingForPlayer(player.id)}/${actionPhaseRules.actionsPerPlayer} actions left`;
      icon = "…";
    } else if (prompt.phase === "battle") {
      const revisionRequired = openRevisions.some((window) => window.affectedPlayerId === player.id);
      const locked = Boolean(teams[player.id]?.locked);
      if (revisionRequired) {
        status = "Revision Required";
        tone = "alert";
        detail = "Team correction blocks progress";
        icon = "!";
      } else if ([LIVE_REFEREE_FLOW_STATES.TEAM_BUILD, LIVE_REFEREE_FLOW_STATES.TEAM_LOCK].includes(flowState)) {
        status = locked ? "Locked" : flowState === LIVE_REFEREE_FLOW_STATES.TEAM_BUILD ? "Building" : "Waiting to Lock";
        tone = locked ? "done" : flowState === LIVE_REFEREE_FLOW_STATES.TEAM_BUILD ? "acting" : "waiting";
        detail = locked ? "Team confirmed" : "Team not locked";
        icon = locked ? "✓" : "…";
      } else if ([LIVE_REFEREE_FLOW_STATES.RIVAL_BATTLES, LIVE_REFEREE_FLOW_STATES.GYM_PAYOUT].includes(flowState)) {
        const playerBattles = scheduledBattles.filter((battle) => [battle.player1Id, battle.player2Id].includes(player.id));
        const completedBattles = playerBattles.filter((battle) => battle.status === "Completed" || battle.battleRecordId);
        const complete = playerBattles.length > 0 && completedBattles.length === playerBattles.length;
        status = complete ? "Reported" : "Waiting for Report";
        tone = complete ? "done" : "waiting";
        detail = playerBattles.length ? `${completedBattles.length}/${playerBattles.length} battles recorded` : "No scheduled battle";
        icon = complete ? "✓" : "…";
      } else if (locked) {
        status = "Locked";
        tone = "done";
        detail = "Team confirmed";
        icon = "✓";
      }
    }

    return {
      player,
      status,
      tone,
      detail,
      icon,
      eligible
    };
  });
}

function liveFeedTimestamp(value) {
  const date = new Date(value || Date.now());
  if (Number.isNaN(date.getTime())) return "";
  return date.toLocaleString([], { month: "short", day: "numeric", hour: "numeric", minute: "2-digit" });
}

