function openLiveTimingControls({ activityId = "", intent = "" } = {}) {
  state.activityResponseDrawerOpen = true;
  saveState();
  render();
  window.requestAnimationFrame(() => {
    const drawer = els.activityResponseDrawer;
    if (!drawer) return;
    let target = null;
    if (activityId) {
      target = [...drawer.querySelectorAll("[data-activity-card]")]
        .find((card) => card.dataset.activityCard === activityId) || null;
    }
    if (!target && intent === "manual") target = drawer.querySelector("[data-manual-timing-window]");
    if (!target && intent === "token") target = drawer.querySelector("[data-token-use-form]");
    if (!target && activityId && intent === "response") target = drawer.querySelector(`[data-response-form="${activityId}"]`);
    if (!target && activityId && intent === "transaction") target = drawer.querySelector(`[data-transaction-form="${activityId}"]`);
    target ||= drawer.querySelector("[data-manual-timing-window]") || drawer;
    target.scrollIntoView({ block: "center", behavior: "smooth" });
    const focusTarget = intent === "manual"
      ? target.querySelector?.('[data-manual-window-field="title"]')
      : intent === "token"
        ? target.querySelector?.('[data-token-use-field="tokenName"]')
      : intent === "response"
        ? target.querySelector?.('[data-response-field="note"]')
        : intent === "transaction"
          ? target.querySelector?.('[data-transaction-field="moneyAmount"]')
          : null;
    focusTarget?.focus();
  });
}

function liveActivityById(activityId) {
  return (state.interactionEvents || []).find((event) => (
    event.id === activityId
    && event.status === "open"
    && sandboxInteractionEventVisible(event, state)
  )) || null;
}

function livePromptWaitingNames(activity) {
  const waiting = livePromptPlayerIds(activity).waitingOnPlayerIds
    .map((playerId) => state.players.find((player) => player.id === playerId)?.name)
    .filter(Boolean);
  return waiting.join(", ");
}

function liveEventCompletionWarning(activity) {
  const waitingNames = livePromptWaitingNames(activity);
  return waitingNames ? `Not all players have passed or responded. Still waiting on: ${waitingNames}. Finalize anyway?` : "";
}

function liveCanFinalizeActivity(activity) {
  const warning = liveEventCompletionWarning(activity);
  return !warning || confirm(warning);
}

function hasOpenPendingEvent(targetState = state) {
  return Boolean(getCurrentPendingEvent(targetState));
}

function pendingEventGuardText(activity) {
  if (!activity) return "the pending response window";
  return [activity.title, activity.message]
    .map((part) => String(part || "").trim())
    .filter(Boolean)
    .join(": ") || "the pending response window";
}

function closePendingEventGuardModal() {
  pendingEventGuardAction = null;
  els.pendingEventGuardModal?.classList.add("hidden");
}

function openPendingEventGuardModal(activity, actionName, callback) {
  pendingEventGuardAction = {
    activityId: activity.id,
    actionName,
    callback
  };
  const playerIds = livePromptPlayerIds(activity);
  const waitingNames = livePlayerNames(playerIds.waitingOnPlayerIds, "No players waiting");
  const respondedNames = livePlayerNames(playerIds.respondedPlayerIds, "None");
  const passedNames = livePlayerNames(playerIds.passedPlayerIds, "None");
  if (els.pendingEventGuardTitle) els.pendingEventGuardTitle.textContent = actionName ? `Pause Before ${actionName}` : "Timeline Paused";
  if (els.pendingEventGuardMessage) {
    els.pendingEventGuardMessage.textContent = `A response window is still open: ${pendingEventGuardText(activity)}. Finalize or cancel it before continuing.`;
  }
  if (els.pendingEventGuardDetails) {
    els.pendingEventGuardDetails.innerHTML = `
      <span><strong>Waiting On</strong><small>${escapeHtml(waitingNames)}</small></span>
      <span><strong>Responded</strong><small>${escapeHtml(respondedNames)}</small></span>
      <span><strong>No Response</strong><small>${escapeHtml(passedNames)}</small></span>
    `;
  }
  els.pendingEventGuardModal?.classList.remove("hidden");
}

function guardPendingEventBeforeAction(actionName, callback) {
  const activity = getCurrentPendingEvent();
  if (!activity) return true;
  openPendingEventGuardModal(activity, actionName, callback);
  return false;
}

function goToLiveRefereeFromGuard() {
  state.liveRefereeCollapsed = false;
  state.liveRefereeWindowMode = "floating";
  saveClientUiState({ immediate: true });
  closePendingEventGuardModal();
  render();
}

function openTableControlsFromGuard() {
  const activityId = pendingEventGuardAction?.activityId || getCurrentPendingEvent()?.id || "";
  closePendingEventGuardModal();
  openLiveTimingControls({ activityId });
}

function overridePendingEventGuard() {
  const guard = pendingEventGuardAction;
  const activity = guard?.activityId ? liveActivityById(guard.activityId) : getCurrentPendingEvent();
  if (activity) {
    if (provisionalDeclarationRuntime.isProvisionalActivity(activity)) {
      alert("An unconfirmed declaration cannot be finalized or overridden. The declarer must confirm or withdraw, or the host may release it as recovery.");
      return;
    }
    if (!liveCanFinalizeActivity(activity)) return;
    state.liveTable = normalizeLiveTableState({ ...(state.liveTable || {}), lastResolvedEventId: activity.id });
    resolveInteractionActivity(activity.id, "resolved", { renderAfter: false });
  }
  pendingEventGuardAction = null;
  els.pendingEventGuardModal?.classList.add("hidden");
  Promise.resolve(guard?.callback?.()).catch((error) => {
    console.error("Pending event guard override failed", error);
    render();
  });
}

function livePlayerName(playerId, fallback = "Table") {
  return state.players.find((player) => player.id === playerId)?.name || fallback;
}

function livePlayerNames(playerIds = [], fallback = "None") {
  const names = [...new Set(playerIds)]
    .map((playerId) => livePlayerName(playerId, ""))
    .filter(Boolean);
  return names.length ? names.join(", ") : fallback;
}

function livePlayerSelectOptions(playerIds = [], selectedId = "", emptyLabel = "No eligible players") {
  const ids = [...new Set(playerIds)].filter(Boolean);
  if (!ids.length) return `<option value="">${escapeHtml(emptyLabel)}</option>`;
  const safeSelected = ids.includes(selectedId) ? selectedId : ids[0];
  return ids.map((playerId) => {
    const player = state.players.find((entry) => entry.id === playerId);
    return `<option value="${escapeHtml(playerId)}" ${playerId === safeSelected ? "selected" : ""}>${escapeHtml(player?.name || playerId)}</option>`;
  }).join("");
}

function effectApplicationLabel(value = "") {
  return {
    automatic: "Automatic",
    guided: "Guided",
    hostconfirmed: "Host Confirmed",
    manual: "Host Confirmed",
    audit: "Host Confirmed",
    hybrid: "Guided"
  }[String(value || "").toLowerCase()] || "Host Confirmed";
}

function activityEffectApplication(activity) {
  return normalizeEffectResolutionMode(activity?.payload?.resolutionMode || activity?.payload?.effectApplication || EFFECT_RESOLUTION_MODES.HOST_CONFIRMED);
}

function livePromptResolutionText(prompt) {
  if (prompt.resultSession) return "Finalizing accepts the result and closes this response window. Effect Application: Automatic.";
  if (prompt.currentPendingEventId) {
    const application = effectApplicationLabel(activityEffectApplication(prompt.pendingEvent));
    if (prompt.currentPromptStep?.kind === "response") {
      return `Resolve ${livePromptStepResponseLabel(prompt.currentPromptStep.response)} to return to the previous situation. Effect Application: ${application}.`;
    }
    return `Complete this event when its response cycle closes. Effect Application: ${application}.`;
  }
  if (prompt.type === "action-turn") return prompt.canAdvance
    ? "All actions are spent. The host can advance when the table is ready."
    : "Nothing is pending. Wait for the current player to choose an action, or create a manual event if the table pauses.";
  return "Nothing is pending. Continue the phase, create a manual event, or use advanced timing controls if needed.";
}

function liveHostNextStepText(prompt) {
  if (prompt.currentPendingEventId) {
    const waiting = livePlayerNames(prompt.waitingOnPlayerIds, "no one");
    if ((prompt.waitingOnPlayerIds || []).length) {
      return `Waiting on ${waiting}. Record responses, trades, or No Response before finalizing.`;
    }
    return prompt.currentPromptStep?.kind === "response"
      ? `${livePromptStepResponseLabel(prompt.currentPromptStep.response)} is ready to resolve.`
      : "Everyone eligible has answered. Complete the event when the table is ready.";
  }
  if (prompt.type === "action-turn") {
    return prompt.canAdvance
      ? "Action Phase is complete. Advance the phase when the table agrees."
      : "Send the current player to Action Phase controls, or create a manual event if something interrupts.";
  }
  return "No event is pending. Create a manual event when the table needs a response window.";
}

function handleLiveTablePass(activityId, playerId = activePlayer().id, { openAdvancedOnMissing = true } = {}) {
  const activity = liveActivityById(activityId);
  if (!activity) {
    if (openAdvancedOnMissing) openLiveTimingControls();
    return;
  }
  const passer = state.players.find((player) => player.id === playerId);
  if (!playerCanRespondToActivity(activity, passer?.id)) {
    alert("Choose a player who is eligible and still waiting before recording No Response.");
    if (openAdvancedOnMissing) openLiveTimingControls({ activityId: activity.id });
    return;
  }
  const promptStep = currentInteractionPromptStep(activity);
  const promptText = livePromptStepText(activity, promptStep, { short: true });
  if (playerAlreadyAnsweredActivity(activity, passer.id, promptStep.id)) {
    alert(`${passer.name} already passed or responded to the current prompt.`);
    return;
  }
  const updated = addInteractionResponse(activity.id, {
    type: "pass",
    playerId: passer.id,
    respondingToPromptId: promptStep.id,
    note: `No response to ${promptText}.`
  });
  const savedResponse = updated?.responses?.[updated.responses.length - 1];
  addLogEntry({
    action: "interaction",
    category: "system",
    player: passer.name,
    item: `${passer.name} chose no response to ${promptText}.`,
    title: "No response recorded",
    summary: [`Window: ${activity.title}`, `Prompt: ${promptText}`, "No response"],
    type: "interaction-pass",
    categories: ["system", "interaction"],
    tags: ["timing-window", "pass"],
    playerIds: [passer.id, activity.actorPlayerId, activity.targetPlayerId].filter(Boolean),
    linkedEventId: activity.id,
    responseId: savedResponse?.id || "",
    eventOrder: savedResponse?.eventOrder
  });
  advanceAutomaticInteractionPrompts(activity);
  resetLiveRefereeScreenState();
  saveState({ immediate: true });
  render();
}

async function handleLiveTableAcceptResult(sessionId, activityId = "") {
  const session = (state.randomPokemonSessions || []).find((entry) => entry.id === sessionId && entry.status === "pending");
  if (!session) {
    alert("No pending Pokemon result is available to accept.");
    return;
  }
  const activity = activityId ? liveActivityById(activityId) : liveActivityById(session.interactionEventId);
  if (activity && !liveCanFinalizeActivity(activity)) return;
  resetLiveRefereeScreenState();
  await confirmRandomPokemonSession(session.id, { skipPendingGuard: true });
}

async function handleLiveTableRerollResult(sessionId) {
  const session = (state.randomPokemonSessions || []).find((entry) => entry.id === sessionId && entry.status === "pending");
  if (!session) {
    alert("No pending Pokemon result is available to reroll.");
    return;
  }
  await rerollRandomPokemonSession(session.id, { actorPlayerId: activePlayer().id });
  saveState({ immediate: true });
  render();
}

async function handleLiveTableResolve(activityId, { resolutionText = "" } = {}) {
  const activity = liveActivityById(activityId);
  if (!activity) {
    openLiveTimingControls();
    return;
  }
  if (provisionalDeclarationRuntime.isProvisionalActivity(activity)) {
    alert("Complete or withdraw this declaration before resolving an effect.");
    return;
  }
  const currentStep = currentInteractionPromptStep(activity);
  if (currentStep.kind === "response") {
    if (!liveCanFinalizeActivity(activity)) return;
    resolveCurrentInteractionPrompt(activity, { force: true, source: "host", resolutionText });
    advanceAutomaticInteractionPrompts(activity);
    resetLiveRefereeScreenState();
    saveState({ immediate: true });
    render();
    return;
  }
  const resultSession = liveResultSessionForActivity(activity);
  if (resultSession) {
    await handleLiveTableAcceptResult(resultSession.id, activity.id);
    return;
  }
  if (!liveCanFinalizeActivity(activity)) return;
  resetLiveRefereeScreenState();
  resolveInteractionActivity(activity.id, "resolved", { resolutionText });
}

function recoverFailedInteractionActivity(activityId) {
  const activity = liveActivityById(activityId);
  if (!activity) {
    openLiveTimingControls();
    return false;
  }
  if (!(hasSiteAdminAccessForGame() || hasSiteAdminAccess())) {
    alert("Only a host or site admin can recover a failed event.");
    return false;
  }
  const situation = interactionSituationLifecycle.normalizeSituation(activity);
  if (situation.status !== interactionSituationLifecycle.STATUSES.FAILED_RECOVERY_REQUIRED) {
    alert("This event is not in a recovery-required state.");
    return false;
  }
  const plan = interactionSituationLifecycle.recoveryPlan(activity);
  if (!confirm(`Cancel this failed event and restore its safe pre-event state?\n\n${activity.title || "Failed event"}`)) return false;
  let restoredCollections = [];
  if (plan.rollback) {
    const snapshot = activity.payload?.tokenDeclarationUndo;
    if (!snapshot) {
      interactionSituationLifecycle.markFailed(activity, "The event began mutating state, but its recovery snapshot is missing. Use Advanced Controls and preserve the save for repair.");
      saveState({ immediate: true });
      render();
      return false;
    }
    restoredCollections = interactionSituationLifecycle.restoreMutationSnapshot(state, snapshot, structuredClone);
    syncPlayerPokemonLists();
  }
  const refundedCount = plan.refund
    ? refundTokenConsumptionsForLink({ eventId: activity.id }, "Failed event recovery")
    : 0;
  interactionSituationLifecycle.markCanceledRefunded(activity, {
    tokenConsumed: situation.tokenConsumed,
    mutationState: plan.rollback
      ? interactionSituationLifecycle.MUTATION_STATES.ROLLED_BACK
      : interactionSituationLifecycle.MUTATION_STATES.NOT_STARTED
  });
  activity.status = "canceled";
  activity.resolvedAt = new Date().toISOString();
  activity.resolutionMode = "failed-recovery";
  activity.payload ||= {};
  activity.payload.resolutionResult = "canceledRefunded";
  activity.payload.recovery = {
    recoveredAt: activity.resolvedAt,
    recoveredByPlayerId: activePlayer().id,
    plan: plan.action,
    restoredCollections,
    refundedTokenCount: refundedCount
  };
  const rootResolution = interactionPromptResolution(activity, interactionRootPromptId(activity));
  rootResolution.status = "canceled";
  rootResolution.outcome = "canceledRefunded";
  rootResolution.resolvedAt = activity.resolvedAt;
  addLogEntry({
    action: "admin",
    category: "system",
    player: activePlayer().name || "Host",
    item: `Recovered failed event: ${activity.title || activity.id}.`,
    title: "Failed event recovered",
    summary: [
      plan.rollback ? "Partial mutations were restored from the declaration snapshot." : "No partial mutation rollback was required.",
      refundedCount ? `${refundedCount} Token was refunded.` : "No Token refund was required."
    ],
    type: "interaction-recovery",
    categories: ["system", "interaction", "admin"],
    tags: ["failed-recovery", "canceled-refunded"],
    linkedEventId: activity.id,
    playerIds: [activity.actorPlayerId, activity.targetPlayerId].filter(Boolean)
  });
  state.liveTable = normalizeLiveTableState({
    ...(state.liveTable || {}),
    currentPendingEventId: "",
    lastResolvedEventId: activity.id
  });
  pushBackendActivityStatus(activity.id, activity.status, activity.resolutionMode, activity);
  resetLiveRefereeScreenState();
  saveState({ immediate: true });
  render();
  return true;
}

function handleLiveTableCancel(activityId) {
  const activity = liveActivityById(activityId);
  if (!activity) {
    openLiveTimingControls();
    return;
  }
  if (provisionalDeclarationRuntime.isProvisionalActivity(activity)) {
    alert("Use Withdraw Declaration. Hosts may release an abandoned unconfirmed declaration from Host controls.");
    return;
  }
  if (!confirm(`Cancel this pending event?\n\n${activity.title || "Pending event"}`)) return;
  state.liveTable = normalizeLiveTableState({ ...(state.liveTable || {}), lastResolvedEventId: activity.id });
  resetLiveRefereeScreenState();
  resolveInteractionActivity(activity.id, "canceled");
}

function cancelCurrentPromptResponse(activityId) {
  const activity = liveActivityById(activityId);
  if (!activity) {
    openLiveTimingControls();
    return;
  }
  const currentStep = currentInteractionPromptStep(activity);
  if (currentStep.kind !== "response" || !currentStep.response) {
    alert("The original pending event cannot be canceled here. Use Cancel Event or Advanced Controls.");
    return;
  }
  const response = (activity.responses || []).find((entry) => entry.id === currentStep.response.id);
  if (!response) {
    alert("That response could not be found.");
    return;
  }
  if (!confirm(`Cancel this response prompt?\n\n${livePromptStepText(activity, currentStep)}`)) return;
  response.status = "canceled";
  response.canceledAt = new Date().toISOString();
  response.cancelReason = "Canceled from Live Referee";
  response.createsPrompt = false;
  const refundedCount = refundTokenConsumptionsForLink({ eventId: activity.id, responseId: response.id }, "Response prompt canceled");
  addLogEntry({
    action: "interaction",
    category: "system",
    player: livePlayerName(response.playerId, "Table"),
    item: `Withdrew response prompt: ${livePromptStepText(activity, currentStep, { short: true })}.`,
    title: "Response withdrawn and refunded",
    summary: [`Window: ${activity.title}`, `Withdrawn: ${livePromptStepText(activity, currentStep)}`, "Current prompt returned to the previous chain step.", refundedCount ? `Refunded ${refundedCount} token${refundedCount === 1 ? "" : "s"}.` : ""].filter(Boolean),
    type: "interaction-response-canceled",
    categories: ["system", "interaction"],
    tags: ["live-referee", "timing-window", "response", "canceled"],
    playerIds: [response.playerId, activity.actorPlayerId, activity.targetPlayerId].filter(Boolean),
    linkedEventId: activity.id,
    responseId: response.id,
    eventOrder: nextEventOrder()
  });
  resetLiveRefereeScreenState();
  saveState({ immediate: true });
  render();
}

