function liveRefereeEffectsSourceMarkup(prompt, selectedPlayerId = liveRefereeControlledPlayerId()) {
  const player = state.players.find((entry) => entry.id === selectedPlayerId) || null;
  const canUseManual = Boolean(prompt?.pendingEvent && prompt.responsesAllowed);
  const available = liveRefereeAvailableTokenGroups(prompt, selectedPlayerId);
  const sourceChoices = [
    available.groups.length ? liveRefereeChoiceButtonMarkup({ label: "Tokens", screen: "tokens", variant: "primary" }) : "",
    liveRefereeChoiceButtonMarkup({ label: "Class - Later", disabled: true }),
    liveRefereeChoiceButtonMarkup({ label: "Perks - Later", disabled: true }),
    liveRefereeChoiceButtonMarkup({ label: "Items - Later", disabled: true }),
    liveRefereeChoiceButtonMarkup({ label: "Manual", screen: "manualEffect", disabled: !canUseManual })
  ].filter(Boolean);
  return liveRefereeGameScreenMarkup({
    className: "live-referee-effects-screen",
    situation: available.groups.length || canUseManual ? "Choose an effect source." : "No usable effects right now.",
    detail: player?.name ? `Acting as ${player.name}.` : "",
    body: liveRefereePickerScrollMarkup(liveRefereeSubmenuOptionsMarkup(sourceChoices), "Effect source choices"),
    choices: liveRefereeNavActionsMarkup([
      liveRefereeChoiceButtonMarkup({ label: "Back", screen: "play" })
    ])
  });
}

function liveRefereeProvisionalEffectChooserMarkup(prompt, selectedPlayerId = liveRefereeControlledPlayerId()) {
  const timing = provisionalDeclarationRuntime.controlTimingStatus(state, {
    actionsPerPlayer: actionPhaseRules.actionsPerPlayer,
    isBlocking: interactionSituationLifecycle.isBlocking
  });
  const { player, groups } = getUsableEffectsForContext({
    playerId: selectedPlayerId,
    gymId: Number(state.gym || 1),
    phase: currentPhase()
  });
  const legalGroups = groups.filter((group) => group.definition?.usesControlTiming
    && !group.definition?.isResponse
    && group.definition?.timingWindows?.includes(TOKEN_TIMING_WINDOWS.ACTION_OPEN)
    && group.items?.length);
  const buttons = legalGroups.map((group) => {
    const exactItem = group.items[0];
    return liveRefereeChoiceButtonMarkup({
      label: `${group.name} x${group.count}`,
      attrs: `data-provisional-effect-claim data-effect-contract-id="${escapeHtml(group.definition.id)}" data-inventory-record-id="${escapeHtml(exactItem.id)}" data-declaring-player-id="${escapeHtml(player?.id || "")}"`,
      variant: "primary"
    });
  });
  const actionPlayer = state.players.find((entry) => entry.id === timing.decision?.currentPlayerId);
  return liveRefereeGameScreenMarkup({
    className: "live-referee-declare-effects-screen",
    situation: timing.open ? "Choose an effect to declare." : "Control Timing has closed.",
    detail: timing.open
      ? `Selecting an exact effect pauses ${actionPlayer?.name || "the Action player"}'s destination decision. Targets come next.`
      : timing.reason,
    body: liveRefereePickerScrollMarkup(
      buttons.length
        ? liveRefereeSubmenuOptionsMarkup(buttons, { compact: buttons.length > 5 })
        : `<p class="empty-state compact">${escapeHtml(player?.name || "This player")} has no legal Control effect to begin now.</p>`,
      `${player?.name || "Player"}'s legal Control effects`
    ),
    choices: liveRefereeNavActionsMarkup([
      liveRefereeChoiceButtonMarkup({ label: "Back", screen: "play" })
    ])
  });
}

function liveRefereeTokenListScreenMarkup(prompt, selectedPlayerId = liveRefereeControlledPlayerId()) {
  const { player, groups, blockedGroups } = liveRefereeAvailableTokenGroups(prompt, selectedPlayerId);
  const actorName = player?.name || "Selected player";
  const emptyText = prompt.pendingEvent
    ? `No usable tokens for ${actorName} right now.`
    : `No usable tokens for ${actorName} right now.`;
  const categoryGroups = new Map();
  groups.forEach((group) => {
    const category = group.metadata.timingCategory || TOKEN_TIMING_CATEGORIES.MANUAL;
    if (!categoryGroups.has(category)) categoryGroups.set(category, []);
    categoryGroups.get(category).push(group);
  });
  const tokenButtons = [...categoryGroups.entries()].map(([category, entries]) => `
    <section class="live-referee-token-category" data-token-category="${escapeHtml(category)}">
      <h3>${escapeHtml(tokenTimingCategoryLabel(category))}</h3>
      ${liveRefereeSubmenuOptionsMarkup(entries.map((group) => liveRefereeChoiceButtonMarkup({
        label: `${group.name} x${group.count}`,
        attrs: `data-live-referee-effect-pick="${escapeHtml(group.name)}" data-token-definition-id="${escapeHtml(group.definition.id)}"`,
        variant: category === TOKEN_TIMING_CATEGORIES.PROTECTION ? "primary" : "ghost"
      })), { compact: groups.length > 4 })}
    </section>
  `);
  const blockedMarkup = blockedGroups.length ? `
    <details class="live-referee-unavailable-effects">
      <summary>Relevant but unavailable (${blockedGroups.length})</summary>
      ${blockedGroups.map((group) => `<p><b>${escapeHtml(group.name)}</b>: ${escapeHtml(group.usability.reason)}</p>`).join("")}
    </details>
  ` : "";
  return liveRefereeGameScreenMarkup({
    className: "live-referee-tokens-screen",
    situation: groups.length ? "Choose a token." : "No usable tokens right now.",
    detail: groups.length ? `${actorName}'s usable tokens.` : emptyText,
    body: liveRefereePickerScrollMarkup(
      `${tokenButtons.length ? tokenButtons.join("") : `<p class="empty-state compact">${escapeHtml(emptyText)}</p>`}${blockedMarkup}`,
      `${actorName}'s usable effects`
    ),
    choices: liveRefereeNavActionsMarkup([
      liveRefereeChoiceButtonMarkup({ label: "Back", screen: "effects" }),
      liveRefereeChoiceButtonMarkup({ label: "Cancel", screen: "play" })
    ])
  });
}

function liveRefereeRosterPokemonOptions(selectedId = "", { actorPlayerId = "", targetControllerRelation = "", selfOnly = false, otherPlayerOnly = false, activeOnly = false, eligibility = null } = {}) {
  const normalizedRelation = String(targetControllerRelation || "").trim();
  const records = (state.pokemonRecords || [])
    .filter((pokemon) => !["Released", "Removed"].includes(pokemon.status))
    .filter((pokemon) => !activeOnly || !pokemon.rosterType || pokemon.rosterType === "Active")
    .filter((pokemon) => !(selfOnly || normalizedRelation === "self") || pokemon.trainerId === actorPlayerId)
    .filter((pokemon) => !(otherPlayerOnly || ["rival", "otherPlayer", "differentController"].includes(normalizedRelation)) || pokemon.trainerId !== actorPlayerId)
    .filter((pokemon) => typeof eligibility !== "function" || eligibility(pokemon)?.ok)
    .sort((a, b) => {
      const ownerA = livePlayerName(a.trainerId, "");
      const ownerB = livePlayerName(b.trainerId, "");
      return ownerA.localeCompare(ownerB) || a.name.localeCompare(b.name);
    });
  if (!records.length) return `<option value="">No roster Pokemon available</option>`;
  return [
    `<option value="">Choose a Pokemon</option>`,
    ...records.map((pokemon) => {
      const owner = livePlayerName(pokemon.trainerId, "Unknown");
      const label = `${owner} - ${pokemon.name}${pokemon.rosterType && pokemon.rosterType !== "Active" ? ` (${pokemon.rosterType})` : ""}`;
      return `<option value="${escapeHtml(pokemon.id)}" ${pokemon.id === selectedId ? "selected" : ""}>${escapeHtml(label)}</option>`;
    })
  ].join("");
}

function liveRefereeControlSpeciesOptions(tokenName = "") {
  const key = slugify(tokenName);
  if (key === "unban") {
    const names = [
      ...activeLingeringStatuses().filter((status) => ["ban", "restrict"].includes(status.type)).map((status) => status.targetPokemonName),
      ...Object.values(state.globalPokemonRules || {}).filter((rule) => ["Banned", "Restricted"].includes(rule.status) && !ruleIsExpired(rule)).map((rule) => rule.name)
    ].filter(Boolean);
    return [...new Map(names.map((name) => [pokemonRuleKey(name), { displayName: name }])).values()]
      .sort((a, b) => a.displayName.localeCompare(b.displayName));
  }
  const allSpecies = pokemonSpeciesNameOptions();
  if (!["restrict", "extra-ban"].includes(key)) return allSpecies;
  const options = controlTokenEffectOptions();
  return allSpecies.filter((entry) => {
    const name = entry.displayName || entry.name || "";
    if (controlTokenEffects?.speciesHasUnbanProtection(state, name, options)) return false;
    if (key === "restrict") {
      return !controlTokenEffects?.activeSpeciesStatuses(state, name, "restrict", options).length
        && currentPokemonRuleStatusByName(name) !== "Restricted";
    }
    return !controlTokenEffects?.activeSpeciesStatuses(state, name, "ban", options).length
      && currentPokemonRuleStatusByName(name) !== "Banned";
  });
}

function liveRefereeSpeciesDatalistMarkup(id = "live-referee-species-options", entries = pokemonSpeciesNameOptions()) {
  return `
    <datalist id="${escapeHtml(id)}">
      ${entries.map((entry) => `<option value="${escapeHtml(entry.displayName)}"></option>`).join("")}
    </datalist>
  `;
}

function liveRefereeIncinerateTargetsForPlayer(player) {
  const resources = controlTokenEffects?.incinerateEligibleResources?.(player)
    || (player?.inventory || []).filter((resource) => (
      String(resource?.id || "").trim()
      && controlTokenEffects?.inventoryResourceCategory?.(resource)
      && !controlTokenEffects?.isMasterBallResource?.(resource)
    ));
  const totals = new Map();
  resources.forEach((resource) => {
    const key = `${controlTokenEffects?.inventoryResourceCategory?.(resource)}:${slugify(resource.moveName || resource.name || "")}`;
    totals.set(key, Number(totals.get(key) || 0) + 1);
  });
  const seen = new Map();
  return resources.map((resource) => {
    const category = controlTokenEffects?.inventoryResourceCategory?.(resource) || "Item";
    const name = String(resource.moveName || resource.name || "Unknown Resource").trim();
    const key = `${category}:${slugify(name)}`;
    const ordinal = Number(seen.get(key) || 0) + 1;
    seen.set(key, ordinal);
    return {
      id: resource.id,
      name,
      category,
      label: Number(totals.get(key) || 0) > 1 ? `${name} · Copy ${ordinal}` : name
    };
  }).sort((a, b) => a.category.localeCompare(b.category) || a.name.localeCompare(b.name) || a.id.localeCompare(b.id));
}

function liveRefereeIncineratePlayerCardMarkup(player, draft = null) {
  const resources = liveRefereeIncinerateTargetsForPlayer(player);
  if (!resources.length) {
    return `
      <article class="live-referee-incinerate-player empty" data-incinerate-player-card="${escapeHtml(player.id)}">
        <header>
          ${liveRefereePlayerAvatarMarkup(player)}
          <strong>${escapeHtml(player.name)}</strong>
          <em data-incinerate-player-status>No legal target</em>
        </header>
        <div class="live-referee-incinerate-empty">
          <b>No legal Items or TMs</b>
          <span>Master Ball resources and records without stable IDs are excluded.</span>
        </div>
      </article>
    `;
  }
  const saved = draft?.incinerateCards?.[player.id] || {};
  const category = ["all", "item", "tm"].includes(saved.category) ? saved.category : "all";
  const query = String(saved.query || "");
  const selectedResource = resources.find((resource) => resource.id === saved.resourceId) || null;
  const selectedId = selectedResource && (category === "all" || selectedResource.category.toLowerCase() === category)
    ? selectedResource.id
    : "";
  if (draft) {
    draft.incinerateCards ||= {};
    draft.incinerateCards[player.id] = { category, query, resourceId: selectedId };
  }
  return `
    <article class="live-referee-incinerate-player" data-incinerate-player-card="${escapeHtml(player.id)}" data-incinerate-category="${escapeHtml(category)}">
      <header>
        ${liveRefereePlayerAvatarMarkup(player)}
        <strong>${escapeHtml(player.name)}</strong>
        <em data-incinerate-player-status>Choose 1</em>
      </header>
      <div class="live-referee-incinerate-tools">
        <div class="live-referee-incinerate-tabs" role="group" aria-label="Filter ${escapeHtml(player.name)} targets">
          <button type="button" class="${category === "all" ? "active" : ""}" data-incinerate-resource-filter="all" aria-pressed="${category === "all"}">All</button>
          <button type="button" class="${category === "item" ? "active" : ""}" data-incinerate-resource-filter="item" aria-pressed="${category === "item"}">Items</button>
          <button type="button" class="${category === "tm" ? "active" : ""}" data-incinerate-resource-filter="tm" aria-pressed="${category === "tm"}">TMs</button>
        </div>
        <input type="search" data-incinerate-resource-search value="${escapeHtml(query)}" placeholder="Search ${escapeHtml(player.name)}'s bag" aria-label="Search ${escapeHtml(player.name)} targets" autocomplete="off">
      </div>
      <div class="live-referee-incinerate-list" role="radiogroup" aria-label="Choose one target from ${escapeHtml(player.name)}">
        ${resources.map((resource) => `
          <label data-incinerate-resource-row data-resource-category="${escapeHtml(resource.category.toLowerCase())}" data-resource-search="${escapeHtml(resource.name.toLowerCase())}" ${(category !== "all" && resource.category.toLowerCase() !== category) || (query && !resource.name.toLowerCase().includes(query.toLowerCase())) ? "hidden" : ""}>
            <input type="radio" name="incinerate-target-${escapeHtml(slugify(player.id))}" value="${escapeHtml(resource.id)}" data-incinerate-target data-player-id="${escapeHtml(player.id)}" ${resource.id === selectedId ? "checked" : ""}>
            <span class="live-referee-incinerate-resource-icon ${escapeHtml(resource.category.toLowerCase())}" aria-hidden="true">${resource.category === "TM" ? "TM" : "IT"}</span>
            <strong>${escapeHtml(resource.label)}</strong>
            <small>${escapeHtml(resource.category)}</small>
          </label>
        `).join("")}
        <p class="live-referee-incinerate-filter-empty" data-incinerate-filter-empty hidden>No targets match this filter.</p>
      </div>
    </article>
  `;
}

function liveRefereeIncinerateTargetScreenMarkup({ prompt, tokenName, metadata, actor } = {}) {
  const draft = liveRefereeEffectDraftFor(tokenName, actor?.id || "");
  const rivals = (state.players || []).filter((player) => player.id !== actor?.id);
  const requiredCount = rivals.filter((player) => liveRefereeIncinerateTargetsForPlayer(player).length).length;
  const noTargetCount = rivals.length - requiredCount;
  return `
    <section class="live-referee-game-screen live-referee-effect-screen live-referee-incinerate-screen" data-live-referee-effect-form data-incinerate-target-form data-incinerate-required-count="${requiredCount}">
      ${liveRefereeSituationMarkup(`Choose one target from each opposing player.${noTargetCount ? ` ${noTargetCount} ${noTargetCount === 1 ? "player has" : "players have"} no legal target.` : ""}`)}
      ${liveRefereeEffectHiddenFields(tokenName, metadata)}
      <div class="live-referee-incinerate-grid">
        ${rivals.map((player) => liveRefereeIncineratePlayerCardMarkup(player, draft)).join("") || `<p class="empty-state compact">There are no opposing players.</p>`}
      </div>
      <div class="live-referee-incinerate-confirmation">
        <div>
          <strong data-incinerate-selection-summary>${requiredCount ? `0 of ${requiredCount} required targets selected` : "No legal rival targets"}</strong>
          <span>Review every selection before confirming.</span>
        </div>
        ${liveRefereeNavActionsMarkup(liveRefereeEffectNavigationChoices(tokenName, {
          confirmLabel: `Confirm ${tokenName}`,
          confirmAttrs: "data-live-referee-effect-submit data-incinerate-confirm",
          confirmDisabled: requiredCount > 0
        }), { compact: true })}
      </div>
    </section>
  `;
}

function filterLiveRefereeIncinerateCard(card) {
  if (!card || card.classList.contains("empty")) return;
  const query = String(card.querySelector("[data-incinerate-resource-search]")?.value || "").trim().toLowerCase();
  const category = card.dataset.incinerateCategory || "all";
  let visibleCount = 0;
  card.querySelectorAll("[data-incinerate-resource-row]").forEach((row) => {
    const matchesCategory = category === "all" || row.dataset.resourceCategory === category;
    const matchesQuery = !query || String(row.dataset.resourceSearch || "").includes(query);
    row.hidden = !(matchesCategory && matchesQuery);
    if (!row.hidden) visibleCount += 1;
  });
  const empty = card.querySelector("[data-incinerate-filter-empty]");
  if (empty) empty.hidden = visibleCount > 0;
}

function persistLiveRefereeIncinerateCardDraft(card, { immediate = false } = {}) {
  if (!card || card.classList.contains("empty")) return;
  const draft = liveRefereeEffectDraftFor();
  const playerId = card.dataset.incineratePlayerCard || "";
  if (!playerId) return;
  draft.incinerateCards ||= {};
  draft.incinerateCards[playerId] = {
    category: card.dataset.incinerateCategory || "all",
    query: String(card.querySelector("[data-incinerate-resource-search]")?.value || ""),
    resourceId: card.querySelector("[data-incinerate-target]:checked")?.value || ""
  };
  state.liveRefereeEffectDraft = draft;
  saveClientUiState({ immediate });
  persistProvisionalDeclarationDraft({ immediate })?.catch((error) => console.warn("Incinerate declaration draft save failed.", error));
}

function updateLiveRefereeIncinerateSelectionUi(form) {
  if (!form?.matches?.("[data-incinerate-target-form]")) return;
  const requiredCount = Number(form.dataset.incinerateRequiredCount || 0);
  let selectedCount = 0;
  form.querySelectorAll("[data-incinerate-player-card]").forEach((card) => {
    if (card.classList.contains("empty")) return;
    const selected = card.querySelector("[data-incinerate-target]:checked");
    const status = card.querySelector("[data-incinerate-player-status]");
    card.classList.toggle("selected", Boolean(selected));
    if (selected) selectedCount += 1;
    if (status) status.textContent = selected ? "1 selected" : "Choose 1";
  });
  const summary = form.querySelector("[data-incinerate-selection-summary]");
  if (summary) summary.textContent = requiredCount
    ? `${selectedCount} of ${requiredCount} required target${requiredCount === 1 ? "" : "s"} selected`
    : "No legal rival targets";
  const confirm = form.querySelector("[data-incinerate-confirm]");
  if (confirm) confirm.disabled = form.dataset.submitting === "true" || selectedCount !== requiredCount;
}

function liveRefereeWickedBlowDataReady() {
  return liveRefereeWickedBlowDataState === "ready" && pokemonBuildDataReady();
}

function requestLiveRefereeWickedBlowData() {
  if (pokemonBuildDataReady()) {
    liveRefereeWickedBlowDataState = "ready";
    liveRefereeWickedBlowDataError = "";
    return Promise.resolve(window.rivalSagaBuildData);
  }
  if (liveRefereeWickedBlowDataPromise) return liveRefereeWickedBlowDataPromise;
  liveRefereeWickedBlowDataState = "loading";
  liveRefereeWickedBlowDataError = "";
  liveRefereeWickedBlowDataPromise = ensurePokemonBuildDataLoaded({ renderOnLoad: false })
    .then((data) => {
      const ready = pokemonBuildDataReady() && Boolean(data?.pokemon && data?.species);
      liveRefereeWickedBlowDataState = ready ? "ready" : "error";
      liveRefereeWickedBlowDataError = ready ? "" : "Wicked Blow could not load the Pokemon evolution and Battle Tier reference data.";
      return data;
    })
    .catch((error) => {
      liveRefereeWickedBlowDataState = "error";
      liveRefereeWickedBlowDataError = error?.message || "Wicked Blow could not load its Pokemon reference data.";
      return EMPTY_POKEMON_BUILD_DATA;
    })
    .finally(() => {
      liveRefereeWickedBlowDataPromise = null;
      if (slugify(state.liveRefereeSelectedEffectName) === "wicked-blow"
        && normalizeLiveRefereeScreenName(state.liveRefereeScreen) === "tokenTarget") {
        renderLiveRefereePanel();
      }
    });
  return liveRefereeWickedBlowDataPromise;
}

function liveRefereeWickedBlowActiveRosterTargets() {
  if (!liveRefereeWickedBlowDataReady()) return [];
  return (state.players || []).map((player) => {
    const targets = activeRosterForPlayer(player.id).map((pokemon, index) => {
      const activeTarget = controlTokenEffects?.wickedBlowActiveRosterTarget?.(state, pokemon, controlTokenEffectOptions())
        || { ok: false, reason: "Wicked Blow targeting is unavailable." };
      if (!activeTarget.ok) return null;
      const rosterSpecies = String(pokemonCommittedSpecies(pokemon) || pokemon.name || "").trim();
      const preview = controlTokenEffects?.wickedBlowResolutionPlan?.(state, pokemon, controlTokenEffectOptions(), true)
        || { ok: false, reason: "Wicked Blow resolution is unavailable." };
      return {
        pokemon,
        index,
        rosterSpecies,
        battleTier: pokemonSagaTier(rosterSpecies) || "Unassigned",
        preview
      };
    }).filter(Boolean);
    return { player, targets };
  }).filter((entry) => entry.targets.length);
}

function liveRefereeWickedBlowPlayerCardMarkup(entry, selectedId, actorPlayerId) {
  const { player, targets } = entry;
  return `
    <article class="live-referee-wicked-player">
      <header>
        ${liveRefereePlayerAvatarMarkup(player)}
        <div><strong>${escapeHtml(player.name)}</strong><span>${player.id === actorPlayerId ? "Your Active Roster" : "Active Roster"}</span></div>
        <em>${targets.length} legal</em>
      </header>
      <div class="live-referee-wicked-targets" role="radiogroup" aria-label="Choose one Pokemon from ${escapeHtml(player.name)}'s Active Roster">
        ${targets.map(({ pokemon, battleTier, preview }) => {
          const finalTier = preview.tierCalculation?.finalEvolutionTier || "Unknown";
          const replacementTier = preview.tierCalculation?.replacementTier || "Unavailable";
          const selected = preview.ok && pokemon.id === selectedId;
          return `
            <label class="${preview.ok ? "" : "unavailable"}${selected ? " selected" : ""}" data-wicked-blow-target-row>
              <input type="radio" name="wicked-blow-target" value="${escapeHtml(pokemon.id)}" data-wicked-blow-target ${selected ? "checked" : ""} ${preview.ok ? "" : "disabled"}>
              <span class="live-referee-wicked-sprite${pokemonSpriteClassSuffix(pokemon)}">${renderPokemonSpriteContent(pokemon)}</span>
              <span class="live-referee-wicked-identity">
                <strong>${escapeHtml(pokemon.name || pokemonCommittedSpecies(pokemon))}</strong>
                <small>Active Roster · Exact ID ${escapeHtml(String(pokemon.id).slice(-8))}</small>
              </span>
              <span class="live-referee-wicked-tier">
                <b>${escapeHtml(battleTier)}</b>
                <small>${preview.ok ? `${finalTier} -> ${replacementTier}` : preview.reason}</small>
              </span>
            </label>
          `;
        }).join("")}
      </div>
    </article>
  `;
}

function liveRefereeWickedBlowTargetScreenMarkup({ tokenName, metadata, actor } = {}) {
  const draft = liveRefereeEffectDraftFor(tokenName, actor?.id || "");
  if (!pokemonBuildDataReady()) {
    requestLiveRefereeWickedBlowData();
    const failed = liveRefereeWickedBlowDataState === "error";
    return `
      <section class="live-referee-game-screen live-referee-effect-screen live-referee-wicked-screen loading" data-live-referee-effect-form data-wicked-blow-loading-state="${failed ? "error" : "loading"}">
        ${liveRefereeSituationMarkup(
          failed ? "Wicked Blow reference data is unavailable." : "Loading Wicked Blow targets...",
          failed ? liveRefereeWickedBlowDataError : "Checking evolution families, final evolutions, and Battle Tiers."
        )}
        <div class="live-referee-data-loading" role="status" aria-live="polite">
          <span aria-hidden="true"></span>
          <strong>${failed ? "Target selection is safely blocked." : "Loading Pokemon data"}</strong>
        </div>
        ${liveRefereeNavActionsMarkup([
          liveRefereeChoiceButtonMarkup({ label: "Back", screen: "tokens" }),
          liveRefereeChoiceButtonMarkup({ label: failed ? "Retry" : "Please wait", attrs: failed ? "data-wicked-blow-data-retry" : "", variant: failed ? "primary" : "ghost", disabled: !failed }),
          liveRefereeChoiceButtonMarkup({ label: "Cancel", screen: "play" })
        ], { compact: true })}
      </section>
    `;
  }
  liveRefereeWickedBlowDataState = "ready";
  liveRefereeWickedBlowDataError = "";
  const rosters = liveRefereeWickedBlowActiveRosterTargets();
  const legalIds = new Set(rosters.flatMap((entry) => entry.targets.filter((target) => target.preview.ok).map((target) => target.pokemon.id)));
  const selectedId = legalIds.has(draft.targetPokemonId) ? draft.targetPokemonId : "";
  draft.targetPokemonId = selectedId;
  const legalCount = legalIds.size;
  return `
    <section class="live-referee-game-screen live-referee-effect-screen live-referee-wicked-screen" data-live-referee-effect-form data-wicked-blow-target-form>
      ${liveRefereeSituationMarkup("Use Wicked Blow on which Active Roster Pokemon?")}
      ${liveRefereeEffectHiddenFields(tokenName, metadata)}
      <input type="hidden" data-live-referee-effect-field="targetPokemonId" value="${escapeHtml(selectedId)}">
      <div class="live-referee-wicked-grid">
        ${rosters.map((entry) => liveRefereeWickedBlowPlayerCardMarkup(entry, selectedId, actor?.id || "")).join("") || `<p class="empty-state compact">No player has a legal Active Roster target.</p>`}
      </div>
      <div class="live-referee-wicked-confirmation">
        <strong data-wicked-blow-selection-summary>${selectedId ? "1 exact Active Roster Pokemon selected" : legalCount ? "Choose 1 exact Active Roster Pokemon" : "No legal Wicked Blow targets"}</strong>
        ${liveRefereeNavActionsMarkup(liveRefereeEffectNavigationChoices(tokenName, {
          confirmLabel: `Confirm ${tokenName}`,
          confirmAttrs: "data-live-referee-effect-submit data-wicked-blow-confirm",
          confirmDisabled: !selectedId
        }), { compact: true })}
      </div>
    </section>
  `;
}

function updateLiveRefereeWickedBlowSelectionUi(form) {
  if (!form?.matches?.("[data-wicked-blow-target-form]")) return;
  const selected = form.querySelector("[data-wicked-blow-target]:checked");
  form.querySelectorAll("[data-wicked-blow-target-row]").forEach((row) => {
    row.classList.toggle("selected", Boolean(row.querySelector("[data-wicked-blow-target]:checked")));
  });
  const field = form.querySelector('[data-live-referee-effect-field="targetPokemonId"]');
  if (field) field.value = selected?.value || "";
  const summary = form.querySelector("[data-wicked-blow-selection-summary]");
  if (summary) summary.textContent = selected ? "1 exact Active Roster Pokemon selected" : "Choose 1 exact Active Roster Pokemon";
  const confirm = form.querySelector("[data-wicked-blow-confirm]");
  if (confirm) confirm.disabled = form.dataset.submitting === "true" || !selected;
}

function persistLiveRefereeWickedBlowDraft(form, { immediate = false } = {}) {
  if (!form?.matches?.("[data-wicked-blow-target-form]")) return;
  const draft = liveRefereeEffectDraftFor();
  draft.targetPokemonId = form.querySelector("[data-wicked-blow-target]:checked")?.value || "";
  state.liveRefereeEffectDraft = draft;
  saveClientUiState({ immediate });
  persistProvisionalDeclarationDraft({ immediate })?.catch((error) => console.warn("Wicked Blow declaration draft save failed.", error));
}

function isStandardCurseTokenId(tokenId = "") {
  const ids = tokenControlController?.STANDARD_CURSE_TOKEN_IDS || [
    "toxic-curse",
    "iron-ball-curse",
    "flame-curse",
    "silencing-curse",
    "imprison-curse"
  ];
  return ids.includes(slugify(tokenId));
}

function liveRefereeStandardCurseActiveRosterTargets() {
  return (state.players || []).map((player) => {
    const targets = activeRosterForPlayer(player.id).map((pokemon) => {
      const legality = controlTokenEffects?.standardCurseTarget?.(state, pokemon, controlTokenEffectOptions())
        || { ok: false, reason: "Curse targeting is unavailable." };
      const species = String(pokemonCommittedSpecies(pokemon) || pokemon.name || "").trim();
      const protectedByCurseImmunity = Boolean(controlTokenEffects?.pokemonHasCurseImmunity?.(state, pokemon, controlTokenEffectOptions()));
      const protectedBySubstitute = pokemonHasActiveStatus(pokemon.id, "substitute-attached");
      return {
        pokemon,
        legality,
        battleTier: pokemonSagaTier(species) || "Unassigned",
        protectionLabel: protectedByCurseImmunity ? "Curse Immune" : protectedBySubstitute ? "Substitute attached" : ""
      };
    });
    return { player, targets };
  }).filter((entry) => entry.targets.length);
}

function liveRefereeStandardCursePlayerCardMarkup(entry, selectedId, actorPlayerId) {
  const legalCount = entry.targets.filter((target) => target.legality.ok).length;
  return `
    <article class="live-referee-wicked-player">
      <header>
        ${liveRefereePlayerAvatarMarkup(entry.player)}
        <div><strong>${escapeHtml(entry.player.name)}</strong><span>${entry.player.id === actorPlayerId ? "Your Active Roster" : "Active Roster"}</span></div>
        <em>${legalCount} legal</em>
      </header>
      <div class="live-referee-wicked-targets" role="radiogroup" aria-label="Choose one Pokemon from ${escapeHtml(entry.player.name)}'s Active Roster">
        ${entry.targets.map(({ pokemon, legality, battleTier, protectionLabel }) => {
          const selected = legality.ok && pokemon.id === selectedId;
          return `
            <label class="${legality.ok ? "" : "unavailable"}${selected ? " selected" : ""}" data-standard-curse-target-row>
              <input type="radio" name="standard-curse-target" value="${escapeHtml(pokemon.id)}" data-standard-curse-target ${selected ? "checked" : ""} ${legality.ok ? "" : "disabled"}>
              <span class="live-referee-wicked-sprite${pokemonSpriteClassSuffix(pokemon)}">${renderPokemonSpriteContent(pokemon)}</span>
              <span class="live-referee-wicked-identity">
                <strong>${escapeHtml(pokemon.name || pokemonCommittedSpecies(pokemon))}</strong>
                <small>Active Roster · Exact ID ${escapeHtml(String(pokemon.id).slice(-8))}</small>
              </span>
              <span class="live-referee-wicked-tier">
                <b>${escapeHtml(battleTier)}</b>
                <small>${escapeHtml(legality.ok ? (protectionLabel || "Species anchor eligible") : legality.reason)}</small>
              </span>
            </label>
          `;
        }).join("")}
      </div>
    </article>
  `;
}

