function persistLiveRefereeGenericEffectDraft(form, { immediate = false } = {}) {
  if (!form?.matches?.("[data-live-referee-effect-form]")) return;
  const draft = liveRefereeEffectDraftFor();
  draft.targetPokemonId = form.querySelector('[data-live-referee-effect-field="targetPokemonId"]')?.value || draft.targetPokemonId || "";
  draft.targetPokemonIds = [...form.querySelectorAll("[data-haze-curse-target]:checked")].map((input) => input.value).filter(Boolean);
  draft.selectedStatusId = form.querySelector('[data-live-referee-effect-field="selectedStatusId"]')?.value || draft.selectedStatusId || "";
  draft.targetPlayerId = form.querySelector('[data-live-referee-effect-field="targetPlayerId"]')?.value || draft.targetPlayerId || "";
  draft.targetText = form.querySelector('[data-live-referee-effect-field="targetText"]')?.value || "";
  draft.notes = form.querySelector('[data-live-referee-effect-field="notes"]')?.value || "";
  draft.resourceDefinitionId = form.querySelector('[data-live-referee-effect-field="resourceDefinitionId"]')?.value || draft.resourceDefinitionId || "";
  draft.choiceKind = form.querySelector('[data-live-referee-effect-field="choiceKind"]')?.value || draft.choiceKind || "";
  draft.inventoryRecordId = form.querySelector('[data-live-referee-effect-field="inventoryRecordId"]')?.value || draft.inventoryRecordId || "";
  draft.moveName = form.querySelector('[data-live-referee-effect-field="moveName"]')?.value || draft.moveName || "";
  state.liveRefereeEffectDraft = draft;
  saveClientUiState({ immediate });
  persistProvisionalDeclarationDraft({ immediate })?.catch((error) => console.warn("Declaration draft save failed.", error));
}

function liveRefereeCurrentEncounterLine(prompt) {
  const session = prompt.resultSession || liveResultSessionForActivity(prompt.pendingEvent);
  if (!session) return "";
  const ownerId = session.resultOwnerPlayerId || session.ownerPlayerId || session.playerId || "";
  const ownerName = livePlayerName(ownerId, "A player");
  const resultName = session.resultDisplayName || session.resultPokemonName || "an encounter";
  return `${ownerName} rolled ${resultName}.`;
}

function liveRefereeSelectedEffectGroup(prompt, selectedPlayerId = liveRefereeControlledPlayerId()) {
  const effectName = state.liveRefereeSelectedEffectName || "";
  const { groups } = liveRefereeAvailableTokenGroups(prompt, selectedPlayerId);
  return groups.find((group) => group.name === effectName || slugify(group.name) === slugify(effectName))
    || liveRefereeTokenInventoryGroups(state.players.find((player) => player.id === selectedPlayerId) || null)
      .find((group) => group.name === effectName || slugify(group.name) === slugify(effectName))
    || null;
}

function liveRefereeCurrentPromptActionLabel(prompt) {
  const activity = prompt?.pendingEvent;
  const step = prompt?.currentPromptStep;
  if (!activity || !step) return "this prompt";
  if (step.kind === "response") return livePromptStepResponseLabel(step.response) || "this response";
  return liveRefereePromptTokenName(activity) || liveRefereeEventTypeLabel(activity, "this event");
}

function liveRefereeEffectHiddenFields(tokenName, metadata = {}) {
  return `
    <input type="hidden" data-live-referee-effect-field="tokenName" value="${escapeHtml(tokenName)}">
    <input type="hidden" data-live-referee-effect-field="timingCategory" value="${escapeHtml(metadata.timingCategory || "")}">
    <input type="hidden" data-live-referee-effect-field="targetType" value="${escapeHtml(metadata.targetType || "")}">
    <input type="hidden" data-live-referee-effect-field="targetScope" value="${escapeHtml(metadata.targetScope || "")}">
  `;
}

function liveRefereeEffectNavigationChoices(tokenName, {
  confirmAttrs = "data-live-referee-effect-submit",
  confirmLabel = "Use Effect",
  confirmDisabled = false,
  backScreen = "tokens"
} = {}) {
  if (currentProvisionalDeclaration()) {
    return [
      liveRefereeChoiceButtonMarkup({ label: "Withdraw Declaration", attrs: "data-provisional-declaration-withdraw" }),
      liveRefereeChoiceButtonMarkup({ label: confirmLabel || `Confirm ${tokenName}`, attrs: confirmAttrs, variant: "primary", disabled: confirmDisabled })
    ];
  }
  return [
    liveRefereeChoiceButtonMarkup({ label: "Back", screen: backScreen }),
    liveRefereeChoiceButtonMarkup({ label: "Cancel", screen: "play" }),
    liveRefereeChoiceButtonMarkup({ label: confirmLabel || `Use ${tokenName}`, attrs: confirmAttrs, variant: "primary", disabled: confirmDisabled })
  ];
}

function liveRefereeEffectTargetScreenMarkup({ prompt, tokenName, metadata, situation, fields = "", submitLabel = "Use Effect", submitDisabled = false, className = "" } = {}) {
  return `
    <section class="live-referee-game-screen live-referee-effect-screen ${className}" data-live-referee-effect-form>
      ${liveRefereeSituationMarkup(situation)}
      ${liveRefereeEffectHiddenFields(tokenName, metadata)}
      ${fields ? `<div class="live-referee-menu-form">${fields}</div>` : ""}
      ${liveRefereeNavActionsMarkup(liveRefereeEffectNavigationChoices(tokenName, {
        confirmLabel: submitLabel,
        confirmDisabled: submitDisabled
      }), { compact: true })}
    </section>
  `;
}

function liveRefereeMoveDeleterTargetScreenMarkup({ prompt, tokenName, metadata, actor } = {}) {
  if (!pokemonBuildDataReady()) {
    ensurePokemonBuildDataLoaded({ renderOnLoad: false }).then(() => render()).catch((error) => console.warn("Move Deleter move data failed to load.", error));
    return liveRefereeEffectTargetScreenMarkup({
      prompt,
      tokenName,
      metadata,
      situation: "Loading the move list.",
      submitLabel: `Confirm ${tokenName}`,
      submitDisabled: true,
      className: "move-deleter-target"
    });
  }
  const draft = liveRefereeEffectDraftFor(tokenName, actor?.id || "");
  const moves = Object.values(teambuilderDataSource().moves || {})
    .map((move) => teambuilderCanonicalMoveName(move?.name || ""))
    .filter((name, index, list) => name && !rivalSagaMoveIsExcluded(name) && list.indexOf(name) === index)
    .sort((left, right) => left.localeCompare(right));
  const listId = `live-referee-moves-${slugify(tokenName) || "move-deleter"}`;
  return liveRefereeEffectTargetScreenMarkup({
    prompt,
    tokenName,
    metadata,
    situation: "Which move will be unavailable during the next Gym?",
    fields: `
      <label class="wide">
        <span>Move</span>
        <input type="search" data-live-referee-effect-field="targetText" value="${escapeHtml(draft.targetText || "")}" list="${escapeHtml(listId)}" placeholder="Search canonical moves" autocomplete="off">
        <datalist id="${escapeHtml(listId)}">${moves.map((name) => `<option value="${escapeHtml(name)}"></option>`).join("")}</datalist>
      </label>
    `,
    submitLabel: `Confirm ${tokenName}`,
    submitDisabled: !moves.length,
    className: "move-deleter-target"
  });
}

function liveRefereeLingeringAromaTargetScreenMarkup({ prompt, tokenName, metadata, actor } = {}) {
  const effects = (controlTokenEffects?.activeExplicitOngoingEffects?.(state, controlTokenEffectOptions()) || [])
    .filter((effect) => controlTokenEffects?.ongoingEffectBenefitsPlayer?.(effect, actor?.id || ""));
  const draft = liveRefereeEffectDraftFor(tokenName, actor?.id || "");
  return liveRefereeEffectTargetScreenMarkup({
    prompt,
    tokenName,
    metadata,
    situation: effects.length ? "Which ongoing effect will Lingering Aroma replace?" : "No ongoing effect is available.",
    fields: effects.length ? `
      <label class="wide">
        <span>Ongoing Effect</span>
        <select data-live-referee-effect-field="targetText">
          <option value="">Choose an ongoing effect</option>
          ${effects.map((effect) => `<option value="${escapeHtml(effect.id)}"${effect.id === draft.targetText ? " selected" : ""}>${escapeHtml(effect.name || effect.type)} - ${escapeHtml(livePlayerName(effect.actorPlayerId, "Table"))}</option>`).join("")}
        </select>
      </label>
    ` : "",
    submitLabel: `Confirm ${tokenName}`,
    submitDisabled: !effects.length,
    className: "lingering-aroma-target"
  });
}

function liveRefereeHazeTargetScreenMarkup({ tokenName, metadata, actor } = {}) {
  const draft = liveRefereeEffectDraftFor(tokenName, actor?.id || "");
  const selected = new Set((draft.targetPokemonIds || []).slice(0, 2));
  const selectedPokemon = (state.pokemonRecords || []).filter((pokemon) => selected.has(pokemon.id));
  const selectedSpecies = new Set(selectedPokemon.map((pokemon) => pokemonRuleKey(pokemonCommittedSpecies(pokemon))));
  const groups = liveRefereeStandardCurseActiveRosterTargets();
  return `
    <section class="live-referee-game-screen live-referee-effect-screen live-referee-wicked-screen" data-live-referee-effect-form data-haze-curse-target-form>
      ${liveRefereeSituationMarkup("Choose two different Pokemon names.")}
      ${liveRefereeEffectHiddenFields(tokenName, metadata)}
      <div class="live-referee-haze-selected" aria-label="Selected Haze Pokemon names">
        <strong>Selected names</strong>
        ${selectedPokemon.map((pokemon) => `<span data-haze-selected-species="${escapeHtml(pokemonRuleKey(pokemonCommittedSpecies(pokemon)))}">
          <i class="live-referee-wicked-sprite${pokemonSpriteClassSuffix(pokemon)}">${renderPokemonSpriteContent(pokemon)}</i>
          ${escapeHtml(pokemonCommittedSpecies(pokemon))}
        </span>`).join("")}
        ${Array.from({ length: Math.max(0, 2 - selectedPokemon.length) }, () => "<span class=\"empty\">Choose a name</span>").join("")}
      </div>
      <div class="live-referee-wicked-grid">
        ${groups.map((entry) => `
          <article class="live-referee-wicked-player">
            <header>${liveRefereePlayerAvatarMarkup(entry.player)}<div><strong>${escapeHtml(entry.player.name)}</strong><span>Active Roster</span></div></header>
            <div class="live-referee-wicked-targets" aria-label="Choose Haze species anchors">
              ${entry.targets.map(({ pokemon, legality, battleTier }) => {
                const checked = selected.has(pokemon.id);
                const speciesKey = pokemonRuleKey(pokemonCommittedSpecies(pokemon));
                const duplicateSpecies = selectedSpecies.has(speciesKey) && !checked;
                const disabled = !legality.ok || duplicateSpecies || (selected.size >= 2 && !checked);
                return `<label class="${disabled ? "unavailable" : ""}${checked ? " selected" : ""}" data-haze-curse-target-row>
                  <input type="checkbox" value="${escapeHtml(pokemon.id)}" data-haze-curse-target data-species-key="${escapeHtml(speciesKey)}" ${checked ? "checked" : ""} ${disabled ? "disabled" : ""}>
                  <span class="live-referee-wicked-sprite${pokemonSpriteClassSuffix(pokemon)}">${renderPokemonSpriteContent(pokemon)}</span>
                  <span class="live-referee-wicked-identity"><strong>${escapeHtml(pokemon.name)}</strong><small>Exact ID ${escapeHtml(String(pokemon.id).slice(-8))}</small></span>
                  <span class="live-referee-wicked-tier"><b>${escapeHtml(battleTier)}</b><small>${duplicateSpecies ? "Species already selected" : legality.ok ? "Species anchor" : escapeHtml(legality.reason)}</small></span>
                </label>`;
              }).join("")}
            </div>
          </article>`).join("")}
      </div>
      <div class="live-referee-wicked-confirmation">
        <strong data-haze-selection-summary>${selected.size} of 2 names selected</strong>
        ${liveRefereeNavActionsMarkup(liveRefereeEffectNavigationChoices(tokenName, { confirmLabel: `Confirm ${tokenName}`, confirmAttrs: "data-live-referee-effect-submit data-haze-confirm", confirmDisabled: selected.size !== 2 }), { compact: true })}
      </div>
    </section>`;
}

function liveRefereeKnockOffChoices(targetPokemonId = "") {
  const pokemon = findPokemonRecord(targetPokemonId);
  const owner = pokemon ? state.players.find((player) => player.id === pokemon.trainerId) : null;
  const slot = pokemon ? (activeTeamBuildDraftForPlayer(pokemon.trainerId)?.slots || []).find((entry) => entry.pokemonRecordId === pokemon.id) : null;
  if (!pokemon || !owner || !slot) return [];
  const choices = [];
  const held = (owner.inventory || []).find((item) => item.id === slot.itemInventoryItemId);
  if (held && !controlTokenEffects?.isMasterBallResource?.(held)) choices.push({ kind: "item", inventoryRecordId: held.id, moveName: "", label: `Held Item - ${held.name}` });
  (slot.moveProvenance || []).forEach((provenance, index) => {
    if (provenance?.source !== "tm" || !provenance.inventoryRecordId) return;
    const resource = (owner.inventory || []).find((item) => item.id === provenance.inventoryRecordId);
    const moveName = slot.moves?.[index] || provenance.moveName;
    if (resource && moveName) choices.push({ kind: "tm", inventoryRecordId: resource.id, moveName, label: `TM Move - ${moveName}` });
  });
  return choices;
}

function liveRefereeKnockOffTargetScreenMarkup({ tokenName, metadata, actor } = {}) {
  const draft = liveRefereeEffectDraftFor(tokenName, actor?.id || "");
  const choices = liveRefereeKnockOffChoices(draft.targetPokemonId);
  const selectedKey = `${draft.choiceKind}|${draft.inventoryRecordId}|${draft.moveName}`;
  return liveRefereeEffectTargetScreenMarkup({
    tokenName, metadata,
    situation: draft.targetPokemonId ? "What will Knock Off remove?" : "Choose one exact Active Roster Pokemon.",
    fields: `
      <label class="wide"><span>Active Roster Pokemon</span><select data-live-referee-effect-field="targetPokemonId" data-knock-off-target>${liveRefereeRosterPokemonOptions(draft.targetPokemonId, { actorPlayerId: actor?.id || "", targetControllerRelation: "anyPlayer", activeOnly: true })}</select></label>
      ${draft.targetPokemonId ? `<label class="wide"><span>Held Item or TM move</span><select data-knock-off-choice><option value="">Choose exact record</option>${choices.map((choice) => {
        const key = `${choice.kind}|${choice.inventoryRecordId}|${choice.moveName}`;
        return `<option value="${escapeHtml(key)}" ${key === selectedKey ? "selected" : ""}>${escapeHtml(choice.label)}</option>`;
      }).join("")}</select></label>` : ""}
      <input type="hidden" data-live-referee-effect-field="choiceKind" value="${escapeHtml(draft.choiceKind || "")}">
      <input type="hidden" data-live-referee-effect-field="inventoryRecordId" value="${escapeHtml(draft.inventoryRecordId || "")}">
      <input type="hidden" data-live-referee-effect-field="moveName" value="${escapeHtml(draft.moveName || "")}">
    `,
    submitLabel: `Confirm ${tokenName}`,
    submitDisabled: !draft.targetPokemonId || !choices.length || !draft.inventoryRecordId,
    className: "knock-off-target"
  });
}

function liveRefereeDittoTargetScreenMarkup({ tokenName, metadata, actor } = {}) {
  const draft = liveRefereeEffectDraftFor(tokenName, actor?.id || "");
  const options = (globalThis.rivalSagaTokenEffectContract?.list || []).filter((definition) => (
    definition.id !== "ditto-token" && globalThis.rivalSagaTokenEffectContract.activationUsabilityFor(definition).ok
    && !/ticket/i.test(definition.family || definition.name || "")
  )).sort((a, b) => a.name.localeCompare(b.name));
  return liveRefereeEffectTargetScreenMarkup({
    tokenName, metadata,
    situation: "What Token will Ditto become?",
    fields: `<label class="wide"><span>Token</span><select data-live-referee-effect-field="resourceDefinitionId"><option value="">Choose a Token</option>${options.map((definition) => `<option value="${escapeHtml(definition.id)}" ${definition.id === draft.resourceDefinitionId ? "selected" : ""}>${escapeHtml(definition.name)} - ${escapeHtml(definition.family)}</option>`).join("")}</select></label>`,
    submitLabel: "Transform Ditto",
    submitDisabled: !options.length,
    className: "ditto-target"
  });
}

function liveRefereeFollowMeTargetScreenMarkup({ prompt, tokenName, metadata, actor } = {}) {
  const step = prompt?.currentPromptStep;
  const plan = followMeResponseResolutionPlan(prompt?.pendingEvent, step, actor?.id || "", { previewOnly: true });
  if (!plan.ok) {
    return liveRefereeEffectTargetScreenMarkup({
      prompt, tokenName, metadata,
      situation: plan.reason,
      submitLabel: `Use ${tokenName}`,
      submitDisabled: true,
      className: "follow-me-target"
    });
  }
  if (!plan.requiresPokemonChoice) {
    return liveRefereeEffectTargetScreenMarkup({
      prompt, tokenName, metadata,
      situation: `Redirect ${liveRefereeCurrentPromptActionLabel(prompt)} to ${actor?.name || "you"}?`,
      fields: `<input type="hidden" data-live-referee-effect-field="targetPlayerId" value="${escapeHtml(actor?.id || "")}">`,
      submitLabel: `Use ${tokenName}`,
      className: "follow-me-target"
    });
  }
  const draft = liveRefereeEffectDraftFor(tokenName, actor?.id || "");
  return liveRefereeEffectTargetScreenMarkup({
    prompt, tokenName, metadata,
    situation: `Which of ${actor?.name || "your"}'s Pokemon becomes the target?`,
    fields: `
      <label class="wide">
        <span>Corresponding Active Roster Pokemon</span>
        <select data-live-referee-effect-field="targetPokemonId">${liveRefereeRosterPokemonOptions(draft.targetPokemonId || "", {
          actorPlayerId: actor?.id || "",
          targetControllerRelation: "self",
          selfOnly: true,
          activeOnly: true
        })}</select>
      </label>
    `,
    submitLabel: `Use ${tokenName}`,
    className: "follow-me-target"
  });
}

function afterYouControlChoiceMarkup(sourceMetadata, actor, draft) {
  const targetType = normalizeEffectTargetType(sourceMetadata.targetType);
  const targetScope = normalizeEffectTargetScope(sourceMetadata.targetScope);
  if (targetType === EFFECT_TARGET_TYPES.POKEMON && targetScope === EFFECT_TARGET_SCOPES.SPECIES) {
    const listId = `after-you-species-${slugify(sourceMetadata.id)}`;
    return `
      <label class="wide">
        <span>Fresh Pokemon Species</span>
        <input type="text" data-live-referee-effect-field="targetText" value="${escapeHtml(draft.targetText || "")}" list="${escapeHtml(listId)}" placeholder="Choose a species">
        ${liveRefereeSpeciesDatalistMarkup(listId, liveRefereeControlSpeciesOptions(sourceMetadata.name))}
      </label>`;
  }
  if (targetType === EFFECT_TARGET_TYPES.POKEMON && targetScope === EFFECT_TARGET_SCOPES.ROSTER_INSTANCE) {
    return `
      <label class="wide">
        <span>Fresh Pokemon Target</span>
        <select data-live-referee-effect-field="targetPokemonId">${liveRefereeRosterPokemonOptions(draft.targetPokemonId || "", {
          actorPlayerId: actor?.id || "",
          targetControllerRelation: sourceMetadata.targetControllerRelation,
          selfOnly: sourceMetadata.selfOnly,
          otherPlayerOnly: sourceMetadata.otherPlayerOnly,
          activeOnly: Boolean(sourceMetadata.mechanicContract?.activeRosterRequired)
        })}</select>
      </label>`;
  }
  if (targetType === EFFECT_TARGET_TYPES.PLAYER && targetScope === EFFECT_TARGET_SCOPES.SINGLE_PLAYER) {
    const options = (state.players || []).filter((player) => playerMatchesEffectTargetRelation(player.id, actor?.id || "", sourceMetadata));
    return `
      <label class="wide">
        <span>Fresh Player Target</span>
        <select data-live-referee-effect-field="targetPlayerId">
          <option value="">Choose player</option>
          ${options.map((player) => `<option value="${escapeHtml(player.id)}"${player.id === draft.targetPlayerId ? " selected" : ""}>${escapeHtml(player.name)}</option>`).join("")}
        </select>
      </label>`;
  }
  return "";
}

function liveRefereeAfterYouTargetScreenMarkup({ prompt, tokenName, metadata, actor } = {}) {
  const step = prompt?.currentPromptStep;
  const plan = afterYouResponseResolutionPlan(prompt?.pendingEvent, step, actor?.id || "", { previewOnly: true });
  if (!plan.ok) {
    return liveRefereeEffectTargetScreenMarkup({
      prompt, tokenName, metadata,
      situation: plan.reason,
      submitLabel: `Use ${tokenName}`,
      submitDisabled: true,
      className: "after-you-target"
    });
  }
  if (["afterYouImmunity", "afterYouProtection"].includes(plan.kind)) {
    return liveRefereeEffectTargetScreenMarkup({
      prompt,
      tokenName,
      metadata: plan.sourceMetadata,
      situation: plan.kind === "afterYouImmunity"
        ? "Copy Immunity to negate the original Immunity?"
        : `Copy ${plan.sourceDefinition.name} before the original resolves?`,
      submitLabel: `Copy ${plan.sourceDefinition.name}`,
      className: "after-you-target"
    });
  }
  const draft = liveRefereeEffectDraftFor(tokenName, actor?.id || "");
  return liveRefereeEffectTargetScreenMarkup({
    prompt,
    tokenName,
    metadata: plan.sourceMetadata,
    situation: `Choose fresh targets for copied ${plan.sourceDefinition.name}.`,
    fields: afterYouControlChoiceMarkup(plan.sourceMetadata, actor, draft),
    submitLabel: `Copy ${plan.sourceDefinition.name}`,
    className: "after-you-target"
  });
}

function liveRefereeEffectUseScreenMarkup(prompt, selectedPlayerId = liveRefereeControlledPlayerId()) {
  const actor = state.players.find((player) => player.id === selectedPlayerId) || null;
  const group = liveRefereeSelectedEffectGroup(prompt, selectedPlayerId);
  const tokenName = group?.name || state.liveRefereeSelectedEffectName || "";
  const metadata = group?.metadata || tokenEffectMetadataByName(tokenName);
  const effectDraft = liveRefereeEffectDraftFor(tokenName, selectedPlayerId);
  const speciesListId = `live-referee-species-${slugify(tokenName) || "token"}`;
  const targetType = normalizeEffectTargetType(metadata.targetType);
  const targetScope = normalizeEffectTargetScope(metadata.targetScope);
  if (!tokenName) {
    return liveRefereeGameScreenMarkup({
      className: "live-referee-effect-screen",
      situation: "Choose a token first.",
      choices: liveRefereeNavActionsMarkup([
        liveRefereeChoiceButtonMarkup({ label: "Back", screen: "tokens" })
      ])
    });
  }
  if (metadata.id === "follow-me") {
    return liveRefereeFollowMeTargetScreenMarkup({ prompt, tokenName, metadata, actor });
  }
  if (metadata.id === "after-you") {
    return liveRefereeAfterYouTargetScreenMarkup({ prompt, tokenName, metadata, actor });
  }
  if (targetType === EFFECT_TARGET_TYPES.CURRENT_PROMPT
    || (targetScope === EFFECT_TARGET_SCOPES.CURRENT_PROMPT && metadata.timingCategory === TOKEN_TIMING_CATEGORIES.PROTECTION)) {
    const promptLabel = liveRefereeCurrentPromptActionLabel(prompt);
    return liveRefereeEffectTargetScreenMarkup({
      prompt,
      tokenName,
      metadata,
      situation: `Use ${tokenName} against ${promptLabel}?`,
      submitLabel: `Use ${tokenName}`,
      submitDisabled: !prompt.pendingEvent,
      className: "current-prompt"
    });
  }
  if (targetType === EFFECT_TARGET_TYPES.ENCOUNTER_RESULT) {
    const encounterLine = liveRefereeCurrentEncounterLine(prompt);
    return liveRefereeEffectTargetScreenMarkup({
      prompt,
      tokenName,
      metadata,
      situation: encounterLine ? (slugify(tokenName).includes("reroll") ? "Reroll this encounter?" : `Use ${tokenName} on this encounter?`) : "No encounter result is waiting.",
      fields: encounterLine ? `<p class="live-referee-target-summary">${escapeHtml(encounterLine)}</p>` : "",
      submitLabel: slugify(tokenName).includes("reroll") ? "Reroll" : `Use ${tokenName}`,
      submitDisabled: !encounterLine,
      className: "encounter-target"
    });
  }
  if (metadata.id === "incinerate") {
    return liveRefereeIncinerateTargetScreenMarkup({ prompt, tokenName, metadata, actor });
  }
  if (metadata.id === "wicked-blow") {
    return liveRefereeWickedBlowTargetScreenMarkup({ prompt, tokenName, metadata, actor });
  }
  if (metadata.id === "move-deleter") {
    return liveRefereeMoveDeleterTargetScreenMarkup({ prompt, tokenName, metadata, actor });
  }
  if (metadata.id === "lingering-aroma") {
    return liveRefereeLingeringAromaTargetScreenMarkup({ prompt, tokenName, metadata, actor });
  }
  if (metadata.id === "haze-curse") {
    return liveRefereeHazeTargetScreenMarkup({ prompt, tokenName, metadata, actor });
  }
  if (metadata.id === "knock-off-curse") {
    return liveRefereeKnockOffTargetScreenMarkup({ prompt, tokenName, metadata, actor });
  }
  if (metadata.id === "ditto-token") {
    return liveRefereeDittoTargetScreenMarkup({ prompt, tokenName, metadata, actor });
  }
  if (metadata.id === "devolve-token") {
    return liveRefereeStandardCurseTargetScreenMarkup({ prompt, tokenName, metadata, actor });
  }
  if (isStandardCurseTokenId(metadata.id)) {
    return liveRefereeStandardCurseTargetScreenMarkup({ prompt, tokenName, metadata, actor });
  }
  if (targetType === EFFECT_TARGET_TYPES.POKEMON) {
    if (targetScope === EFFECT_TARGET_SCOPES.SPECIES) {
      const speciesOptions = liveRefereeControlSpeciesOptions(tokenName);
      const isUnban = slugify(tokenName) === "unban";
      const unbanStatuses = isUnban
        ? (controlTokenEffects?.activeStatuses?.(state, controlTokenEffectOptions(), (status) => ["ban", "restrict"].includes(status.type)) || [])
        : [];
      const selectedUnbanStatus = unbanStatuses.find((status) => status.id === effectDraft.selectedStatusId) || null;
      return liveRefereeEffectTargetScreenMarkup({
        prompt,
        tokenName,
        metadata,
        situation: isUnban ? "Remove which active Ban or Restrict?" : `Use ${tokenName} on which Pokemon species?`,
        fields: isUnban ? `
          <label class="wide">
            <span>Exact Active Ban or Restrict</span>
            <select data-live-referee-effect-field="selectedStatusId" ${!unbanStatuses.length ? "disabled" : ""}>
              <option value="">Choose an exact status</option>
              ${unbanStatuses.map((status) => `<option value="${escapeHtml(status.id)}" data-species-name="${escapeHtml(status.targetPokemonName || status.speciesId || "")}"${status.id === effectDraft.selectedStatusId ? " selected" : ""}>${escapeHtml(status.targetPokemonName || status.speciesId || "Pokemon")} — ${status.type === "ban" ? "Ban" : "Restrict"} — ${escapeHtml(String(status.id).slice(-8))}</option>`).join("")}
            </select>
            <input type="hidden" data-live-referee-effect-field="targetText" value="${escapeHtml(selectedUnbanStatus?.targetPokemonName || selectedUnbanStatus?.speciesId || effectDraft.targetText || "")}">
          </label>
        ` : `
          <label class="wide">
            <span>Pokemon Species / Name</span>
            <input type="text" data-live-referee-effect-field="targetText" value="${escapeHtml(effectDraft.targetText || "")}" list="${escapeHtml(speciesListId)}" placeholder="Abra, Armarouge, Sceptile">
            ${liveRefereeSpeciesDatalistMarkup(speciesListId, speciesOptions)}
          </label>
        `,
        submitLabel: `Use ${tokenName}`,
        submitDisabled: isUnban && (!unbanStatuses.length || !effectDraft.selectedStatusId),
        className: "species-target"
      });
    }
    if (targetScope === EFFECT_TARGET_SCOPES.ROSTER_INSTANCE) {
      const targetsSelf = metadata.selfOnly || metadata.targetControllerRelation === "self";
      const ownerLabel = actor?.name ? `${actor.name}'s` : "your";
      const targetSituation = targetsSelf
        ? `Use ${tokenName} on which of ${ownerLabel} Pokemon?`
        : `Use ${tokenName} on which rostered Pokemon?`;
      return liveRefereeEffectTargetScreenMarkup({
        prompt,
        tokenName,
        metadata,
        situation: targetSituation,
        fields: `
          <label class="wide">
            <span>${targetsSelf ? "Your Pokemon" : "Rostered Pokemon"}</span>
            <select data-live-referee-effect-field="targetPokemonId">${liveRefereeRosterPokemonOptions(effectDraft.targetPokemonId || "", {
              actorPlayerId: actor?.id || "",
              targetControllerRelation: metadata.targetControllerRelation,
              selfOnly: metadata.selfOnly,
              otherPlayerOnly: metadata.otherPlayerOnly,
              activeOnly: Boolean(metadata.mechanicContract?.activeRosterRequired || ["arena-trap", "extra-ban-token", "clear-smog"].includes(metadata.id)),
              eligibility: metadata.id === "arena-trap"
                ? (pokemon) => arenaTrapBringLegalityForPokemon(pokemon, actor?.id || "")
                : null
            })}</select>
          </label>
        `,
        submitLabel: `Use ${tokenName}`,
        className: "roster-target"
      });
    }
  }
  if (targetType === EFFECT_TARGET_TYPES.PLAYER && targetScope === EFFECT_TARGET_SCOPES.SINGLE_PLAYER) {
    if (metadata.selfOnly) {
      return liveRefereeEffectTargetScreenMarkup({
        prompt,
        tokenName,
        metadata,
        situation: `Use ${tokenName} for ${actor?.name || "yourself"}?`,
        fields: `<input type="hidden" data-live-referee-effect-field="targetPlayerId" value="${escapeHtml(actor?.id || "")}">`,
        submitLabel: `Use ${tokenName}`,
        className: "player-target"
      });
    }
    return liveRefereeEffectTargetScreenMarkup({
      prompt,
      tokenName,
      metadata,
      situation: `Use ${tokenName} on which player?`,
      fields: `
        <label class="wide">
          <span>Target Player</span>
          <select data-live-referee-effect-field="targetPlayerId">${playerOptionsMarkup(effectDraft.targetPlayerId || "", { includeBlank: true, blankLabel: "Choose player" })}</select>
        </label>
      `,
      submitLabel: `Use ${tokenName}`,
      className: "player-target"
    });
  }
  if (targetType === EFFECT_TARGET_TYPES.TABLE
    || targetType === EFFECT_TARGET_TYPES.NONE
    || [EFFECT_TARGET_SCOPES.ALL_PLAYERS, EFFECT_TARGET_SCOPES.TABLE_WIDE, EFFECT_TARGET_SCOPES.NONE].includes(targetScope)) {
    return liveRefereeEffectTargetScreenMarkup({
      prompt,
      tokenName,
      metadata,
      situation: `Use ${tokenName} for the table?`,
      submitLabel: `Use ${tokenName}`,
      className: "table-target"
    });
  }
  return liveRefereeEffectTargetScreenMarkup({
    prompt,
    tokenName,
    metadata,
    situation: `Record ${tokenName}.`,
    fields: `
        <label class="wide">
          <span>Manual Target / Note</span>
          <input type="text" data-live-referee-effect-field="targetText" value="${escapeHtml(effectDraft.targetText || "")}" placeholder="Pokemon, player, resource, or table note">
        </label>
        <label class="wide">
          <span>Note</span>
          <input type="text" data-live-referee-effect-field="notes" value="${escapeHtml(effectDraft.notes || "")}" placeholder="Short table note">
        </label>
    `,
    submitLabel: `Record ${tokenName}`,
    className: "manual-target"
  });
}

function liveRefereeTrimSentence(value = "") {
  return String(value || "").trim().replace(/[.!?]+$/g, "");
}

function liveRefereePossessive(name = "A player") {
  const clean = String(name || "A player").trim() || "A player";
  return `${clean}${/s$/i.test(clean) ? "'" : "'s"}`;
}

function liveRefereeTitleCase(value = "") {
  return String(value || "")
    .replace(/[-_]+/g, " ")
    .replace(/\s+/g, " ")
    .trim()
    .replace(/\b\w/g, (char) => char.toUpperCase());
}

function liveRefereeEventTypeLabel(activity, fallback = "Event") {
  const category = liveActivityTimingCategory(activity);
  if (category) return tokenTimingCategoryLabel(category);
  return liveRefereeTitleCase(activity?.payload?.eventType || activity?.sourceType || activity?.type || fallback || "Event") || "Event";
}

function liveRefereeFirstPayloadValue(activity, keys = []) {
  return keys
    .map((key) => String(activity?.payload?.[key] || activity?.[key] || "").trim())
    .find(Boolean) || "";
}

function liveRefereeParsedUsedAction(activity) {
  const texts = [activity?.title, activity?.message]
    .map((part) => String(part || "").trim())
    .filter(Boolean);
  for (const text of texts) {
    const match = text.match(/\bused\s+(.+?)(?:\s+(?:on|targeting|against|for)\s+|[.!?]|$)/i);
    if (match?.[1]) return match[1].trim();
  }
  return "";
}

function liveRefereeParsedTarget(activity) {
  const texts = [activity?.title, activity?.message]
    .map((part) => String(part || "").trim())
    .filter(Boolean);
  for (const text of texts) {
    const match = text.match(/\b(?:on|targeting|against|for)\s+([^.!?]+)/i);
    if (match?.[1]) return match[1].trim();
  }
  return "";
}

function liveRefereePromptTokenName(activity) {
  const direct = liveRefereeFirstPayloadValue(activity, [
    "tokenName",
    "effectName",
    "actionName",
    "abilityName",
    "moveName",
    "responseName",
    "resultName"
  ]);
  if (direct) return direct;
  const parsed = liveRefereeParsedUsedAction(activity);
  if (parsed) return parsed;
  const title = String(activity?.title || "").trim();
  if (title && title.length <= 42 && !/\b(used|rolled|pending|window|event|response)\b/i.test(title)) return title;
  return "";
}

function liveRefereeTargetName(activity, fallback = "Table") {
  const targetType = normalizeEffectTargetType(activity?.payload?.targetType);
  const targetScope = normalizeEffectTargetScope(activity?.payload?.targetScope);
  if (targetType === EFFECT_TARGET_TYPES.CURRENT_PROMPT || targetScope === EFFECT_TARGET_SCOPES.CURRENT_PROMPT) return "";
  if (targetType === EFFECT_TARGET_TYPES.POKEMON && targetScope === EFFECT_TARGET_SCOPES.ROSTER_INSTANCE) {
    const ownerName = activity?.payload?.targetPlayerName || livePlayerName(activity?.targetPlayerId, "");
    const pokemonName = activity?.payload?.targetPokemonName || activity?.payload?.targetText || "";
    if (ownerName && pokemonName) return `${liveRefereePossessive(ownerName)} ${pokemonName}`;
    if (pokemonName) return pokemonName;
  }
  if (targetType === EFFECT_TARGET_TYPES.POKEMON && targetScope === EFFECT_TARGET_SCOPES.SPECIES) {
    const speciesName = activity?.payload?.targetText || activity?.payload?.targetPokemonName || "";
    if (speciesName) return speciesName;
  }
  const direct = liveRefereeFirstPayloadValue(activity, [
    "targetText",
    "targetPokemonName",
    "targetPokemon",
    "pokemonName",
    "targetName",
    "targetPlayerName",
    "targetResource",
    "target"
  ]);
  if (direct) return direct;
  const parsed = liveRefereeParsedTarget(activity);
  if (parsed) return parsed;
  return activity?.targetPlayerId ? livePlayerName(activity.targetPlayerId, fallback) : fallback;
}

function liveRefereePromptSubject(activity, step) {
  if (step?.kind === "response") {
    const responsePlayer = livePlayerName(step.response?.playerId, "A player");
    return `${liveRefereePossessive(responsePlayer)} ${livePromptStepResponseLabel(step.response)}`;
  }
  const actorName = livePlayerName(activity?.actorPlayerId || activity?.targetPlayerId, "A player");
  const tokenName = liveRefereePromptTokenName(activity);
  if (tokenName) return `${liveRefereePossessive(actorName)} ${tokenName}`;
  return activity?.payload?.resultName
    || activity?.title
    || liveRefereeEventTypeLabel(activity, "Original Event");
}

function liveRefereeRootPromptSentence(activity, prompt) {
  if (!activity) return prompt?.body || "No event is pending.";
  const actorName = livePlayerName(activity.actorPlayerId || activity.targetPlayerId, "A player");
  const tokenName = liveRefereePromptTokenName(activity);
  const targetName = liveRefereeTargetName(activity, "");
  if (tokenName) return `${actorName} used ${tokenName}${targetName ? ` on ${targetName}` : ""}.`;
  if (prompt?.resultName) return `${actorName} rolled ${prompt.resultName}${prompt.sourceLabel ? ` from ${prompt.sourceLabel}` : ""}.`;
  const text = livePromptStepText(activity, interactionRootPromptStep(activity));
  return `${liveRefereeTrimSentence(text)}.`;
}

function liveRefereePromptStepLabel(activity, step, { short = false } = {}) {
  if (!step || step.kind === "event") {
    return liveRefereeTrimSentence(liveRefereeRootPromptSentence(activity, {}));
  }
  return livePromptStepText(activity, step, { short });
}

function liveRefereeWhatHappenedText(prompt) {
  const activity = prompt.pendingEvent;
  const step = prompt.currentPromptStep;
  if (!activity || !step) return prompt.body || liveHostNextStepText(prompt);
  if (step.kind === "response") {
    const currentText = liveRefereeTrimSentence(livePromptStepText(activity, step, { short: true }));
    const parentStep = prompt.respondingToPromptStep || parentInteractionPromptStep(activity, step);
    const parentText = liveRefereeTrimSentence(liveRefereePromptSubject(activity, parentStep));
    return `${currentText} in response to ${parentText || "the previous prompt"}.`;
  }
  return liveRefereeRootPromptSentence(activity, prompt);
}

function liveRefereeRespondingToText(prompt) {
  const activity = prompt.pendingEvent;
  const step = prompt.currentPromptStep;
  if (!activity || step?.kind !== "response") return "";
  const parentStep = prompt.respondingToPromptStep || parentInteractionPromptStep(activity, step);
  if (!parentStep) return "";
  return parentStep.kind === "event"
    ? liveRefereeRootPromptSentence(activity, prompt)
    : `${liveRefereeTrimSentence(livePromptStepText(activity, parentStep))}.`;
}

function liveRefereeSupportMarkup(prompt, { actorName, targetName, eventType, effectStatus } = {}) {
  if (!prompt.pendingEvent) return "";
  const respondingTo = prompt.currentPromptStep?.kind === "response"
    ? liveRefereePromptStepLabel(prompt.pendingEvent, prompt.respondingToPromptStep || parentInteractionPromptStep(prompt.pendingEvent, prompt.currentPromptStep), { short: true })
    : "Original Event";
  const rows = [
    ["Actor", actorName || "Table"],
    ["Target", targetName || "Table"],
    ["Effect", effectStatus || "Manual Required"],
    ["Event Type", eventType || "Event"],
    ["Responding To", respondingTo || "Original Event"]
  ];
  return `
    <div class="live-referee-support-row" aria-label="Prompt details">
      ${rows.map(([label, value]) => `<span><small>${escapeHtml(label)}</small><strong>${escapeHtml(value)}</strong></span>`).join("")}
    </div>
  `;
}

function liveRefereeMainSupportText(prompt, effectStatus, respondingToText = "") {
  if (!prompt.pendingEvent) return prompt.body || liveHostNextStepText(prompt);
  if (respondingToText) return `Responding to: ${respondingToText}`;
  return `Effect application: ${effectStatus}.`;
}

function liveRefereeWaitingListMarkup(prompt) {
  const waitingIds = prompt.waitingOnPlayerIds || [];
  const label = prompt.pendingEvent ? "Waiting on" : "Current turn";
  if (!prompt.pendingEvent) {
    const actorId = prompt.currentActorPlayerId || liveRefereeControlledPlayerId(prompt);
    return `
      <section class="live-referee-waiting-summary calm">
        <span>${label}</span>
        <strong>${escapeHtml(livePlayerName(actorId, "Table"))}</strong>
      </section>
    `;
  }
  if (!waitingIds.length) {
    return `
      <section class="live-referee-waiting-summary ready">
        <span>${label}</span>
        <strong>Ready to finalize</strong>
      </section>
    `;
  }
  const names = waitingIds.map((playerId) => livePlayerName(playerId, playerId)).filter(Boolean);
  return `
    <section class="live-referee-waiting-summary">
      <span>${label}</span>
      <strong>${escapeHtml(names.join(", "))}</strong>
    </section>
  `;
}

function renderLiveRefereePromptChain(prompt) {
  const activity = prompt.pendingEvent;
  const chain = prompt.promptChain || [];
  const currentStep = prompt.currentPromptStep;
  if (!activity || !chain.length || !currentStep) return "";
  return `
    <section class="live-referee-chain-panel" aria-label="Prompt Chain">
      <span>Prompt Chain</span>
      <div class="live-referee-chain-list">
        ${chain.map((step, index) => {
          const resolution = interactionPromptResolution(activity, step.id);
          const isCurrent = step.id === currentStep.id;
          const statusLabel = isCurrent ? "CURRENT" : resolution.status === "negated" ? "NEGATED" : resolution.status === "canceled" ? "CANCELED / REFUNDED" : resolution.status === "resolved" ? "RESOLVED" : "";
          return `
            <span class="${isCurrent ? "current" : resolution.status}">
              <em>${index + 1}</em>
              <strong>${escapeHtml(liveRefereePromptStepLabel(activity, step, { short: true }))}</strong>
              ${statusLabel ? `<small>${statusLabel}</small>` : ""}
            </span>
          `;
        }).join("")}
      </div>
    </section>
  `;
}

function renderLiveRefereeResponder(prompt, responderId) {
  if (!prompt.pendingEvent) return "";
  const unlocked = demoControlsUnlocked();
  const responderName = livePlayerName(responderId, "Table");
  const canAnswer = Boolean((prompt.waitingOnPlayerIds || []).includes(responderId)
    && playerCanRespondToActivity(prompt.pendingEvent, responderId));
  if (!(prompt.waitingOnPlayerIds || []).length) {
    return `
      <section class="live-referee-responder-line ready">
        <strong>Everyone has answered.</strong>
        <span>Finalize when the table is ready.</span>
      </section>
    `;
  }
  return `
    <section class="live-referee-responder-line${unlocked ? " testing" : ""}${canAnswer ? "" : " blocked"}">
      <div>
        <span class="live-referee-responder-label">Player Acting Now</span>
        ${unlocked ? `<span class="live-referee-mode-pill">Demo Controls Unlocked</span>` : ""}
      </div>
      <strong>${escapeHtml(canAnswer ? `${responderName}, choose a response.` : `${responderName} is selected.`)}</strong>
      <span>${escapeHtml(canAnswer
        ? (unlocked ? "Demo mode ignores account links. Switch trainer profile to test another responder." : "Choose one response option below.")
        : `Waiting on ${livePlayerNames(prompt.waitingOnPlayerIds)}. Switch trainer profile if you want to answer as one of them.`)}</span>
    </section>
  `;
}

function liveRefereeDetailsNames(ids = [], fallback = "None") {
  const names = ids.map((playerId) => livePlayerName(playerId, playerId)).filter(Boolean);
  return names.length ? names.join(", ") : fallback;
}

function liveRefereeDebugMarkup(prompt) {
  const activity = prompt.pendingEvent;
  if (!activity) return "";
  const rows = [
    ["Root Prompt", interactionRootPromptId(activity)],
    ["Current Prompt", prompt.currentPromptId || currentInteractionPromptStep(activity).id],
    ["Parent Prompt", prompt.respondingToPromptStep?.id || "Original Event"],
    ["Eligible", liveRefereeDetailsNames(prompt.requiredPlayerIds)],
    ["Responded", liveRefereeDetailsNames(prompt.respondedPlayerIds)],
    ["No Response", liveRefereeDetailsNames(prompt.passedPlayerIds)],
    ["Open Trades", String(activityTransactionRecords(activity).length)],
    ["Effect Application", effectApplicationLabel(activityEffectApplication(activity))]
  ];
  return `
    <section class="live-referee-detail-block">
      <span>Prompt Debug</span>
      <div class="live-referee-debug-grid">
        ${rows.map(([label, value]) => `<small><em>${escapeHtml(label)}</em><strong>${escapeHtml(value)}</strong></small>`).join("")}
      </div>
    </section>
  `;
}

function renderLiveRefereeDetails(prompt, { actorName, targetName, eventType, effectStatus } = {}) {
  if (!prompt.pendingEvent) return "";
  const activity = prompt.pendingEvent;
  return `
    <details class="live-referee-details">
      <summary>Show Details</summary>
      <div class="live-referee-detail-stack">
        ${renderLiveRefereePromptChain(prompt)}
        <section class="live-referee-detail-block">
          <span>Event Details</span>
          ${liveRefereeSupportMarkup(prompt, { actorName, targetName, eventType, effectStatus })}
        </section>
        <section class="live-referee-detail-block">
          <span>Player Status</span>
          ${renderLiveRefereeStatusRow(prompt)}
        </section>
        <section class="live-referee-detail-block">
          <span>Responses Recorded</span>
          ${responseHistoryMarkup(activity)}
        </section>
        <section class="live-referee-detail-block">
          <span>Token Uses</span>
          ${tokenConsumptionHistoryMarkup(activity)}
        </section>
        <section class="live-referee-detail-block">
          <span>Transactions Recorded</span>
          ${transactionHistoryMarkup(activity)}
        </section>
        ${liveRefereeDebugMarkup(prompt)}
      </div>
    </details>
  `;
}

