function openObjectActionMenu({ event, player, effect, canRemove = false, removeType = "" }) {
  activePokemonActionId = null;
  objectActionDraft = { playerId: player.id, effect: structuredClone(effect), canRemove, removeType };
  const actions = [
    { action: "activate", label: "Activate" },
    { action: "view", label: "View" },
    ...(canRemove ? [{ action: "remove", label: "Remove" }] : [])
  ];
  els.pokemonActionMenu.replaceChildren(...actions.map((item) => {
    const button = document.createElement("button");
    button.type = "button";
    button.dataset.objectAction = item.action;
    button.textContent = item.label;
    return button;
  }));
  els.pokemonActionMenu.style.left = `${Math.min(event.clientX, window.innerWidth - 190)}px`;
  els.pokemonActionMenu.style.top = `${Math.min(event.clientY, window.innerHeight - 180)}px`;
  els.pokemonActionMenu.classList.remove("hidden");
}

function handleObjectAction(action) {
  if (!objectActionDraft) return;
  const draft = objectActionDraft;
  const player = state.players.find((candidate) => candidate.id === draft.playerId) || activePlayer();
  closePokemonActionMenu();
  if (action === "activate") {
    if (!requirePrivatePrepAccess(player, "effect activation")) return;
    if (isRerollToken(draft.effect)) {
      openRerollTargetModal(player.id);
      return;
    }
    const utilityDefinition = utilityTokenDefinitionByName(draft.effect.name);
    if (utilityDefinition?.effectType === "trainer-class-wheel" && utilityDefinition.selfOnly) {
      startTrainerClassWheelActivation(player, draft.effect, utilityDefinition, player);
      return;
    }
    openActivationOverlay({
      player,
      effect: draft.effect,
      target: player,
      targetType: "player"
    });
  }
  if (action === "view") {
    alert(`${draft.effect.name}\n${capitalize(draft.effect.type)} effect`);
  }
  if (action === "remove" && draft.canRemove) {
    removeEffect(draft.removeType || draft.effect.type, draft.effect.name);
  }
}

function movePokemonRoster(pokemon) {
  pokemon.rosterType = pokemon.rosterType === "Legacy" ? "Active" : "Legacy";
  pokemon.status = "Active";
  logPokemonAction(pokemon, "Roster Updated", `Moved to ${pokemon.rosterType}`);
  syncPlayerPokemonLists();
  saveState();
  render();
}

function releasePokemon(pokemon) {
  if (!confirm(`Release ${pokemon.name}?`)) return;
  pokemon.status = "Released";
  pokemon.rosterType = "Released";
  logPokemonAction(pokemon, "Released", "Released from roster");
  syncPlayerPokemonLists();
  saveState();
  render();
}

function addPokemonModifier(pokemon, type) {
  const value = prompt(type === "buff" ? "Buff text" : "Nerf text");
  if (!value?.trim()) return;
  const key = type === "buff" ? "buffs" : "nerfs";
  pokemon[key] = [...(pokemon[key] || []), value.trim()];
  logPokemonAction(pokemon, type === "buff" ? "Buff Added" : "Nerf Added", `${type === "buff" ? "Buff" : "Nerf"} added: ${value.trim()}`);
  saveState();
  render();
}

function tradePokemonPlaceholder(pokemon) {
  const targetName = prompt("Trade to which trainer? This will be wired to a trainer picker later.");
  if (!targetName?.trim()) return;
  logPokemonAction(pokemon, "Trade Planned", `Trade placeholder: ${targetName.trim()}`);
  saveState();
  render();
}

async function evolvePokemonTo(pokemon, evolvedName) {
  if (!pokemonEvolutionAllowedBySeriesLock(pokemon, evolvedName)) {
    const lock = activeSeriesEvolutionLock(pokemon);
    alert(`${pokemon.name} is locked to the ${lock?.speciesName || "selected"} evolution branch for the current Series.`);
    return;
  }
  const oldName = pokemon.name;
  const oldSpecies = pokemonCommittedSpecies(pokemon) || oldName;
  const existingAcquisitionTier = pokemon.acquisitionTier || getPokemonAcquisitionTier(oldName);
  pokemon.name = pokemonDisplayName(evolvedName);
  pokemon.currentSpecies = pokemon.name;
  pokemon.currentEvolutionStage = teambuilderEvolutionStageIndex(pokemon.name);
  pokemon.evolutionLineId = teambuilderEvolutionLineId(pokemon.name) || pokemon.evolutionLineId || "";
  pokemon.evolutionHistory = [{
    fromSpecies: oldSpecies,
    toSpecies: pokemon.name,
    series: state.series,
    gym: Number(state.gym),
    source: "manualEvolution",
    timestamp: new Date().toISOString()
  }, ...(pokemon.evolutionHistory || [])];
  pokemon.spriteUrl = await fetchPokemonSpriteUrl(evolvedName);
  pokemon.acquisitionTier = existingAcquisitionTier || await resolvePokemonFamilyAcquisitionTier(evolvedName);
  pokemon.gameCornerMetadata = getPokemonGameCornerMetadata(evolvedName) || getPokemonGameCornerMetadata(oldName) || pokemon.gameCornerMetadata || null;
  logPokemonAction(pokemon, "Evolved", `${oldName} evolved into ${pokemon.name}`);
  syncPlayerPokemonLists();
  saveState();
  closeEvolutionModal();
  render();
}

function closeEvolutionModal() {
  evolutionTargetId = null;
  els.evolutionModal.classList.add("hidden");
  els.evolutionOptions.replaceChildren();
}

function manualEvolvePokemon() {
  const pokemon = findPokemonRecord(evolutionTargetId);
  if (!pokemon) return;
  const evolvedName = prompt("Evolution data not found. Enter evolved name manually.");
  if (!evolvedName?.trim()) return;
  evolvePokemonTo(pokemon, evolvedName.trim());
}

async function openEvolutionFlow(pokemon) {
  evolutionTargetId = pokemon.id;
  els.evolutionTitle.textContent = `Evolve ${pokemon.name}`;
  els.evolutionPrompt.textContent = "Looking up evolution options...";
  els.evolutionOptions.innerHTML = "";
  els.evolutionModal.classList.remove("hidden");
  try {
    const options = await evolutionOptionsForPokemon(pokemon);
    if (!options.length) {
      els.evolutionPrompt.textContent = activeSeriesEvolutionLock(pokemon)
        ? "No legal evolutions are available within this Pokemon's current Series Evolution Lock."
        : "No further evolutions found.";
      return;
    }
    const lock = activeSeriesEvolutionLock(pokemon);
    els.evolutionPrompt.textContent = lock
      ? `Choose an evolution on the ${lock.speciesName} branch. Stats, buffs, nerfs, ownership, and origin stay on this Pokemon.`
      : "Choose an evolution. Stats, buffs, nerfs, ownership, and origin stay on this Pokemon.";
    const optionCards = await Promise.all(options.map(async (option) => {
      const spriteUrl = await fetchPokemonSpriteUrl(option.name);
      const button = document.createElement("button");
      button.type = "button";
      button.className = "evolution-option";
      button.dataset.name = option.name;
      button.innerHTML = `${spriteUrl ? `<img src="${escapeHtml(spriteUrl)}" alt="">` : `<span>${escapeHtml(option.label.slice(0, 1))}</span>`}<strong>${escapeHtml(option.label)}</strong>`;
      return button;
    }));
    els.evolutionOptions.replaceChildren(...optionCards);
  } catch {
    els.evolutionPrompt.textContent = "Evolution data not found. Use manual entry for custom or unusual Pokemon.";
  }
}

function handlePokemonAction(action) {
  const pokemon = findPokemonRecord(activePokemonActionId);
  if (!pokemon) return;
  closePokemonActionMenu();
  if (action === "move") movePokemonRoster(pokemon);
  if (action === "release") releasePokemon(pokemon);
  if (action === "buff") addPokemonModifier(pokemon, "buff");
  if (action === "nerf") addPokemonModifier(pokemon, "nerf");
  if (action === "trade") tradePokemonPlaceholder(pokemon);
  if (action === "evolve") openEvolutionFlow(pokemon);
}

function saveState({ immediate = false, immediateBackend = false } = {}) {
  if (tokenScenarioSandboxActive()) return;
  if (immediate) flushStoredStateSave(state);
  else queueStoredStateSave();
  const queued = queueBackendStateSave({ delay: immediateBackend ? 0 : 350 });
  return immediateBackend && queued ? flushBackendStateSave() : undefined;
}

function formatMoney(value) {
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD",
    maximumFractionDigits: 0
  }).format(value).replace("$", "");
}

function activePlayer() {
  const selected = state.players.find((player) => player.id === state.activePlayerId);
  if (selected) return selected;
  const fallback = state.players[0];
  if (fallback) state.activePlayerId = fallback.id;
  return fallback;
}

function switchActivePlayer(playerId, { testingOverride = false } = {}) {
  const player = state.players.find((entry) => entry.id === playerId);
  if (!player) return false;
  const cart = currentCart();
  if (cart.items.length && cart.playerId && cart.playerId !== player.id) {
    const cartOwner = state.players.find((candidate) => candidate.id === cart.playerId);
    if (testingOverride) {
      state.shopCart = { playerId: "", items: [], open: false };
    } else if (cartOwner && currentProfileCanControlPlayer(cartOwner)) {
      if (!confirm(`Clear ${cartOwner?.name || "the current trainer"}'s pending cart and switch to ${player.name}?`)) return false;
      state.shopCart = { playerId: "", items: [], open: false };
    }
  }
  state.activePlayerId = player.id;
  return true;
}

function currentCart() {
  state.shopCart ||= { playerId: "", items: [], open: false };
  state.shopCart.items ||= [];
  return state.shopCart;
}

function cartPlayer() {
  const cart = currentCart();
  return state.players.find((player) => player.id === cart.playerId) || activePlayer();
}

function cartTotal() {
  return currentCart().items.reduce((total, item) => total + item.price * item.quantity, 0);
}

function cartQuantityTotal() {
  return currentCart().items.reduce((total, item) => total + Number(item.quantity || 0), 0);
}

function pulseCartTab() {
  els.cartTab.classList.add("cart-tab-pulse");
  clearTimeout(cartPulseTimer);
  cartPulseTimer = setTimeout(() => els.cartTab.classList.remove("cart-tab-pulse"), 650);
}

function baselineShopLevel() {
  return 0;
}

function effectiveShopLevel(player, shop = state.activeShop) {
  return Math.max(baselineShopLevel(), player.shopLevels?.[shop] ?? 0);
}

function shopAccessLabel(player) {
  const level = effectiveShopLevel(player);
  return `${shopLevelNames[level]} (${level + 1}/5)`;
}

function shopLevelLabel(player, shop) {
  const level = effectiveShopLevel(player, shop);
  return `${shopLevelNames[level]} (${level + 1}/5)`;
}

function shopProgressLabel(player, shop) {
  return "Points removed";
}

function actionShopDiscountPercent(player = activePlayer(), shop = state.activeShop, series = state.series) {
  return 0;
}

function discountedShopPrice(item, shop = state.activeShop, player = activePlayer()) {
  if (item?.shopAction === "badge-point") return getBadgePurchaseCost(player);
  const price = Number(item.price || 0);
  const discount = actionShopDiscountPercent(player, shop);
  if (!price || !discount || shop === "tokens" || shop === "utility") return price;
  return Math.max(0, Math.round(price * (100 - discount) / 100));
}

function playerHasActionShopException(player, shop = state.activeShop) {
  if (!player || currentPhase() !== "action") return false;
  const visits = activeActionVisitsForPlayer(player.id);
  if (["items", "tms"].includes(shop)) return visits.some((visit) => visit.locationId === "department-store");
  return false;
}

function canPurchaseFromShopNow(player, shop = state.activeShop, item = {}) {
  if (item?.shopAction === "badge-point") return currentPhase() === "shop";
  if (item?.shopPhaseOnly) return currentPhase() === "shop";
  if (currentPhase() === "shop") return true;
  return playerHasActionShopException(player, shop);
}

function shopPurchaseTimingMessage(shop = state.activeShop) {
  if (shop === "items") return "Items can be purchased during Shop Phase or during an Action Phase Department Store visit.";
  if (shop === "tms") return "TMs can be purchased during Shop Phase or during an Action Phase Department Store visit.";
  return "Purchases can only be finalized during Shop Phase unless a specific rule or location allows it.";
}

function shopDisplayName(shop = state.activeShop) {
  if (shop === "tms") return "TM Shop";
  if (shop === "items") return "Items";
  if (shop === "utility") return "Utility Shop";
  return "Token Shop";
}

function inventoryTypeForShop(shopType, item = {}) {
  if (shopType === "tms") return "TM";
  if (shopType === "tokens" && ["game-corner", "legacy"].includes(String(item.tokenType || "").toLowerCase())) return "TICKET";
  if (shopType === "tokens") return "TOKEN";
  if (item.type && !["TOKEN", "TM"].includes(item.type)) return item.type;
  return "ITEM";
}

function inventoryEntryIsTm(item = {}) {
  if (String(item.type || "").toUpperCase() === "TM") return true;
  if (/^tm-/i.test(String(item.catalogId || ""))) return true;
  return /^tm-/i.test(String(item.id || ""))
    && Boolean(teambuilderTmShopEntryForMove(item.moveName || item.name));
}

function normalizeTmInventoryEntry(item = {}) {
  if (!inventoryEntryIsTm(item) || String(item.type || "").toUpperCase() === "TM") return item;
  return {
    ...item,
    moveType: item.moveType || item.type || "",
    type: "TM"
  };
}

function parseRecord(record = "0-0") {
  const match = String(record).match(/(\d+)\s*-\s*(\d+)/);
  if (!match) return { wins: 0, losses: 0, games: 0, pct: 0 };
  const wins = Number(match[1]);
  const losses = Number(match[2]);
  const games = wins + losses;
  return { wins, losses, games, pct: games ? wins / games : 0 };
}

function formatRecord(record) {
  return `${record.wins}-${record.losses}`;
}

function formatWinPct(record) {
  return record.games ? `${(record.pct * 100).toFixed(1)}%` : "--";
}

function ensureSeriesPerformance(player) {
  const source = Array.isArray(player.seriesPerformance) ? player.seriesPerformance : [];
  player.seriesPerformance = Array.from({ length: 9 }, (_, index) => {
    const existing = source[index] || {};
    const fallbackCurrent = !source.length && index === 0;
    return {
      label: existing.label || seriesNames[index],
      sagaPoints: Number(existing.sagaPoints ?? (fallbackCurrent ? player.sagaPoints ?? 0 : 0)),
      record: existing.record || (fallbackCurrent ? player.seriesRecord || player.record || "0-0" : "0-0"),
      placement: existing.placement ?? null
    };
  });
  return player.seriesPerformance;
}

function seriesEntriesFor(player) {
  const source = Array.isArray(player.seriesPerformance) ? player.seriesPerformance : [];
  return Array.from({ length: 9 }, (_, index) => {
    const existing = source[index] || {};
    const fallbackCurrent = !source.length && index === 0;
    return {
      label: existing.label || seriesNames[index],
      sagaPoints: Number(existing.sagaPoints ?? (fallbackCurrent ? player.sagaPoints ?? 0 : 0)),
      record: existing.record || (fallbackCurrent ? player.seriesRecord || player.record || "0-0" : "0-0"),
      placement: existing.placement ?? null
    };
  });
}

function averagePlacement(entries) {
  const placements = entries
    .map((entry) => Number(entry.placement))
    .filter((placement) => Number.isFinite(placement) && placement > 0);
  if (!placements.length) return null;
  return placements.reduce((total, placement) => total + placement, 0) / placements.length;
}

function perkCheckpointProgress(totalSagaPoints) {
  const total = Math.max(0, Number(totalSagaPoints || 0));
  const interval = sagaPointRules.perkOfferInterval;
  const pointsTowardNext = total % interval;
  return {
    perkOffersEarned: Math.floor(total / interval),
    pointsTowardNext,
    pointsUntilNext: pointsTowardNext === 0 ? 0 : interval - pointsTowardNext
  };
}

function normalizePerkTier(tier) {
  const value = String(tier || "").trim().toLowerCase();
  if (value === "a" || value.includes("crystal") || value.includes("platinum")) return "A";
  if (value === "b" || value.includes("gold")) return "B";
  return "C";
}

function perkTierLabel(tier) {
  return PERK_TIER_META[normalizePerkTier(tier)]?.label || "Silver Tier";
}

function perkTierShortLabel(tier) {
  return PERK_TIER_META[normalizePerkTier(tier)]?.shortLabel || "Silver";
}

function perkAvailabilityLabel(perk) {
  if (!perk?.isConsumable) return "Permanent";
  const uses = Math.max(0, Number(perk.uses || 0));
  return uses ? `Consumable - ${uses} ${uses === 1 ? "use" : "uses"}` : "Consumable";
}

function normalizePerkDefinition(definition) {
  const name = String(definition?.name || "").trim();
  const id = slugify(definition?.id || name);
  if (!id || !name) return null;
  return {
    id,
    name,
    tier: normalizePerkTier(definition.tier),
    description: String(definition.description || "No effect description imported yet."),
    moveAccess: definition.moveAccess && typeof definition.moveAccess === "object"
      ? { ...definition.moveAccess }
      : null,
    isConsumable: Boolean(definition.isConsumable || definition.consumable),
    uses: Number.isFinite(Number(definition.uses)) ? Math.max(0, Math.floor(Number(definition.uses))) : null,
    offerBanned: Boolean(definition.offerBanned || definition.bannedFromOffers)
  };
}

function perkDefinitions() {
  return PERK_DEFINITIONS.map(normalizePerkDefinition).filter(Boolean);
}

function perkDefinitionById(perkId) {
  return perkDefinitions().find((perk) => perk.id === perkId) || null;
}

function activePerkAssignments(playerId = "") {
  return (state.perkSystem?.assignments || []).filter((assignment) => assignment.status === "active" && (!playerId || assignment.playerId === playerId));
}

function ownedPerkIds() {
  const ids = new Set(activePerkAssignments().map((assignment) => assignment.perkId));
  state.players.forEach((player) => {
    (player.perks || []).forEach((perk) => ids.add(slugify(typeof perk === "string" ? perk : perk?.name)));
  });
  return ids;
}

function perkIsAvailableForOffer(perk, excludedIds = new Set(), ownedIds = ownedPerkIds()) {
  return Boolean(perk?.id)
    && !perk.offerBanned
    && !ownedIds.has(perk.id)
    && !excludedIds.has(perk.id);
}

function validPerksForTier(tier, excludedIds = new Set()) {
  const ownedIds = ownedPerkIds();
  return perkDefinitions().filter((perk) => perk.tier === normalizePerkTier(tier)
    && perkIsAvailableForOffer(perk, excludedIds, ownedIds));
}

function rollPerkTier() {
  const roll = Math.random() * 100;
  if (roll <= PERK_TIER_ODDS.C) return "C";
  if (roll <= PERK_TIER_ODDS.C + PERK_TIER_ODDS.B) return "B";
  return "A";
}

function randomEntry(entries) {
  return entries[Math.floor(Math.random() * entries.length)] || null;
}

function perkChoiceFromDefinition(perk) {
  return {
    perkId: perk.id,
    perkName: perk.name,
    tier: perk.tier,
    description: perk.description,
    isConsumable: perk.isConsumable,
    uses: perk.uses
  };
}

function pickPerkChoiceForTier(tier, excludedIds) {
  return randomEntry(validPerksForTier(tier, excludedIds));
}

function pickAnyAvailablePerk(excludedIds) {
  const ownedIds = ownedPerkIds();
  const valid = perkDefinitions().filter((perk) => perkIsAvailableForOffer(perk, excludedIds, ownedIds));
  return randomEntry(valid);
}

function replacementPerkForPendingChoice(roll, choice, choiceIndex, excludedIds) {
  const sameTier = pickPerkChoiceForTier(choice.tier, excludedIds);
  if (sameTier) return sameTier;
  if (roll.safetyGuaranteed && choiceIndex === 0) return null;
  let replacement = null;
  for (let attempt = 0; attempt < 16 && !replacement; attempt += 1) {
    replacement = pickPerkChoiceForTier(rollPerkTier(), excludedIds);
  }
  return replacement || pickAnyAvailablePerk(excludedIds);
}

function refreshUnavailablePendingPerkChoices(excludedRollId = "") {
  const ownedIds = ownedPerkIds();
  (state.perkSystem?.pendingRolls || []).forEach((roll) => {
    if (roll.claimed || roll.rollId === excludedRollId) return;
    const excludedIds = new Set();
    roll.choices = (roll.choices || []).map((choice, choiceIndex) => {
      const definition = perkDefinitionById(choice.perkId);
      if (perkIsAvailableForOffer(definition, excludedIds, ownedIds)) {
        excludedIds.add(choice.perkId);
        return choice;
      }
      const replacement = replacementPerkForPendingChoice(roll, choice, choiceIndex, excludedIds);
      if (!replacement) {
        addPerkSystemWarning(`${roll.safetyGuaranteed && choiceIndex === 0 ? "Crystal Safety" : "Perk"} offer could not find an available replacement choice.`);
        return null;
      }
      excludedIds.add(replacement.id);
      return perkChoiceFromDefinition(replacement);
    }).filter(Boolean);
  });
}

function addPerkSystemWarning(message) {
  state.perkSystem ||= {};
  state.perkSystem.adminWarnings ||= [];
  state.perkSystem.adminWarnings.unshift({
    id: `perk-warning-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
    message,
    createdAt: new Date().toISOString()
  });
  state.perkSystem.adminWarnings = state.perkSystem.adminWarnings.slice(0, 12);
}

function generatePerkRollOffer(player, threshold) {
  state.perkSystem ||= {};
  const excludedIds = new Set();
  const choices = [];
  const eligibleForSafety = (state.perkSystem.aTierSafetyEligiblePlayerIds || []).includes(player.id);
  const plannedSlots = eligibleForSafety ? ["A", null, null] : [null, null, null];
  plannedSlots.forEach((plannedTier, index) => {
    let perk = null;
    if (plannedTier === "A") {
      perk = pickPerkChoiceForTier("A", excludedIds);
      if (!perk) {
        addPerkSystemWarning(`${player.name}'s Crystal Safety offer could not find an available Crystal perk.`);
        return;
      }
    } else {
      for (let attempt = 0; attempt < 16 && !perk; attempt += 1) {
        perk = pickPerkChoiceForTier(rollPerkTier(), excludedIds);
      }
      if (!perk) perk = pickAnyAvailablePerk(excludedIds);
    }
    if (!perk) {
      if (index === 0 && !perkDefinitions().length) addPerkSystemWarning("No perk definitions have been imported yet, so perk offers cannot generate choices.");
      return;
    }
    excludedIds.add(perk.id);
    choices.push(perkChoiceFromDefinition(perk));
  });
  const containsATier = choices.some((choice) => choice.tier === "A");
  if (containsATier && !state.perkSystem.aTierSafetyTriggered) {
    state.perkSystem.aTierSafetyTriggered = true;
    state.perkSystem.aTierSafetyTriggeringPlayerId = player.id;
    state.perkSystem.aTierSafetyEligiblePlayerIds = state.players.filter((entry) => entry.id !== player.id).map((entry) => entry.id);
    state.perkSystem.aTierSafetyCompletedPlayerIds = [];
  }
  if (eligibleForSafety) {
    state.perkSystem.aTierSafetyEligiblePlayerIds = (state.perkSystem.aTierSafetyEligiblePlayerIds || []).filter((id) => id !== player.id);
    state.perkSystem.aTierSafetyCompletedPlayerIds = [...new Set([...(state.perkSystem.aTierSafetyCompletedPlayerIds || []), player.id])];
  }
  return {
    rollId: `perk-roll-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
    playerId: player.id,
    sagaPointThreshold: threshold,
    choices,
    createdAt: new Date().toISOString(),
    claimed: false,
    chosenPerkId: null,
    skipped: false,
    safetyGuaranteed: eligibleForSafety
  };
}

function awardPendingPerkRollsForPlayer(player) {
  if (!player) return [];
  if (!perkDefinitions().length) {
    addPerkSystemWarning("No perk definitions have been imported yet, so pending perk rolls were not created.");
    return [];
  }
  state.perkSystem ||= {};
  state.perkSystem.pendingRolls ||= [];
  state.perkSystem.highestThresholdAwardedByPlayerId ||= {};
  const currentThreshold = Math.floor(Math.max(0, Number(player.sagaPoints || 0)) / sagaPointRules.perkOfferInterval) * sagaPointRules.perkOfferInterval;
  const previousThreshold = Number(state.perkSystem.highestThresholdAwardedByPlayerId[player.id] || 0);
  const created = [];
  for (let threshold = previousThreshold + sagaPointRules.perkOfferInterval; threshold <= currentThreshold; threshold += sagaPointRules.perkOfferInterval) {
    const offer = generatePerkRollOffer(player, threshold);
    state.perkSystem.pendingRolls.push(offer);
    created.push(offer);
  }
  if (currentThreshold > previousThreshold) state.perkSystem.highestThresholdAwardedByPlayerId[player.id] = currentThreshold;
  return created;
}

function awardPendingPerkRollsForAllPlayers() {
  return state.players.flatMap((player) => awardPendingPerkRollsForPlayer(player));
}

function createManualPerkRollForPlayer(playerId) {
  const player = state.players.find((entry) => entry.id === playerId) || activePlayer();
  if (!player) return null;
  const existingOffer = (state.perkSystem?.pendingRolls || [])
    .filter((roll) => roll.playerId === player.id && !roll.claimed)
    .sort((left, right) => String(right.createdAt || "").localeCompare(String(left.createdAt || "")))[0];
  if (existingOffer) return existingOffer;
  if (!perkDefinitions().length) {
    addPerkSystemWarning("No perk definitions have been imported yet, so manual perk rolls cannot generate choices.");
    return null;
  }
  state.perkSystem ||= {};
  state.perkSystem.pendingRolls ||= [];
  const offer = {
    ...generatePerkRollOffer(player, "Manual"),
    manual: true
  };
  state.perkSystem.pendingRolls.push(offer);
  addLogEntry({
    action: "perk",
    category: "perks",
    player: player.name,
    playerId: player.id,
    item: `${player.name} generated a manual 3-choice perk roll.`,
    title: `${player.name} generated a perk roll`,
    summary: `Manual perk roll\nChoices: ${offer.choices.map((choice) => choice.perkName).join(", ") || "None"}`,
    type: "perk-roll-manual",
    categories: ["perks"],
    tags: ["perk", "perk-roll", "manual"],
    playerIds: [player.id]
  });
  return offer;
}

function openTestRollPerks({ updateHistory = true } = {}) {
  void updateHistory;
  closeGameMenu({ restoreFocus: false });
  closeGameLeagueMenu({ restoreFocus: false });
  closeGameHeaderPopovers();
  perkTestRollerPreviousFocus = document.activeElement;
  perkTestRollerPlayerId = activePlayer()?.id || state.activePlayerId || state.players[0]?.id || "";
  els.perkTestRollerModal?.classList.remove("hidden");
  const offer = ensurePerkTestRollerOffer();
  renderPerkTestRoller();
  requestAnimationFrame(() => {
    els.perkTestRollerRoll?.focus();
    if (offer) focusPerkTestRollerOffer(offer.rollId);
  });
}

function closePerkTestRoller({ restoreFocus = true } = {}) {
  if (!els.perkTestRollerModal || els.perkTestRollerModal.classList.contains("hidden")) return;
  els.perkTestRollerModal.classList.add("hidden");
  if (restoreFocus) (perkTestRollerPreviousFocus || els.gameMenuToggle)?.focus?.();
  perkTestRollerPreviousFocus = null;
}

function selectedPerkTestRollerPlayer() {
  const selectedId = els.perkTestRollerPlayer?.value || perkTestRollerPlayerId || state.activePlayerId;
  const player = state.players.find((entry) => entry.id === selectedId) || activePlayer() || state.players[0] || null;
  perkTestRollerPlayerId = player?.id || "";
  return player;
}

function pendingPerkRollsForPlayer(playerId) {
  return (state.perkSystem?.pendingRolls || [])
    .filter((roll) => roll.playerId === playerId && !roll.claimed)
    .sort((left, right) => String(right.createdAt || "").localeCompare(String(left.createdAt || "")));
}

function ensurePerkTestRollerOffer() {
  const player = selectedPerkTestRollerPlayer();
  if (!player) return null;
  const offer = createManualPerkRollForPlayer(player.id);
  saveState();
  return offer;
}

function renderPerkTestRoller() {
  if (!els.perkTestRollerModal || els.perkTestRollerModal.classList.contains("hidden")) return;
  const player = selectedPerkTestRollerPlayer();
  if (els.perkTestRollerPlayer) {
    els.perkTestRollerPlayer.replaceChildren(...state.players.map((entry) => new Option(entry.name, entry.id)));
    if (player) els.perkTestRollerPlayer.value = player.id;
  }
  if (!player) {
    if (els.perkTestRollerStatus) els.perkTestRollerStatus.innerHTML = "";
    if (els.perkTestRollerResults) els.perkTestRollerResults.innerHTML = `<p class="empty-state compact">Add a trainer before rolling perks.</p>`;
    return;
  }
  const rolls = pendingPerkRollsForPlayer(player.id);
  const progress = perkCheckpointProgress(player.sagaPoints || 0);
  const highest = Number(state.perkSystem?.highestThresholdAwardedByPlayerId?.[player.id] || 0);
  const assignments = activePerkAssignments(player.id);
  if (els.perkTestRollerStatus) {
    els.perkTestRollerStatus.innerHTML = `
      <span><b>${Number(player.sagaPoints || 0)}</b> Saga Points</span>
      <span><b>${rolls.length}</b> Pending Rolls</span>
      <span><b>${highest || 0}</b> Highest Awarded</span>
      <span><b>${progress.pointsUntilNext || "Ready"}</b> ${progress.pointsUntilNext ? "SP to Next" : "Next Roll"}</span>
      <span><b>${assignments.length}</b> Active Perks</span>
    `;
  }
  if (els.perkTestRollerRoll) {
    els.perkTestRollerRoll.textContent = rolls.length
      ? `View Pending Offer${rolls.length > 1 ? `s (${rolls.length})` : ""}`
      : "Roll 3 Perks";
  }
  if (els.perkTestRollerResults) {
    els.perkTestRollerResults.innerHTML = rolls.length ? rolls.map((roll) => `
      <article class="perk-roll-card" data-perk-test-roll-card="${escapeHtml(roll.rollId)}">
        <div class="perk-roll-card-header">
          <div>
            <p class="eyebrow">${escapeHtml(player.name)} - ${escapeHtml(roll.manual ? "Manual Roll" : `${roll.sagaPointThreshold} SP`)}</p>
            <h3>${roll.safetyGuaranteed ? "Crystal Safety Offer" : "Perk Offer"}</h3>
          </div>
          <button class="ghost-button mini-button" type="button" data-skip-perk-roll="${escapeHtml(roll.rollId)}">Skip</button>
        </div>
        <div class="perk-choice-grid">
          ${roll.choices.length ? roll.choices.map((choice) => `
            <button class="perk-choice-card perk-choice-${escapeHtml(choice.tier.toLowerCase())}" type="button" data-choose-perk-roll="${escapeHtml(roll.rollId)}" data-perk-id="${escapeHtml(choice.perkId)}">
              <span>${escapeHtml(perkTierShortLabel(choice.tier))}</span>
              <strong>${escapeHtml(choice.perkName)}</strong>
              <em>${escapeHtml(perkAvailabilityLabel(choice))}</em>
              <small>${escapeHtml(choice.description)}</small>
            </button>
          `).join("") : `<p class="empty-state compact">No valid perk choices generated. Check that perk definitions are loaded.</p>`}
        </div>
      </article>
    `).join("") : `<p class="empty-state compact">No pending perk rolls for ${escapeHtml(player.name)}. Press Roll 3 Perks to generate the three-card offer.</p>`;
  }
  renderPerkTestRollerSafety();
}

function renderPerkTestRollerSafety() {
  if (!els.perkTestRollerSafety) return;
  const system = state.perkSystem || {};
  const triggerPlayer = state.players.find((player) => player.id === system.aTierSafetyTriggeringPlayerId);
  const warnings = system.adminWarnings || [];
  els.perkTestRollerSafety.innerHTML = `
    <h3>Crystal Safety Lever</h3>
    <p>${system.aTierSafetyTriggered ? `Triggered by ${escapeHtml(triggerPlayer?.name || "Unknown")}. Eligible players get one guaranteed Crystal choice on their next perk offer.` : "Not triggered yet. The first generated offer containing a Crystal perk activates it for every other player."}</p>
    ${warnings.length ? `<ul class="info-warning-list">${warnings.slice(0, 3).map((warning) => `<li>${escapeHtml(warning.message)}</li>`).join("")}</ul>` : ""}
  `;
}

function focusPerkTestRollerOffer(rollId) {
  if (!rollId || !els.perkTestRollerResults) return;
  requestAnimationFrame(() => {
    const card = Array.from(els.perkTestRollerResults.querySelectorAll("[data-perk-test-roll-card]"))
      .find((entry) => entry.dataset.perkTestRollCard === rollId);
    if (!card) return;
    card.scrollIntoView({ behavior: "smooth", block: "center" });
    card.classList.remove("perk-roll-card-focus");
    requestAnimationFrame(() => card.classList.add("perk-roll-card-focus"));
    window.setTimeout(() => card.classList.remove("perk-roll-card-focus"), 1400);
  });
}

function perkSlotUsage(playerId, tier) {
  return activePerkAssignments(playerId).filter((assignment) => assignment.tier === normalizePerkTier(tier)).length;
}

function removePlayerPerkName(player, perkName) {
  const lower = String(perkName || "").toLowerCase();
  player.perks = (player.perks || []).filter((perk) => String(typeof perk === "string" ? perk : perk?.name || "").toLowerCase() !== lower);
}

function choosePerkRoll(rollId, perkId) {
  const roll = (state.perkSystem?.pendingRolls || []).find((entry) => entry.rollId === rollId);
  const player = state.players.find((entry) => entry.id === roll?.playerId);
  const choice = roll?.choices?.find((entry) => entry.perkId === perkId);
  if (!roll || !player || !choice || roll.claimed) return;
  const definition = perkDefinitionById(choice.perkId);
  if (!perkIsAvailableForOffer(definition)) {
    refreshUnavailablePendingPerkChoices();
    saveState();
    render();
    alert("That perk is already owned or no longer available. This offer has been refreshed.");
    return;
  }
  const tier = normalizePerkTier(choice.tier);
  const limit = PERK_TIER_META[tier].slots;
  if (perkSlotUsage(player.id, tier) >= limit) {
    const replaceable = activePerkAssignments(player.id).filter((assignment) => assignment.tier === tier);
    const promptText = replaceable.map((assignment, index) => `${index + 1}. ${assignment.perkName}`).join("\n");
    const answer = prompt(`${perkTierShortLabel(tier)} perk slots are full. Enter the number of the perk to replace, or cancel to skip choosing now:\n${promptText}`);
    const index = Number(answer) - 1;
    const replaced = replaceable[index];
    if (!replaced) return;
    replaced.status = "replaced";
    replaced.removedAt = new Date().toISOString();
    replaced.replacedByPerkId = choice.perkId;
    removePlayerPerkName(player, replaced.perkName);
  }
  state.perkSystem.assignments.push({
    id: `perk-assignment-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
    playerId: player.id,
    perkId: choice.perkId,
    perkName: choice.perkName,
    tier,
    isConsumable: Boolean(choice.isConsumable),
    usesRemaining: choice.isConsumable ? Number(choice.uses || 0) : null,
    status: "active",
    sourceRollId: roll.rollId,
    acquiredAt: new Date().toISOString()
  });
  player.perks = [choice.perkName, ...(player.perks || []).filter((perk) => String(perk) !== choice.perkName)];
  roll.claimed = true;
  roll.chosenPerkId = choice.perkId;
  roll.skipped = false;
  refreshUnavailablePendingPerkChoices(roll.rollId);
  addLogEntry({
    action: "perk",
    category: "perks",
    player: player.name,
    playerId: player.id,
    item: `${player.name} chose ${choice.perkName} from a ${perkTierShortLabel(tier)} perk roll.`,
    type: "perk-roll-claimed",
    tags: ["perk", "perk-roll", tier],
    quantity: 1,
    price: 0
  });
  saveState();
  render();
}

function skipPerkRoll(rollId) {
  const roll = (state.perkSystem?.pendingRolls || []).find((entry) => entry.rollId === rollId);
  if (!roll || roll.claimed) return;
  const player = state.players.find((entry) => entry.id === roll.playerId);
  roll.claimed = true;
  roll.skipped = true;
  roll.chosenPerkId = null;
  addLogEntry({
    action: "perk",
    category: "perks",
    player: player?.name || "Unknown",
    playerId: roll.playerId,
    item: `${player?.name || "A player"} skipped a perk roll at ${roll.sagaPointThreshold} Saga Points.`,
    type: "perk-roll-skipped",
    tags: ["perk", "perk-roll", "skip"],
    quantity: 1,
    price: 0
  });
  saveState();
  render();
}

function sagaLapProgress(totalSagaPoints) {
  const total = Math.max(0, Number(totalSagaPoints || 0));
  const interval = sagaPointRules.majorLapInterval;
  return {
    lap: Math.floor(total / interval),
    lapProgress: total % interval
  };
}

function leaderboardRows() {
  const rows = state.players.map((player) => {
    const seriesEntries = seriesEntriesFor(player);
    const hasSeriesRecords = seriesEntries.some((entry) => parseRecord(entry.record).games > 0);
    const overallRecord = hasSeriesRecords
      ? seriesEntries.reduce((total, entry) => {
        const record = parseRecord(entry.record);
        total.wins += record.wins;
        total.losses += record.losses;
        return total;
      }, { wins: 0, losses: 0 })
      : parseRecord(player.record || "0-0");
    overallRecord.games = overallRecord.wins + overallRecord.losses;
    overallRecord.pct = overallRecord.games ? overallRecord.wins / overallRecord.games : 0;

    const seriesWins = Number(player.seriesWins || seriesEntries.filter((entry) => Number(entry.placement) === 1).length || 0);
    return {
      player,
      seriesEntries,
      totalSagaPoints: seriesEntries.reduce((total, entry) => total + Number(entry.sagaPoints || 0), 0),
      overallRecord,
      averagePlacement: averagePlacement(seriesEntries),
      seriesWins,
      currentBounty: Number(player.currentBounty ?? seriesWins * sagaPointRules.championBountyPerSeriesWin)
    };
  }).sort((a, b) => {
    if (b.totalSagaPoints !== a.totalSagaPoints) return b.totalSagaPoints - a.totalSagaPoints;
    return b.overallRecord.pct - a.overallRecord.pct;
  });

  let previous = null;
  rows.forEach((row, index) => {
    const tied = previous
      && previous.totalSagaPoints === row.totalSagaPoints
      && previous.overallRecord.pct === row.overallRecord.pct;
    row.rank = tied ? previous.rank : index + 1;
    previous = row;
  });
  return rows;
}

function derivedPlayerRecords(player) {
  const row = leaderboardRows().find((entry) => entry.player.id === player.id);
  const seriesIndex = Math.max(0, seriesNames.indexOf(state.series));
  const currentSeriesEntry = row?.seriesEntries?.[seriesIndex] || seriesEntriesFor(player)[seriesIndex] || {};
  return {
    seriesRecord: parseRecord(currentSeriesEntry.record || "0-0"),
    overallRecord: row?.overallRecord || parseRecord(player.record || "0-0")
  };
}

function itemIsUnlocked(item, player) {
  if (item.cannotPurchase) return false;
  if (item.shopAction === "badge-point") return currentPhase() === "shop";
  if (state.activeShop === "items" || item.shopType === "items") return true;
  if (item.tokenType || item.type === "TOKEN" || state.activeShop === "tokens" || state.activeShop === "utility") return true;
  const requiredLevel = Number.isFinite(Number(item.level)) ? Number(item.level) - 1 : tierLevel[item.tier] ?? 0;
  return requiredLevel <= effectiveShopLevel(player);
}

function setupControls() {
  seriesNames.forEach((series) => els.seriesSelect.add(new Option(series, series)));
  for (let gym = 1; gym <= 9; gym += 1) els.gymSelect.add(new Option(`Gym ${gym}`, String(gym)));
  seriesNames.forEach((series) => els.adminSeriesSelect.add(new Option(series, series)));
  for (let gym = 1; gym <= 9; gym += 1) els.adminGymSelect.add(new Option(`Gym ${gym}`, String(gym)));
  renderItemShopFilterControls();
  tmTypeOrder.forEach((type) => els.tmTypeFilter.add(new Option(displayTmType(type), type)));
  els.tmTypeFilter.value = "All";
  els.tmDamageClassFilter.value = "All";
  if (els.shopSortSelect) els.shopSortSelect.value = `${state.shopSort?.mode || "price"}-${state.shopSort?.direction || "asc"}`;
  state.players.forEach((player) => els.targetPlayer.add(new Option(player.name, player.id)));
  state.players.forEach((player) => els.adminRepairPlayer.add(new Option(player.name, player.id)));
  state.players.forEach((player) => els.adminActionRepairPlayer.add(new Option(player.name, player.id)));
  els.mvpTrainerFilter.add(new Option("All trainers", "all"));
  els.mvpSeriesFilter.add(new Option("All series", "all"));
  els.mvpGymFilter.add(new Option("All gyms", "all"));
  seriesNames.forEach((series) => els.mvpSeriesFilter.add(new Option(series, series)));
  for (let gym = 1; gym <= 9; gym += 1) els.mvpGymFilter.add(new Option(`Gym ${gym}`, String(gym)));
  seriesNames.forEach((series) => els.mvpBattleSeries?.add(new Option(series, series)));
  state.players.forEach((player) => {
    els.mvpTrainerFilter.add(new Option(player.name, player.id));
    els.battlePlayer1.add(new Option(player.name, player.id));
    els.battlePlayer2.add(new Option(player.name, player.id));
    els.battleWinner.add(new Option(player.name, player.id));
  });
  if (state.players[1]) els.battlePlayer2.value = state.players[1].id;
  seriesNames.forEach((series) => els.battleLogSeries.add(new Option(series, series)));
  for (let gym = 1; gym <= 9; gym += 1) els.battleLogGym.add(new Option(`Gym ${gym}`, String(gym)));
}

function placementTurnOrderPlayerIds(series = state.series) {
  const seriesIndex = seriesNames.indexOf(series);
  const ranked = state.players.map((player, index) => {
    const seriesEntry = player.seriesPerformance?.[seriesIndex] || {};
    const placement = Number(seriesEntry.placement || 99);
    const sagaPoints = Number(seriesEntry.sagaPoints || 0);
    return { player, index, placement, sagaPoints };
  }).sort((a, b) => {
    if (a.placement !== b.placement) return a.placement - b.placement;
    if (a.sagaPoints !== b.sagaPoints) return b.sagaPoints - a.sagaPoints;
    return a.index - b.index;
  });
  if (ranked.every((entry) => entry.placement === 99 && entry.sagaPoints === 0)) {
    return leaderboardRows().map((row) => row.player.id);
  }
  return ranked.map((entry) => entry.player.id);
}

function actionPhaseTurnOrderPlayerIds(series = state.series, gym = state.gym) {
  const gymState = ensureActionPhaseGymState(series, gym);
  return gymState.turnOrderPlayerIds || placementTurnOrderPlayerIds(series);
}

function phaseEventOrderNames() {
  const orderIds = currentPhase() === "action"
    ? actionPhaseTurnOrderPlayerIds()
    : placementTurnOrderPlayerIds();
  return orderIds.map((playerId) => state.players.find((player) => player.id === playerId)?.name).filter(Boolean);
}

function phaseAgenda() {
  const gym = Number(state.gym);
  const phase = currentPhase();
  const items = [];
  const order = phaseEventOrderNames();
  if (phase === "start") {
    return {
      items: ["Expire old effects.", "Resolve mandatory start-of-Gym triggers.", "Allow optional start-of-Gym effects.", "Confirm ready for Action Phase."],
      order: [],
      summary: "Start-of-Gym upkeep",
      showOrder: false
    };
  }
  if (phase === "battle") {
    return {
      items: ["Team Preparation.", "Team Submission / Lock.", "Sabotage.", "Team Preview.", "Rival Battles.", "Battle Data Reporting."],
      order: [],
      summary: "Battle Phase",
      showOrder: false
    };
  }
  if (phase === "battle-results") {
    return {
      items: ["Finalize battle results.", "Apply salary and placement rewards.", "Resolve Victory Road manually if needed.", "Calculate Momentum and rewards.", "Update records and corrections."],
      order: [],
      summary: "Battle Results Phase",
      showOrder: false
    };
  }
  if (phase === "shop") {
    return {
      items: ["Finalize purchases before advancing."],
      order: [],
      summary: "Shop Phase",
      showOrder: false
    };
  }
  const isOpeningSetup = state.series === seriesNames[0] && gym === 1 && phase === "action";
  if (isOpeningSetup) {
    items.push("Roll Trainer Classes");
    items.push("Roll Starters");
  }
  if (!isOpeningSetup && [1, 5].includes(gym) && phase === "action") {
    items.push("Free Trainer Class reroll available");
  }
  if ([3, 7].includes(gym) && phase !== "action") {
    items.push("Place one-gym Restrict");
  }
  if ([5, 9].includes(gym) && phase !== "action") {
    items.push("Place bans");
  }
  if (gym === 9) {
    items.push("Champion Gym: Champion Round wins are worth +2 Saga Points");
  }
  return {
    items,
    order,
    summary: items[0] || "Phase hooks ready",
    showOrder: true
  };
}

function phaseReminders() {
  const agenda = phaseAgenda();
  return [
    ...agenda.items,
    ...(agenda.showOrder ? [`Order: ${agenda.order.join(" -> ")}`] : [])
  ];
}

function actionPhaseKey(series = state.series, gym = state.gym) {
  return `${series}-G${Number(gym)}`;
}

function ensureActionPhaseGymState(series = state.series, gym = state.gym) {
  state.actionPhaseState ||= { selections: {}, seriesTrackers: {} };
  state.actionPhaseState.selections ||= {};
  state.actionPhaseState.seriesTrackers ||= {};
  const key = actionPhaseKey(series, gym);
  state.actionPhaseState.selections[key] ||= {
    series,
    gym: Number(gym),
    playerVisits: {},
    selectedLocationId: "",
    turnOrderPlayerIds: [],
      actionOperations: [],
      activeActionOperationId: "",
      destinationCommit: null
  };
  const gymState = state.actionPhaseState.selections[key];
  gymState.playerVisits ||= {};
  gymState.selectedLocationId ||= "";
  gymState.actionOperations = Array.isArray(gymState.actionOperations) ? gymState.actionOperations : [];
  gymState.activeActionOperationId ||= "";
  if (gymState.destinationCommit && typeof gymState.destinationCommit === "object") {
    gymState.destinationCommit = {
      id: String(gymState.destinationCommit.id || ""),
      requestId: String(gymState.destinationCommit.requestId || ""),
      status: Object.values(provisionalDeclarationRuntime.DESTINATION_STATES).includes(gymState.destinationCommit.status)
        ? gymState.destinationCommit.status
        : provisionalDeclarationRuntime.DESTINATION_STATES.RELEASED,
      playerId: String(gymState.destinationCommit.playerId || ""),
      actionNumber: Math.max(1, Number(gymState.destinationCommit.actionNumber || 1)),
      locationId: String(gymState.destinationCommit.locationId || ""),
      serviceId: String(gymState.destinationCommit.serviceId || ""),
      acceptedAt: gymState.destinationCommit.acceptedAt || "",
      operationId: String(gymState.destinationCommit.operationId || ""),
      releasedAt: gymState.destinationCommit.releasedAt || "",
      releaseReason: gymState.destinationCommit.releaseReason || "",
      completedAt: gymState.destinationCommit.completedAt || ""
    };
  } else {
    gymState.destinationCommit = null;
  }
  const activePlayerIds = new Set((state.players || []).map((player) => player.id));
  const existingOrder = (gymState.turnOrderPlayerIds || []).filter((playerId) => activePlayerIds.has(playerId));
  const missingOrder = placementTurnOrderPlayerIds(series).filter((playerId) => !existingOrder.includes(playerId));
  gymState.turnOrderPlayerIds = [...existingOrder, ...missingOrder];
  const visitIds = new Set(Object.values(gymState.playerVisits).flat().map((visit) => visit?.id).filter(Boolean));
  gymState.actionOperations = gymState.actionOperations
    .filter((operation) => operation?.visitId && visitIds.has(operation.visitId))
    .map((operation) => ({
      id: operation.id || `action-operation-${operation.visitId}`,
      visitId: operation.visitId,
      playerId: operation.playerId || "",
      actionNumber: Math.max(1, Number(operation.actionNumber || 1)),
      locationId: operation.locationId || "",
      locationName: operation.locationName || "",
      serviceId: operation.serviceId || "",
      committed: operation.committed !== false,
      committedAt: operation.committedAt || operation.createdAt || new Date().toISOString(),
      status: ["resolving", "completed", "cancelled"].includes(operation.status) ? operation.status : "resolving",
      linkedFeatureType: operation.linkedFeatureType || "",
      linkedFeatureSessionId: operation.linkedFeatureSessionId || "",
      linkedPendingSituationId: operation.linkedPendingSituationId || "",
      completedAt: operation.completedAt || "",
      completionReason: operation.completionReason || ""
    }));
  if (!gymState.actionOperations.some((operation) => operation.id === gymState.activeActionOperationId && operation.status === "resolving")) {
    gymState.activeActionOperationId = gymState.actionOperations.find((operation) => operation.status === "resolving")?.id || "";
  }
  if (staleActionDestinationCommit(gymState)) {
    const staleLocationId = gymState.destinationCommit?.locationId || "";
    gymState.destinationCommit = null;
    if (staleLocationId && gymState.selectedLocationId === staleLocationId) gymState.selectedLocationId = "";
    actionPhaseStateRepairQueued = true;
  }
  return gymState;
}

function staleActionDestinationCommit(gymState = {}) {
  const commit = gymState.destinationCommit;
  if (!commit || ![
    provisionalDeclarationRuntime.DESTINATION_STATES.ACCEPTED,
    provisionalDeclarationRuntime.DESTINATION_STATES.RESOLVING,
    provisionalDeclarationRuntime.DESTINATION_STATES.COMPLETED
  ].includes(commit.status)) return false;
  if (commit.status === provisionalDeclarationRuntime.DESTINATION_STATES.ACCEPTED && !commit.operationId) {
    const acceptedMs = Date.parse(commit.acceptedAt || "");
    return Number.isFinite(acceptedMs) && Date.now() - acceptedMs > ACTION_DESTINATION_START_GRACE_MS;
  }
  const operation = (gymState.actionOperations || []).find((entry) => entry.id === commit.operationId);
  if (!operation) return true;
  if (operation.status !== "resolving") return true;
  const visits = gymState.playerVisits?.[commit.playerId] || [];
  const visit = visits.find((entry) => entry.id === operation.visitId);
  return !isActiveActionVisit(visit);
}

function ensureActionSeriesTracker(series = state.series, playerId = activePlayer().id) {
  state.actionPhaseState ||= { selections: {}, seriesTrackers: {} };
  state.actionPhaseState.seriesTrackers ||= {};
  state.actionPhaseState.seriesTrackers[series] ||= {};
  state.actionPhaseState.seriesTrackers[series][playerId] ||= {
    itemDiscountStacks: 0,
    tmDiscountStacks: 0,
    rangerCredits: 0,
    rangerMilestones: [],
    rangerVisits: 0,
    rangerEffects: [],
    pokemonCenterCarePackages: []
  };
  const tracker = state.actionPhaseState.seriesTrackers[series][playerId];
  tracker.itemDiscountStacks ||= 0;
  tracker.tmDiscountStacks ||= 0;
  tracker.rangerCredits ||= 0;
  tracker.rangerMilestones ||= [];
  tracker.rangerVisits ||= 0;
  tracker.rangerEffects ||= [];
  tracker.pokemonCenterCarePackages ||= [];
  return tracker;
}

function actionVisitsForPlayer(playerId = activePlayer().id, series = state.series, gym = state.gym) {
  const gymState = ensureActionPhaseGymState(series, gym);
  gymState.playerVisits[playerId] ||= [];
  return gymState.playerVisits[playerId];
}

function isActiveActionVisit(visit) {
  if (!visit) return false;
  const linkedGameCornerSession = visit.locationId === "gamecorner"
    ? (state.gameCornerSessions || []).find((session) => session.actionVisitId === visit.id)
    : null;
  const linkedWheelSession = visit.wheelSessionId
    ? (state.wheelSessions || []).find((session) => session.id === visit.wheelSessionId)
    : null;
  return !visit.undone
    && !visit.cancelled
    && !["undone", "cancelled"].includes(String(visit.status || "").toLowerCase())
    && !["undone", "cancelled"].includes(String(linkedGameCornerSession?.status || "").toLowerCase())
    && !["undone", "cancelled"].includes(String(linkedWheelSession?.status || "").toLowerCase());
}

function activeActionVisitsForPlayer(playerId = activePlayer().id, series = state.series, gym = state.gym) {
  return actionVisitsForPlayer(playerId, series, gym).filter(isActiveActionVisit);
}

function actionUsedByPlayer(playerId = activePlayer().id, series = state.series, gym = state.gym) {
  return activeActionVisitsForPlayer(playerId, series, gym)
    .reduce((total, visit) => total + Number(visit.actionCost || 1), 0);
}

function actionRemainingForPlayer(playerId = activePlayer().id, series = state.series, gym = state.gym) {
  return Math.max(0, actionPhaseRules.actionsPerPlayer - actionUsedByPlayer(playerId, series, gym));
}

function currentActionOperation(series = state.series, gym = state.gym) {
  const gymState = ensureActionPhaseGymState(series, gym);
  return gymState.actionOperations.find((operation) => operation.id === gymState.activeActionOperationId && operation.status === "resolving")
    || gymState.actionOperations.find((operation) => operation.status === "resolving")
    || null;
}

function actionOperationForVisit(visitId, series = state.series, gym = state.gym) {
  return ensureActionPhaseGymState(series, gym).actionOperations.find((operation) => operation.visitId === visitId) || null;
}

function beginActionOperation(visit) {
  if (!visit?.id) return null;
  const gymState = ensureActionPhaseGymState(visit.series || state.series, visit.gym || state.gym);
  let operation = gymState.actionOperations.find((entry) => entry.visitId === visit.id);
  if (!operation) {
    operation = {
      id: `action-operation-${visit.id}`,
      visitId: visit.id,
      playerId: visit.playerId,
      actionNumber: Math.max(1, actionUsedByPlayer(visit.playerId, visit.series || state.series, visit.gym || state.gym)),
      locationId: visit.locationId,
      locationName: visit.locationName,
      serviceId: visit.serviceId || "",
      committed: true,
      committedAt: visit.createdAt || new Date().toISOString(),
      status: "resolving",
      linkedFeatureType: "",
      linkedFeatureSessionId: "",
      linkedPendingSituationId: "",
      completedAt: "",
      completionReason: ""
    };
    gymState.actionOperations.push(operation);
  }
  gymState.activeActionOperationId = operation.id;
  const destinationCommit = gymState.destinationCommit;
  if (destinationCommit
    && destinationCommit.playerId === visit.playerId
    && destinationCommit.locationId === visit.locationId
    && destinationCommit.serviceId === (visit.serviceId || "")
    && destinationCommit.status === provisionalDeclarationRuntime.DESTINATION_STATES.ACCEPTED) {
    destinationCommit.status = provisionalDeclarationRuntime.DESTINATION_STATES.RESOLVING;
    destinationCommit.operationId = operation.id;
  }
  visit.actionOperationId = operation.id;
  visit.actionOperationStatus = operation.status;
  return operation;
}

function commitActionVisit(visit) {
  if (!visit?.id) return null;
  const visits = actionVisitsForPlayer(visit.playerId, visit.series || state.series, visit.gym || state.gym);
  if (!visits.some((entry) => entry.id === visit.id)) visits.push(visit);
  beginActionOperation(visit);
  return visit;
}

function linkActionOperation(visitId, { featureType = "", featureSessionId = "", pendingSituationId = "" } = {}) {
  const operation = actionOperationForVisit(visitId);
  if (!operation) return null;
  if (featureType) operation.linkedFeatureType = featureType;
  if (featureSessionId) operation.linkedFeatureSessionId = featureSessionId;
  if (pendingSituationId) operation.linkedPendingSituationId = pendingSituationId;
  return operation;
}

function linkedActionOperationSession(operation) {
  if (!operation?.linkedFeatureSessionId) return null;
  const collections = {
    wheel: state.wheelSessions,
    "silph-co": state.silphCoSessions,
    "bulletin-board": state.bulletinBoardSessions,
    breeder: null,
    "game-corner": state.gameCornerSessions,
    "pokemon-center": state.pokemonCenterSessions,
    graveyard: state.graveyardSessions,
    "department-store": state.departmentStoreVisits,
    pc: state.pcSessions
  };
  return (collections[operation.linkedFeatureType] || []).find((session) => session.id === operation.linkedFeatureSessionId) || null;
}

function actionOperationBlockReason(operation) {
  if (!operation || operation.status !== "resolving") return "";
  const pending = typeof getCurrentPendingEvent === "function" ? getCurrentPendingEvent() : null;
  if (pending) return "A linked pending effect or response chain is still open.";
  if (operation.linkedPendingSituationId) {
    const notification = (state.playerNotifications || []).find((entry) => entry.id === operation.linkedPendingSituationId);
    if (notification && !["completed", "resolved", "cancelled", "dismissed"].includes(String(notification.status || "pending").toLowerCase())) {
      return "A required manual task or mandatory follow-up is still open.";
    }
  }
  const requiredFollowup = (state.playerNotifications || []).find((entry) => entry.payload?.actionVisitId === operation.visitId
    && entry.requiresAction !== false
    && !["completed", "resolved", "cancelled", "dismissed"].includes(String(entry.status || "pending").toLowerCase()));
  if (requiredFollowup) return "A required manual task or mandatory follow-up is still open.";
  const wheel = (state.wheelSessions || []).find((session) => session.sourceActionVisitId === operation.visitId || session.actionVisitId === operation.visitId);
  if (wheel && !["completed", "cancelled", "undone"].includes(String(wheel.status || "").toLowerCase())) return "The linked wheel session is still open.";
  const session = linkedActionOperationSession(operation);
  if (!session) return "";
  const status = String(session.status || "").toLowerCase();
  if (operation.linkedFeatureType === "bulletin-board") return session.confirmed ? "" : "The required quest confirmation is still open.";
  if (["breeder", "game-corner", "pokemon-center", "graveyard", "pc", "department-store"].includes(operation.linkedFeatureType)) {
    return session.actionOperationReady ? "" : "The location visit is still open.";
  }
  return ["completed", "cancelled", "undone"].includes(status) ? "" : "The linked location session is still unfinished.";
}

function completeActionOperationForVisit(visitId, completionReason = "location-flow-complete", series = state.series, gym = state.gym) {
  const operation = actionOperationForVisit(visitId, series, gym);
  if (!operation) return false;
  if (operation.status === "completed") return true;
  const blocker = actionOperationBlockReason(operation);
  if (blocker) {
    const pending = typeof getCurrentPendingEvent === "function" ? getCurrentPendingEvent() : null;
    if (pending?.id) operation.linkedPendingSituationId = pending.id;
    return false;
  }
  operation.status = "completed";
  operation.completedAt = new Date().toISOString();
  operation.completionReason = completionReason;
  const gymState = ensureActionPhaseGymState(series, gym);
  if (gymState.destinationCommit?.operationId === operation.id) {
    gymState.destinationCommit.status = provisionalDeclarationRuntime.DESTINATION_STATES.COMPLETED;
    gymState.destinationCommit.completedAt = operation.completedAt;
  }
  if (gymState.activeActionOperationId === operation.id) gymState.activeActionOperationId = "";
  const visit = actionVisitById(visitId, operation.playerId, series, gym);
  if (visit) visit.actionOperationStatus = "completed";
  return true;
}

function clearActionOperationForUndoneVisit(visitId, playerId = activePlayer().id, series = state.series, gym = state.gym) {
  if (!visitId) return false;
  const gymState = ensureActionPhaseGymState(series, gym);
  const removedOperations = (gymState.actionOperations || []).filter((operation) => operation.visitId === visitId);
  const removedOperationIds = new Set(removedOperations.map((operation) => operation.id));
  if (removedOperationIds.size) {
    gymState.actionOperations = (gymState.actionOperations || []).filter((operation) => !removedOperationIds.has(operation.id));
  }
  if (removedOperationIds.has(gymState.activeActionOperationId)) gymState.activeActionOperationId = "";
  const commit = gymState.destinationCommit;
  if (commit && (removedOperationIds.has(commit.operationId) || (commit.playerId === playerId && commit.operationId && removedOperations.some((operation) => operation.locationId === commit.locationId)))) {
    gymState.destinationCommit = null;
  } else if (staleActionDestinationCommit(gymState)) {
    gymState.destinationCommit = null;
  }
  return Boolean(removedOperationIds.size || !gymState.destinationCommit);
}

async function finishCurrentActionOperation() {
  let operation = currentActionOperation();
  if (!operation) return;
  if (backendSync.enabled && backendSync.hydrated) {
    try {
      await ensureBackendStateSavedBeforeAuthoritativeMutation();
    } catch (error) {
      alert(error?.message || "The current game state could not be saved before finishing this Action.");
      return;
    }
    operation = currentActionOperation();
    if (!operation) return;
  }
  const session = linkedActionOperationSession(operation);
  if (session && ["breeder", "game-corner", "pokemon-center", "graveyard", "pc", "department-store"].includes(operation.linkedFeatureType)) {
    session.actionOperationReady = true;
    session.actionOperationFinishedAt = new Date().toISOString();
    session.status = "completed";
    session.completedAt ||= session.actionOperationFinishedAt;
  }
  const blocker = actionOperationBlockReason(operation);
  if (blocker) {
    alert(blocker);
    return;
  }
  if (backendSync.enabled && backendSync.hydrated) {
    try {
      const gymState = ensureActionPhaseGymState();
      const commit = gymState.destinationCommit;
      if (!commit?.id || commit.operationId !== operation.id) throw new Error("The Action destination no longer matches this visit.");
      const response = await backendFetch(`/api/games/${encodeURIComponent(backendSync.gameId)}/action-destination-commits/${encodeURIComponent(commit.id)}/complete`, {
        method: "POST",
        body: JSON.stringify({
          clientId: backendSync.clientId,
          expectedVersion: Number(backendSync.version || 0),
          operationId: operation.id
        })
      });
      const payload = await readAuthoritativeTimingResponse(response);
      if (!applyAuthoritativeTimingPayload(payload, { renderAfter: true, hydrateDeclaration: false })) {
        backendSync.lastSavedAt = payload.updatedAt || backendSync.lastSavedAt || "";
        setBackendSaveStatus("saved");
        render();
      }
      return;
    } catch (error) {
      alert(error?.message || "The Action visit could not be completed.");
      return;
    }
  }
  completeActionOperationForVisit(operation.visitId, "location-session-finished");
  saveState();
  render();
}

function actionTurnInfo(series = state.series, gym = state.gym) {
  const orderIds = actionPhaseTurnOrderPlayerIds(series, gym);
  const totalActionUnits = orderIds.reduce((total, playerId) => total + actionUsedByPlayer(playerId, series, gym), 0);
  const operation = currentActionOperation(series, gym);
  if (operation && orderIds.includes(operation.playerId)) {
    return {
      orderIds,
      currentPlayerId: operation.playerId,
      currentIndex: orderIds.indexOf(operation.playerId),
      totalActionUnits,
      allComplete: false,
      resolving: true,
      operation
    };
  }
  const allComplete = orderIds.every((playerId) => actionRemainingForPlayer(playerId, series, gym) <= 0);
  if (!orderIds.length || allComplete) {
    return {
      orderIds,
      currentPlayerId: "",
      currentIndex: -1,
      totalActionUnits,
      allComplete
    };
  }
  for (let offset = 0; offset < orderIds.length; offset += 1) {
    const index = (totalActionUnits + offset) % orderIds.length;
    const playerId = orderIds[index];
    if (actionRemainingForPlayer(playerId, series, gym) > 0) {
      return {
        orderIds,
        currentPlayerId: playerId,
        currentIndex: index,
        totalActionUnits,
        allComplete: false
      };
    }
  }
  return {
    orderIds,
    currentPlayerId: "",
    currentIndex: -1,
    totalActionUnits,
    allComplete: true
  };
}

function actionLocationById(locationId) {
  return actionPhaseRules.locations.find((location) => location.id === locationId);
}

function actionLocationCanConfirm(location, playerId = activePlayer().id, actionCost = Number(location?.actionCost || 1)) {
  if (!location) return { ok: false, reason: "Choose a location first." };
  if (currentPhase() !== "action") {
    return { ok: false, reason: `Current phase is ${phaseLabels[currentPhase()]}. Action visits are normally made during Action Phase.` };
  }
  const provisional = currentProvisionalDeclaration();
  if (provisional) {
    const declarer = state.players.find((player) => player.id === provisional.payload?.declaringPlayerId);
    return {
      ok: false,
      reason: `${declarer?.name || "A player"} is completing a ${provisional.payload?.effectName || "Control effect"} declaration. Withdraw or confirm it before choosing a destination.`
    };
  }
  const acceptedDestination = provisionalDeclarationRuntime.activeDestinationCommit(ensureActionPhaseGymState());
  if (acceptedDestination) {
    return { ok: false, reason: "This Action destination has already been committed and is starting." };
  }
  const turn = actionTurnInfo();
  if (turn.resolving) {
    const owner = state.players.find((player) => player.id === turn.currentPlayerId);
    return { ok: false, reason: `${owner?.name || "The active trainer"} is still resolving their current Action.` };
  }
  if (!hostTestingOverrideEnabled() && turn.currentPlayerId && playerId !== turn.currentPlayerId) {
    const currentTurnPlayer = state.players.find((player) => player.id === turn.currentPlayerId);
    return { ok: false, reason: `It is ${currentTurnPlayer?.name || "another trainer"}'s Action Phase turn.` };
  }
  if (actionRemainingForPlayer(playerId) < Number(actionCost || 1)) {
    return { ok: false, reason: "No actions remaining for this trainer." };
  }
  if (location.visitLimit?.scope === "exploration-phase") {
    const alreadyVisited = activeActionVisitsForPlayer(playerId).some((visit) => visit.locationId === location.id);
    if (alreadyVisited) return { ok: false, reason: `${location.name} can only be visited once per Action Phase.` };
  }
  if (location.visitLimit?.scope === "gym") {
    const alreadyVisited = activeActionVisitsForPlayer(playerId).some((visit) => visit.locationId === location.id);
    if (alreadyVisited) return { ok: false, reason: `${location.name} can only be visited once per Gym.` };
  }
  return { ok: true, reason: "" };
}

function wheelDefinitionById(wheelId) {
  if (wheelId === "trainer-class-wheel") return wheelDefinitions.trainerClassWheel || null;
  return wheelDefinitions[wheelId] || null;
}

function actionVisitById(visitId, playerId = activePlayer().id, series = state.series, gym = state.gym) {
  return actionVisitsForPlayer(playerId, series, gym).find((visit) => visit.id === visitId) || null;
}

function pendingWheelSessions() {
  state.wheelSessions ||= [];
  state.wheelSessions.forEach((session) => {
    if (session.wheelId === "trainer-class-wheel") session.wheelId = "trainerClassWheel";
    if (session.wheelId === "trainerClassWheel") {
      session.sourceType ||= "token";
      session.sourceLabel ||= session.tokenName || "Trainer Class Token";
      session.targetPlayerId ||= session.playerId;
      session.maxRolls = Number(session.maxRolls || 1);
    }
  });
  return state.wheelSessions.filter((session) => ["pending", "review"].includes(session.status));
}

function selectedWheelSession() {
  const pending = pendingWheelSessions();
  if (!pending.length) return null;
  let session = pending.find((entry) => entry.id === state.selectedWheelSessionId);
  if (!session) {
    session = pending[0];
    state.selectedWheelSessionId = session.id;
  }
  return session;
}

function activeWheelVisit() {
  const pending = pendingWheelSessions();
  const selected = selectedWheelSession();
  const candidates = [selected, ...pending.filter((session) => session?.id !== selected?.id)].filter(Boolean);
  for (const session of candidates) {
    if (session.wheelId === "trainer-class-wheel") session.wheelId = "trainerClassWheel";
    const isTokenWheel = session.sourceType === "token" || session.wheelId === "trainerClassWheel";
    const visit = isTokenWheel ? null : actionVisitById(session.sourceActionVisitId, session.playerId, session.series, session.gym);
    const wheel = wheelDefinitionById(session.wheelId);
    if (!wheel) continue;
    if (!visit && !isTokenWheel) continue;
    state.selectedWheelSessionId = session.id;
    return { session, visit, wheel, player: state.players.find((player) => player.id === session.playerId) || activePlayer() };
  }
  return null;
}

function createWheelSession({ wheelId, visit, player, location }) {
  const wheel = wheelDefinitionById(wheelId);
  if (!wheel) return null;
  state.wheelSessions ||= [];
  const session = {
    id: `wheel-session-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
    wheelId,
    playerId: player.id,
    sourceActionVisitId: visit.id,
    sourceLabel: location?.name || "Wheel",
    series: state.series,
    gym: Number(state.gym),
    phase: currentPhase(),
    maxRolls: Number(wheel.maxRollsPerVisit || 0),
    status: "pending",
    rolls: [],
    createdAt: new Date().toISOString(),
    completedAt: null
  };
  state.wheelSessions.push(session);
  visit.wheelSessionId = session.id;
  state.selectedWheelSessionId = session.id;
  state.wheelDrawerOpen = true;
  return session;
}

function createTrainerClassWheelSession({ actorPlayer, targetPlayer, consumedToken, definition, previousPlayers, previousPokemonRecords, previousTokenActivations, previousWheelSessions }) {
  const wheel = wheelDefinitionById("trainerClassWheel");
  if (!wheel || !actorPlayer || !targetPlayer || !consumedToken) return null;
  state.wheelSessions ||= [];
  const session = {
    id: `wheel-session-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
    wheelId: "trainerClassWheel",
    playerId: actorPlayer.id,
    targetPlayerId: targetPlayer.id,
    sourceType: "token",
    sourceLabel: consumedToken.name,
    sourceActionVisitId: "",
    tokenId: consumedToken.id,
    tokenName: consumedToken.name,
    tokenDefinitionId: tokenDefinitionId(utilityTokenDefinitions, definition),
    series: state.series,
    gym: Number(state.gym),
    phase: currentPhase(),
    maxRolls: 1,
    status: "pending",
    rolls: [],
    createdAt: new Date().toISOString(),
    completedAt: null,
    undoSnapshot: {
      actionType: "undoUtilityTokenActivation",
      previousPlayers,
      previousPokemonRecords,
      previousTokenActivations,
      previousWheelSessions
    }
  };
  state.wheelSessions.push(session);
  state.selectedWheelSessionId = session.id;
  state.wheelDrawerOpen = true;
  return session;
}

function weightedWheelOutcome(wheel) {
  const totalWeight = wheel.outcomes.reduce((total, outcome) => total + Number(outcome.weight || 0), 0);
  let roll = Math.random() * totalWeight;
  for (const outcome of wheel.outcomes) {
    roll -= Number(outcome.weight || 0);
    if (roll <= 0) return outcome;
  }
  return wheel.outcomes[wheel.outcomes.length - 1];
}

function wheelOutcomeSegmentDegrees(wheel, outcomeId) {
  const totalWeight = wheel.outcomes.reduce((total, outcome) => total + Number(outcome.weight || 0), 0) || 1;
  let cursor = 0;
  for (const outcome of wheel.outcomes) {
    const span = (Number(outcome.weight || 0) / totalWeight) * 360;
    if (outcome.id === outcomeId) return { start: cursor, end: cursor + span, span };
    cursor += span;
  }
  return { start: 0, end: 0, span: 0 };
}

function wheelOutcomeLandingDegrees(wheel, outcomeId) {
  const segment = wheelOutcomeSegmentDegrees(wheel, outcomeId);
  if (!segment.span) return 0;
  const padding = Math.min(segment.span * 0.18, 8);
  const start = segment.start + padding;
  const end = segment.end - padding;
  if (end <= start) return segment.start + (segment.span / 2);
  return start + Math.random() * (end - start);
}

function wheelOutcomeSegments(wheel) {
  const totalWeight = wheel.outcomes.reduce((total, outcome) => total + Number(outcome.weight || 0), 0) || 1;
  let cursor = 0;
  return wheel.outcomes.map((outcome) => {
    const span = (Number(outcome.weight || 0) / totalWeight) * 360;
    const segment = {
      outcomeId: outcome.id,
      label: outcome.label,
      startAngle: cursor,
      endAngle: cursor + span,
      weight: Number(outcome.weight || 0)
    };
    cursor += span;
    return segment;
  });
}

function wheelSegmentAtPointer(rotationAngle, segments) {
  if (!segments?.length) return null;
  const angleUnderPointer = normalizeAngle(0 - rotationAngle);
  return segments.find((segment, index) => {
    const end = index === segments.length - 1 ? 360.000001 : segment.endAngle;
    return angleUnderPointer >= segment.startAngle && angleUnderPointer < end;
  }) || segments[segments.length - 1];
}

function updateWheelLivePointerDisplay({ status = "Passing", finalOutcomeId = "", finalLabel = "" } = {}) {
  const display = els.wheelLatestResult;
  const wheelDisc = els.wheelVisual?.querySelector(".wheel-disc");
  const segments = JSON.parse(display?.dataset.segments || "[]");
  if (!display || !segments.length) return null;
  let segment = finalOutcomeId ? segments.find((entry) => entry.outcomeId === finalOutcomeId) : null;
  if (!segment && wheelDisc) {
    segment = wheelSegmentAtPointer(rotationFromTransform(getComputedStyle(wheelDisc).transform), segments);
  }
  const outcomeId = finalOutcomeId || segment?.outcomeId || "";
  const label = finalLabel || segment?.label || "Ready";
  display.innerHTML = `
    <span>${escapeHtml(status)}</span>
    <strong>${escapeHtml(label)}</strong>
  `;
  els.wheelOutcomes?.querySelectorAll("[data-wheel-outcome-id]").forEach((entry) => {
    entry.classList.toggle("pointer-active", entry.dataset.wheelOutcomeId === outcomeId);
  });
  return segment;
}

function playCommittedTrainerClassWheelAnimation(sessionId, startRotation, finalRotation, outcome) {
  const session = state.wheelSessions.find((entry) => entry.id === sessionId);
  if (!session || session.wheelId !== "trainerClassWheel") return;
  const disc = els.wheelVisual?.querySelector(".wheel-disc");
  if (!disc) return;
  let liveTimer = null;
  let finished = false;
  const finishVisual = () => {
    if (finished) return;
    finished = true;
    if (liveTimer) clearInterval(liveTimer);
    const latestSession = state.wheelSessions.find((entry) => entry.id === sessionId);
    if (latestSession) {
      latestSession.visualSpinUntil = 0;
      latestSession.visualSpinOutcomeId = "";
      latestSession.visualRotation = finalRotation;
    }
    updateWheelLivePointerDisplay({
      status: "Class result",
      finalOutcomeId: outcome?.id || "",
      finalLabel: outcome?.label || ""
    });
    saveState();
    render();
  };
  els.wheelVisual.classList.remove("spinning");
  disc.style.transition = "none";
  disc.style.setProperty("--wheel-rotation", `${Number(startRotation || 0)}deg`);
  void disc.offsetWidth;
  els.wheelVisual.classList.add("spinning");
  disc.style.transition = "";
  liveTimer = setInterval(() => {
    try {
      updateWheelLivePointerDisplay({ status: "Passing" });
    } catch (error) {
      console.warn("Trainer Class Wheel live display failed", error);
      clearInterval(liveTimer);
    }
  }, 80);
  requestAnimationFrame(() => {
    updateWheelLivePointerDisplay({ status: "Passing" });
    disc.style.setProperty("--wheel-rotation", `${Number(finalRotation || 0)}deg`);
  });
  disc.addEventListener("transitionend", finishVisual, { once: true });
  setTimeout(finishVisual, 5600);
}

function nextWheelLandingRotation(session, wheel, outcomeId) {
  const current = Number(session.visualRotation || 0);
  const currentTurn = ((current % 360) + 360) % 360;
  const targetTurn = (360 - wheelOutcomeLandingDegrees(wheel, outcomeId)) % 360;
  let delta = targetTurn - currentTurn;
  if (delta < 0) delta += 360;
  return current + 2160 + delta;
}

function applyWheelReward(player, wheel, outcome, rollId, session, visit) {
  if (outcome.rewardType !== "token") return { reward: null, note: "No reward" };
  const isGameCorner = wheel.id === "gameCornerGamble";
  const gcTokenDefinition = isGameCorner ? gameCornerTokenDefinitionByTier(outcome.rewardData?.gameCornerTier || outcome.rewardData?.tier || outcome.label) : null;
  const reward = {
    id: `${gcTokenDefinition?.id || `${wheel.id}-${outcome.id}`}-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
    name: gcTokenDefinition?.name || outcome.rewardData?.name || `${outcome.label} Reward`,
    type: isGameCorner ? "TICKET" : "TOKEN",
    tokenType: isGameCorner ? "game-corner" : "wheel",
    tier: isGameCorner ? "Tickets" : gcTokenDefinition?.gameCornerTier || outcome.rewardData?.tier || outcome.label,
    gameCornerTier: gcTokenDefinition?.gameCornerTier || "",
    gameCornerTierId: gcTokenDefinition?.gameCornerTierId || "",
    description: gcTokenDefinition?.description || "",
    price: 0,
    source: wheel.name,
    playerId: player.id,
    series: session?.series || state.series,
    gym: Number(session?.gym || state.gym),
    wheelId: wheel.id,
    wheelSessionId: session?.id || "",
    actionVisitId: visit?.id || session?.sourceActionVisitId || "",
    sourceVisitId: visit?.id || session?.sourceActionVisitId || "",
    wheelRollId: rollId,
    acquiredAt: new Date().toISOString()
  };
  player.inventory.unshift(reward);
  return { reward, note: `Awarded ${reward.name}` };
}

function completeTrainerClassWheelSpin(session, outcome) {
  if (!session || !["pending", "review"].includes(session.status) || session.wheelId !== "trainerClassWheel") return false;
  const wheel = wheelDefinitionById("trainerClassWheel");
  const player = state.players.find((candidate) => candidate.id === session.playerId) || activePlayer();
  const targetPlayer = state.players.find((candidate) => candidate.id === (session.targetPlayerId || player.id)) || player;
  if (!wheel || !player || !targetPlayer || !outcome) return false;
  session.isSpinning = false;
  session.pendingOutcomeId = "";
  state.selectedWheelSessionId = session.id;
  session.rolls ||= [];
  const isReroll = session.status === "review" && session.rolls.length > 0;
  if (!isReroll && session.rolls.length >= Number(session.maxRolls || wheel.maxRollsPerVisit || 1)) {
    session.status = "review";
    session.completedAt ||= new Date().toISOString();
    return true;
  }
  const previousClass = targetPlayer.trainerClass || "None";
  const nextClass = outcome.rewardData?.trainerClass || outcome.label || "";
  const rollId = `wheel-roll-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`;
  targetPlayer.trainerClass = nextClass;
  const roll = {
    id: rollId,
    wheelId: wheel.id,
    wheelSessionId: session.id,
    actionVisitId: "",
    sourceVisitId: "",
    gameCornerSessionId: "",
    playerId: player.id,
    targetPlayerId: targetPlayer.id,
    series: session.series,
    gym: Number(session.gym),
    outcomeId: outcome.id,
    outcomeLabel: outcome.label,
    result: outcome.label,
    cost: 0,
    costPaid: 0,
    reward: null,
    rewardId: "",
    rewardName: "",
    ledgerEntryId: "",
    reroll: isReroll,
    timestamp: new Date().toISOString()
  };
  session.rolls.push(roll);
  session.rollIds = session.rolls.map((entry) => entry.id);
  const activation = {
    id: `token-activation-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
    tokenId: session.tokenId || "",
    tokenName: session.tokenName || wheel.name,
    tokenDefinitionId: session.tokenDefinitionId || "",
    tokenCategory: "control",
    actorPlayerId: player.id,
    targetPlayerId: targetPlayer.id,
    series: state.series,
    gym: Number(state.gym),
    phase: currentPhase(),
    wheelSessionId: session.id,
    result: nextClass,
    details: [`${player.name} ${isReroll ? "rerolled" : "used"} ${session.tokenName || wheel.name}`, `Spun ${wheel.name}.`, `${targetPlayer.name}: ${previousClass} -> ${nextClass}`],
    createdAt: new Date().toISOString()
  };
  state.tokenActivations ||= [];
  state.tokenActivations.unshift(activation);
  const details = [
    `${player.name} ${isReroll ? "rerolled" : "used"} ${session.tokenName || wheel.name}`,
    `${isReroll ? "Rerolled" : "Spun"} ${wheel.name}`,
    `Result: ${nextClass}`,
    `${targetPlayer.name}: ${previousClass} -> ${nextClass}`
  ];
  const classLogEntry = addLogEntry({
    action: "token",
    category: "tokens",
    player: player.name,
    item: `${player.name} ${isReroll ? "rerolled" : "used"} ${session.tokenName || wheel.name}: ${targetPlayer.name} became ${nextClass}`,
    title: `${player.name} ${isReroll ? "rerolled" : "spun"} ${wheel.name}`,
    summary: details.join("\n"),
    details,
    type: "trainer-class-wheel",
    categories: ["tokens", "control", "classes", "wheel"],
    tags: ["token", "control", "trainer-class-wheel", session.tokenName || "", nextClass],
    subtypes: ["Control", "Trainer Class"],
    playerIds: [...new Set([player.id, targetPlayer.id])],
    tokenNames: session.tokenName ? [session.tokenName] : [],
    tokenActivationId: activation.id,
    wheelSessionId: session.id,
    wheelId: wheel.id,
    result: nextClass,
    undoable: true,
    undone: false,
    undoData: session.undoSnapshot || { actionType: "undoUtilityTokenActivation" }
  });
  roll.activityLogEntryId = classLogEntry?.id || "";
  session.status = "review";
  session.completedAt = new Date().toISOString();
  return true;
}

function completeWheelSpin(sessionId, outcomeId) {
  const session = state.wheelSessions.find((entry) => entry.id === sessionId);
  if (!session || session.status !== "pending") return;
  session.isSpinning = false;
  session.pendingOutcomeId = "";
  state.selectedWheelSessionId = session.id;
  if (session.wheelId === "trainer-class-wheel") session.wheelId = "trainerClassWheel";
  const wheel = wheelDefinitionById(session.wheelId);
  const outcome = wheel?.outcomes.find((entry) => entry.id === outcomeId) || (wheel ? weightedWheelOutcome(wheel) : null);
  if (session.wheelId === "trainerClassWheel") {
    if (completeTrainerClassWheelSpin(session, outcome)) {
      saveState();
      render();
    }
    return;
  }
  const player = state.players.find((candidate) => candidate.id === session.playerId) || activePlayer();
  const isTokenWheel = session.sourceType === "token" || session.wheelId === "trainerClassWheel";
  const visit = isTokenWheel ? null : actionVisitById(session.sourceActionVisitId, session.playerId, session.series, session.gym);
  if (!wheel || !player || (!visit && !isTokenWheel)) return;
  const gameCornerSession = visit
    ? (state.gameCornerSessions || []).find((session) => session.gambleWheelSessionId === sessionId || session.actionVisitId === visit.id)
    : null;
  session.rolls ||= [];
  if (visit) visit.wheelRolls ||= [];
  if (session.rolls.length >= Number(session.maxRolls || wheel.maxRollsPerVisit || Infinity)) return;
  const cost = Number(wheel.cost?.amount || 0);
  if (wheel.cost?.type === "money" && Number(player.balance || 0) < cost) {
    els.wheelLatestResult.textContent = `Not enough money to spin (${formatMoney(cost)} required).`;
    return;
  }
  const rollId = `wheel-roll-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`;
  let ledgerEntryId = null;
  if (wheel.cost?.type === "money" && cost > 0) {
    const moneyChange = applyPlayerMoneyChange(player, -cost, {
      direction: "spend",
      sourceType: wheel.id === "gameCornerGamble" ? "game-corner-spin" : "wheel-spin",
      sourceLabel: `${wheel.name} spin`,
      note: `${outcome.label} result`,
      wheelSessionId: session.id,
      actionVisitId: visit.id,
      sourceVisitId: visit.id,
      gameCornerSessionId: gameCornerSession?.id || "",
      result: outcome.label,
      breakdown: { wheelId: wheel.id, wheelSessionId: session.id, gameCornerSessionId: gameCornerSession?.id || "", actionVisitId: visit.id, rollId, outcomeId: outcome.id }
    });
    ledgerEntryId = moneyChange.ledgerEntry?.id || null;
  }
  const rewardResult = wheel.id === "trainerClassWheel"
    ? { reward: null, note: outcome.label }
    : applyWheelReward(player, wheel, outcome, rollId, session, visit);
  const roll = {
    id: rollId,
    wheelId: wheel.id,
    wheelSessionId: session.id,
    actionVisitId: visit?.id || "",
    sourceVisitId: visit?.id || "",
    gameCornerSessionId: gameCornerSession?.id || "",
    playerId: player.id,
    series: session.series,
    gym: Number(session.gym),
    outcomeId: outcome.id,
    outcomeLabel: outcome.label,
    result: outcome.label,
    cost,
    costPaid: cost,
    reward: rewardResult.reward,
    rewardId: rewardResult.reward?.id || "",
    rewardName: rewardResult.reward?.name || "",
    ledgerEntryId,
    timestamp: new Date().toISOString()
  };
  session.rolls.push(roll);
  session.rollIds = session.rolls.map((entry) => entry.id);
  if (visit) visit.wheelRolls.push(roll);
  if (wheel.id === "gameCornerGamble" && gameCornerSession) {
    const groupedEntry = updateGameCornerActionLog(gameCornerSession, player, (entry) => {
      appendLogCategory(entry, "wheel");
      appendLogCategory(entry, "money");
      appendUniqueLogValue(entry, "tags", "game-corner-spin");
      appendUniqueLogValue(entry, "wheelSessionIds", session.id);
      appendUniqueLogValue(entry, "ledgerEntryIds", ledgerEntryId);
      if (rewardResult.reward) {
        appendLogCategory(entry, "items");
        appendUniqueLogValue(entry, "tokenNames", rewardResult.reward.name);
        appendUniqueLogValue(entry, "itemNames", rewardResult.reward.name);
        appendUniqueLogValue(entry, "tokenIds", rewardResult.reward.id);
      }
      entry.moneyChanges ||= [];
      entry.moneyChanges.push({
        amount: -cost,
        direction: "spend",
        sourceType: "game-corner-spin",
        sourceLabel: `${wheel.name} spin`,
        result: outcome.label,
        ledgerEntryId,
        wheelSessionId: session.id,
        actionVisitId: visit.id
      });
      entry.childEvents ||= [];
      entry.childEvents.push({
        type: "wheel-spin",
        category: "wheel",
        result: outcome.label,
        costPaid: cost,
        rewardName: rewardResult.reward?.name || "",
        ledgerEntryId,
        rollId,
        wheelSessionId: session.id,
        timestamp: roll.timestamp
      });
      appendGroupedLogDetail(entry, `Slot Machine spin ${session.rolls.length}: ${outcome.label}. Spent ${formatMoney(cost)}.${rewardResult.reward ? ` Received ${rewardResult.reward.name}.` : ""}`);
    });
    roll.activityLogEntryId = groupedEntry?.id || "";
  } else {
    const spinLogEntry = addLogEntry({
      action: "wheel",
      category: "wheel",
      subtype: wheel.name,
      player: player.name,
      item: `${player.name} spun ${wheel.name}: ${outcome.label}. Spent ${formatMoney(cost)}.${rewardResult.reward ? ` Received ${rewardResult.reward.name}.` : ""}`,
      type: "wheel-spin",
      quantity: 1,
      price: cost,
      balanceAfter: player.balance,
      visitId: visit.id,
      actionVisitId: visit.id,
      sourceVisitId: visit.id,
      wheelSessionId: session.id,
      wheelId: wheel.id,
      sourceType: "wheel",
      result: outcome.label,
      costPaid: cost,
      rewardName: rewardResult.reward?.name || "",
      itemNames: rewardResult.reward ? [rewardResult.reward.name] : [],
      playerIds: [player.id]
    });
    roll.activityLogEntryId = spinLogEntry?.id || "";
  }
  if (ledgerEntryId) {
    const ledgerEntry = (state.moneyLedger || []).find((entry) => entry.id === ledgerEntryId);
    if (ledgerEntry) ledgerEntry.rewardName = rewardResult.reward?.name || "";
  }
  if (session.rolls.length >= Number(session.maxRolls || wheel.maxRollsPerVisit || Infinity)) {
    session.status = "review";
    session.completedAt = new Date().toISOString();
    if (wheel.id === "gameCornerGamble" && gameCornerSession) {
      updateGameCornerActionLog(gameCornerSession, player, (entry) => {
        appendGroupedLogDetail(entry, `Slot Machine session ready to close after ${session.rolls.length} spins.`);
      });
    } else if (wheel.id !== "trainerClassWheel") {
      addLogEntry({
        action: "wheel",
        category: "other",
        player: player.name,
        item: `${wheel.name} session completed: ${session.rolls.length}/${session.maxRolls} spins used`,
        type: "wheel-session-complete",
        quantity: session.rolls.length,
        price: 0,
        balanceAfter: player.balance,
        wheelSessionId: session.id,
        wheelId: wheel.id,
        playerIds: [player.id]
      });
    }
  }
  saveState();
  render();
}

function spinActiveWheel() {
  const active = activeWheelVisit();
  if (!active) return;
  const { session, wheel, player } = active;
  const isTrainerClassWheel = wheel.id === "trainerClassWheel";
  const canRerollTrainerClass = isTrainerClassWheel && session.status === "review" && (session.rolls || []).length > 0;
  if ((!canRerollTrainerClass && session.status !== "pending") || session.isSpinning) return;
  if (!canRerollTrainerClass && (session.rolls || []).length >= Number(session.maxRolls || wheel.maxRollsPerVisit || Infinity)) return;
  const cost = Number(wheel.cost?.amount || 0);
  if (wheel.cost?.type === "money" && Number(player.balance || 0) < cost) {
    els.wheelLatestResult.textContent = `Not enough money to spin (${formatMoney(cost)} required).`;
    return;
  }
  const outcome = weightedWheelOutcome(wheel);
  const startRotation = Number(session.visualRotation || 0);
  session.pendingOutcomeId = outcome.id;
  session.visualRotation = nextWheelLandingRotation(session, wheel, outcome.id);
  if (wheel.id === "trainerClassWheel") {
    const finalRotation = Number(session.visualRotation || 0);
    session.visualSpinUntil = Date.now() + 5600;
    session.visualSpinOutcomeId = outcome.id;
    if (completeTrainerClassWheelSpin(session, outcome)) {
      saveState();
      render();
      playCommittedTrainerClassWheelAnimation(session.id, startRotation, finalRotation, outcome);
    } else {
      session.isSpinning = false;
      session.pendingOutcomeId = "";
      session.visualSpinUntil = 0;
      session.visualSpinOutcomeId = "";
      saveState();
      render();
      alert("Could not apply Trainer Class Wheel result. Try the token again or use Admin repair.");
    }
    return;
  }
  if (state.skipWheelAnimation) {
    completeWheelSpin(session.id, outcome.id);
    return;
  }
  session.isSpinning = true;
  saveState();
  els.spinWheel.disabled = true;
  els.wheelVisual.classList.add("spinning");
  try {
    updateWheelLivePointerDisplay({ status: "Passing" });
  } catch (error) {
    console.warn("Wheel live display failed", error);
  }
  const wheelDisc = els.wheelVisual.querySelector(".wheel-disc");
  const liveTimer = setInterval(() => {
    try {
      updateWheelLivePointerDisplay({ status: "Passing" });
    } catch (error) {
      console.warn("Wheel live display failed", error);
      clearInterval(liveTimer);
    }
  }, 80);
  let finalized = false;
  const finalizeSpin = () => {
    if (finalized) return;
    finalized = true;
    clearInterval(liveTimer);
    const latestSession = state.wheelSessions.find((entry) => entry.id === session.id);
    if (!latestSession) return;
    if (latestSession.status !== "pending" && latestSession.isSpinning) {
      latestSession.isSpinning = false;
      latestSession.pendingOutcomeId = "";
      saveState();
      render();
      return;
    }
    if (latestSession.status !== "pending") return;
    completeWheelSpin(session.id, outcome.id);
  };
  wheelDisc?.addEventListener("transitionend", finalizeSpin, { once: true });
  wheelDisc?.style.setProperty("--wheel-rotation", `${Number(session.visualRotation || 0)}deg`);
  setTimeout(finalizeSpin, 5600);
}

function finishWheelSession({ skipPendingGuard = false } = {}) {
  if (!skipPendingGuard && !guardPendingEventBeforeAction("Finish Wheel Session", () => finishWheelSession({ skipPendingGuard: true }))) return;
  const active = activeWheelVisit();
  if (!active) return;
  const { session, wheel, player, visit } = active;
  const gameCornerSession = wheel.id === "gameCornerGamble" && visit
    ? (state.gameCornerSessions || []).find((entry) => entry.gambleWheelSessionId === session.id || entry.actionVisitId === visit.id)
    : null;
  if (session.isSpinning) {
    session.isSpinning = false;
    const pendingOutcomeId = session.pendingOutcomeId;
    session.pendingOutcomeId = "";
    if (pendingOutcomeId && session.status === "pending") {
      completeWheelSpin(session.id, pendingOutcomeId);
      return;
    }
    saveState();
    render();
    return;
  }
  if (wheel.id === "trainerClassWheel" && !(session.rolls || []).length) {
    alert("Spin the Trainer Class Wheel before closing this token session.");
    return;
  }
  if (session.status === "review") {
    session.status = "completed";
    if (visit?.id) completeActionOperationForVisit(visit.id, "wheel-session-closed");
    if (gameCornerSession) {
      updateGameCornerActionLog(gameCornerSession, player, (entry) => {
        appendGroupedLogDetail(entry, `Slot Machine session closed after ${(session.rolls || []).length} spins.`);
      });
    }
    const next = pendingWheelSessions().find((entry) => entry.id !== session.id);
    state.selectedWheelSessionId = next?.id || "";
    state.wheelDrawerOpen = Boolean(next);
    saveState();
    render();
    return;
  }
  session.status = "review";
  session.completedAt = new Date().toISOString();
  if (gameCornerSession) {
    updateGameCornerActionLog(gameCornerSession, player, (entry) => {
      appendGroupedLogDetail(entry, `Slot Machine session ready to close after ${(session.rolls || []).length} spins.`);
    });
  } else if (wheel.id !== "trainerClassWheel") {
    addLogEntry({
      action: "wheel",
      category: "other",
      player: player.name,
      item: `${wheel.name} session completed: ${(session.rolls || []).length}/${session.maxRolls} spins used`,
      type: "wheel-session-complete",
      quantity: (session.rolls || []).length,
      price: 0,
      balanceAfter: player.balance,
      wheelSessionId: session.id,
      wheelId: wheel.id,
      playerIds: [player.id]
    });
  }
  saveState();
  render();
}

function closeWheelPanel() {
  state.wheelDrawerOpen = false;
  saveState();
  renderWheelPanel();
}

function actionStatusLabel(playerId) {
  return `${actionUsedByPlayer(playerId)}/${actionPhaseRules.actionsPerPlayer}`;
}

function actionLocationIcon(location) {
  const icons = {
    pokemon: "PK",
    shop: "$",
    utility: "RC",
    tokens: "TK",
    recovery: "+",
    quests: "BB"
  };
  return icons[location.category] || "AP";
}

function rangerMilestoneRewardLabel(milestone) {
  return milestone.reward === "Choose a Weather Token" ? "Weather Token Choice" : milestone.reward;
}

function nextRangerMilestone(tracker) {
  const credits = Number(tracker.rangerCredits || 0);
  return actionLocationById("ranger-base")?.milestones.find((milestone) => milestone.credits > credits) || null;
}

function statusTokenDefinitionByName(name) {
  const key = slugify(name);
  return Object.values(statusTokenDefinitions).find((definition) => definition.names.some((candidate) => slugify(candidate) === key)) || null;
}

function utilityTokenDefinitionByName(name) {
  const key = slugify(name);
  return Object.values(utilityTokenDefinitions).find((definition) => definition.names.some((candidate) => slugify(candidate) === key)) || null;
}

function tokenDefinitionId(definitions, definition) {
  return Object.entries(definitions).find(([, value]) => value === definition)?.[0] || slugify(definition?.names?.[0] || "");
}

function statusTokenDefinitionId(definition) {
  return Object.entries(statusTokenDefinitions).find(([, value]) => value === definition)?.[0] || slugify(definition?.label || "");
}

function isStatusToken(item) {
  return Boolean(statusTokenDefinitionByName(item?.name || item?.id || ""));
}

function statusExpiresAt(durationGyms) {
  if (!durationGyms) return { expiresAtSeries: "", expiresAtGym: null };
  const currentIndex = Math.max(0, seriesNames.indexOf(state.series));
  const totalGymIndex = currentIndex * 9 + Number(state.gym || 1) + Number(durationGyms || 0);
  const seriesIndex = Math.floor((totalGymIndex - 1) / 9);
  const gym = ((totalGymIndex - 1) % 9) + 1;
  return {
    expiresAtSeries: seriesNames[seriesIndex] || state.series,
    expiresAtGym: gym
  };
}

function remainingStatusGyms(status) {
  if (!status?.durationGyms) return null;
  const elapsed = gymDistanceFromPlacement(status.series, status.gym, state.series, state.gym);
  return Math.max(0, Number(status.durationGyms || 0) - elapsed);
}

function activeLingeringStatuses(filter = {}) {
  return (state.lingeringStatuses || []).filter((status) => {
    if (status.status !== "active") return false;
    if (controlTokenEffects?.statusIsActive) {
      if (!controlTokenEffects.statusIsActive(status, controlTokenEffectOptions())) return false;
    } else if (status.durationGyms && remainingStatusGyms(status) <= 0) return false;
    const phaseScope = status.payload?.phaseScope;
    if (phaseScope && ((phaseScope.series && phaseScope.series !== state.series)
      || (phaseScope.gym && Number(phaseScope.gym) !== Number(state.gym))
      || (phaseScope.phase && phaseScope.phase !== currentPhase()))) return false;
    if (filter.playerId && status.targetPlayerId !== filter.playerId && status.actorPlayerId !== filter.playerId) return false;
    if (filter.targetPlayerId && status.targetPlayerId !== filter.targetPlayerId) return false;
    if (filter.pokemonId && status.targetPokemonId !== filter.pokemonId) return false;
    if (filter.pokemonNameKey && (status.targetPokemonNameKey || pokemonRuleKey(status.targetPokemonName)) !== filter.pokemonNameKey) return false;
    if (filter.type && status.type !== filter.type) return false;
    if (filter.isCurse !== undefined && Boolean(status.isCurse) !== Boolean(filter.isCurse)) return false;
    return true;
  });
}

function pokemonLingeringStatuses(pokemonId) {
  const pokemon = (state.pokemonRecords || []).find((record) => record.id === pokemonId);
  if (!pokemon) return [];
  if (controlTokenEffects?.statusAffectsPokemon) {
    return activeLingeringStatuses().filter((status) => (
      controlTokenEffects.statusAffectsPokemon(status, pokemon, controlTokenEffectOptions())
    ));
  }
  const excluded = (status) => (status.excludedRosterInstanceIds || status.payload?.excludedRosterInstanceIds || []).includes(pokemonId);
  const idStatuses = activeLingeringStatuses({ pokemonId }).filter((status) => !excluded(status));
  const nameStatuses = activeLingeringStatuses({ pokemonNameKey: pokemonRuleKey(pokemon.name) }).filter((status) => !excluded(status));
  return [...new Map([...idStatuses, ...nameStatuses].map((status) => [status.id, status])).values()];
}

function playerLingeringStatuses(playerId) {
  return activeLingeringStatuses({ targetPlayerId: playerId }).filter((status) => !status.targetPokemonId);
}

function pokemonHasActiveStatus(pokemonId, type) {
  return pokemonLingeringStatuses(pokemonId).some((status) => status.type === type);
}

function pokemonNameHasActiveStatus(name, type) {
  return activeLingeringStatuses({ pokemonNameKey: pokemonRuleKey(name), type }).length > 0;
}

function statusDisplayLabel(status) {
  const remaining = remainingStatusGyms(status);
  const suffix = remaining === null ? ""
    : remaining === 0 && status.expiresAtPhase
      ? ` - until ${phaseLabels[status.expiresAtPhase] || status.expiresAtPhase}`
      : ` - ${remaining} Gym${remaining === 1 ? "" : "s"}`;
  const labels = {
    ban: "Banned",
    restrict: "Restricted",
    safeguard: "Safeguard",
    "unban-protection": "Unban Protected",
    "buff-restrict-immune": "Restrict Immune",
    "rage-candy-enhancement": "Rage Candy Bar",
    "substitute-attached": "Substitute",
    "instance-restrict": "Instance Restricted",
    "ban-phase-protection": "Ban Protected This Phase",
    "global-move-restriction": status.payload?.moveName ? `Move Deleter: ${status.payload.moveName}` : "Move Deleter",
    "cold-wave-suppression": "Cold Wave",
    "ongoing-effect-text-replacement": "Lingering Aroma",
    "curse-move-delete": status.payload?.moveName ? `Curse: ${status.payload.moveName} Banned` : "Curse: Move Deleted",
    "curse-iron-ball": "Curse: Iron Ball",
    "curse-silencing": "Curse: Max 2 Moves",
    "curse-haze": "Curse: Buffs Negated",
    "curse-purge": "Curse: Purge",
    "curse-toxic-orb": "Curse: Toxic Orb",
    "curse-flame-orb": "Curse: Flame Orb",
    "curse-knock-off": status.payload?.targetItemOrMoveName ? `Curse: Knock Off ${status.payload.targetItemOrMoveName}` : "Curse: Knock Off",
    "curse-imprison": "Curse: Imprisoned",
    "curse-devolve": "Devolved",
    "curse-foresight": "Foresight Marked"
  };
  const suppressed = controlTokenEffects?.statusSuppressedByColdWave?.(state, status, {
    ...controlTokenEffectOptions(),
    state
  });
  return `${labels[status.type] || status.name || status.type}${suffix}${suppressed ? " - Suppressed by Cold Wave" : ""}`;
}

function expireLingeringStatuses() {
  const options = controlTokenEffectOptions();
  const expired = controlTokenEffects?.expireAtPhaseBoundary
    ? controlTokenEffects.expireAtPhaseBoundary(state, options)
    : [];
  if (currentPhase() === "start" && controlTokenEffects) {
    controlTokenEffects.expireAtStartOfGym(state, options).forEach((status) => {
      if (!expired.includes(status)) expired.push(status);
    });
  }
  if (controlTokenEffects?.expireLingeringAromaRelationships) {
    controlTokenEffects.expireLingeringAromaRelationships(state, options).forEach((status) => {
      if (!expired.includes(status)) expired.push(status);
    });
  }
  if (!controlTokenEffects) {
    (state.lingeringStatuses || []).forEach((status) => {
      if (status.status !== "active" || !status.durationGyms || remainingStatusGyms(status) > 0) return;
      status.status = "expired";
      expired.push(status);
    });
  }
  Object.values(state.globalPokemonRules || {}).forEach((rule) => {
    if (["Restricted", "Unbanned"].includes(rule.status) && ruleIsExpired(rule)) {
      const previousStatus = rule.status;
      rule.status = "Normal";
      rule.lastAction = previousStatus === "Restricted" ? "Restriction Expired" : "Unban Protection Expired";
    }
  });
  expired.forEach((status) => {
    if (!String(status.type || "").startsWith("curse-") || status.expirationLoggedAt) return;
    const pokemon = findPokemonRecord(status.targetPokemonId);
    const owner = state.players.find((player) => player.id === status.targetPlayerId || player.id === pokemon?.trainerId);
    status.expirationLoggedAt = new Date().toISOString();
    addLogEntry({
      action: "token",
      category: "tokens",
      player: owner?.name || "Curse",
      item: `${status.sourceTokenName || status.name || "Curse"} expired for ${owner?.name ? `${owner.name}'s ` : ""}${pokemon?.name || status.targetPokemonName || "Pokemon"}.`,
      type: "curse-expiration",
      categories: ["tokens", "pokemon"],
      tags: ["curse", "expiration", "exact-instance"],
      playerIds: [owner?.id].filter(Boolean),
      pokemonIds: [pokemon?.id || status.targetPokemonId].filter(Boolean)
    });
  });
  return expired;
}

function expireTokenInventoryRuntimeRecords() {
  if (!tokenInventoryRuntime?.expireInventory) return { removedTemporaryCopies: [], completedCooldowns: [] };
  const result = tokenInventoryRuntime.expireInventory(state.players || [], tokenInventoryRuntimeContext());
  (result.removedTemporaryCopies || []).forEach(({ playerId, item }) => {
    const player = state.players.find((entry) => entry.id === playerId);
    addLogEntry({
      action: "token",
      category: "tokens",
      player: player?.name || "Token Inventory",
      item: `${item.name || "Temporary copied Token"} expired unused at the end of its creation Gym.`,
      title: "Temporary Token copy expired",
      summary: "The temporary 7 Tools copy was removed from exact inventory.",
      type: "temporary-token-expiration",
      categories: ["tokens", "inventory"],
      tags: ["7-tools", "temporary-copy", "expiration"],
      playerIds: [playerId].filter(Boolean),
      tokenNames: [item.name].filter(Boolean)
    });
  });
  (result.completedCooldowns || []).forEach(({ playerId, itemId, itemName }) => {
    const player = state.players.find((entry) => entry.id === playerId);
    addLogEntry({
      action: "token",
      category: "tokens",
      player: player?.name || "Token Inventory",
      item: `${itemName} completed its Counterspell cooldown and is usable again.`,
      title: "Counterspell cooldown completed",
      summary: `Exact Token inventory ID: ${itemId}`,
      type: "token-cooldown-completed",
      categories: ["tokens", "inventory"],
      tags: ["counterspell", "cooldown", "phase-anchor"],
      playerIds: [playerId].filter(Boolean),
      tokenNames: [itemName].filter(Boolean)
    });
  });
  return result;
}

function pokemonStatusTargetOptions(player, definition) {
  const records = (state.pokemonRecords || [])
    .filter((pokemon) => pokemon.trainerId === player?.id && !["Removed"].includes(pokemon.status));
  if (definition?.targetMode === "banned-pokemon") {
    return records.filter((pokemon) => pokemonNameHasActiveStatus(pokemon.name, "ban")
      || pokemonNameHasActiveStatus(pokemon.name, "restrict")
      || ["Banned", "Restricted"].includes(currentPokemonRuleStatusByName(pokemon.name)));
  }
  return records;
}

function statusTokenTargetLimit(definition) {
  if (definition?.targetMode === "multi-pokemon") return Number(definition.targetCount || 1);
  if (definition?.targetMode === "player") return 0;
  return 1;
}

function inventoryItemMatchesTokenDefinition(item, definition, tokenName = "") {
  if (!itemIsTokenLike(item)) return false;
  const candidateKeys = new Set([
    item.id,
    item.name,
    displayInventoryTokenName(item.name)
  ].map(slugify).filter(Boolean));
  const targetKeys = new Set([
    tokenName,
    displayInventoryTokenName(tokenName),
    ...(definition?.names || []),
    definition ? tokenDefinitionId(utilityTokenDefinitions, definition) : ""
  ].map(slugify).filter(Boolean));
  return [...targetKeys].some((key) => candidateKeys.has(key));
}

function findInventoryTokenIndex(player, tokenName, definition = null, preferredTokenId = "") {
  const inventory = player?.inventory || [];
  if (preferredTokenId) {
    const exactIndex = inventory.findIndex((item) => item.id === preferredTokenId);
    if (exactIndex >= 0) {
      const exactItem = inventory[exactIndex];
      if (!tokenInventoryRecordAvailability(exactItem).ok) return -1;
      if (inventoryItemMatchesTokenDefinition(exactItem, definition, tokenName)) return exactIndex;
      const clickedNameMatches = [exactItem.name, displayInventoryTokenName(exactItem.name)]
        .map(slugify)
        .filter(Boolean)
        .includes(slugify(tokenName));
      return clickedNameMatches && itemIsTokenLike(exactItem) ? exactIndex : -1;
    }
  }
  return inventory.findIndex((item) => tokenInventoryRecordAvailability(item).ok
    && inventoryItemMatchesTokenDefinition(item, definition, tokenName));
}

function consumeInventoryToken(player, tokenName, definition = null, preferredTokenId = "") {
  const index = findInventoryTokenIndex(player, tokenName, definition, preferredTokenId);
  if (index < 0) return null;
  return player.inventory.splice(index, 1)[0];
}

function playerHasTokenForEffect(player, tokenName, metadata = tokenEffectMetadataByName(tokenName), preferredTokenId = "") {
  return findInventoryTokenIndex(player, tokenName, metadata?.definition || null, preferredTokenId) >= 0;
}

function addTokenConsumptionRecord({ player, token, tokenName, metadata = tokenEffectMetadataByName(tokenName), linkedEventId = "", linkedResponseId = "", promptId = "", source = "live-referee-token" }) {
  if (!player || !token) return null;
  state.tokenConsumptions ||= [];
  const record = normalizeTokenConsumptionRecord({
    id: `token-consumption-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
    playerId: player.id,
    tokenId: token.id || "",
    tokenDefinitionId: metadata?.id || token.canonicalDefinitionId || token.canonicalId || "",
    tokenName: token.name || tokenName,
    quantity: 1,
    consumedAt: new Date().toISOString(),
    linkedEventId,
    linkedResponseId,
    promptId,
    consumptionMode: metadata?.consumptionMode || TOKEN_CONSUMPTION_MODES.REFUND_IF_CANCELED,
    status: "consumed",
    refundStatus: "not-refunded",
    source,
    inventoryItem: structuredClone(token),
    eventOrder: nextEventOrder()
  });
  state.tokenConsumptions.unshift(record);
  return record;
}

function consumeTokenForEffect({ player, tokenName, metadata = tokenEffectMetadataByName(tokenName), linkedEventId = "", linkedResponseId = "", promptId = "", preferredTokenId = "", source = "live-referee-token" }) {
  if (!player) return null;
  const consumedToken = consumeInventoryToken(player, tokenName, metadata?.definition || null, preferredTokenId);
  if (!consumedToken) return null;
  const consumption = addTokenConsumptionRecord({
    player,
    token: consumedToken,
    tokenName,
    metadata,
    linkedEventId,
    linkedResponseId,
    promptId,
    source
  });
  controlTokenEffects?.copyConsumedTokenForRelationships?.(state, consumption, {
    ...controlTokenEffectOptions(),
    definitionFor: (value) => globalThis.rivalSagaTokenEffectContract?.definitionFor?.(value) || null
  });
  return { token: consumedToken, consumption };
}

function tokenConsumptionMatchesLink(record, { eventId = "", responseId = "" } = {}) {
  if (!record || record.status === "refunded") return false;
  if (responseId && record.linkedResponseId === responseId) return true;
  if (eventId && record.linkedEventId === eventId && !responseId) return true;
  return false;
}

function refundTokenConsumption(record, reason = "Canceled") {
  const normalized = normalizeTokenConsumptionRecord(record);
  if (!normalized || normalized.status === "refunded" || normalized.refundedAt) return false;
  const player = state.players.find((entry) => entry.id === normalized.playerId);
  if (!player) {
    record.status = "manual-refund-needed";
    record.refundStatus = "manual-refund-needed";
    record.refundReason = reason;
    return false;
  }
  player.inventory ||= [];
  const item = normalized.inventoryItem
    ? structuredClone(normalized.inventoryItem)
    : testingInventoryEntry({ id: normalized.tokenId || slugify(normalized.tokenName), name: normalized.tokenName, tokenType: "token", type: "TOKEN", tier: "Refund" }, "tokens", "Token Refund");
  if (isCanceledGameContentEntry(item)) {
    record.status = "retired-content";
    record.refundStatus = "not-applicable";
    record.refundReason = "Removed from Rival Saga";
    return false;
  }
  if (!item.id) item.id = createInventoryEntryId(slugify(normalized.tokenName) || "token-refund");
  if (!player.inventory.some((entry) => entry.id && entry.id === item.id)) {
    item.source = item.source || "Token Refund";
    item.refundedAt = new Date().toISOString();
    player.inventory.unshift(item);
  }
  record.status = "refunded";
  record.refundStatus = "refunded";
  record.refundedAt = new Date().toISOString();
  record.refundReason = reason;
  return true;
}

function refundTokenConsumptionsForLink({ eventId = "", responseId = "" } = {}, reason = "Canceled") {
  state.tokenConsumptions ||= [];
  let refunded = 0;
  state.tokenConsumptions.forEach((record) => {
    if (!tokenConsumptionMatchesLink(record, { eventId, responseId })) return;
    if (refundTokenConsumption(record, reason)) refunded += 1;
  });
  return refunded;
}

