function createPlayerNotification(playerIdOrDraft, options = {}) {
  const draft = typeof playerIdOrDraft === "object" && playerIdOrDraft && !Array.isArray(playerIdOrDraft)
    ? playerIdOrDraft
    : { ...options, playerId: playerIdOrDraft };
  const {
    playerId,
    type,
    title,
    message,
    sourceType = "",
    sourceId = "",
    pokemonId = "",
    priority = 1,
    requiresAction = true,
    payload = {}
  } = draft;
  state.playerNotifications ||= [];
  const notification = {
    id: `notification-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
    playerId,
    type,
    title,
    message,
    sourceType,
    sourceId,
    pokemonId,
    series: state.series,
    gym: Number(state.gym),
    phase: currentPhase(),
    status: "pending",
    priority,
    requiresAction,
    payload,
    createdAt: new Date().toISOString(),
    completedAt: null
  };
  state.playerNotifications.unshift(notification);
  return notification;
}

function createEvolutionBranchLockNotification(player, pokemon, acquisition) {
  if (!player || !pokemon || !acquisition?.lockCreated) return null;
  return createPlayerNotification(player.id, {
    type: "series-evolution-lock-created",
    title: "Evolution Branch Locked",
    message: `You obtained ${acquisition.obtainedSpecies}. ${acquisition.receivedSpecies} has been added to your roster and is locked to the ${acquisition.lockSpecies} evolution branch for the remainder of this Series. This Pokemon may remain ${acquisition.receivedSpecies}, but it cannot evolve into a different branch until the Series ends. Battle Tier restrictions still apply.`,
    sourceType: "pokemon-acquisition",
    sourceId: pokemon.id,
    pokemonId: pokemon.id,
    priority: 3,
    requiresAction: false,
    payload: {
      obtainedPokemon: acquisition.obtainedSpecies,
      receivedPokemon: acquisition.receivedSpecies,
      lockedEvolution: acquisition.lockSpecies,
      duration: "Current Series",
      lockPath: acquisition.lockPath.map((entry) => entry.species)
    }
  });
}

function createEvolutionLocksRemovedNotification(player, previousSeries, removedLocks) {
  if (!player || !removedLocks?.length) return null;
  const lines = removedLocks.map((entry) => `${entry.pokemonName} - previously locked to ${entry.lockedEvolution}`).join(", ");
  return createPlayerNotification(player.id, {
    type: "series-evolution-locks-removed",
    title: "Evolution Locks Removed",
    message: `The ${previousSeries} Series has ended. Your Series Evolution Locks have been removed. The following Pokemon may now use other legal evolution branches: ${lines}. Normal Battle Tier restrictions still apply.`,
    sourceType: "series-transition",
    priority: 3,
    requiresAction: false,
    payload: {
      previousSeries,
      removedLocks,
      duration: "Series ended"
    }
  });
}

function clearSeriesEvolutionLocksForSeries(seriesId) {
  const previousSeries = String(seriesId || "");
  if (!previousSeries) return [];
  const removedByPlayer = new Map();
  (state.pokemonRecords || []).forEach((pokemon) => {
    if (!pokemon.seriesEvolutionLockSpeciesId || pokemon.seriesEvolutionLockSeriesId !== previousSeries) return;
    const entry = {
      pokemonId: pokemon.id,
      pokemonName: pokemon.name,
      receivedPokemon: pokemon.rosterSpeciesName || pokemon.seriesStartSpecies || pokemon.name,
      lockedEvolution: pokemon.seriesEvolutionLockSpeciesName || pokemon.acquiredSpeciesName || pokemon.seriesEvolutionLockSpeciesId
    };
    if (!removedByPlayer.has(pokemon.trainerId)) removedByPlayer.set(pokemon.trainerId, []);
    removedByPlayer.get(pokemon.trainerId).push(entry);
    pokemon.seriesEvolutionLockSpeciesId = "";
    pokemon.seriesEvolutionLockSpeciesName = "";
    pokemon.seriesEvolutionLockSeriesId = "";
    pokemon.seriesEvolutionLockCreatedAt = "";
  });
  const removed = [];
  removedByPlayer.forEach((locks, playerId) => {
    const player = state.players.find((entry) => entry.id === playerId);
    if (player) createEvolutionLocksRemovedNotification(player, previousSeries, locks);
    removed.push(...locks);
  });
  return removed;
}

function makeRewardToken(name, source, extras = {}) {
  const token = {
    id: `${slugify(source)}-${slugify(name)}-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
    name,
    type: "TOKEN",
    tokenType: extras.tokenType || "reward",
    tier: extras.tier || source,
    price: 0,
    source,
    awardedAt: new Date().toISOString(),
    ...extras
  };
  const gcTierId = normalizeGameCornerTierId(token.gameCornerTierId || token.gameCornerTier || token.tier || token.name);
  if (token.tokenType === "game-corner" || gcTierId) {
    const definition = gameCornerTokenDefinitionByTier(gcTierId || token.name);
    token.tokenType = "game-corner";
    token.type = "TICKET";
    token.name = definition.name;
    token.tier = "Game Corner";
    token.gameCornerTier = definition.gameCornerTier;
    token.gameCornerTierId = definition.gameCornerTierId;
    token.description ||= definition.description;
  }
  return token;
}

function activePokemonCenterSession(playerId = activePlayer().id) {
  state.pokemonCenterSessions ||= [];
  return state.pokemonCenterSessions.find((session) => session.playerId === playerId
    && session.series === state.series
    && Number(session.gym) === Number(state.gym)
    && session.status === "active") || null;
}

function pokemonCenterRestorationCost(pokemon) {
  const tier = normalizeGameCornerTierId(pokemon?.acquisitionTier || getPokemonFamilyAcquisitionTier(pokemon?.name || "") || getPokemonAcquisitionTier(pokemon?.name || ""));
  const costs = {
    safari: 1000,
    poke: 2000,
    great: 3000,
    ultra: 4000,
    master: 5000
  };
  return { tier, cost: costs[tier] || 0 };
}

function pokemonCenterDiscountedCost(session, cost) {
  const discount = session?.carePackageDiscountAvailable && !session?.carePackageDiscountUsed ? 1000 : 0;
  return { discount, finalCost: Math.max(0, Number(cost || 0) - discount) };
}

function playerStatusTargets(player, pattern, statusType) {
  const targets = [];
  const statusMap = new Map();
  activeLingeringStatuses({ targetPlayerId: player.id }).forEach((status) => statusMap.set(status.id, status));
  (state.pokemonRecords || [])
    .filter((pokemon) => pokemon.trainerId === player.id && !["Released", "Removed"].includes(pokemon.status))
    .forEach((pokemon) => pokemonLingeringStatuses(pokemon.id).forEach((status) => statusMap.set(status.id, status)));
  statusMap.forEach((status) => {
    if (statusType === "curse" && !status.isCurse) return;
    if (statusType === "restrict" && status.type !== "restrict") return;
    const pokemon = status.targetPokemonId
      ? (state.pokemonRecords || []).find((record) => record.id === status.targetPokemonId)
      : (state.pokemonRecords || []).find((record) => record.trainerId === player.id
        && pokemonRuleKey(record.name) === (status.targetPokemonNameKey || pokemonRuleKey(status.targetPokemonName)));
    targets.push({
      id: `lingering::${status.id}`,
      label: `${pokemon?.name || status.targetPokemonName || player.name}: ${statusDisplayLabel(status)}`,
      scope: "lingering",
      statusId: status.id,
      pokemonId: pokemon?.id || "",
      pokemonName: pokemon?.name || status.targetPokemonName || "",
      text: statusDisplayLabel(status),
      statusType
    });
  });
  (player.nerfs || []).forEach((text, index) => {
    if (pattern.test(String(text))) targets.push({ id: `player::${index}`, label: `${player.name}: ${text}`, scope: "player", index, text, statusType });
  });
  (state.pokemonRecords || [])
    .filter((pokemon) => pokemon.trainerId === player.id && !["Released", "Removed"].includes(pokemon.status))
    .forEach((pokemon) => {
      const globalRuleStatus = currentPokemonRuleStatusByName(pokemon.name);
      if (statusType === "restrict" && globalRuleStatus === "Restricted") {
        targets.push({
          id: `global-rule::${pokemonRuleKey(pokemon.name)}`,
          label: `${pokemon.name}: Restricted`,
          scope: "global-rule",
          pokemonId: pokemon.id,
          pokemonName: pokemon.name,
          text: "Restricted",
          statusType
        });
      }
      (pokemon.nerfs || []).forEach((text, index) => {
        if (pattern.test(String(text))) targets.push({ id: `pokemon::${pokemon.id}::${index}`, label: `${pokemon.name}: ${text}`, scope: "pokemon", pokemonId: pokemon.id, index, text, statusType });
      });
      if (pattern.test(String(pokemon.ruleStatus || ""))) {
        targets.push({ id: `pokemon-rule::${pokemon.id}`, label: `${pokemon.name}: ${pokemon.ruleStatus}`, scope: "pokemon-rule", pokemonId: pokemon.id, text: pokemon.ruleStatus, statusType });
      }
    });
  const seen = new Set();
  return targets.filter((target) => {
    const key = `${target.scope}:${target.statusId || target.pokemonName || target.id}:${target.statusType}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function gameCornerTokensForPlayer(player = activePlayer()) {
  return (player.inventory || []).filter(isGameCornerToken);
}

function isGameCornerToken(item) {
  if (!item) return false;
  if (item.tokenType === "game-corner") return true;
  if (item.gameCornerTierId || item.gameCornerTier) return Boolean(normalizeGameCornerTierId(item.gameCornerTierId || item.gameCornerTier));
  return /\bgc\s*(?:token|ticket)\b/i.test(String(item.name || "")) && Boolean(normalizeGameCornerTierId(item.name));
}

function isLegacyTicket(item) {
  if (!item) return false;
  if (item.tokenType === "legacy") return true;
  return /^legacy\s+(?:token|ticket)$/i.test(String(item.name || "").trim());
}

function isKeyItemTicket(item) {
  return isLegacyTicket(item) || isGameCornerToken(item);
}

function gameCornerTokenTier(item) {
  for (const candidate of [item?.gameCornerTierId, item?.gameCornerTier, item?.name, item?.tier]) {
    const tier = normalizeGameCornerTier(candidate);
    if (tier) return tier;
  }
  return "";
}

function gameCornerTokenCounts(player = activePlayer()) {
  const counts = Object.fromEntries(gameCornerTokenDefinitions.map((definition) => [definition.gameCornerTierId, 0]));
  gameCornerTokensForPlayer(player).forEach((token) => {
    const tierId = normalizeGameCornerTierId(gameCornerTokenTier(token));
    if (tierId && counts[tierId] !== undefined) counts[tierId] += 1;
  });
  return counts;
}

function wheelSessionHasRemainingSpins(wheelSessionId) {
  const session = (state.wheelSessions || []).find((entry) => entry.id === wheelSessionId);
  if (!session) return false;
  const wheel = wheelDefinitionById(session.wheelId);
  const max = Number(session.maxRolls || wheel?.maxRollsPerVisit || Infinity);
  return session.status === "pending" && (session.rolls || []).length < max;
}

function activeGameCornerSession(playerId = activePlayer().id, serviceId = "") {
  state.gameCornerSessions ||= [];
  const sessions = state.gameCornerSessions
    .filter((session) => session.playerId === playerId
      && session.series === state.series
      && Number(session.gym) === Number(state.gym)
      && session.status === "active")
    .sort((a, b) => new Date(b.createdAt || 0) - new Date(a.createdAt || 0));
  if (serviceId === "gamecorner-gamble") {
    return sessions.find((session) => !session.gambleWheelSessionId || wheelSessionHasRemainingSpins(session.gambleWheelSessionId)) || null;
  }
  return sessions[0] || null;
}

