function uniqueTestingOptions(options = []) {
  const seen = new Set();
  return options.filter((option) => {
    const key = String(option?.id || option?.name || "").toLowerCase();
    if (!key || seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function curatedTestingOptions(options = [], preferredNames = [], limit = 12) {
  const unique = uniqueTestingOptions(options);
  const byKey = new Map();
  unique.forEach((option) => {
    [option.id, option.name].map(slugify).filter(Boolean).forEach((key) => {
      if (!byKey.has(key)) byKey.set(key, option);
    });
  });
  const picked = [];
  preferredNames.forEach((name) => {
    const option = byKey.get(slugify(name));
    if (option && !picked.includes(option)) picked.push(option);
  });
  unique.forEach((option) => {
    if (picked.length < limit && !picked.includes(option)) picked.push(option);
  });
  return picked.slice(0, limit);
}

function concreteTestingItemOptions(options = []) {
  return options.flatMap((option) => {
    const definition = staticShopChoiceDefinitionByName(option?.name);
    if (!definition?.options?.length) return [option];
    return definition.options.map((name) => ({
      ...option,
      id: `${option.id || slugify(option.name)}--${slugify(name)}`,
      name,
      parentShopItemName: option.name
    }));
  });
}

function testingInventoryEntry(option, shopType, sourceLabel = "Max Testing Setup") {
  return {
    id: createInventoryEntryId(option.id || option.name || shopType),
    catalogId: option.id || "",
    name: option.name || option.id || "Testing Resource",
    type: inventoryTypeForShop(shopType, option),
    moveType: shopType === "tms" ? option.type || "" : undefined,
    tokenType: option.tokenType || (shopType === "tokens" ? "token" : undefined),
    tier: option.tier || option.category || "Testing",
    price: Number(option.price || 0),
    originalPrice: Number(option.price || 0),
    discountPercent: 100,
    description: option.description || "",
    source: sourceLabel,
    purchasedAt: new Date().toISOString()
  };
}

function testingPokemonNamesForPlayer(playerIndex = 0, count = 26) {
  const pool = maxTestingPokemonPool;
  return Array.from({ length: count }, (_, index) => pool[(playerIndex * count + index) % pool.length]);
}

function createTestingPokemonRecord(player, name, rosterType = "Active", extra = {}) {
  const status = rosterType === "Released" ? "Released" : "Active";
  const chosenSpriteKey = choosePokemonSpriteLookupKey(name);
  const pokemon = normalizePokemonRecord({
    id: makePokemonId(player.id, name),
    name,
    trainerId: player.id,
    status,
    rosterType,
    firstCaughtSeries: state.series,
    firstCaughtGym: state.gym,
    spriteUrl: pokemonDbSpriteUrlForLookup(chosenSpriteKey),
    chosenSpriteKey,
    source: "Testing / Max Setup",
    sourceTier: "Testing",
    addedAt: new Date().toISOString(),
    buffs: extra.buffs || [],
    nerfs: extra.nerfs || []
  });
  addPokemonLog(pokemon, "Testing / Max Setup", `Added as ${rosterType}`);
  state.pokemonRecords.unshift(pokemon);
  return pokemon;
}

function maxAllPlayersForTesting() {
  if (!confirm("This will give every player max testing resources and rosters. Continue?")) return;
  const tokenOptions = uniqueTestingOptions([
    ...activeTokenCatalog().map((option) => ({ ...option, type: "TOKEN" })),
    ...manualTokenOptions(),
    { id: "immunity", name: "Immunity", tokenType: "protection", type: "TOKEN", tier: "Protection" },
    { id: "seven-tools", name: "7 Tools Of The Bandit", tokenType: "protection", type: "TOKEN", tier: "Protection" },
    { id: "protection-token", name: "Protection Token", tokenType: "protection", type: "TOKEN", tier: "Protection" }
  ]);
  const itemOptions = curatedTestingOptions(concreteTestingItemOptions(battleItemShopData || []), [
    "Leftovers",
    "Choice Band",
    "Choice Scarf",
    "Choice Specs",
    "Focus Sash",
    "Life Orb",
    "Assault Vest",
    "Rocky Helmet",
    "Heavy-Duty Boots",
    "Eviolite",
    "Expert Belt",
    "Sitrus Berry"
  ], 12);
  const tmOptions = curatedTestingOptions(tmShopData || [], [
    "Protect",
    "Substitute",
    "Swords Dance",
    "Nasty Plot",
    "Calm Mind",
    "Dragon Dance",
    "U-turn",
    "Volt Switch",
    "Earthquake",
    "Ice Beam",
    "Thunderbolt",
    "Flamethrower",
    "Will-O-Wisp",
    "Stealth Rock",
    "Recover",
    "Roost"
  ], 16);
  const previousTestPokemonIds = new Set((state.pokemonRecords || [])
    .filter((pokemon) => pokemon.source === "Testing / Max Setup")
    .map((pokemon) => pokemon.id));
  state.pokemonRecords = (state.pokemonRecords || []).filter((pokemon) => !previousTestPokemonIds.has(pokemon.id));
  state.pokemonLog = (state.pokemonLog || []).filter((entry) => !previousTestPokemonIds.has(entry.pokemonId));

  const tokenCopies = 6;
  const itemCopies = 1;
  const tmCopies = 1;
  state.players.forEach((player, playerIndex) => {
    player.balance = 999999;
    player.momentum = Math.max(Number(player.momentum || 0), 99);
    player.badgePoints = Math.max(Number(player.badgePoints || 0), 99);
    player.shopLevels = { items: 4, tms: 4, tokens: 4 };
    const existingNonTestingInventory = (player.inventory || []).filter((entry) => entry.source !== "Max Testing Setup");
    const testingInventory = [
      ...tokenOptions.flatMap((option) => Array.from({ length: tokenCopies }, () => testingInventoryEntry(option, "tokens"))),
      ...itemOptions.flatMap((option) => Array.from({ length: itemCopies }, () => testingInventoryEntry(option, "items"))),
      ...tmOptions.flatMap((option) => Array.from({ length: tmCopies }, () => testingInventoryEntry(option, "tms")))
    ];
    player.inventory = [...testingInventory, ...existingNonTestingInventory];

    const names = testingPokemonNamesForPlayer(playerIndex);
    names.slice(0, 20).forEach((name, index) => {
      createTestingPokemonRecord(player, name, "Active", index % 5 === 0 ? { buffs: ["Testing Buff"] } : {});
    });
    names.slice(20, 22).forEach((name) => createTestingPokemonRecord(player, name, "Legacy"));
    names.slice(22, 26).forEach((name, index) => {
      createTestingPokemonRecord(player, name, "Released", index % 2 === 0 ? { nerfs: ["Testing Curse History"] } : {});
    });
  });
  syncPlayerPokemonLists();
  addLogEntry({
    action: "admin",
    category: "admin",
    player: "Admin Tools",
    item: `Max testing setup applied to ${state.players.length} players: max money, tokens, item/TM samples, and 26 Pokemon each.`,
    type: "admin-max-testing-setup",
    tags: ["admin", "testing", "max-setup"],
    quantity: state.players.length,
    price: 0,
    balanceAfter: activePlayer().balance
  });
  saveState();
  render();
  syncAdminRepairControls();
  if (els.adminMaxTestingStatus) {
    els.adminMaxTestingStatus.textContent = `Max testing setup applied: ${state.players.length} players, ${tokenOptions.length} token types, ${itemOptions.length} item samples, ${tmOptions.length} TM samples, 26 Pokemon each.`;
  }
}

function giveAdminTestResource() {
  const player = state.players.find((entry) => entry.id === els.adminTestResourcePlayer?.value) || activePlayer();
  const kind = els.adminTestResourceKind?.value || "";
  if (!player) return;
  if (kind === "money-5000" || kind === "money-10000") {
    const amount = kind === "money-10000" ? 10000 : 5000;
    applyPlayerMoneyChange(player, amount, {
      direction: "gain",
      sourceType: "admin-test-resource",
      sourceLabel: "Admin test resource",
      note: "Testing / Host Tools"
    });
    addLogEntry({
      action: "admin",
      category: "admin",
      player: player.name,
      item: `Testing / Host Tools added ${formatMoney(amount)}.`,
      type: "admin-test-resource",
      playerIds: [player.id],
      tags: ["admin", "testing", "money"],
      price: amount,
      balanceAfter: player.balance
    });
    saveState();
    render();
    syncAdminRepairControls();
    if (els.adminTestResourceStatus) els.adminTestResourceStatus.textContent = `Added ${formatMoney(amount)} to ${player.name}.`;
    return;
  }
  const option = adminTestResourceOption(kind);
  if (!option) {
    if (els.adminTestResourceStatus) els.adminTestResourceStatus.textContent = "Choose a test resource.";
    return;
  }
  const token = createManualToken({ ...option, source: "Testing / Host Tools" });
  player.inventory ||= [];
  player.inventory.unshift(token);
  addLogEntry({
    action: "admin",
    category: "items",
    player: player.name,
    item: `Testing / Host Tools added ${token.name}.`,
    type: "admin-test-resource",
    tokenNames: [token.name],
    itemNames: [token.name],
    playerIds: [player.id],
    tags: ["admin", "testing", "token"],
    quantity: 1,
    price: 0,
    balanceAfter: player.balance
  });
  saveState();
  render();
  syncAdminRepairControls();
  if (els.adminTestResourceStatus) els.adminTestResourceStatus.textContent = `Added ${token.name} to ${player.name}.`;
}

