function positionTrainerProfilePanel(anchor = els.trainerProfileToggle, preferredWidth = 300) {
  if (!anchor || !els.trainerProfilePanel) return;
  const rect = anchor.getBoundingClientRect();
  const panelWidth = Math.min(preferredWidth, window.innerWidth * 0.78);
  const left = Math.max(12, Math.min(rect.right - panelWidth, window.innerWidth - panelWidth - 12));
  const top = Math.min(rect.bottom + 8, window.innerHeight - 80);
  els.trainerProfilePanel.style.setProperty("--trainer-profile-panel-width", `${panelWidth}px`);
  els.trainerProfilePanel.style.setProperty("--trainer-profile-panel-left", `${left}px`);
  els.trainerProfilePanel.style.setProperty("--trainer-profile-panel-top", `${top}px`);
}

function saveTrainerProfileFromPanel() {
  const player = activePlayer();
  if (!requirePrivatePrepAccess(player, "trainer profile")) return;
  const nameInput = els.trainerProfilePanel?.querySelector("#trainerProfileNameInput");
  const titleSelect = els.trainerProfilePanel?.querySelector("#trainerProfileTitleSelect");
  if (!nameInput || !titleSelect) return;
  const index = Math.max(0, state.players.findIndex((candidate) => candidate.id === player.id));
  const fallbackName = `Player ${index + 1}`;
  const beforeName = player.name || fallbackName;
  player.name = nameInput.value.trim() || fallbackName;
  player.title = titleSelect.value;
  addLogEntry({
    action: "admin",
    category: "player",
    player: player.name,
    item: `Trainer profile updated: ${beforeName} -> ${player.name}.`,
    type: "trainer-profile",
    quantity: 1,
    price: 0,
    balanceAfter: player.balance
  });
  els.trainerProfilePanel.classList.add("hidden");
  saveState();
  render();
}

function syncPlayerOptionLabels() {
  const namesById = new Map(state.players.map((player) => [player.id, player.name]));
  document.querySelectorAll("option").forEach((option) => {
    if (namesById.has(option.value)) option.textContent = namesById.get(option.value);
  });
}

function resolvePlayerNotification(notificationId) {
  const notification = (state.playerNotifications || []).find((entry) => entry.id === notificationId);
  if (!notification || notification.status !== "pending") return;
  const notificationPlayer = state.players.find((entry) => entry.id === notification.playerId);
  if (notificationPlayer && !requirePrivatePrepAccess(notificationPlayer, "notifications")) return;
  if (notification.type === "pc-rival-legacy-choice") {
    const player = state.players.find((entry) => entry.id === notification.playerId);
    const choices = (notification.payload?.pokemonIds || [])
      .map((id) => (state.pokemonRecords || []).find((pokemon) => pokemon.id === id))
      .filter(Boolean);
    if (!player || !choices.length) return;
    const chosenName = prompt(`Choose one Pokemon to move to Legacy:\n${choices.map((pokemon) => pokemon.name).join("\n")}`);
    if (!chosenName?.trim()) return;
    const pokemon = choices.find((entry) => entry.name.toLowerCase() === chosenName.trim().toLowerCase()) || choices[0];
    const previousPokemon = structuredClone(pokemon);
    const previousNotifications = structuredClone(state.playerNotifications || []);
    pokemon.status = "Legacy";
    pokemon.rosterType = "Legacy";
    completePlayerNotification(notification.id, { pokemonId: pokemon.id, pokemonName: pokemon.name });
    addLogEntry({
      action: "pokemon",
      category: "pokemon",
      player: player.name,
      item: `${player.name} moved ${pokemon.name} to Legacy from PC choice.`,
      title: `${pokemon.name} moved to Legacy`,
      summary: `${pokemon.name} moved to Legacy\nPC rival choice resolved`,
      details: [`Pokemon: ${pokemon.name}`, `Actor: ${state.players.find((entry) => entry.id === notification.payload?.actorPlayerId)?.name || "Unknown"}`],
      type: "notification-resolution",
      categories: ["pokemon", "notification"],
      tags: ["notification", "pc", "legacy-token"],
      playerIds: [player.id, notification.payload?.actorPlayerId].filter(Boolean),
      pokemonIds: [pokemon.id],
      pokemonNames: [pokemon.name],
      notificationId: notification.id,
      sourceType: notification.sourceType,
      undoable: true,
      undone: false,
      undoData: {
        actionType: "undoNotificationResolution",
        notificationId: notification.id,
        playerId: player.id,
        pokemonId: pokemon.id,
        previousPokemon,
        previousNotifications
      }
    });
    syncPlayerPokemonLists();
    saveState();
    render();
    return;
  }
  const player = state.players.find((entry) => entry.id === notification.playerId);
  const pokemon = (state.pokemonRecords || []).find((entry) => entry.id === notification.pokemonId);
  if (!player || !pokemon) return;
  const isDaycareMoveNotification = ["breeder-egg-move", "daycare-tm-move"].includes(notification.type);
  const isDragonsDenReward = notification.type === "dragons-den-reward";
  let resolvedDragonRewardType = notification.payload?.rewardType || "move";
  if (isDragonsDenReward && resolvedDragonRewardType === "move-or-ability") {
    const kind = prompt("Dragon's Den reward type: enter move or ability", "move")?.trim().toLowerCase();
    if (!kind) return;
    if (!['move', 'ability'].includes(kind)) return alert("Choose either move or ability.");
    resolvedDragonRewardType = kind;
  }
  const isAbilityReward = isDragonsDenReward && resolvedDragonRewardType === "ability";
  const isMoveAccessReward = isDaycareMoveNotification || isDragonsDenReward && !isAbilityReward;
  const promptLabel = notification.type === "dragons-den-reward"
    ? isAbilityReward ? "Ability" : "Move"
    : "TM";
  const value = prompt(`${promptLabel} for ${pokemon.name}`);
  if (!value?.trim()) return;
  const chosenInput = value.trim();
  const chosen = isMoveAccessReward
    ? teambuilderCanonicalMoveName(chosenInput)
    : teambuilderDataSource().abilities?.[teambuilderDataKey(chosenInput)]?.name || chosenInput;
  if (isMoveAccessReward && !teambuilderKnownMoveName(chosen)) {
    alert(`${chosen} is not in the imported Rival Saga move database.`);
    return;
  }
  if (isDaycareMoveNotification) {
    const compatibleEggKeys = new Set((notification.payload?.legalTmMoves || daycareTmMoveOptions(pokemon))
      .map((move) => teambuilderCanonicalMoveKey(move)));
    if (!compatibleEggKeys.has(teambuilderCanonicalMoveKey(chosen))) {
      alert(`${pokemon.name} cannot learn ${chosen} as a TM.`);
      return;
    }
  }
  if (isDragonsDenReward && !isAbilityReward) {
    const data = teambuilderPokemonData(pokemon) || {};
    const legalKeys = new Set([...(data.levelUpMoves || []), ...(data.tmMoves || [])]
      .filter((move) => !rivalSagaMoveIsExcluded(move))
      .map((move) => teambuilderCanonicalMoveKey(move)));
    if (!legalKeys.has(teambuilderCanonicalMoveKey(chosen))) {
      alert(`${pokemon.name} cannot legally learn ${chosen} under the Dragon's Den rule.`);
      return;
    }
  }
  if (isAbilityReward && !teambuilderDataSource().abilities?.[teambuilderDataKey(chosen)]) {
    alert(`${chosen} is not in the imported Rival Saga ability database.`);
    return;
  }
  if (isAbilityReward && !arenaTrapCustomizationAbilityOptions().some((ability) => teambuilderDataKey(ability) === teambuilderDataKey(chosen))) {
    alert(`${chosen} is not on the AAA-approved Ability list.`);
    return;
  }
  const previousPokemon = structuredClone(pokemon);
  const previousNotifications = structuredClone(state.playerNotifications || []);
  const previousMoveAccessGrants = structuredClone(player.moveAccessGrants || []);
  pokemon.buffs = (pokemon.buffs || []).filter((buff) => {
    if (isDaycareMoveNotification) return buff !== "TM Move Pending";
    if (isDragonsDenReward) return !String(buff).startsWith("Dragon's Den ") || !String(buff).endsWith(" Pending");
    return true;
  });
  const buffLabel = isDaycareMoveNotification
    ? `Day Care TM: ${chosen}`
    : isAbilityReward
      ? `Dragon's Den Ability: ${chosen}`
      : `Dragon's Den Move: ${chosen}`;
  pokemon.buffs = [...new Set([...(pokemon.buffs || []), buffLabel])];
  const moveAccessGrant = isMoveAccessReward ? grantTeambuilderMoveAccess(player, {
    sourceType: "location",
    sourceName: isDaycareMoveNotification ? "Day Care" : "Dragon's Den",
    sourceLabel: isDaycareMoveNotification ? "Day Care TM" : "Dragon's Den Move",
    sourceRefType: "player-notification",
    sourceRefId: notification.id,
    mode: "specific-moves",
    moveNames: [chosen],
    pokemonRecordId: pokemon.id,
    speciesName: pokemon.name,
    duration: "permanent",
    status: "active",
    note: `${pokemon.name} gained permanent access to ${chosen}.`
  }) : null;
  completePlayerNotification(notification.id, { value: chosen, moveAccessGrantId: moveAccessGrant?.id || "" });
  addPokemonLog(pokemon, "Notification Resolved", `${promptLabel}: ${chosen}`);
  addLogEntry({
    action: "pokemon",
    category: "pokemon",
    player: player.name,
    item: isDaycareMoveNotification
      ? `${pokemon.name} learned TM Move: ${chosen}`
      : `${pokemon.name} Dragon's Den reward resolved: ${chosen}`,
    title: isDaycareMoveNotification ? `${pokemon.name} learned TM Move` : `${pokemon.name} reward resolved`,
    summary: isDaycareMoveNotification ? `${pokemon.name} learned TM Move: ${chosen}` : `${pokemon.name} Dragon's Den reward resolved: ${chosen}`,
    details: [`Pokemon: ${pokemon.name}`, `${promptLabel}: ${chosen}`],
    type: "notification-resolution",
    categories: ["pokemon", "notification"],
    tags: ["notification", notification.sourceType || notification.type],
    playerIds: [player.id],
    pokemonIds: [pokemon.id],
    pokemonNames: [pokemon.name],
    notificationId: notification.id,
    sourceType: notification.sourceType,
    undoable: true,
    undone: false,
    undoData: {
      actionType: "undoNotificationResolution",
      notificationId: notification.id,
      playerId: player.id,
      pokemonId: pokemon.id,
      previousPokemon,
      previousNotifications,
      previousMoveAccessGrants
    }
  });
  saveState();
  render();
}

function render() {
  const player = activePlayer();
  if (!TOP_LEVEL_PAGE_IDS.includes(state.activePage)) state.activePage = "playerHub";
  const activePage = state.activePage || "playerHub";
  if (!PLAYER_HUB_VIEW_IDS.includes(state.activeView)) state.activeView = "sheet";
  ensureGymPhaseState();
  expireLingeringStatuses();
  applyTheme(player.theme || player.id || "saga");
  applyHeaderTheme(player.headerTheme || "default");
  els.seriesSelect.value = state.series;
  els.gymSelect.value = String(state.gym);
  renderPhaseControl();
  const freeTestingMode = hostTestingOverrideEnabled();
  document.body?.classList.toggle("free-testing-mode", freeTestingMode);
  els.actionDemoBadge?.classList.toggle("active", freeTestingMode);
  els.actionDemoBadge?.setAttribute("aria-label", freeTestingMode ? "Demo Mode is on" : "Open Demo Mode controls");
  if (!freeTestingMode) {
    els.actionDemoBadge?.setAttribute("aria-expanded", "false");
    els.actionDemoNotice?.classList.add("hidden");
  }
  els.activePlayerName.textContent = player.name;
  syncPlayerOptionLabels();
  els.trainerMetaLine.textContent = player.title || "No title unlocked";
  els.activeTrainerClass.textContent = player.trainerClass || "None";
  els.activeTrainerClassDetail.textContent = player.trainerClass || "None";
  els.activeClassOrigin.textContent = player.classOrigin || "None";
  const activePrepAccess = privatePrepAccessForPlayer(player, "trainer prep");
  els.trainerCard?.classList.toggle("private-prep-denied", !activePrepAccess.allowed);
  [els.addPerk, els.addBuff, els.addNerf, els.trainerAvatarButton, els.themeToggle, els.globalThemeToggle].forEach((button) => {
    if (!button) return;
    button.disabled = !activePrepAccess.allowed;
    button.title = activePrepAccess.allowed ? button.getAttribute("aria-label") || "" : activePrepAccess.reason;
  });
  if (els.activeClassOrigin) {
    els.activeClassOrigin.contentEditable = activePrepAccess.allowed ? "true" : "false";
    els.activeClassOrigin.tabIndex = activePrepAccess.allowed ? 0 : -1;
    els.activeClassOrigin.title = activePrepAccess.allowed ? "" : activePrepAccess.reason;
  }
  if (els.activeTrainerClassDetail) {
    els.activeTrainerClassDetail.title = activePrepAccess.allowed ? "Choose trainer class" : activePrepAccess.reason;
  }
  const derivedRecords = derivedPlayerRecords(player);
  els.activeSeriesRecord.textContent = formatRecord(derivedRecords.seriesRecord);
  els.activeRecord.textContent = formatRecord(derivedRecords.overallRecord);
  els.activeMomentum.textContent = String(player.momentum ?? 0);
  els.activeSagaPoints.textContent = String(player.sagaPoints ?? 0);
  els.activeItemAccess.textContent = shopProgressLabel(player, "items");
  els.activeTmAccess.textContent = shopProgressLabel(player, "tms");
  els.activeRangerCredits.textContent = String(ensureActionSeriesTracker(state.series, player.id).rangerCredits || 0);
  if (els.activeBadgePoints) els.activeBadgePoints.textContent = String(player.badgePoints || 0);
  els.activeBalance.textContent = formatMoney(player.balance);
  els.activeBalance.title = "Open money ledger";
  els.activeBalance.tabIndex = 0;
  els.activeBalance.classList.add("clickable-balance");
  renderPlayerNotifications(player);
  renderTrainerProfilePanel(player);
  if (player.avatarUrl) {
    els.activeTrainerAvatar.src = player.avatarUrl;
    els.activeTrainerAvatar.parentElement.classList.add("has-image");
  } else {
    els.activeTrainerAvatar.removeAttribute("src");
    els.activeTrainerAvatar.parentElement.classList.remove("has-image");
  }
  els.playerHubView.classList.toggle("hidden", activePage !== "playerHub");
  els.actionPhaseView.classList.toggle("hidden", activePage !== "actionPhase");
  els.leaderboardView.classList.toggle("hidden", activePage !== "leaderboard");
  els.mvpRaceView.classList.toggle("hidden", activePage !== "mvpRace");
  els.battlePhaseView.classList.toggle("hidden", activePage !== "battlePhase");
  els.banlistView.classList.toggle("hidden", activePage !== "banlist");
  els.infoView?.classList.toggle("hidden", activePage !== "info");
  placeSharedTrainerCard(activePage, state.activeView);
  const logClosed = state.activityLogCollapsed !== false;
  els.layout.classList.toggle("log-open", !logClosed);
  els.layout.classList.remove("live-referee-open", "live-referee-collapsed", "live-referee-expanded");
  els.detailsColumn.classList.toggle("drawer-open", !logClosed);
  els.activityPanel.classList.toggle("open", !logClosed);
  els.activityLogContent.classList.remove("hidden");
  els.toggleActivityLog.textContent = "Close";
  els.toggleActivityLog.setAttribute("aria-expanded", String(!logClosed));
  els.activityLogTab.setAttribute("aria-expanded", String(!logClosed));
  const visibleLogCount = (state.log || []).filter((entry) => !entry.undone).length;
  els.activityLogTab.textContent = logClosed ? (visibleLogCount ? `Log ${visibleLogCount}` : "Log") : "Close Log";
  els.activityLogTab.setAttribute("aria-label", logClosed ? `Open Activity Log${visibleLogCount ? `, ${visibleLogCount} entries` : ""}` : "Close Activity Log");
  if (els.liveRefereeColumn) {
    els.liveRefereeColumn.hidden = Boolean(state.liveRefereeCollapsed);
  }
  document.querySelectorAll(".top-level-tab").forEach((tab) => {
    if (tab.dataset.gameRibbon || tab.dataset.leagueDestination) return;
    tab.classList.toggle("active", tab.dataset.page === activePage);
  });
  els.shopView.classList.toggle("hidden", state.activeView !== "shop");
  els.teambuilderView?.classList.toggle("hidden", state.activeView !== "teambuilder");
  els.actionsView.classList.toggle("hidden", state.activeView !== "actions");
  els.sheetView.classList.toggle("hidden", state.activeView !== "sheet");
  document.querySelectorAll(".app-tab").forEach((tab) => {
    tab.classList.toggle("active", tab.dataset.view === state.activeView);
  });
  renderEffectPills(els.activePerks, player.perks || [], "No perks", "perk");
  renderActiveBulletinQuests(player);
  renderEffectPills(els.activeBuffs, player.buffs || [], "No buffs", "buff");
  renderEffectPills(els.activeNerfs, player.nerfs || [], "No nerfs", "nerf");
  renderGlobalThemeMenu(player);
  renderHeaderThemeMenu(player);

  renderTrainerMenu();
  if (activePage === "playerHub") {
    if (state.activeView === "shop") {
      renderShop(player);
    } else if (state.activeView === "teambuilder") {
      renderTeambuilder(player);
    } else if (state.activeView === "actions") {
      renderActionBuilder();
    } else {
      renderInventory(player);
      renderSheet(player);
    }
  } else if (activePage === "actionPhase") {
    renderActionPhase();
  } else if (activePage === "leaderboard") {
    renderLeaderboard();
  } else if (activePage === "mvpRace") {
    renderMvpRace();
  } else if (activePage === "battlePhase") {
    renderBattlePhase();
  } else if (activePage === "banlist") {
    renderBanlist();
  } else if (activePage === "info") {
    renderInfoPage();
  }
  renderPerkTestRoller();
  if (state.activityLogCollapsed === false) {
    renderActivityFilters();
    renderLog();
  }
  renderActivityToasts();
  renderActivityResponseDrawer();
  renderLiveRefereePanel();
  renderOpponentDrawer();
  renderCart();
  renderWheelPanel();
  renderRandomPokemonPanel();
  renderSiteShell();
  syncTokenSandboxBanner();
  if (actionPhaseStateRepairQueued && !backendSync.applyingRemote && !tokenScenarioSandboxActive()) {
    actionPhaseStateRepairQueued = false;
    saveState({ immediate: true, immediateBackend: true });
  }
}

function applyShopTheme(root, colors, contrast) {
  const onBrand = colors.onBrand || "#ffffff";
  const lightSurface = relativeLuminance(colors.surface) >= 0.62;
  const shopPageBg = lightSurface
    ? `linear-gradient(180deg, color-mix(in srgb, ${colors.surface} 88%, ${colors.brand} 12%), color-mix(in srgb, ${colors.surface} 94%, ${colors.bg} 6%))`
    : `linear-gradient(180deg, color-mix(in srgb, ${colors.bg} 86%, ${colors.brand} 14%), ${colors.bg})`;
  const shopPanelBg = lightSurface
    ? `color-mix(in srgb, ${colors.surface} 88%, ${colors.brand} 12%)`
    : `color-mix(in srgb, ${colors.surface} 88%, ${colors.brand} 12%)`;
  const shopPanelBgStrong = lightSurface
    ? `color-mix(in srgb, ${colors.surface} 82%, ${colors.brand} 18%)`
    : `color-mix(in srgb, ${colors.surface2} 82%, ${colors.brand} 18%)`;
  const shopSectionHeaderBg = lightSurface
    ? `color-mix(in srgb, ${colors.surface} 86%, ${colors.brand} 14%)`
    : `color-mix(in srgb, ${colors.surface2} 86%, ${colors.brand} 14%)`;
  const shopCardBg = lightSurface
    ? `color-mix(in srgb, ${colors.surface} 95%, ${colors.brand} 5%)`
    : colors.surface;
  const shopCardBgAccent = lightSurface
    ? `color-mix(in srgb, ${colors.surface} 90%, ${colors.brand} 10%)`
    : `color-mix(in srgb, ${colors.surface} 86%, ${colors.brand} 14%)`;
  const shopInputBg = lightSurface
    ? `color-mix(in srgb, ${colors.surface} 92%, ${colors.brand} 8%)`
    : `color-mix(in srgb, ${colors.surface} 86%, ${colors.bg} 14%)`;
  const shopBorder = lightSurface
    ? `color-mix(in srgb, ${colors.line} 62%, ${colors.brand} 38%)`
    : `color-mix(in srgb, ${colors.line} 82%, transparent)`;
  const shopSecondary = lightSurface
    ? `color-mix(in srgb, ${colors.surface} 90%, ${colors.brand} 10%)`
    : contrast.surface;
  const shopSecondaryBorder = lightSurface
    ? `color-mix(in srgb, ${colors.line} 72%, ${colors.brand} 28%)`
    : contrast.line;
  const shopTooltipBg = lightSurface
    ? `color-mix(in srgb, ${colors.ink} 92%, ${colors.brand} 8%)`
    : `color-mix(in srgb, ${colors.surface2} 88%, ${colors.brand} 12%)`;
  root.style.setProperty("--shop-page-bg", colors.shopPageBg || shopPageBg);
  root.style.setProperty("--shop-panel-bg", colors.shopPanelBg || shopPanelBg);
  root.style.setProperty("--shop-panel-bg-strong", colors.shopPanelBgStrong || shopPanelBgStrong);
  root.style.setProperty("--shop-section-header-bg", colors.shopSectionHeaderBg || shopSectionHeaderBg);
  root.style.setProperty("--shop-card-bg", colors.shopCardBg || shopCardBg);
  root.style.setProperty("--shop-card-bg-accent", colors.shopCardBgAccent || shopCardBgAccent);
  root.style.setProperty("--shop-input-bg", colors.shopInputBg || shopInputBg);
  root.style.setProperty("--shop-border", colors.shopBorder || shopBorder);
  root.style.setProperty("--shop-border-hover", colors.shopBorderHover || `color-mix(in srgb, ${colors.brand} 62%, ${colors.line})`);
  root.style.setProperty("--shop-primary", colors.shopPrimary || colors.brand);
  root.style.setProperty("--shop-primary-ink", colors.shopPrimaryInk || onBrand);
  root.style.setProperty("--shop-secondary", colors.shopSecondary || shopSecondary);
  root.style.setProperty("--shop-secondary-border", colors.shopSecondaryBorder || shopSecondaryBorder);
  root.style.setProperty("--shop-secondary-ink", colors.shopSecondaryInk || (lightSurface ? colors.ink : contrast.ink));
  root.style.setProperty("--shop-text", colors.shopText || colors.ink);
  root.style.setProperty("--shop-muted", colors.shopMuted || colors.muted);
  root.style.setProperty("--shop-token-ring", colors.shopTokenRing || `color-mix(in srgb, ${colors.brand} 65%, ${colors.line})`);
  root.style.setProperty("--shop-token-ring-muted", colors.shopTokenRingMuted || `color-mix(in srgb, ${colors.line} 66%, ${colors.brand} 34%)`);
  root.style.setProperty("--shop-token-surface", colors.shopTokenSurface || (lightSurface ? `color-mix(in srgb, ${colors.surface} 90%, ${colors.brand} 10%)` : `color-mix(in srgb, ${colors.surface} 82%, ${colors.brand} 18%)`));
  root.style.setProperty("--shop-token-price-bg", colors.shopTokenPriceBg || (lightSurface ? `color-mix(in srgb, ${colors.surface} 80%, ${colors.brand} 20%)` : `color-mix(in srgb, ${colors.surface2} 70%, ${colors.brand} 30%)`));
  root.style.setProperty("--shop-token-action-bg", colors.shopTokenActionBg || colors.brand);
  root.style.setProperty("--shop-token-action-border", colors.shopTokenActionBorder || `color-mix(in srgb, ${colors.brand} 70%, ${colors.line})`);
  root.style.setProperty("--shop-token-glow", colors.shopTokenGlow || `color-mix(in srgb, ${colors.brand} ${lightSurface ? 14 : 24}%, transparent)`);
  root.style.setProperty("--shop-tooltip-bg", colors.shopTooltipBg || shopTooltipBg);
  root.style.setProperty("--shop-tooltip-text", colors.shopTooltipText || (lightSurface ? colors.surface : contrast.ink));
  root.style.setProperty("--shop-control-accent", colors.shopControlAccent || colors.danger);
  root.style.setProperty("--shop-curse-accent", colors.shopCurseAccent || colors.brandDark);
  root.style.setProperty("--shop-encounter-accent", colors.shopEncounterAccent || colors.gold);
  root.style.setProperty("--shop-protection-accent", colors.shopProtectionAccent || colors.brand);
  root.style.setProperty("--shop-game-corner-accent", colors.shopGameCornerAccent || colors.gold);
  root.style.setProperty("--shop-field-accent", colors.shopFieldAccent || colors.brandDark);
}

function applyTheme(themeId) {
  const theme = themes[themeId] || themes.midnightRed || Object.values(themes)[0];
  const root = document.documentElement;
  const contrast = contrastSurfaceTokens(theme.colors.surface2, theme.colors.ink, theme.colors.muted, theme.colors.line);
  const lightTheme = relativeLuminance(theme.colors.surface) >= 0.62;
  const accent2 = theme.colors.accent2 || theme.colors.gold || theme.colors.brandDark;
  root.style.setProperty("--bg", theme.colors.bg);
  root.style.setProperty("--surface", theme.colors.surface);
  root.style.setProperty("--surface-2", theme.colors.surface2);
  root.style.setProperty("--ink", theme.colors.ink);
  root.style.setProperty("--muted", theme.colors.muted);
  root.style.setProperty("--line", theme.colors.line);
  root.style.setProperty("--brand", theme.colors.brand);
  root.style.setProperty("--brand-dark", theme.colors.brandDark);
  root.style.setProperty("--accent-2", accent2);
  root.style.setProperty("--on-accent-2", theme.colors.onAccent2 || theme.colors.onBrand || "#ffffff");
  root.style.setProperty("--gold", theme.colors.gold);
  root.style.setProperty("--success", theme.colors.success || "#138a4b");
  root.style.setProperty("--warning", theme.colors.warning || "#b26b00");
  root.style.setProperty("--info", theme.colors.info || theme.colors.brand);
  root.style.setProperty("--danger", theme.colors.danger);
  root.style.setProperty("--on-brand", theme.colors.onBrand || "#ffffff");
  root.style.setProperty("--result-bg", theme.colors.resultBg || contrast.surface);
  root.style.setProperty("--result-ink", theme.colors.resultInk || contrast.ink);
  root.style.setProperty("--result-border", theme.colors.resultBorder || theme.colors.success || theme.colors.brand);
  const softShadow = theme.colors.shadow || (lightTheme
    ? "0 10px 28px rgba(22, 31, 40, 0.12)"
    : "0 12px 32px rgba(0, 0, 0, 0.34)");
  const strongShadow = theme.colors.strongShadow || (lightTheme
    ? "0 18px 46px rgba(22, 31, 40, 0.18)"
    : "0 22px 54px rgba(0, 0, 0, 0.5)");
  root.style.setProperty("--shadow", softShadow);
  root.style.setProperty("--shadow-soft", softShadow);
  root.style.setProperty("--shadow-strong", strongShadow);
  root.style.setProperty("--edge-highlight", lightTheme ? "rgba(255, 255, 255, 0.78)" : "rgba(255, 255, 255, 0.14)");
  root.style.colorScheme = lightTheme ? "light" : "dark";
  root.style.setProperty("--contrast-surface", contrast.surface);
  root.style.setProperty("--contrast-surface-ink", contrast.ink);
  root.style.setProperty("--contrast-surface-text", contrast.ink);
  root.style.setProperty("--contrast-surface-muted", contrast.muted);
  root.style.setProperty("--contrast-surface-line", contrast.line);
  root.style.setProperty("--header-bg", theme.colors.headerBg || theme.colors.surface);
  root.style.setProperty("--header-sub-bg", theme.colors.headerSubBg || theme.colors.surface);
  root.style.setProperty("--header-ink", theme.colors.headerInk || theme.colors.ink);
  root.style.setProperty("--header-muted", theme.colors.headerMuted || theme.colors.muted);
  root.style.setProperty("--header-line", theme.colors.headerLine || theme.colors.line);
  root.style.setProperty("--header-accent", theme.colors.headerAccent || theme.colors.brand);
  root.style.setProperty("--header-chip-bg", theme.colors.headerChipBg || theme.colors.surface2);
  root.style.setProperty("--header-chip-ink", theme.colors.headerChipInk || theme.colors.ink);
  root.style.setProperty("--header-chip-line", theme.colors.headerChipLine || theme.colors.line);
  root.style.setProperty("--header-control-bg", theme.colors.headerControlBg || theme.colors.surface);
  root.style.setProperty("--header-control-ink", theme.colors.headerControlInk || theme.colors.ink);
  root.style.setProperty("--header-control-line", theme.colors.headerControlLine || theme.colors.line);
  applyShopTheme(root, theme.colors, contrast);
}

function hexToRgb(hex) {
  const clean = String(hex || "").replace("#", "").trim();
  if (clean.length !== 6) return null;
  const value = Number.parseInt(clean, 16);
  if (!Number.isFinite(value)) return null;
  return {
    r: (value >> 16) & 255,
    g: (value >> 8) & 255,
    b: value & 255
  };
}

function relativeLuminance(hex) {
  const rgb = hexToRgb(hex);
  if (!rgb) return 1;
  const channel = (value) => {
    const normalized = value / 255;
    return normalized <= 0.03928 ? normalized / 12.92 : ((normalized + 0.055) / 1.055) ** 2.4;
  };
  return 0.2126 * channel(rgb.r) + 0.7152 * channel(rgb.g) + 0.0722 * channel(rgb.b);
}

function contrastSurfaceTokens(surface, ink, muted, line) {
  const darkSurface = relativeLuminance(surface) < 0.38;
  return {
    surface,
    ink: darkSurface ? "#f8fbff" : ink,
    muted: darkSurface ? "rgba(248, 251, 255, 0.78)" : muted,
    line: darkSurface ? "rgba(248, 251, 255, 0.28)" : line
  };
}

function applyHeaderTheme(themeId) {
  const theme = playerHeaderThemes[themeId] || headerThemes.default;
  const globalTheme = themes[activePlayer()?.theme] || themes.midnightRed || Object.values(themes)[0];
  const fallback = {
    headerBg: globalTheme.colors.headerBg || globalTheme.colors.surface,
    headerSubBg: globalTheme.colors.headerSubBg || globalTheme.colors.surface2 || globalTheme.colors.surface,
    headerInk: globalTheme.colors.headerInk || globalTheme.colors.ink,
    headerMuted: globalTheme.colors.headerMuted || globalTheme.colors.muted,
    headerLine: globalTheme.colors.headerLine || globalTheme.colors.line,
    headerAccent: globalTheme.colors.headerAccent || globalTheme.colors.brand,
    headerChipBg: globalTheme.colors.headerChipBg || globalTheme.colors.surface,
    headerChipInk: globalTheme.colors.headerChipInk || globalTheme.colors.ink,
    headerChipLine: globalTheme.colors.headerChipLine || globalTheme.colors.line,
    headerControlBg: globalTheme.colors.headerControlBg || globalTheme.colors.surface,
    headerControlInk: globalTheme.colors.headerControlInk || globalTheme.colors.ink,
    headerControlLine: globalTheme.colors.headerControlLine || globalTheme.colors.line
  };
  const root = document.documentElement;
  root.style.setProperty("--header-bg", theme.colors.headerBg || fallback.headerBg);
  root.style.setProperty("--header-sub-bg", theme.colors.headerSubBg || fallback.headerSubBg);
  root.style.setProperty("--header-ink", theme.colors.headerInk || fallback.headerInk);
  root.style.setProperty("--header-muted", theme.colors.headerMuted || fallback.headerMuted);
  root.style.setProperty("--header-line", theme.colors.headerLine || fallback.headerLine);
  root.style.setProperty("--header-accent", theme.colors.headerAccent || theme.colors.headerLine || fallback.headerAccent);
  root.style.setProperty("--header-chip-bg", theme.colors.headerChipBg || theme.colors.headerSubBg || fallback.headerChipBg);
  root.style.setProperty("--header-chip-ink", theme.colors.headerChipInk || theme.colors.headerInk || fallback.headerChipInk);
  root.style.setProperty("--header-chip-line", theme.colors.headerChipLine || theme.colors.headerLine || fallback.headerChipLine);
  root.style.setProperty("--header-control-bg", theme.colors.headerControlBg || theme.colors.headerBg || fallback.headerControlBg);
  root.style.setProperty("--header-control-ink", theme.colors.headerControlInk || theme.colors.headerInk || fallback.headerControlInk);
  root.style.setProperty("--header-control-line", theme.colors.headerControlLine || theme.colors.headerLine || fallback.headerControlLine);
}

function renderThemeChoices(container, choices, activeId, onSelect) {
  container.replaceChildren(...Object.entries(choices).map(([id, theme]) => {
    const button = document.createElement("button");
    button.type = "button";
    button.className = `theme-choice${activeId === id ? " active" : ""}`;
    button.dataset.theme = id;
    const colors = theme.colors;
    button.innerHTML = `
      <span class="theme-swatches">
        <i style="background:${colors.brand || colors.headerLine || "#999"}"></i>
        <i style="background:${colors.accent2 || colors.headerAccent || colors.surface2 || colors.headerSubBg || "#ddd"}"></i>
        <i style="background:${colors.gold || colors.headerInk || "#555"}"></i>
      </span>
      <span>${theme.name}</span>
    `;
    button.addEventListener("click", () => {
      onSelect(id);
    });
    return button;
  }));
}

function renderGlobalThemeMenu(player) {
  renderThemeChoices(els.globalThemeMenu, themes, player.theme || "midnightRed", (id) => {
    if (!requirePrivatePrepAccess(player, "trainer profile")) return;
    player.theme = id;
    els.globalThemeMenu.classList.add("hidden");
    els.globalThemeToggle?.setAttribute("aria-expanded", "false");
    saveState();
    render();
  });
}

function renderHeaderThemeMenu(player) {
  renderThemeChoices(els.themeMenu, playerHeaderThemes, player.headerTheme || "default", (id) => {
    if (!requirePrivatePrepAccess(player, "trainer profile")) return;
    player.headerTheme = id;
    els.themeMenu.classList.add("hidden");
    saveState();
    render();
  });
}

function renderMiniPills(container, values, emptyText = "No perks") {
  const visible = values.filter((value) => value && value !== "Reserved space").slice(0, 4);
  container.replaceChildren(...(visible.length ? visible : [emptyText]).map((value) => {
    const pill = document.createElement("span");
    pill.className = "mini-pill";
    pill.textContent = value;
    return pill;
  }));
}

function renderEffectPills(container, values, emptyText, type) {
  const visible = values.filter((value) => value && value !== "Reserved space");
  if (!visible.length) {
    const pill = document.createElement("span");
    pill.className = "mini-pill empty-effect";
    pill.textContent = emptyText;
    container.replaceChildren(pill);
    return;
  }

  container.replaceChildren(...visible.map((value) => {
    const pill = document.createElement("span");
    pill.className = "mini-pill actionable-pill";
    pill.tabIndex = 0;
    pill.textContent = value;
    pill.addEventListener("click", (event) => {
      event.stopPropagation();
      if (!requirePrivatePrepAccess(activePlayer(), `${type} editing`)) return;
      openObjectActionMenu({
        event,
        player: activePlayer(),
        effect: { id: `${type}:${value}`, type, name: value },
        canRemove: true,
        removeType: type
      });
    });
    pill.addEventListener("keydown", (event) => {
      if (!["Enter", " "].includes(event.key)) return;
      event.preventDefault();
      if (!requirePrivatePrepAccess(activePlayer(), `${type} editing`)) return;
      const rect = pill.getBoundingClientRect();
      openObjectActionMenu({
        event: { clientX: rect.left + 12, clientY: rect.bottom + 6 },
        player: activePlayer(),
        effect: { id: `${type}:${value}`, type, name: value },
        canRemove: true,
        removeType: type
      });
    });
    return pill;
  }));
}

function addEffect(type) {
  if (!requirePrivatePrepAccess(activePlayer(), `${type} editing`)) return;
  const value = prompt(type === "nerf" ? "Add nerf" : type === "buff" ? "Add buff" : "Add perk");
  const name = value?.trim();
  if (!name) return;
  const player = activePlayer();
  const key = type === "nerf" ? "nerfs" : type === "buff" ? "buffs" : "perks";
  player[key] = [name, ...(player[key] || []).filter((item) => item !== "Reserved space")];
  addLogEntry({
    action: "effect",
    category: type === "nerf" ? "nerfs" : "perks",
    player: player.name,
    item: `${type === "nerf" ? "Nerf" : type === "buff" ? "Buff" : "Perk"} added: ${name}`,
    type,
    quantity: 1,
    price: 0,
    balanceAfter: player.balance
  });
  saveState();
  render();
}

function removeEffect(type, value) {
  const player = activePlayer();
  if (!requirePrivatePrepAccess(player, `${type} editing`)) return;
  const key = type === "nerf" ? "nerfs" : type === "buff" ? "buffs" : "perks";
  player[key] = (player[key] || []).filter((item) => item !== value);
  addLogEntry({
    action: "effect",
    category: type === "nerf" ? "nerfs" : "perks",
    player: player.name,
    item: `${type === "nerf" ? "Nerf" : type === "buff" ? "Buff" : "Perk"} removed: ${value}`,
    type,
    quantity: 1,
    price: 0,
    balanceAfter: player.balance
  });
  saveState();
  render();
}

function adjustMomentum(delta) {
  const player = activePlayer();
  const before = player.momentum ?? 0;
  player.momentum = Math.max(0, (player.momentum ?? 0) + delta);
  addLogEntry({
    action: "momentum",
    category: "player",
    player: player.name,
    item: `Momentum ${before} -> ${player.momentum}`,
    type: "momentum",
    quantity: 1,
    price: 0,
    balanceAfter: player.balance
  });
  saveState();
  render();
}

function applyNaturalShopLevelIncrease(phaseState) {
  if (!phaseState || phaseState.shopLevelIncreaseApplied) return [];
  const naturalLevel = Math.min(4, Math.max(0, Number(state.gym || 1)));
  const changes = [];
  state.players.forEach((player) => {
    player.shopLevels ||= { items: 0, tms: 0, tokens: 0 };
    const beforeItems = Number(player.shopLevels.items || 0);
    const beforeTms = Number(player.shopLevels.tms || 0);
    player.shopLevels.items = Math.max(beforeItems, naturalLevel);
    player.shopLevels.tms = Math.max(beforeTms, naturalLevel);
    if (player.shopLevels.items !== beforeItems || player.shopLevels.tms !== beforeTms) {
      changes.push({
        playerId: player.id,
        playerName: player.name,
        beforeItems,
        afterItems: player.shopLevels.items,
        beforeTms,
        afterTms: player.shopLevels.tms
      });
    }
  });
  phaseState.shopLevelIncreaseApplied = true;
  addLogEntry({
    action: "phase",
    category: "series",
    player: "Phase System",
    item: changes.length
      ? `Natural shop levels applied for ${phaseCode()}: ${changes.map((entry) => `${entry.playerName} Items ${entry.beforeItems}->${entry.afterItems}, TMs ${entry.beforeTms}->${entry.afterTms}`).join("; ")}`
      : `Natural shop levels checked for ${phaseCode()}: no increases needed`,
    type: "phase-shop-level-increase",
    quantity: changes.length,
    price: 0,
    balanceAfter: 0
  });
  return changes;
}

function phaseAdvanceConfirmMessage(target = nextPhaseTarget()) {
  if (target.phase === "chooseStartSeries") return "Choose the first series for this game, or use Random Series.";
  if (target.flowOnly) return `Move the Live Referee to ${LIVE_REFEREE_FLOW_LABELS[target.flowState] || target.label}?`;
  if (target.phase === "action") return "Are you sure you want to advance to the Action Phase?";
  if (target.phase === "battle") return "Are you sure you want to advance to the Battle Phase?";
  if (target.phase === "battle-results") return "Are you sure you want to advance to the Battle Results Phase?";
  if (target.phase === "shop") return "Are you sure you want to advance to the Shop Phase?";
  if (target.requiresSeriesChoice) return "Choose the next series, or use Random Series.";
  const next = nextSeriesGym();
  return next
    ? `Are you sure you want to advance to ${next.series} Gym ${next.gym}?`
    : "Are you sure you want to advance to the next gym?";
}

function phaseAdvanceBlockedByActionOperation(target = nextPhaseTarget()) {
  if (!target || target.phase === "chooseStartSeries") return "";
  const operation = currentActionOperation();
  if (!operation) return "";
  const owner = state.players.find((player) => player.id === operation.playerId);
  const trainer = owner?.name || "The active trainer";
  const location = operation.locationName || actionLocationById(operation.locationId)?.name || "their current Action";
  return `${trainer} is still resolving ${location}. Finish or undo that Action before advancing phases.`;
}





function skipHoneyEndOfActionProcedure(activityId) {
  const activity = liveActivityById(activityId);
  const procedure = honeyProcedureForActivity(activity);
  if (!procedure) return false;
  procedure.status = "skipped";
  procedure.resolvedAt = new Date().toISOString();
  activity.status = "resolved";
  activity.resolution = "skipped-without-consumption";
  saveState({ immediate: true });
  render();
  return true;
}


function renderPhaseSeriesChoice(target = pendingPhaseAdvance) {
  const show = Boolean(target?.requiresSeriesChoice || target?.phase === "chooseStartSeries");
  els.phaseSeriesChoice?.classList.toggle("hidden", !show);
  if (!show || !els.phaseSeriesChoiceSelect) return;
  const options = target.phase === "chooseStartSeries" ? [...seriesNames] : availableSeriesChoices();
  els.phaseSeriesChoiceSelect.replaceChildren(...options.map((series) => new Option(series, series)));
  els.phaseSeriesChoiceSelect.value = target.selectedSeries && options.includes(target.selectedSeries)
    ? target.selectedSeries
    : options[0] || seriesNames[0];
}

function openPhaseAdvanceConfirm() {
  pendingPhaseAdvance = nextPhaseTarget();
  const blockedReason = phaseAdvanceBlockedByActionOperation(pendingPhaseAdvance);
  if (blockedReason) {
    pendingPhaseAdvance = null;
    alert(blockedReason);
    return;
  }
  els.phaseConfirmTitle.textContent = pendingPhaseAdvance.phase === "chooseStartSeries"
    ? "Choose Starting Series"
    : pendingPhaseAdvance.phase === "nextGym" ? "Advance Gym?" : pendingPhaseAdvance.flowOnly ? "Advance Gameflow?" : "Advance Phase?";
  els.phaseConfirmMessage.textContent = phaseAdvanceConfirmMessage(pendingPhaseAdvance);
  els.confirmPhaseAdvance.textContent = pendingPhaseAdvance.phase === "chooseStartSeries" ? "Start Series" : "Confirm";
  renderPhaseSeriesChoice(pendingPhaseAdvance);
  els.phaseConfirmModal.classList.remove("hidden");
}

function openStartSeriesChoice() {
  if (!state.seriesChoiceRequired || pendingPhaseAdvance || !els.phaseConfirmModal?.classList.contains("hidden")) return;
  pendingPhaseAdvance = { phase: "chooseStartSeries", label: "Start Series", requiresSeriesChoice: true };
  els.phaseConfirmTitle.textContent = "Choose Starting Series";
  els.phaseConfirmMessage.textContent = phaseAdvanceConfirmMessage(pendingPhaseAdvance);
  els.confirmPhaseAdvance.textContent = "Start Series";
  renderPhaseSeriesChoice(pendingPhaseAdvance);
  els.phaseConfirmModal.classList.remove("hidden");
}

function phaseAdvanceUndoSnapshot() {
  return {
    series: state.series,
    gym: Number(state.gym),
    currentPhase: currentPhase(),
    phaseState: structuredClone(state.phaseState || {}),
    seriesOrder: structuredClone(state.seriesOrder || []),
    seriesChoiceRequired: Boolean(state.seriesChoiceRequired),
    momentum: Object.fromEntries(state.players.map((player) => [player.id, Number(player.momentum || 0)])),
    inventories: Object.fromEntries(state.players.map((player) => [player.id, structuredClone(player.inventory || [])])),
    pokemonRecords: structuredClone(state.pokemonRecords || []),
    playerNotifications: structuredClone(state.playerNotifications || []),
    breederDeposits: structuredClone(state.breederDeposits || []),
    dragonsDenSessions: structuredClone(state.dragonsDenSessions || []),
    lingeringStatuses: structuredClone(state.lingeringStatuses || []),
    globalPokemonRules: structuredClone(state.globalPokemonRules || {}),
    banlistHistory: structuredClone(state.banlistHistory || []),
    delayedEffects: structuredClone(state.delayedEffects || []),
    broughtTeamSnapshots: structuredClone(state.broughtTeamSnapshots || []),
    copiedActivations: structuredClone(state.copiedActivations || []),
    postPayoutProcedures: structuredClone(state.postPayoutProcedures || []),
    endOfActionProcedures: structuredClone(state.endOfActionProcedures || []),
    copiedTokenRelationships: structuredClone(state.copiedTokenRelationships || []),
    privateEffectRecords: structuredClone(state.privateEffectRecords || []),
    encounterCopyRecords: structuredClone(state.encounterCopyRecords || []),
    effectOperations: structuredClone(state.effectOperations || [])
  };
}

function closePhaseAdvanceConfirm() {
  pendingPhaseAdvance = null;
  els.confirmPhaseAdvance.textContent = "Confirm";
  els.phaseSeriesChoice?.classList.add("hidden");
  els.phaseConfirmModal.classList.add("hidden");
}

async function confirmPhaseAdvance({ skipPendingGuard = false } = {}) {
  if (!pendingPhaseAdvance) return;
  const target = pendingPhaseAdvance;
  const blockedReason = phaseAdvanceBlockedByActionOperation(target);
  if (blockedReason) {
    alert(blockedReason);
    return;
  }
  const unresolvedDevelopment = (state.playerNotifications || []).find((notification) =>
    ["breeder-egg-move", "daycare-tm-move", "dragons-den-reward"].includes(notification.type)
    && !["completed", "resolved", "cancelled", "dismissed"].includes(String(notification.status || "pending").toLowerCase()));
  if (unresolvedDevelopment && (target.phase === "battle" || target.flowState === LIVE_REFEREE_FLOW_STATES.TEAM_LOCK)) {
    const owner = state.players.find((player) => player.id === unresolvedDevelopment.playerId);
    alert(`${owner?.name || "A trainer"} must resolve ${unresolvedDevelopment.title || "a facility reward"} before Team Lock.`);
    return;
  }
  const revisionOperation = currentBlockingBattleRevisionOperation();
  if (revisionOperation) {
    alert("Sabotage is paused until every required team revision is confirmed.");
    return;
  }
  if (target.requiresSeriesChoice || target.phase === "chooseStartSeries") {
    target.selectedSeries = els.phaseSeriesChoiceSelect?.value || randomSeriesChoice();
  }
  if (!skipPendingGuard && !guardPendingEventBeforeAction(target.phase === "battle" ? "Start Battle Phase" : "Advance Phase", () => {
    pendingPhaseAdvance = target;
    confirmPhaseAdvance({ skipPendingGuard: true });
  })) return;
  closePhaseAdvanceConfirm();
  await performPhaseAdvance(target);
}

function advancePhase() {
  openPhaseAdvanceConfirm();
}

window.advancePhase = advancePhase;
window.confirmPhaseAdvance = confirmPhaseAdvance;
window.closePhaseAdvanceConfirm = closePhaseAdvanceConfirm;

async function performPhaseAdvance(target = nextPhaseTarget()) {
  const undoSnapshot = phaseAdvanceUndoSnapshot();
  const phaseState = currentGymPhaseState();
  const now = new Date().toISOString();
  const previousPhase = phaseState.currentPhase;
  if (!target.flowOnly && previousPhase === "action" && target.phase === "battle") {
  }
  if (target.flowOnly) {
    if (target.requiresTeamsLocked && !phaseTeamsLocked()) {
      alert("All players must lock legal teams before this gameflow step can begin.");
      return;
    }
    const previousFlowState = currentLiveRefereeFlowState();
    if (target.flowState === LIVE_REFEREE_FLOW_STATES.TEAM_LOCK) setBattlePhaseSubstep("teamSubmissionLock");
    if (target.flowState === LIVE_REFEREE_FLOW_STATES.SABOTAGE) setBattlePhaseSubstep("sabotage");
    if (target.flowState === LIVE_REFEREE_FLOW_STATES.TEAM_PREVIEW) {
      const revealed = await revealTeamPreview({ skipPendingGuard: true });
      if (!revealed) return;
    } else if (target.flowState === LIVE_REFEREE_FLOW_STATES.RIVAL_BATTLES) {
      setBattlePhaseSubstep("rivalBattles");
    }
    setLiveRefereeFlowState(target.flowState, phaseState);
    phaseState.phaseHistory ||= [];
    phaseState.phaseHistory.push({
      series: state.series,
      gym: Number(state.gym),
      phase: previousPhase,
      flowState: target.flowState,
      enteredAt: now,
      completedAt: null
    });
    addLogEntry({
      action: "phase",
      category: "series",
      player: "Phase System",
      item: `Advanced ${LIVE_REFEREE_FLOW_LABELS[previousFlowState] || previousFlowState} to ${LIVE_REFEREE_FLOW_LABELS[target.flowState] || target.flowState}`,
      title: `${LIVE_REFEREE_FLOW_LABELS[target.flowState] || target.flowState} started`,
      type: "gameflow-advance",
      quantity: 1,
      price: 0,
      balanceAfter: 0,
      undoable: true,
      undone: false,
      undoData: {
        actionType: "undoPhaseAdvance",
        previousState: undoSnapshot,
        newState: phaseAdvanceUndoSnapshot()
      }
    });
    render();
    await saveState({ immediate: true, immediateBackend: true });
    return;
  }
  if (target.phase === "chooseStartSeries") {
    const selectedSeries = seriesNames.includes(target.selectedSeries) ? target.selectedSeries : randomSeriesChoice();
    state.series = selectedSeries;
    state.gym = 1;
    state.seriesChoiceRequired = false;
    state.seriesOrder = [selectedSeries];
    state.battleLogView = { series: selectedSeries, gym: 1 };
    const startPhaseState = setCurrentGymPhase("start", selectedSeries, 1);
    startPhaseState.phaseHistory = [{
      series: selectedSeries,
      gym: 1,
      phase: "start",
      enteredAt: now,
      completedAt: null
    }];
    addLogEntry({
      action: "phase",
      category: "series",
      player: "Phase System",
      item: `Started new game at ${selectedSeries} Gym 1 Start of Gym Phase`,
      type: "series-start",
      quantity: 1,
      price: 0,
      balanceAfter: 0
    });
    render();
    await saveState({ immediate: true, immediateBackend: true });
    return;
  }
  const history = phaseState.phaseHistory || [];
  const openEntry = [...history].reverse().find((entry) => entry.phase === previousPhase && !entry.completedAt);
  if (openEntry) openEntry.completedAt = now;
  if (target.phase === "nextGym") {
    const next = nextSeriesGym(state.series, state.gym, target.selectedSeries);
    if (!next) {
      alert("Paldea Gym 9 is the final scheduled gym. No next gym is available yet.");
      return;
    }
    const previousLabel = `${state.series} Gym ${state.gym}`;
    const outgoingGymOptions = controlTokenEffectOptions(now);
    controlTokenEffects?.expireColdWaveAtGymEnd?.(state, outgoingGymOptions);
    controlTokenEffects?.expireMoveRestrictionsAtGymEnd?.(state, outgoingGymOptions);
    if (next.series !== state.series) clearSeriesEvolutionLocksForSeries(state.series);
    state.series = next.series;
    state.gym = next.gym;
    processAutomaticFacilityReturns();
    state.seriesOrder ||= [];
    if (!state.seriesOrder.includes(next.series)) state.seriesOrder.push(next.series);
    state.battleLogView = { series: next.series, gym: Number(next.gym) };
    const nextPhaseState = setCurrentGymPhase("start", next.series, next.gym);
    nextPhaseState.phaseHistory.push({
      series: next.series,
      gym: Number(next.gym),
      phase: "start",
      enteredAt: now,
      completedAt: null
    });
    expireLingeringStatuses();
    expireTokenInventoryRuntimeRecords();
    processDueTeleportDelayedEffects(now);
    addLogEntry({
      action: "phase",
      category: "series",
      player: "Phase System",
      item: `Advanced from ${previousLabel} Shop Phase to ${next.series} Gym ${next.gym} Start of Gym Phase`,
      type: "phase-advance",
      quantity: 1,
      price: 0,
      balanceAfter: 0,
      undoable: true,
      undone: false,
      undoData: {
        actionType: "undoPhaseAdvance",
        previousState: undoSnapshot,
        newState: phaseAdvanceUndoSnapshot()
      }
    });
  } else {
    const updatedPhaseState = setCurrentGymPhase(target.phase);
    if (target.phase === "battle-results" && controlTokenEffects?.expireArenaTrapsAtBattleEnd) {
      const expiredArenaTraps = controlTokenEffects.expireArenaTrapsAtBattleEnd(state, controlTokenEffectOptions(now));
      (expiredArenaTraps.cleanupRecords || []).forEach((cleanup) => {
        const pokemon = findPokemonRecord(cleanup.rosterInstanceId);
        const owner = state.players.find((player) => player.id === cleanup.targetPlayerId);
        addLogEntry({
          action: "token",
          category: "tokens",
          player: owner?.name || "Arena Trap",
          item: `Arena Trap expired for ${owner?.name ? `${owner.name}'s ` : ""}${pokemon?.name || "Pokemon"}.`,
          title: "Arena Trap cleanup completed",
          summary: [
            "Forced-team lock removed.",
            "Curse protection removed.",
            cleanup.removedBuffIds?.length ? `${cleanup.removedBuffIds.length} linked customization record${cleanup.removedBuffIds.length === 1 ? "" : "s"} expired.` : "No linked Arena customization was active.",
            "Historical submitted team records were not changed."
          ].join("\n"),
          type: "arena-trap-expiration",
          categories: ["tokens", "battle", "pokemon"],
          tags: ["arena-trap", "expiration", "exact-instance"],
          playerIds: [cleanup.targetPlayerId].filter(Boolean),
          pokemonIds: [cleanup.rosterInstanceId].filter(Boolean)
        });
      });
    }
    expireLingeringStatuses();
    expireTokenInventoryRuntimeRecords();
    updatedPhaseState.phaseHistory.push({
      series: state.series,
      gym: Number(state.gym),
      phase: target.phase,
      enteredAt: now,
      completedAt: null
    });
    processDueTeleportDelayedEffects(now);
    const logEntry = {
      action: "phase",
      category: "series",
      player: "Phase System",
      item: `Started ${phaseLabels[target.phase]} for ${state.series} Gym ${state.gym}`,
      type: "phase-advance",
      quantity: 1,
      price: 0,
      balanceAfter: 0,
      undoable: true,
      undone: false,
      undoData: {
        actionType: "undoPhaseAdvance",
        previousState: undoSnapshot,
        newState: null
      }
    };
    if (target.phase === "shop") applyNaturalShopLevelIncrease(updatedPhaseState);
    logEntry.undoData.newState = phaseAdvanceUndoSnapshot();
    addLogEntry(logEntry);
  }
  els.phaseAgendaPanel.classList.add("hidden");
  els.phaseAgendaToggle.setAttribute("aria-expanded", "false");
  render();
  await saveState({ immediate: true, immediateBackend: true });
}

