  els.avatarZoom.addEventListener("input", () => {
    if (!avatarCropState) return;
    avatarCropState.zoom = Number(els.avatarZoom.value);
    updateAvatarCropper();
  });
  els.avatarCropViewport.addEventListener("pointerdown", (event) => {
    if (!avatarCropState) return;
    avatarCropState.dragging = true;
    avatarCropState.lastX = event.clientX;
    avatarCropState.lastY = event.clientY;
    els.avatarCropViewport.setPointerCapture(event.pointerId);
  });
  els.avatarCropViewport.addEventListener("pointermove", (event) => {
    if (!avatarCropState?.dragging) return;
    avatarCropState.x += event.clientX - avatarCropState.lastX;
    avatarCropState.y += event.clientY - avatarCropState.lastY;
    avatarCropState.lastX = event.clientX;
    avatarCropState.lastY = event.clientY;
    updateAvatarCropper();
  });
  els.avatarCropViewport.addEventListener("pointerup", () => {
    if (avatarCropState) avatarCropState.dragging = false;
  });
  els.avatarCropViewport.addEventListener("pointercancel", () => {
    if (avatarCropState) avatarCropState.dragging = false;
  });
  els.avatarCropViewport.addEventListener("wheel", (event) => {
    if (!avatarCropState) return;
    event.preventDefault();
    const nextZoom = Math.min(3, Math.max(1, avatarCropState.zoom + (event.deltaY > 0 ? -0.08 : 0.08)));
    avatarCropState.zoom = nextZoom;
    els.avatarZoom.value = String(nextZoom);
    updateAvatarCropper();
  });
  els.saveAvatarCrop.addEventListener("click", saveAvatarCrop);
