    if (wasOpen) {
      els.trainerProfilePanel.classList.add("hidden");
      return;
    }
    renderTrainerClassPanel(activePlayer());
    positionTrainerProfilePanel(els.activeTrainerClassDetail, 380);
    els.trainerProfilePanel.classList.remove("hidden");
    els.trainerMenu.classList.add("hidden");
