  [
    [els.activeClassOrigin, "classOrigin"]
  ].forEach(([element, field]) => {
    element.addEventListener("focus", () => {
      element.dataset.startValue = element.textContent.trim();
    });
    element.addEventListener("input", () => {
      const player = activePlayer();
      const value = element.textContent.trim();
      if (field === "trainerClass") {
        setTrainerClass(player, value || "", false);
      } else if (field === "classOrigin") {
        player.classOrigin = value || "Unknown";
      }
      saveState();
    });
    element.addEventListener("blur", () => {
      const player = activePlayer();
      const before = element.dataset.startValue || "";
      const after = element.textContent.trim() || "Unknown";
      if (field !== "trainerClass" && before && before !== after) {
        addLogEntry({
          action: "class",
          category: "classes",
          player: player.name,
          item: `${field === "trainerClass" ? "Class" : "Class origin"} changed: ${before} -> ${after}`,
          type: field,
          quantity: 1,
          price: 0,
          balanceAfter: player.balance
        });
      }
      if (field === "trainerClass") {
        setTrainerClass(player, element.textContent.trim() || "", before !== after);
      }
      commitTrainerField(field, element.textContent);
    });
    element.addEventListener("keydown", (event) => {
      if (event.key === "Enter") {
        event.preventDefault();
        element.blur();
      }
    });
  });
